window.__SEARCH_INDEX__={"countries":[{"name":"Albania","url":"albania/field-notes.html","flag":"al","kind":"field-notes"},{"name":"Belgium","url":"belgium/field-notes.html","flag":"be","kind":"field-notes"},{"name":"Bosnia","url":"bosnia/field-notes.html","flag":"ba","kind":"field-notes"},{"name":"Croatia","url":"croatia/field-notes.html","flag":"hr","kind":"field-notes"},{"name":"Denmark","url":"denmark/field-notes.html","flag":"dk","kind":"field-notes"},{"name":"Estonia","url":"estonia/field-notes.html","flag":"ee","kind":"field-notes"},{"name":"Finland","url":"finland/field-notes.html","flag":"fi","kind":"field-notes"},{"name":"Georgia","url":"georgia/field-notes.html","flag":"ge","kind":"field-notes"},{"name":"Germany","url":"germany/field-notes.html","flag":"de","kind":"field-notes"},{"name":"Greece","url":"greece/field-notes.html","flag":"gr","kind":"field-notes"},{"name":"Hungary","url":"hungary/field-notes.html","flag":"hu","kind":"field-notes"},{"name":"Kosovo","url":"kosovo/field-notes.html","flag":"xk","kind":"field-notes"},{"name":"Latvia","url":"latvia/field-notes.html","flag":"lv","kind":"field-notes"},{"name":"Montenegro","url":"montenegro/field-notes.html","flag":"me","kind":"field-notes"},{"name":"Netherlands","url":"netherlands/field-notes.html","flag":"nl","kind":"field-notes"},{"name":"North Macedonia","url":"north-macedonia/field-notes.html","flag":"mk","kind":"field-notes"},{"name":"Serbia","url":"serbia/field-notes.html","flag":"rs","kind":"field-notes"},{"name":"Slovenia","url":"slovenia/field-notes.html","flag":"si","kind":"field-notes"},{"name":"Sweden","url":"sweden/field-notes.html","flag":"se","kind":"field-notes"},{"name":"Switzerland","url":"switzerland/field-notes.html","flag":"ch","kind":"field-notes"},{"name":"Egypt","url":"egypt/field-notes.html","flag":"eg","kind":"field-notes"},{"name":"Tanzania","url":"tanzania/field-notes.html","flag":"tz","kind":"field-notes"},{"name":"Armenia","url":"armenia/field-notes.html","flag":"am","kind":"field-notes"},{"name":"India","url":"india/field-notes.html","flag":"in","kind":"field-notes"},{"name":"Indonesia","url":"indonesia/field-notes.html","flag":"id","kind":"field-notes"},{"name":"Philippines","url":"philippines/field-notes.html","flag":"ph","kind":"field-notes"},{"name":"Türkiye","url":"turkiye/field-notes.html","flag":"tr","kind":"field-notes"},{"name":"Argentina","url":"argentina/field-notes.html","flag":"ar","kind":"field-notes"},{"name":"Brazil","url":"brazil/field-notes.html","flag":"br","kind":"field-notes"},{"name":"Chile","url":"chile/field-notes.html","flag":"cl","kind":"field-notes"},{"name":"Colombia","url":"colombia/field-notes.html","flag":"co","kind":"field-notes"},{"name":"El Salvador","url":"el-salvador/index.html","flag":"sv","kind":"guide"},{"name":"Mexico","url":"mexico/field-notes.html","flag":"mx","kind":"field-notes"},{"name":"Peru","url":"peru/field-notes.html","flag":"pe","kind":"field-notes"},{"name":"Australia","url":"australia/field-notes.html","flag":"au","kind":"field-notes"}],"articles":[{"title":"El Salvador Travel Guide with Perfect 1-2 Week Itinerary","url":"el-salvador/el-salvador-itinerary.html","country":"el-salvador","tag":"Itinerary","date":"Apr 5, 2026"},{"title":"Top 10 Things to Do in El Salvador","url":"el-salvador/top-10-el-salvador.html","country":"el-salvador","tag":"Top 10","date":"Apr 16, 2026"},{"title":"The Ultimate Guide to Santa Ana, El Salvador's Second City","url":"el-salvador/santa-ana.html","country":"el-salvador","tag":"City Guide","date":"Mar 22, 2026"},{"title":"Ruta de las Flores — El Salvador's Historic Route","url":"el-salvador/ruta-de-las-flores.html","country":"el-salvador","tag":"Route Guide","date":"Mar 25, 2026"},{"title":"The 7 Waterfalls Hike — El Salvador's Most Spectacular Trail","url":"el-salvador/7-waterfalls-hike.html","country":"el-salvador","tag":"Hike Guide","date":"Mar 27, 2026"},{"title":"El Tunco & The Coast: The Best Beaches in El Salvador","url":"el-salvador/el-tunco.html","country":"el-salvador","tag":"Beach Guide","date":"Mar 30, 2026"}],"pages":[{"url":"albania/field-notes.html","title":"Albania Travel Guide","text":"Albania Travel Guide General Albania is an extremely underrated country in Southeastern Europe that is quickly gaining popularity. Located right between Greece and Montenegro, the coastline is just as beautiful and has been dubbed the \"Albanian Riviera.\" In the North of Albania lies the Accursed Mountains, home to some amazing hiking and crystal-clear blue mountain springs. Albania also has a fascinating modern history. Under a repressive dictator named Enver Hoxha, Albania suffered tremendously and became the 3rd poorest country in the world in 1985 with an average wage of $15 per month. During the subsequent decades, Albania struggled to recover and large crime networks contributed to its reputation as a dangerous location. However, this couldn't feel further from the truth when you're in Albania. The country has made tremendous strides to recover and I felt extremely safe when I was there. Albanians were all very welcoming people. Only becoming a popular tourist destination in the last 5 years, Albania is still a bit rough around the edges with hotels springing up everywhere. Go before it gets as crowded and popular as Croatia and Greece! Suggested Route Overview Transport Mini-buses (called \"Furgons\") — the most popular mode of intercity transport are a massive network of mini-buses called Furgons that will take you just about anywhere in Albania ranging from small towns to cities. Gjirafa.com is by far the best resource for bus schedules and routes Furgons are very cheap and comfortable, but don't expect them to run on time and they tend to stop in random places for locals to get off. The main \"bus station\" in Tirana is just a chaotic parking lot with 100+ vans and drivers shouting destinations Taxi & Ridesharing — There are a few ridesharing apps in Albania. However, it was pretty unreliable to get a ride. I found taxis to be fair as long as you negotiate or ask around for pricing beforehand Google Maps — is unreliable when it comes to hiking paths: download AllTrails or maps.me as a backup Mostly cash is used in Albania , primarily the Albania Lek, but also the Euro at times. ATMs are easy to find, but make sure you keep a bit of extra cash on hand How long to spend — I would recommend spending 2 weeks in Albania for a first timer. This will allow you to see all the highlights of Albania ranging from the Albanian Riviera, hike in the Accursed mountains and explore Tirana without feeling too rushed Albanian Riviera — Himarë 3–4 days recommended The Albanian Riviera lies on the Southwestern coast of Albania stretching from Vlorë all the way down to Ksamil near the border with Greece. It is home to some of the most clear blue-green water that I have ever seen and is comparable to Greece but with way fewer tourists. There is a strong Greek influence throughout the area with a large Greek minority, Greek food everywhere and Greek signage all over town. There are many towns along the Albanian coast that you could spend your time in, but I chose to spend my time in Himarë which was a gorgeous little town in the middle of the riviera. All of my tips will be about Himarë, but similar activities are available all across the coast. However, there are plenty of other locations you can visit: The two largest towns and main transport hubs are Vlorë in the North and Sarandë in the South Vlorë — I had a quick stop in Vlorë and wouldn't recommend it staying there as the beach really wasn't special Sarandë — largest town on the Albanian riviera. It has the most beach clubs, restaurants and nightlife. A great stop if you are taking the ferry from Corfu and coming to/from Greece Ksamil — known to have the most beautiful water and beaches in Albania, but it is also very popular so expect it to be packed during the high season. Located ~30 minutes away from Sarandë Smaller, more quaint towns along the coast include Dhërmi (white Greek town), Porto Palermo (castle and secluded bay), and Borsh (quiet and hippy vibes) What to Do Grama Bay Boat Tour — if you're looking to visit some amazing beaches with incredibly blue water, this is the tour for you. Many of the beaches are only accessible by boat so there aren't many other tourists here. Stops include Pigeon's Cave, Gjipe Beach, Pirate's Cave and a mermaid cave The highlight of this tour was the final stop at Grama Bay which is considered one of the most beautiful beaches in the world. Make sure you do the short hike (~20 minutes) up to the top of Grama for the best views of the beach below The particular tour I booked was run by Himare Seas the Day , leaving from the main harbor in Himare. It cost ~70€ which felt expensive, but the experience was incredible with a very funny captain Visit the beaches — there are a plethora of beaches that you can visit while in Himarë. I've ranked them in descending order starting with my favorites: Filikuri Beach — 30-minute hike from town, one of my favorite beaches in all of Europe with the clearest blue-green water. The descent is steep and sketchy: you have to climb down a rock face with a rope. You can also take a water taxi if that sounds like too much. The view from above is amazing as well and the beach wasn't crowded at all when I was there Aquarium Beach — a 30-minute uphill hike from Livadi Beach in the heat, but worth every step. A small hidden alcove with a bar and probably the clearest water on the riviera. You could literally see the fish swimming from above. The beach is really tiny so it tends to get crowded Spile Beach — the main public beach in Himarë right next to town, right along the promenade with beautiful water. There are free umbrellas here if you're looking to chill, but it can get a bit crowded in the summer Livadi Beach — a very big beach stretching for miles lined with beach clubs and restaurants. It is worth stopping at the roof of the abandoned hotel above the beach for a spectacular view over the water. The trail up is covered in pines and a few old communist-era bunkers Jale Beach — a beach located a 20-minute drive from Himarë. It gets good reviews online, but I found it to be more commercialized and not particularly special. I wouldn't go out of your way for it Coastal hike — if you're feeling active, you can hike north along the coastline from Himare and hit almost all of these beaches in one day connecting Spile Beach → Livadi Beach → Aquarium Beach → Jale Beach (about 7 miles or 11 km total). There is no official path or road on Google Maps, but it is a pretty clear path in real-life along the ocean that connects all these beaches. You'll pass by many of Albania's 750,000 bunkers scattered throughout the country side. It can get very hot during the summer so bring plenty of water Old Town Himarë — located 45-minute uphill walk (or short taxi ride) from main town of Himarë and the beach. It is a completely abandoned castle and church. It felt very peaceful with goats and a donkey grazing under olive trees. It isn't particularly impressive so feel free to skip if you don't have enough time Stop at Butterfly Cafe for a beer and Trilece cake. It is a small family-run cafe with vines growing across the terrace roof and a view of the bay below. I went hiking 14 miles in 90-degree heat and it was exactly what I needed Where to Eat Guma Restaurant — a nice restaurant located right on the promenade in Himarë I Love Souvlaki — a great place along the promenade to get Greek food, very quick and affordable Fast-Food Burbo — the town bakery that is very popular among locals. Try the Zabontiropita (ham and cheese pastry) and dhallë, the Albanian sour milk that locals drink with everything Tonea's All Day Brunch & Café (Livadi Beach area) — boho-style restaurant with a very friendly staff Butterfly Cafe (Old Town Himarë) — a small family run restaurant with a great view of the bay below and amazing Trilece cake Where to Stay Beleri House (Airbnb) — a great Airbnb apartment located right on the end of Himare with a great view of the beach, fast internet and relatively affordable Himara Downtown Hostel — one of the most popular hostels in town. My friends had a blast staying here ATTRACTIONS 1 Old Town Himarë 2 Jale Beach 3 Aquarium Beach 4 Livadi Beach 5 Spile Beach 6 Filikuri Beach RESTAURANTS & BARS 7 Butterfly Cafe 8 Guma Restaurant 9 I Love Souvlaki 10 Fast Food Burbo Bakery 11 Tonea's Café ACCOMMODATION 12 Himara Downtown Hostel DAY TRIPS ↗ Grama Bay Boat Tour (Full Day) ↗ Coastal Hike (Half Day) ALBANIA Himarë Touch to explore Double-tap to open in Google Maps Valbona to Theth Hike 4 days recommended This is an amazing hike in the Accursed Mountains (Albanian Alps) in Northern Albania. The hike is complete with impressive mountains, mountain springs filled with bright blue alpine waters, cute little mountain villages and the famous Blue Eye of Theth. This ended up being one of the best travel experiences I've ever had between the scenery, the amazing people I met and the amazing vibe at the guesthouses. While you can organize this hike by yourself, I highly recommend that you do it with Wanderer's Hostel in Shkoder. They organize the entire experience (transport, lodging, food) for around 160€ and it makes the experience a lot more social. Make sure to book a couple months in advance during in summer since they fill up fast! Contact them via email: hostelshkoder@hotmail.com General Logistics The hike starts in the city of Shkoder located in Northern Albania (~2.5 hours by bus from Tirana) The whole hike runs 3 days, but you need to arrive in Shkoder the night before the hike for a briefing from Wanderer's Hostel If you book with Wanderer's Hostel, they will organize both transport and food which is a lifesaver. Just get to the start of the hike, you'll need to take a bus and a ferry and a bus again so just imagine organizing that on your own in rural Albania! The hike starts in Valbona , but you first need to get to Shkoder (roughly 2.5 hours by bus from Tirana). From Shkoder the journey runs: 3-hour bus to Komani → 3-hour ferry along a stunning canyon to Fierze → 1-hour bus to Valbona. Long day, but the ferry through the canyon is worth the trip on its own, gray jagged mountains on both sides, blue-green water below, no agenda Itinerary This experience runs best over 4 days: Day 1 — Arrive Shkoder: you'll need to arrive the day before for your briefing of the hike. Check into Wanderer's Hostel, get oriented and an employee of the hostel will run you through the hiking route and overall itinerary. It may be an overwhelming amount of information, but is straight-forward when you start hiking. The hostel runs a group dinner in the evening which is a good way to meet the people you'll be hiking with Shkoder is a nice town itself so go for a walk to explore the town. If you're interested in photography, stop by the Marubi Museum . It is a small museum with photographs documenting Albanian life in the 1920s–1940s with traditional weddings, royal families, and early events in the country's history Day 2 — Shkoder to Valbona: this day is mostly a transport day to get to Valbona (the town at the start of the hike). From Shkoder the journey runs: 3-hour bus to Komani → 3-hour ferry along a stunning canyon to Fierze → 1-hour bus to Valbona The ferry through the canyon is beautiful with gray jagged mountains on both sides and blue-green water below When you arrive in Valbona in the early afternoon, check into Arben Selimaj Guesthouse . We spent the rest of the afternoon chilling by the beautiful blue stream right at the entrance with mountains all around and getting to know the other backpackers on the hike. There is a communal dinner, then everyone packs sandwiches for the next day Day 3 — Valbona to Theth (The Main Hike): This hike is 9miles or 15km long and takes 5–6 hours total. It didn't feel particularly challenging and there are a lot of places to stop along the way The journey starts at 6AM and vans take you to the trailhead. The hike is forested at first, then becomes a steep white gravel climb to the summit. The best moment: turning back on that gravel slope to see the entire Valbona valley laid out below you. The peak is the perfect place to stop for lunch. There is a huge Albanian flag flying at the top and you have a beautiful view of the valley below. Along the way, you'll run into some local dogs and wild horses as well We finished the hike pretty early at 1PM and checked into Dreni Guesthouse in town of Theth. This was a gorgeous lodge that served some great dinner and had some benches to hangout and have some beers in the evening In the afternoon, do the Theth Waterfall hike (1 extra hour from the guesthouse). There is a huge waterfall with a cold pool and rocks to sit on. I highly recommend it. The hike is pretty short and this is when the whole group really comes together Day 4 — Blue Eye from Theth (optional): Wanderer's hostel allows people to skip the last day, but DO NOT skip it as this was the highlight of the hike for me It is a 3-hour hike each way that is much flatter than the main hike, but with less forest cover. The hike ends at the Blue Eye of Theth, a gorgeous bright blue spring fed by a waterfall surrounded by cliffs. The water comes from melted alpine glaciers so be prepared for freezing temperatures. If you're feeling brave, you can also cliff jump from here On the way back, stop for a swim in a gorge with bright blue water and striking red and white stones (the colors genuinely reminded me of Utah). The next day there are a few different buses back to Shkoder which depart from a restaurant at the end of the trail Tirana 1 day recommended I found Tirana to be pretty skippable, but you'll likely fly in or pass through. I'm not going to lie and say it is the prettiest city, but it is the best place to learn about Albanian history, particularly the oppressive North Korea-like regime of Enver Hoxha. You'll be able to see all the highlights in just one day (or even just half a day). What to Do Bunk'Art 1 or 2 — one of the best museums I visited in the Balkans. For over 40 years, Albania had one of the most oppressive regimes in the world led by a man named Enver Hoxha. It is fascinating to learn about this dictator (that you've probably never heard of). It is located underground in an old nuclear bunker converted into a museum There are two locations Bunk'Art 1 (original location on the outskirts of Tirana) and Bunk'Art 2 (newer location located in the city center) The museum is very dark, but it was absolutely fascinating. I won't spoil all of it, but here is a taste of what you'll learn about: Albania became a hermit state (like North Korea) with guard dogs and barbed wire along the border designed to keep people in. Only 2,800 people per year visited Albania then, compared to 12 million in 2025 Foreigners who were even allowed in were forced to get specific haircuts at the airport on arrival There was a KGB-like network where people would inform on political opponents Skanderbeg Square — main square with huge statue of the national hero and an Albanian flag. It is surrounded by the National Museum , Et'hem Bej Mosque , Bunk'Art 2 and the Clock Tower Of Tirana Tirana Pyramid — a giant, modern concrete pyramid with stairs you can climb for a view of the city. Not particularly impressive, but located right by Skanderbeg Square Blloku neighborhood — formerly exclusive to communist party members, now the fancy neighborhood. You can visit Enver Hoxha's old house. There are a lot of bunkers here too, a reminder of how many of these are scattered across the entire country Tirana Castle — if you're expecting an impressive European castle (like I was), be prepared to be disappointed. It was mostly destroyed except for the outer walls and it is now filled with upscale, touristy restaurants. You can visit the New Bazaar inside here if you're looking to do a bit of shopping Where to Eat Thethi Bakery — a small little bakery across from the North/South bus station, great if you're catching a bus to somewhere else in Albania Where to Stay Bearded Dad Hostel — a very social hostel with group dinners and lots of activities. A good place to meet people before heading north for the hike Blue Door Hostel — the sister hostel to Bearded Dad. Also very social with group dinners and activities like trivia ATTRACTIONS 1 Skanderbeg Square 2 National History Museum 3 Et'hem Bej Mosque 4 Clock Tower 5 Tirana Castle 6 Bunk'Art 2 7 Tirana Pyramid 8 New Bazaar 9 Blloku ACCOMMODATION 10 Bearded Dad Hostel 11 Blue Door Hostel ALBANIA Tirana Touch to explore Double-tap to open in Google Maps Other Towns to Consider There are plenty of other places to consider that I didn't visit in Albania that came highly recommended by other travelers: Albanian Riviera Sarandë — largest town on the Albanian riviera. It has the most beach clubs, restaurants and nightlife. A great stop if you are taking the ferry from Corfu and coming to/from Greece Combine it with the nearby towns of Gjirokastër (historic town) , the Blue Eye and Ksamil (the \"maldives\" of Albania) Ksamil — known to have the most beautiful water and beaches in Albania, but it is also very popular so expect it to be packed during the high season. Located ~30 minutes away from Sarandë Dhërmi — a small, picturesque white town along the coast near Himarë. It is supposed to be more upscale and quiet than Himarë Historic Towns Gjirokastër — a beautiful stone town from the Ottoman Era in the south of Albania near the Greek border. Supposedly the best historic town in Albania Berat — Ottoman city with thousands of windows, located in Central Albania roughly 2 hours from Tirana. It is possible to do a day trip from Tirana, but challenging to do unless you take a guided day tour Krujë — a small historic town within an hour from Tirana. You can stay overnight in the Castle of Krujë and the sunset is nice. It might be the best option to visit a historic Albanian town if you are short on time as Gjirokastër and Berat are challenging day trips from Tirana"},{"url":"argentina/field-notes.html","title":"Argentina Travel Guide","text":"Argentina Travel Guide General Argentina is a country of extremes: the glaciers and granite spires of Patagonia in the south, the thundering Iguazu Falls in the subtropical north, and in between one of the most exciting cities in the world in Buenos Aires . Patagonia is genuinely spectacular and worth the effort to reach; Buenos Aires is one of the most interesting and fun big cities in South America. Argentina is where European traditions blend with South America, creating a unique culture unlike any other. Argentina is a one-stop destination for all types of travelers: from the grand European architecture in Buenos Aires to the gaucho traditions and wine culture in the countryside to some of the continent's most spectacular landscapes in Patagonia and Iguazu Falls. For first timers, I would recommend spending 10 to 14 days in Argentina and combine it with a trip to Chile to fully explore the Patagonia region. Suggested Route Overview Getting around Flights — Argentina is the 8th largest country in the world so the best way to get around is to fly. You'll likely fly into Buenos Aires , capital and heart of Argentina. When flying to Patagonia, the main airport is El Calafate in the north and Ushuaia in the south Buses — long-distance buses are comfortable and connect all major towns with shorter shuttles linking the Patagonian towns and trailheads. Book all of your buses on BusBud Ridesharing — Uber is widely available and extremely cheap in Argentina. It was my primary way of getting around Buenos Aires and even longer airport rides cost less than $10 Driving — Argentineans are relatively safe drivers. In particular, I would rent a car in Patagonia as there is little to no traffic here and easy to drive around Money — the Argentinean Peso is famous for it's rampant inflation and the country has struggled to maintain the stability of their currency. It can be a bit disorienting as a tourist so you'll want to follow the following guidelines: Bring USD to Argentina and you can exchange with local vendors for the \"blue dollar\" rate. Exchanging for the \"blue dollar\" rate with street vendors will sometimes get you a rate 1.5x to 3.0x the official exchange rate, making your money stretch a lot further Some vendors will refuse to take card so carry cash when you can. ATMs here can cause issues as they often run out of cash before the end of the day, some have insane fees ($8 on a $20 withdrawal) and they all have low daily limits Get used to carrying large stacks of cash. When I was there, the most common bill was 1,000 pesos (equivalent to $2 at the time) so every meal would be paid in a huge stack of bills. It seems like they made larger 10,000 and 20,000 pesos bills since so hopefully this relieves the issue Food — Argentinean food is one of the great cuisines. With some of the highest quality beef in the world, make sure you have at lease one steak while you're in the country. Other great dishes to have are the asado (the barbecue), choripán (chorizo sandwich), milanesa (fried cutlet) and empanadas , all washed down with Mendoza Malbec Nightlife — the country's nightlife in a league of its own and it's hard to even keep up as a foreigner. Argentinians go out harder and much later than anywhere else I've seen. Clubs open at 1am, run until 7am, then afterparties start at 9am Safety — Buenos Aires felt very safe in the Palermo, Recoleta and San Telmo neighborhoods. With the decline of the Argentinean economy over recent years, the crime rate has increased so just be careful at night and stick to safer neighborhoods. Puerto Iguazú and Patagonia are some are the safest places in the world so no need to worry about crime there Buenos Aires 3–4 days recommended Buenos Aires is perhaps the one of the most famous and grand cities in South America with noticeable European influence. The historic neighborhoods of Recoleta and Palermo feel like Paris with wide tree-lined boulevards, classical architecture and world-class restaurants and cafés. The pace of life in Buenos Aires is relaxing during the day and the nightlife is genuinely in a class of its own. Spend 3–4 days exploring Buenos Aires. It was fascinating learning about Argentinean culture and the history of how the country was shaped by Italian, Spanish and other European immigrants. What to Do Buenos Aires is a metropolis that sprawls for miles. As a tourist, there are 3 main neighborhoods you want to focus on. From north to south, they are Palermo, Recoleta/Monserrat, San Telmo and La Boca. They are a bit too far to walk so you'll want to take Ubers or public transportation between the different stops. I've organized the activities by different neighborhoods to help you plan your trip: Palermo — the best neighborhood to stay in Buenos Aires. It is very walkable and full of great restaurants, bars, parks and shops Parque Tres de Febrero — a large and beautiful park built around a lake, known as the lungs of Palermo. Paddle boats on the water, street food vendors along the paths and a relaxed local crowd especially at sunset. Spend an afternoon or evening walking around here Avant Garten — located right next to Parque Tres de Febrero is a row of trendy restaurants, bars and creative food spots built under old brick railway arches. Good for a casual dinner or drinks in the evening Museo de Arte Latinoamericano de Buenos Aires — one of the best museums in Latin America, housing over 400 works of modern and contemporary Latin American art. The permanent collection includes works by Frida Kahlo, Diego Rivera and other major 20th century Latin American artists. There is also a rooftop terrace, cinema and cafe on site. It takes about 2 hours to fully explore Costa Rica Street — one of the best streets in Palermo for a night out, lined with restaurants, wine bars and cocktail spots. A popular area for locals to hangout Recoleta & Monserrat — the two most historic neighborhoods in Buenos Aires, located right besides each other. Recoleta is the elegant, Paris-inspired quarter while Monserrat is the oldest neighborhood and political heart of the city Recoleta Cemetery — it might feel strange to visit a cemetery on vacation, but Recoleta Cemetery has some extremely impressive mausoleums and tombs to visit. The cemetery has a distinctly avantgarde Italian style. You'll see a vast array of tombs ranging from small tombs to miniature Roman buildings, many with grand statues, busts and photos of the dead. It is worth an hour to explore and you can even get a tour to learn about the famous Argentineans buried here El Ateneo Grand Splendid — an old theater converted into a bookstore, with ornate railings, tiny lights and the original stage. It is the most impressive bookshop I've been in Café Tortoni — the oldest café in Argentina opened in 1858. The interior is frozen in time and it has been a gathering spot for Argentine intellectuals, artists and politicians for over 160 years. Get a cortado and a plate of churros with hot chocolate Plaza de Mayo — the political and historical heart of Buenos Aires, founded in 1580. Every major event in Argentine history has happened here, from the May Revolution of 1810 to Eva Perón's famous speeches from the balcony of Casa Rosada . The square is still very much alive; you will often find protesters camped out around the Pirámide de Mayo at the center Catedral Metropolitana de Buenos Aires — the neoclassical cathedral on the north edge of the square, home to the tomb of General José de San Martín, Argentina's liberating hero. Impressive interior with gilded altars and high vaulted ceilings Museo Nacional del Cabildo — the colonial-era town hall on the west edge of the square, one of the oldest buildings in Buenos Aires. There is a small museum covering the May Revolution and colonial history. Worth a quick stop Casa Rosada — the famous pink presidential palace on the east edge of the square. Free guided tours of the interior are available on weekends San Telmo — Buenos Aires' bohemian neighborhood, with cobblestone streets, colonial architecture, antique shops and tango venues around every corner Mercado de San Telmo — a stunning 1897 indoor market hall with a glass roof open daily with gourmet food vendors, coffee roasters, antique dealers and vintage record shops. I went here multiple times to eat and it was one of my favorite places in the city San Telmo Sunday Street Fair — every Sunday, the indoor market spills out onto Calle Defensa for over 10 blocks and transforms into one of the largest outdoor markets in the world. There are hundreds of vendors selling antiques, handmade crafts and art, street tango performers and live music. One of the best things to do in Buenos Aires on a Sunday La Boca — the most colorful and chaotic neighborhood in Buenos Aires. Worth a half day to wander around. Make sure to stick to the tourist area during daylight hours, beyond the main streets it is one of the rougher neighborhoods in Buenos Aires El Caminito — the famous pedestrian street lined with bright rainbow corrugated-metal buildings and Messi murals. It is a super lively neighborhood located right next to the river. There are tango dancers performing on the sidewalk and food and souvenir stalls everywhere La Bombonera — the legendary home stadium of Boca Juniors, one of the most passionate football clubs in the world. The stadium is famous for its unique box shape and the sheer noise the fans generate inside. Worth walking past the exterior and checking out the museum even if you can't get match tickets Where to Eat Mi Tío Pizzería (San Telmo) — a tiny mom-and-pop near the San Telmo market. The restaurant serves very authentic Italian food. The gnocchi in a loose tomato sauce loaded with slow-stewed beef was the owner's recommendation and simply amazing Dandy — an upscale Argentinian chain with a few location throughout the city. It is good for a lighter meal if you want to take a break from the Argentinian steaks Parrilla Del Carmen — a no-frills outdoor grill spot popular among locals. They had an incredible asado during the San Telmo Sunday Street Fair Choripán — you can find these available in almost any part of Buenos Aires. These are chorizo sandwiches often served with Chimichurri sauce. These were an amazing everywhere I went from street vendors to restaurants Crobar Club — one of the best clubs in Argentina and an unforgettable experience. It opens at 1am and doesn't get packed until later. The techno here was elite with a really cool LED display. The place is completely packed until 7am when Argentinians head to afterparties Where to Stay Viajero Buenos Aires — a solid hostel option in the centrally located neighborhood of Monserrat. Since nightlife runs extremely late in Argentina, be prepared for people to come in your dorm at very late hours like 5AM or 7AM If you're looking for your own space, there are plenty of Airbnbs and hotels that run extremely cheap in Buenos Aires. I found a great Airbnb apartment in the neighborhood of Palermo for only ~$24/night PALERMO 1 Parque Tres de Febrero 2 Avant Garten 3 MALBA 4 Costa Rica Street 5 Dandy 6 Crobar Club RECOLETA & MONSERRAT 7 Recoleta Cemetery 8 El Ateneo Grand Splendid 9 Café Tortoni 10 Plaza de Mayo 11 Casa Rosada 12 Viajero Buenos Aires SAN TELMO 13 Mercado de San Telmo 14 San Telmo Sunday Fair 15 Mi Tío Pizzería 16 Parrilla Del Carmen LA BOCA 17 El Caminito 18 La Bombonera DAY TRIPS ↗ Colonia del Sacramento (Full Day) ARGENTINA Buenos Aires Touch to explore Double-tap to open in Google Maps El Calafate 1–2 days El Calafate is a lakeside Patagonian town that exists mainly for one staggering sight: the Perito Moreno Glacier . Most people come for a day or two, see the glacier, and move on to El Chaltén as there isn't much to do in this town. One of the few glaciers in the world that is still advancing rather than retreating, Perito Moreno is part of the Southern Patagonian Ice Field, the third largest freshwater reserve on the planet after Antarctica and Greenland. The glacier's face is 5km wide and rises up to 74 meters above the lake surface, with another 700 meters of ice hidden below the waterline. What to Do Perito Moreno Glacier — about 1.5 hours from town, you can take a private taxi (~100k pesos) or public transport to one of the largest glaciers in the world. It is an impressive site to behold and the entire surface area of Perito Moreno is larger than the city of Buenos Aires. Watch for calving: a loud gunshot crack, a chunk falling, slow waves rolling out, and the flipped ice glows a brilliant blue color while floating in the water. There are a few ways to visit the glacier: Perito Moreno Glacier Walkways — there are metal walkways color-coded by route where you walk alongside the massive glacier and admire it from a distance. The yellow track takes you closest to the base, where the glacier wall stands perfectly straight with enormous spiky blue towers, sandwiched between two black mountains. Entry costs around $30 USD or 45,000 ARS for foreign visitors Minitrekking —you can even walk on top of the glacier with a Minitrekking tour. It lasts a total of 1.5 hours on the glacier with crampons, includes a boat ride to the starting point and a whisky on the rocks with glacier ice at the end. Expect to pay around $350 USD, not including park entry Helicopter tour — the best way to grasp the true scale of Perito Moreno. The helicopter flight takes you over the full 30km length of the glacier and the surrounding ice field, revealing deep blue crevasses and rivers of ice impossible to see from the walkways. Around 20–30 minutes in the air, ~$400–500 USD. Book in advance and be prepared for weather cancellations Kayaking — the most intimate way to experience the glacier, putting you at water level among the icebergs that have calved off the face. The tour lasts 1 - 2 hours on the water in double kayaks close enough to the glacier wall to feel the cold radiating off it. No experience required and a dry suit provided. Around $250 USD including transport from El Calafate Explore the Charming Downtown — El Calafate is a surprisingly pleasant small town and worth a few hours of wandering after the glacier. The main street, Avenida del Libertador, is lined with restaurants serving traditional Argentinean food. The local special is the c ordero patagónico which is Patagonian lamb slow-roasted gaucho-style Where to Eat Big Pizza — a surprising spot where I found some of the best value empanadas. I tried the carne suave, spicy carne, onion-and-cheese and cheeseburger for only ~950 pesos or $1 each Where to Stay América del Sur Hostel — a ski-lodge-style hostel with a massive common area, floor-to-ceiling windows overlooking the lake and mountains, a fireplace and a bar. It was one of the best hostels I've ever stayed at with an excellent steak dinner served with red wine and live music El Chaltén 2–3 days recommended El Chaltén is a tiny town of 5,000 founded in 1985. There is basically main street where every building is a seasonal business serving tourists. It's Argentina's trekking capital and the base for the iconic Mount Fitz Roy hike. I would recommend spending 2 to 3 days here to explore amazing hikes here. The hikes here rival the W Trek that I did in Torres Del Paine on the Chilean side of Patagonia. What to Do Laguna de los Tres / Fitz Roy hike (~15 miles / 24 kilometers round trip) — prepare for a long hiking day and one of the most incredible hikes of your life! I would highly recommend an early start to catch the famous sunrise and mountains (Mt Fitz Roy) that inspired the Patagonia logo I woke up at 5:30am and hiked in the dark with a headlamp for a couple hours. It starts with an easy stretch through town and then an ascent to the Mirador del Fitz Roy . Rest here and catch the spectacular sunrise that glowed miraculous shades of orange and purple The hike continues on through a stunning valley with red autumn foliage, streams, marshes and Fitz Roy always in view. The last stage is a 2km ascent up a steep, loose, near-vertical rock size, so take it slow. At the top, Laguna de los Tres is brilliant blue beneath the mountain, with wind so strong I couldn't even hold my phone upright. You hike back the same way from here. It was an extremely long day, but worth every second. Unlike many popular trails, I didn't see very many other tourists which was refreshing. Here is the AllTrails link for the exact route Mirador de los Cóndores (Condor Lookout) — if you're looking for an easy hike before or after the Fitz Roy hike, Mirador de los Cóndores is a great candidate. It is a short 3 mile hike up a short hill at the edge of town. It is a great spot to go for sunset and spot condors circling overhead, with views over the whole little town below Where to Eat Bourbon Smokehouse — one of the more popular restaurants in town. They serve classic Patagonia fare. The cordero (lamb) is an enormous pile of ribs, meat and potatoes and there is a cheap happy-hour here as well Lomolito — the best place to enjoy the Argentine classic lomo-saltado steak sandwich with fries La Diadema — a fancy restaurant located right next to my hostel. It was nearly empty when I went, but the food was delicious Banneton — the main coffee shop on the main street and the best breakfast or rest-day stop Where to Stay Aylen Aike Hostel — a cozy hostel with a small dining table and common area. Most people here head out on hikes during the day and the hostel comes alive at night. You'll meet almost everyone staying here since it is very close quarters and maybe meet a hiking buddy for the next day Make sure to read my field notes on the Chilean side of Patagonia here . Iguazu Falls 2 days recommended Iguazu Falls is one of the most incredible waterfalls in the world, surrounded by lush jungle making you feel like you're in Jurassic Park or Avatar. It is no surprise that it is one of the seven natural wonders of the world. The waterfalls are so massive that they're actually located in 3 countries: Brazil, Argentina and Paraguay. The best way to visit it is to spend 1 day on the Brazilian side and 1 day on the Argentinian side which each offer a different experience. It is very easy to cross the border, you just can take a cheap, local bus from one side to the other. Brazilian side: there are walkways through the forest to platform views of the falls from a distance. The falls stretch for miles side by side. The upper river flows peacefully then drops dramatically. The surrounding forest feels like Avatar. The waterfalls are famous for the biodiversity and is home to hundreds of species of tropical birds Argentinian side: take a boat tour here! They drive the boat directly into the falls and ram the boat into the water wall multiple times. It'll feel like a rollercoaster where you get completely soaked and shake water out of your sleeves afterwards. Bring a poncho and your GoPro How to get there — both the Brazilian side and Argentinean side have airports with regular flights to Rio, São Paulo and Buenos Aires. These flights are very affordable, roughly $30-$40 if you book in advance. It is significantly cheaper to fly to the airport on the side of the country that you're already in. Day Trip to Ciudad del Este, Paraguay If you have an extra day, also take a day trip to Ciudad del Este in Paraguay. It is quite an odd city, a popular spot for Brazilians and Argentineans to buy tax-free electronics (yes, random I know). The city is loaded with Chinese electronics stops. Visit some of the historic sites ( El Mensu History Museum and Catedral San Blas ) and stop by Maru Cafe for a traditional Paraguayan meal. You can get there by public bus. Depending on where you start, the will cross through the borders of Argentina, Brazil and Paraguay. Citizens of these cities are able to freely cross the borders. However, Foreigners are required to ask the bus drivers to stop. The bus doesn't automatically stop so make sure you ask the driver. Don't make the same mistake as me and accidently illegally cross the border... Where to stay I flew into the airport on the Brazilian side and decided to stay in the town of Puerto de Iguazu in Argentina. From the Brazilian airport, it was a simple public bus ride and quick border checkpoint to cross the border. The town of Puerto de Iguazu in Argentina has a lot more tourism infrastructure, restaurants and is the best place to base yourself in the area Tucan Hostel - one of my favorite hostel experiences. The hostel itself was very basic, but was very social and a great place to stay. I met some absolutely amazing people from all over the world and the host named Mariel was extremely friendly. Once a week, they host an absolutely legendary Asado (the weekly Argentinian tradition of having a family barbeque) complete with steak, blood sausage, pork ribs, chicken, chimichurri sauce and red wine Other Places to Consider Argentina is the 8th largest country in the world so there are plenty more places that I didn't have the time to explore: Mendoza — the heart of Argentine wine country at the foot of the Andes. Spend a day cycling between Malbec vineyards and sampling world-class wines Bariloche — an alpine, Swiss-feeling town in the Lake District, famous for its lakes, chocolate and hiking. It is the unofficial gateway to Argentina's northern Patagonia Ushuaia — the southernmost city in the world at the tip of Tierra del Fuego, the \"End of the World\" and the main departure port for Antarctica Salta — a completely different Argentina with red-rock canyons, high-altitude desert, colonial towns and the winding Quebrada de Humahuaca valley"},{"url":"armenia/field-notes.html","title":"Armenia Travel Guide","text":"Armenia Travel Guide General Armenia is a super underrated destination. It has a rich culture that is a unique mix of ancient biblical history and more modern Soviet influences. I found the history both fascinating and dark with the impact of the Armenian Genocide and the recent war with Azerbaijan present in the country. It is a very affordable country that was easy to navigate and no attraction felt overrun by tourists. A trip to Armenia is easily combined with a trip to Georgia as well The country is a mix of contrasts. The large cities like Yerevan (the capital) or Gyumri are very clean and modern. However, as you leave the cities, the countryside is noticeably poorer and more Soviet. The nature in Armenia is very beautiful. The country has a mix of snow-capped mountains and drier landscapes as you get further south toward Iran Suggested Route Overview Safety — I felt very safe in Armenia and it is rated one of the safest countries in terms of petty crime. The only concerns to watch out for are conflicts with neighboring countries as they have tense relations with Türkiye and Azerbaijan with a recent war in 2023 Transport Ridesharing apps are widely available. Use Yandex or the GG app (Armenian Uber) for getting around. You may have to pay with cash, but both work great. The rides were insanely cheap, ranging from $2–5 to get around the city Buses and metro — I had issues paying with a foreign card and the networks aren't very extensive Marshrutka — A network of informal vans that will help you get around Armenia. There are stations in almost every city. Yerevan is very well connected and this is a great option for day trips. Tickets were as cheap as $2 for a 3-hour ride Renting a car is a great option. Car rentals were pretty cheap, the roads are beautiful and easy to navigate Language — Most Armenians speak Russian as a second language, even greeting you with Здравствуйте (Zdravstvuyte), knowing a few words of Russian goes a long way. Younger Armenians speak English, particularly in big cities. Even if there was a language barrier, I found Armenians to be extremely helpful Cash — Armenia uses the Armenian Dram. Credit cards are widely accepted in Yerevan, but always carry cash, especially outside of major cities What to Eat In general, Armenian food is similar to Turkish food with different influences from Persian and Georgian cuisine Manti — baked little dumplings that are crunchy on top and served in tomato and yogurt sauce. Different than Turkish Manti Lahmajun — thin flatbread with spiced lamb — known as the national dish of Armenia Lavash — Armenian flatbread cooked in an underground oven, served with every meal Salads — super fresh with a variety of lettuce, beans and tomatoes Khorovats — Shish Kebabs — pretty similar to Persian barbeque Yerevan 2–3 days recommended The Cascade Complex — a massive Soviet-era staircase with modern art sculptures scattered throughout. Go in the mornings to see Mt. Ararat (the national symbol of Armenia) from the top. The snow-capped peaks looming over the city are genuinely magical Republic Square — the main square with beautiful pink/red sandstone Soviet buildings and a nightly fountain light show around 9pm in summer. They play classical music and shoot water like fireworks for 30 minutes. The National Gallery of Armenia is also located here Free walking tours — I highly recommend doing one. Our guide did a great job explaining Armenian history, Soviet legacy, the genocide, and the current geopolitical situation. Very informative and there was even a stop to try local foods Armenian Genocide Museum — located on a hill overlooking the city. One of the most important stops in Yerevan. There is a museum and eternal flame, sobering, but really important. Plan for an afternoon GUM Market — the main indoor market, popular among locals. Sells dried fruits, cognac, vegetables and meat. Try Sujukh — an Armenian candy made of fruit juice and walnuts Vernissage Market — outdoor souvenir market, better on weekends when it's fully open. I preferred GUM Market which felt more authentic Blue Mosque — the only mosque in the entire country. Gorgeous bright blue dome similar to mosques in Iran and Central Asia. Worth a quick visit Mother Armenia — huge bronze statue in Victory Park, surrounded by Soviet military equipment (tanks, jets, missiles). There is a great view of the city below Kond Neighborhood — the oldest neighborhood in Yerevan, pretty rundown in contrast to the rest of the city. Stop by the family-run Kond.House Coffee and the Kond Pedestrian Tunnel Ararat Brandy Factory — Armenians are famous for their brandy and this factory offers tasting tours Where to Eat Yerevan Tavern — probably my favorite restaurant. Wide variety of classic Armenian food with live music every night Mayrig Yerevan — the fanciest restaurant I went to. The Armenian Manti is baked (not boiled like Turkish) and served with tomato sauce and sour cream. Amazing Anteb Restaurant — known for Western Armenian cuisine. Get the Lahmajun, Zaatar bread and sour lemon dumpling soup Tumanyan Bakery — a local Armenian-style bakery Lumen Coffee 1936 — a hip coffee shop embedded in a historic building AfroLab Specialty Coffee Roastery — modern coffee shop with a really good cold brew Where to Stay Kantar Hostel — a newer hostel near Republic Square with a great free breakfast buffet. Not particularly social from my experience YellowFox Hostel — a family-run hostel. Pretty basic, I preferred Kantar ATTRACTIONS 1 The Cascade Complex 2 Republic Square 3 National Gallery of Armenia 4 Armenian Genocide Museum 5 Vernissage Market 6 Blue Mosque 7 Mother Armenia Monument 8 Kond Neighborhood 9 Yerevan Brandy Factory RESTAURANTS & BARS 10 Yerevan Tavern 11 Mayrig Yerevan 12 Anteb Restaurant 13 Tumanyan Bakery 14 Lumen Coffee 1936 15 AfroLab Specialty Coffee ACCOMMODATION 16 Kantar Hostel DAY TRIPS ↗ Khor Virap Monastery (Half Day) ↗ Geghard & Garni (Full Day) ↗ Lake Sevan (Full Day) ARMENIA Yerevan Touch to explore Double-tap to open in Google Maps Day Trips from Yerevan Organized tours are very cheap ranging from $15–30 for a full day. You can also reach most destinations by rental car or Marshrutka Orgov Space Telescope (ROT-45) — my favorite thing in Armenia. An abandoned Soviet-era radio telescope complex in the middle of nowhere. Incredible control room with pastel murals and old Soviet controls, plus a massive satellite dish to climb. You technically need a government permit but can pay the guys at the gate ~2,000 AMD each. Basically no other tourists. Do not skip this The next 4 were all part of a day tour ( link here ), highly recommended for seeing the most popular sites in one day Khor Virap Monastery — one of the oldest monasteries in the world with Mt. Ararat directly behind it. The contrast of the dark interior with a beam of light cutting through is beautiful. An important reason why Armenia became the first Christian nation Geghard Monastery — half building, half cave carved into the hillside. One of the most sacred spots in Armenia and tied to early biblical history Garni Temple — pagan temple from 77 AD that looks like a mini Acropolis perched on a cliff. Survived the conversion to Christianity as a unique example of early Armenian pre-Christian beliefs Symphony of Stones — a natural river valley surrounded by hexagonal columns formed by cooling lava, standing over 5–6 stories tall. Hidden in a gorgeous green valley with a river running through it Lake Sevan — the most famous lake in Armenia, stunning blue water with mountains all around. Stop at Sevanavank Monastery on the hill for the view Abandoned Soviet Plane — a Tu-134A sitting by a random lake. You can climb on top if you're feeling adventurous Black Wall — a hidden abandoned mine site under grassy hills. Very off the beaten path with no signs or tourists. The surroundings are beautiful, but it's not worth going out of your way Gyumri 1–2 days recommended General Gyumri is Armenia's second largest city and well worth a day trip or overnight. Only 2.5 hours by Marshrutka from Yerevan (~$4). Take the Marshrutka from the central train station parking lot , not the bus stop. It leaves when full so expect a short wait Known as the \"black city\" for its characteristic black and orange stone architecture. The downtown was heavily damaged in a 1988 earthquake and some buildings are still not fully rebuilt, but the center is gorgeous and newly renovated What to Do Vardanants Square — the main square with a large rectangular fountain, white marble walkway and willows. At the end is a brutalist genocide memorial and the St. All Saviors Church in beautiful black and orange stone Abovyan Street & Rijkov Walking Street — popular walking streets with gorgeous black stone buildings. The black stone is a more traditional Armenian architectural style than Yerevan Cathedral of the Holy Mother of God — probably the most beautiful spot in Gyumri. Classic black Armenian church with an enormous yard full of white blossoming trees Mother Armenia of Gyumri — slightly outside the city center, another Mother Armenia statue that is arguably better looking. There is a long walkway lined with stones from major Soviet cities. Don't miss the WWII memorial with an eternal flame Black Circular Fortress — a medieval-feeling circular fortress with black walls, gold trim balconies and red curtains. Only worth visiting if you're already by the Mother Armenia statue Gyumri Market — an open-air market where locals sell produce, meat, fish and spices Where to Eat KTOR M — an underground restaurant near the main square. Get the Khurjin (meat, cheese and mushrooms wrapped in lavash tied in a knot) ATTRACTIONS 1 Vardanants Square 2 St. All Saviors Church 3 Holy Mother Cathedral 4 Abovyan Street 5 Rijkov Walking Street 6 Gyumri Market 7 Mother Armenia of Gyumri 8 Black Circular Fortress RESTAURANTS & BARS 9 KTOR M ARMENIA Gyumri Touch to explore Double-tap to open in Google Maps Other Places to Consider Tatev — recommended by my walking tour guide as the most beautiful region in Armenia. Famous Tatev Monastery and great hiking. 8 hours from Yerevan — worth spending more than a day Dilijan — a small classic village near Lake Sevan. I've heard mixed reviews Alaverdi — a small old Soviet mining town on the border with Georgia. Popular stop on the way from Georgia for monasteries or people interested in abandoned Soviet factories"},{"url":"australia/field-notes.html","title":"Australia Travel Guide","text":"Australia Travel Guide General Australia is a continent in itself and it would take a full year to explore the all the highlights. The country's east coast is one of the world's great backpacker trails and a great place to spend your first time in the country. It is a 2,500km trail starting with the tropical rainforests and the Great Barrier Reef in the far north down through surf towns, island beaches and big harbor cities. It's expensive and vast, but the payoff is enormous: reef, rainforest, white-silica beaches and an incredible social scene at nearly every stop. I'll cover my two month long trip down the country's east coast, north to south down the coast: Cairns , Airlie Beach (the Whitsundays), Noosa , Brisbane , the Gold Coast , Byron Bay and Sydney , with a final trip south to Melbourne . If you don't have as much time and just want to cover the highlights, I'd recommend spending at least 2 weeks covering Cairns (Tropical North), Airlie Beach (the Whitsundays & Great Barrier Reef) and Sydney . Suggested Route Overview Getting around — distances in Australia are vast unlike anywhere else that I've been, expect long 8 - 12 hour car rides or short flights between destinations. Budget enough time in each location and full travel days in between cities The route — the classic east-coast route is Cairns → Airlie Beach (Whitsundays) → K'Gari (Fraser Island) → Brisbane → Gold Coast → Byron Bay → Sydney → Melbourne. Many people also do this same route in reverse if you want to fly into Melbourne first Greyhound Bus Pass — the backpacker default is the Greyhound East Coast Whimit Pass . This is a hop-on/hop-off bus pass connects every major stop along the East Coast. You have unlimited travel along the East Coast for 7, 15, 21 or 30 days. You'll have the flexibility of booking last minute, skipping the long distances drives and taking overnight legs save time During summer months (December to February), you'll have to book at least a few days in advance since the popular route on buses often book out. Unlike the Greyhound in the U.S., the buses are clean and mostly full of backpackers Flights — for the longer trips and to save time, flights are best way to get between cities, budget carriers like Jetstar and Virgin are the best options Campervan / Car — hugely popular for the flexibility, especially if you're chasing beaches and national parks off the bus route Money — the official currency is the Australian dollar (AUD). It's a genuinely expensive country. Food, drinks, accommodation and tours add up fast Food & coffee — Australian food is diverse and multicultural (the Asian food was especially good). The highlights for me were the Aussie pies! You'll find these everywhere and they are cheap, filling and delicious. Australians also take their coffee seriously so you'll find some world-class brews in every city The Backpacker Crowd — the backpacker crows in hostels are filled with Europeans on their working-holiday visa. Be prepared to hangout with 90% British people! There are also a lot of other European backpackers like the Irish, Germans and Dutch. It makes for a great, easy social scene almost everywhere Cairns 4–5 days recommended Cairns was one of my favorite cities in Australia. It is located in the Tropical North of Queensland and the usual starting point for the coast. It is a good base to visit the Great Barrier Reef , the ancient Daintree Rainforest (the world's oldest forest) and some incredible waterfalls. It's close to the equator so expect hot and humid weather. Remember the saying: everything in Australia wants to kill you! You can't swim at most beaches in tropical Queensland because of saltwater crocodiles and from November to April there are box jellyfish in the water so you'll need a stinger suit in the open ocean up north. What to Do Fitzroy Island (Day Trip) — take a 45-minute catamaran to the gorgeous Fitzroy island, covered in jungle and embedded right in the Great Barrier Reef. Walk 1km from the port through the jungle to Nudey Beach . It is rated as one of Australia's best beaches with has crystal water and lots of coral-boulders (fun fact: it's actually the cover photo for this website too!). I had it all to myself which was absolutely incredible and a great place to eat lunch while you watch the waves crash. Expect to spend the full day at Fitzroy Island before taking the ferry back to Cairns There is also a the steep 2.4mi or 4km hike to the peak where you'll have a full 360° view of the island and surrounding reef. Here is the link to the AllTrails route Daintree Rainforest & Cape Tribulation (Day Trip) — take a day tour into the oldest rainforest on earth dating back 180 million years. The first stop is the Daintree River crocodile cruise through the mangroves where you'll see fresh water crocodiles and spitting archer fish. The tour then goes on to where the forest meets the reef at Cape Tribulation and you do a short a rainforest walk among prehistoric fan palms and a Mossman Gorge stop. Finally, we stopped at an Aboriginal culture center and watched an Aboriginal smoke ceremony. Here was the tour that I booked with active tropics explorer Reef Scenic flight — a highlight of Cairns is absolutely the a flight in a small propeller plane over the Great Barrier Reef. The total flight takes 30–45 minutes and you'll fly over some gorgeous coral cays and Green Island . It is a bit expensive, but genuinely one of the best things to do in Cairns. Book ahead here Great Barrier Reef snorkeling day tour — one of the main reasons to visit Australia was to snorkel in the Great Barrier Reef . Boats run daily out to the outer reef for snorkeling or diving among coral and turtles. I would recommend waiting to snorkel if you do the Whitsundays cruise (you'll have 3 days of snorkeling). However, Cairns is a perfect good place to snorkel the Great Barrier Reef Cairns Esplanade Lagoon — you can't swim near the shore in Cairns due to the salt-water crocs and box jellyfish. There is free public swimming lagoon right on the waterfront, a great place to relax and have an easy day Walk the Esplanade — if you have extra time, Cairns has a gorgeous esplanade that you can walk or run down. The marshes are right by here so you might be able to spot some unique wildlife Cairns Night Market — one of Australia's largest night markets with street food stalls and lots of little vendors selling souvenirs. A fun place to visit for an hour at night, but not a must while in Cairns Where to Eat The Roti Shack — a small low-key Caribbean place that served one of the most incredible wraps I've ever had. Highly recommend Perrotta's at the Gallery — an upscale café on the esplanade. The brunch here is great 3 Black Bears Pizza — a solid late-night option for pizza Nightlife Gilligan's — a hostel with a club inside and the main place for backpackers to gather in Cairns. I ended up staying there too which I'll talk about in the Where to Stay section Salt House — a fancy restaurant that turns into an outdoor bar at night. One of the best places to go in the city and they have great discounts on hospitality night Where to Stay Gilligan's — a hostel with a club inside that has an infamous reputation in Australia. I ended up staying here and it was the main backpacker nightlife hub in Cairns. There is a pool and outdoor area. It was a great place to meet people in party, but be warned that it is pretty loud at night if you want to sleep ATTRACTIONS 1 Cairns Esplanade Lagoon 2 Cairns Night Market RESTAURANTS & BARS 3 The Roti Shack 4 Perrotta's at the Gallery 5 Salt House ACCOMMODATION 6 Gilligan's DAY TRIPS ↗ Fitzroy Island (Full Day) ↗ Daintree Rainforest & Cape Tribulation (Full Day) ↗ Reef Scenic Flight (Half Day) ↗ Great Barrier Reef Snorkeling (Full Day) AUSTRALIA Cairns Touch to explore Double-tap to open in Google Maps Airlie Beach & the Whitsundays 3–4 days recommended Airlie Beach is a small, lively resort town and the gateway to the Whitsunday Islands just offshore: 74 islands ringed by the reef and home to what might be the most beautiful beach on the planet. The town itself is tiny and only worth spending one-night-before and one-night-after the sailing trip. What to Do Whitsundays Sailing Trip (2–3 nights) — this was the highlight of the entire east coast. You live aboard a small sailboat with 20–30 other people. You sail off around the Whitsunday Islands , stopping in random spots to snorkel in the Great Barrier Reef (fish, parrotfish, turtles) and swim off the boat. At night, dozens of reef sharks circle the boat making for a magical experience. There are many boats that all run similar routes, but make sure to book one that stops at Whitehaven Beach I booked a 2 night experience (link here ) on a boat called the spankme ( it's a sailing joke ). I met some amazing people and the experience was incredible, but the bunks and food on board were not the greatest. Expect to pay ~$350 to $400 for a 2 night sail Whitehaven Beach — the most incredible beach I've seen in the world. Only reachable only by boat, Whitehaven Beach beach is a 7km beach made up of pure silica sand so fine it squeaks. From the Hill Inlet lookout above it, the white sand swirls through turquoise water making for an iconic view. On our overnight tour, we were the first people there at 7am Reef Scenic Flight — the Whitsundays version of the scenic flight is reportedly even better than the one in Cairns because you fly over both Heart Reef and Whitehaven Beach. Expect it to cost ~$200 Airlie Beach Lagoon — the free waterfront swimming lagoon in town. A good place to relax for an afternoon Boathaven Beach — a quiet secluded beach right outside of town where you can swim in protected areas in the ocean Where to Eat & Drink The Boat House (Boaty's) — a restaurant that serves great burgers and brunch Paddy's Shenanigans Irish Bar — for the night after your sail, you'll likely end up here with your newfound sailing buddies. It is a classic Irish bar that makes for a fun night Where to Stay Nomads Airlie Beach — a no-frills hostel that has a pool and huge courtyard to hangout at. RV and campervans are also allowed here. They offer luggage storage which is useful for items you don't want to bring on the sail ATTRACTIONS 1 Airlie Beach Lagoon 2 Boathaven Beach RESTAURANTS & BARS 3 The Boat House (Boaty's) 4 Paddy's Shenanigans Irish Bar ACCOMMODATION 5 Nomads Airlie Beach MULTI-DAY TRIP ↗ Whitsundays Sailing Trip (2–3 nights) DAY TRIPS ↗ Whitehaven Beach (Full Day) ↗ Reef Scenic Flight (Half Day) AUSTRALIA Airlie Beach Touch to explore Double-tap to open in Google Maps K'gari (Fraser Island) 3–4 days recommended K'gari is the world's largest sand island, reached by vehicle ferry from Rainbow Beach (a small, quiet town between the larger town of Noosa and the island). There are no sealed roads on the island: it's all soft sand tracks, and a stretch of open beach doubles as the main highway. Book a 2 to 3 day 4WD tour with camping to fully experience the island. The island is very untouched and be prepared to drive on soft sand and be surrounded by Dingos at night! What to Do Rainbow Beach — a very sleepy town that is mainly a stopover the night before the K'gari island tour starts Carlo Sand Blow — massive sand dunes located a short walk away from town. The path goes through a residential neighborhood and then the forest. You'll walk out onto vast sand dunes. It was an amazing place to watch the sun set Rainbow Beach Lookout — the best viewpoint in town over the main beach and popular surf spot Rainbow Beach Surf Life Saving Club — a lifeguard club that doubles as a restaurant and bar with an amazing view 4WD Tag-Along Camping Tour — the best way to see the island and many backpacker's favorite experience while in Australia. A couple of companies run these 2 to 3 day trips: you travel in a small convoy of 4WDs with about 8 people per vehicle, taking turns driving as you follow the guide's lead vehicle across the sand. On the first day, you cross from Rainbow Beach to K'gari on the vehicle ferry and camp on the island each night. Here's roughly how a 3-day trip breaks down: Day 1 — cross on the ferry and drop down onto 75 Mile Beach , the sand \"highway\" that runs the length of the island (small planes occasionally land on it) Drive north up the beach and stop at Eli Creek , a shallow, crystal-clear freshwater creek running right off the beach. Grab a pool float or tube and drift down it, then walk back and do it again Stop by the S.S. Maheno shipwreck on the side of the highway. The boat was stranded here in 1935 from a cyclone. At low tide, you can walk right up to it since there are no guardrails Carry on to the northern end for the Champagne Pools , natural rock pools at the ocean's edge that fizz as the waves break over them and the only spot on the island where it's actually safe to swim in the sea. We then set up camp for the night, ringed by an electric dingo fence Day 2 — head inland on the soft sand tracks to Lake McKenzie , a perched freshwater lake with blindingly white silica sand and clear, deep-blue water. It's the best swimming spot on the island and well worth the bumpy drive in. Spend the day around the lakes and rainforest before a second night at camp Day 3 — a final stretch of beach driving and any last stops before catching the ferry back to Rainbow Beach. Watch for wild dingoes trotting along the shoreline the whole trip, and carry a stick if you walk around camp after dark Where to Stay Freedom Hostels Rainbow Beach — a no-frills hostel located in Rainbow Beach. I ended up meeting other backpackers also on my tour the night before ATTRACTIONS 1 Carlo Sand Blow 2 Rainbow Beach Lookout 3 Rainbow Beach Surf Club ACCOMMODATION 4 Freedom Hostels MULTI-DAY TRIP ↗ 4WD Tag-Along Camping Tour (2–3 days) AUSTRALIA Rainbow Beach Touch to explore Double-tap to open in Google Maps Noosa 2–3 days recommended Noosa is the polished, upscale end of the Sunshine Coast. a small beach town of boutiques and good restaurants along Hastings Street that reminded me of Newport Beach in California, wrapped around a genuinely beautiful national park headland. Noosa is a relaxed, pretty and very walkable area, but it is very small. You can see the highlights in as little as a day, but I'd recommend 2–3 days especially if you plan to surf. What to Do Noosa National Park Coastal Walk — the best thing to do in Noosa is a ~3-hour loop along the headland from the main beach out to Sunshine Beach , hugging the cliffs the whole way ( alltrails link ). Highlights along the path include: Boiling Pot Lookout & Dolphin Point — clifftop lookouts over the surf breaks. Far from the main beach, watch for advanced surfers surfing massive waves below. You can also spot dolphins and whales from the cliff-side so bring binoculars if you have them Hell's Gates — dramatic jagged rock formations where the deep-blue tides crash in. The most striking stretch of the walk and a great place to stop for lunch and watch the waves crash Fairy Pools — clear tidal rock pools you can sit in as the waves crash around them. It is a fun place for a quick swim, but gets very crowded since the pools are very small Alexandria Bay — a long, wild, mostly empty beach on the far side of the headland, before the path climbs to Sunshine Beach. It is unofficially a nudist beach and I found out by surprise Sunshine Beach — the walk culminates when you reach a hill overlooking the Sunshine Beach. There is an incredible view here and the long sandy Sunshine Beach stretches for miles Hastings Street & Main Beach — the fancy shopping-and-dining strip opening right onto the main beach, which is packed with learner surfers even on a weekday. This is a very nice area to walk around, do some shopping or grab a bite. It is a popular summer vacation spot for wealthy Australians Noosa Spit — a quiet protected park at the point where the Noosa River meets the sea. There is a small forest here and it is good for a stroll. It is the gateway to the Noosa Everglades upriver where you can do watersports or a kayaking tour Surfing in Noosa — perhaps the town's biggest draw. The sheltered point breaks inside Noosa National Park offer some of Australia's longest, most forgiving waves, making them perfect for beginners, long boarders, and anyone looking for a relaxed surf. Where to Eat & Drink Hastings Street — the town's restaurants and cafés cluster here. Wander along the strip until you find a good restaurant to stop at Where to Stay Bounce Noosa — a beautiful, clean hostel with a pool, bar and very comfortable bunks. The only downside is that Bounce is located out in Noosaville which is far away from the center of town in Hastings Street (closer to the beach and the national park) ATTRACTIONS 1 Hastings Street 2 Sunshine Beach 3 Dolphin Point 4 Hell's Gates 5 Fairy Pools 6 Alexandria Bay 7 Noosa Spit 8 Noosa National Park ACCOMMODATION 9 Bounce Noosa DAY TRIPS ↗ Noosa Everglades (Half Day) AUSTRALIA Noosa Touch to explore Double-tap to open in Google Maps Brisbane 2 days recommended Brisbane is Queensland's relaxed river-city capital: more of a transit and logistics hub than a headline destination. It is famously and ironically called \"Bris-vegas\" by Aussies due to how boring it is. However, a pleasant couple of days built around its riverfront cultural precinct and the best place to hug a koala! What to Do South Bank Parklands — a massive riverfront park across from downtown Brisbane, with Streets Beach a manmade city beach and lagoon, a riverside walk and the Nepal Peace Pagoda , a carved wooden pagoda from the 1988 World Expo Gallery of Modern Art (GOMA) — a large, free contemporary-art museum right on South Bank with a great collection of Modern Art Lone Pine Koala Sanctuary — a short trip from the city where you can actually hold a koala and hand-feed kangaroos. It was a unforgettable experience in Australia and amazing to be so up close and personal with these animals. I bought some lovely photos holding a Koala and the proceeds go to funding wildlife rescue missions Australia Zoo — Steve Irwin's famous zoo, about an hour north toward the Sunshine Coast. It is considered one of the best zoos in Australia. Fun fact: the Irwin family is basically Australia's royal family. His kids are mini-celebrities Story Bridge & Kangaroo Point Cliffs — walk or climb the landmark bridge and wander the riverside cliffs opposite the city for the classic Brisbane skyline view. You can also hop across the river on the free CityHopper ferry Wildlands Brisbane — if you happen to be in Brisbane during New Years, I highly recommend going to Wildlands Brisbane . They have some amazing world-class acts and it was a great way to experience the Australian festival scene. I went in 2023 and I saw Rufus du Sol, Peggy Gou and Dimension. Where to Eat & Drink The South Bank and West End areas have the best cafés and restaurants Roamer Brisbane Bar & Cafe — a trendy café right below the Selina hostel. The coffee and breakfast options here are great AJ's Noodle House — a good casual Vietnamese dinner spot New Season Thai — a modern Thai restaurant in the city center. the ground basil chicken is excellent and genuinely spicy Felons Brewing Co — the most famous and popular brewery in Brisbane located right along the river Where to Stay Roamer Brisbane — formerly a Selina hostel location, it is a polished, upscale hostel with very comfortable beds. They have a festival-style wristband check-in and it is a short walk from South Bank, the river and the free CityHopper ferry. There were almost no other backpackers here when I was there so I had it all to myself Summer House Backpackers Brisbane — I stayed here around New Years and all other hostels were booked out. It was a bit messy when I was there (possibly just my dormmates), but I generally wouldn't recommend it due to location and cleanliness ATTRACTIONS 1 South Bank Parklands 2 Streets Beach 3 Gallery of Modern Art 4 Story Bridge 5 Kangaroo Point Cliffs RESTAURANTS & BARS 6 AJ's Noodle House 7 Felons Brewing Co ACCOMMODATION 8 Roamer Brisbane DAY TRIPS ↗ Australia Zoo (Full Day) ↗ Lone Pine Koala Sanctuary (Half Day) AUSTRALIA Brisbane Touch to explore Double-tap to open in Google Maps Gold Coast 2 days recommended The Gold Coast is Australia's answer to Miami: a wall of high-rises behind an endless run of surf beaches. The city is brash and touristy at its center, but with genuinely lovely headlands and beaches. I would recommend spending 2 days here to explore. What to Do Surfers Paradise — this is the neon main strip with lots of surf shops and bars with a broad beach backed by skyscrapers. This is a popular spot for young Aussies to go on spring break so it is a bit of a younger crowd SkyPoint Observation Deck — the observation deck near the top of the Q1 Tower , one of the tallest towers in the southern hemisphere. Go up to the top of this building for a sweeping view of the entirety of the Gold Coast Burleigh Heads — the best stretch of the Gold Coast: a wide white-sand beach with the Surfers skyline framed in the distance. Grab a bike (you can rent an e-bike with the lime app) from Surfers Paradise and cruise along the beach front path to Burleigh Heads The beachfront Burleigh Pavilion is one of the best places to grab a drink and a meal. There is a gorgeous view from inside of the long coastline and towers. The short Burleigh Head National Park headland walk is also worth it. There is a lookout over both sides of the point Currumbin Wildlife Sanctuary — a popular wildlife park to visit south of Burleigh. It is a good stop for koalas, kangaroos and the lorikeet feeding if you haven't done that elsewhere in Australia Where to Eat & Drink Burleigh Pavilion — right on the sand at Burleigh Heads , with big windows opening onto the beach and a beautiful view of the Surfers skyline. It was one of the best beachfront meals on the coast Greek on Soul — a nice Greek restaurant on the Surfer's Paradise promenade Fishbowl — a solid poke bowl spot in Surfer's Paradise, good for a healthy lunch between beach days Where to Stay The backpacker hostels are mostly located in Surfers Paradise near the strip and the beach. Surfers Paradise is a bit rowdy, but the best place to stay as most activities will be walking distance from your accommodation Budds In Surfers — a really fun hostel located just 100 meters from the beach and walking distance from downtown Surfers Paradise . It was very relaxing by the pool during the day and a fun social vibe at night. The staff had their annual party while I was there so there was a pool party ATTRACTIONS 1 Q1 Tower 2 Burleigh Pavilion 3 Burleigh Head National Park 4 Currumbin Wildlife Sanctuary RESTAURANTS & BARS 5 Greek on Soul ACCOMMODATION 6 Budds In Surfers AUSTRALIA Gold Coast Touch to explore Double-tap to open in Google Maps Byron Bay 2–3 days recommended Byron Bay is the laid-back, slightly hippie heart of the coast. It is a surf-and-wellness town that's alternative in spirit, but clean, pretty and family-friendly in practice. It sits at the most easterly point of mainland Australia, which makes for a spectacular sunrise walk. I would recommend 2 to 3 days in Byron Bay. It is a relaxing place where you could spend a whole week if you like surfing and yoga. It was a welcome change after the intensity of Surfers Paradise . What to Do The Downtown — Byron Bay has a very cute downtown with lots of little shops and restaurants. It was fun area to walk around in Beaches — the town of Byron Bay lies directly on the Main Beach . This is where most of the town gathers. The beach stretches for miles so it is a good place for beach side walk The Pass is the famous longboard surf break Wategos Beach is the pretty, sheltered cove beneath the lighthouse If you happen to be in Byron Bay during Christmas (like I was), the beach fills up with people in Santa Hats and red swim suits. Have morning swim or a picnic here and enjoy the warm Australian Christmas Cape Byron Lighthouse walk — one of the best walks in Byron Bay. It is the coastal track up to the lighthouse and the Most Easterly Point of Australia marker. Do it for sunrise (on a clear morning) and watch for dolphins in the bay below and migrating whales if you're lucky Kayak with Dolphins — a popular guided tour into the bay. Byron is one of the best spots to see dolphins up close. You can book a tour here Byron Bay Markets — the monthly market (plus a weekly farmers' market) is the town in a nutshell with crafts, food trucks, live music and vintage clothing Bangalow — an artsy village east of Byron Bay if you want to dive deeper into the Byron alternative scene. It is also home to the Bangalow Markets which are a bigger, quieter version of the Byron ones Where to Eat & Drink Byron Hot Bread Bakery — a good, cheap bakery for breakfast. They have an amazing a sausage roll and a meat pie for a snack on the way to the beach on the way to the beach Bay Leaf Cafe — a hip, popular brunch spot in town. The cold brew and an egg-and-greens toast were a great choice The Northern — the most popular spot in town and a really fun piano bar. Get in line early as the place fills up. One of the best nights out in Byron Where to Stay Wake Up! Byron Bay — a brand new hostel with amazing facilities and a great social atmosphere. It is located a bit far out of town so either walk along the beach or take the free shuttle into town The Surf House — if you're looking for a more central location that is walkable from downtown, I would recommend The Surf House . My friends stayed here and had a great experience. Unsurprisingly, most of the crowd here is focused on surfing ATTRACTIONS 1 Main Beach 2 The Pass 3 Wategos Beach 4 Cape Byron Lighthouse walk 5 Byron Bay Markets RESTAURANTS & BARS 6 Byron Hot Bread Bakery 7 Bay Leaf Cafe 8 The Northern ACCOMMODATION 9 Wake Up! Byron Bay DAY TRIPS ↗ Bangalow (Half Day) AUSTRALIA Byron Bay Touch to explore Double-tap to open in Google Maps Sydney 4–5 days recommended Sydney is the perfect finale to Australia's east coast: a city where iconic landmarks, golden beaches, and one of the world's most beautiful harbors all sit within easy reach of one another. Spend your days walking the spectacular coastline, surfing at Bondi, cruising the harbor, and exploring neighborhoods that make it easy to see why Sydney consistently ranks among the world's most livable cities. I would recommend spending 4 to 5 days to fully soak in the city beyond just the Opera House. After spending a week in Sydney , I considered even moving here, but that's a different story... What to Do Sydney Opera House & Sydney Harbour Bridge — the iconic landmarks of Sydney. You can visit the Sydney Opera House itself or head to Mrs Macquarie's Chair for the best spot to photograph the Opera House with the bridge behind it. On New Years Eve, Sydney is home to one of the best fireworks shows with fireworks coming out of the Sydney Harbour Bridge Coogee to Bondi Coastal Walk — this was my favorite activity in Sydney. Start by taking a bus down to Coogee Beach on the southeast coast of the city. You then walk ~8mi or ~13km north along the cliffs, passing Gordons Bay (a secluded cove) and Bronte Beach (the most photogenic, with a tidal pool) before ending at Bondi Beach . The walk is paved and very easy to navigate. Here is the AllTrails link Reward yourself with a drink at where the Bondi Icebergs saltwater pool is the classic photo. The whole hike will take roughly 3 to 3.5 hours to complete Taronga Zoo — the best zoo in Australia right across the harbor from the Opera House. Take the ferry from Circular Quay . You'll the ride past the Opera House which in itself is worth it alone. You then arrive at the massive Taronga Zoo , divided into sections by origin of species. The Australian section is the highlight: koalas, kangaroos and wallabies in walk-through enclosures, and tiny fairy penguins native to the harbor. If you're interested in the koala encounter, book the well in advance as it fills up quick! Manly Beach — a famous beach suburb reached by a scenic harbor ferry. It is a completely different vibe from both the downtown and the more famous Bondi Beach . It is a great half-day with its own beach and oceanfront walk The Rocks — a small historic neighborhood located nearby Sydney Opera House .There are cobble stone streets and lots of signs explaining Sydney's early history (with a small free museum of the city's history). Definitely worth a quick stop Museum of Sydney — a small, free museum on the site of the first Government House. It covers the founding of the colony and the story of Bennelong, the Aboriginal man taken in by the first governor to bridge the two cultures Chinatown Sydney — Sydney is home to the largest Chinatown in Oceania with some very good, authentic food. Every Friday from 4 PM to 11 PM, there is a night market which is a fun place to walk around and try street foods from the stalls Blue Mountains day trip — located just 90 minutes from Sydney, you can take a day trip out of the city into the Blue Mountains , known for its eucalyptus-forested canyons and clifftop lookouts. I didn't get to it, but it comes highly recommended from other travelers Where to Eat & Drink The Fine Food Store (The Rocks) — a good brunch stop while exploring the historic quarter; the croque madame and a cold brew hit the spot Gelato Messina (Bondi) — a Sydney institution and worth the stop after the coastal walk Manly Wharf (Manly) — grab fish, chips, calamari and crab sticks from the fish market by the wharf and eat it looking back across the harbor before the ferry home Where to Stay Mad Monkey Potts Point — this hostel was much more run down than most of the hostels I stayed in. However, there is a good location and it is an easy walk to the CBD, the Opera House and the botanical garden from here ATTRACTIONS 1 Sydney Opera House 2 Sydney Harbour Bridge 3 Coogee Beach 4 Bronte Beach 5 Bondi Beach 6 Taronga Zoo 7 Manly Beach 8 Chinatown Sydney RESTAURANTS & BARS 9 The Fine Food Store 10 Manly Wharf ACCOMMODATION 11 Mad Monkey Potts Point DAY TRIPS ↗ Blue Mountains (Full Day) AUSTRALIA Sydney Touch to explore Double-tap to open in Google Maps Melbourne 4–5 days recommended Melbourne feels like Australia's cultural capital. While it lacks Sydney's famous harbor and beaches, it more than makes up for it with hidden laneways, exceptional cafés, world-class restaurants, live sportd, and a thriving arts scene. It's a city best explored without an itinerary, and the perfect base for a trip along the spectacular Great Ocean Road. For first-timers, I spend 4 to 5 days to explore the city at a comfortable pace. On my travels, Melbourne felt like the place the most similar to my native California. Maybe after you'll be able to decide the age old rivalry for yourself: is Melbourne or Sydney better? What to Do Downtown Melbourne Queen Victoria Market — a huge, historic food market. A great stop for dinner and you can do a loop of the food stalls. I ended up going here multiple days since it was close to where I was staying Degraves Street — Melbourne is home to the unique laneway culture with narrow alleys strung with lights and packed with outdoor café tables. Degraves Street is the most impressive example and is located right by the main train station Hosier Lane — the famous graffiti alley. It is small and touristy, but worth a quick look on the way to Federation Square The Lume — an immersive digital art museum at the convention center. The exhibit I saw was built entirely around Aboriginal art and dance, projected floor-to-ceiling and synced to music. Genuinely impressive, not what I expected going in and definitely worth a stop Southbank Promenade — a nice area along the river where you can walk for miles. There is a little strip of restaurants here serving seafood as well Melbourne Skydeck (Eureka Tower) — the tallest observation deck in the Southern Hemisphere and worth doing if you're curious. However, I found the view less impressive view than Q1 on the Gold Coast since Melbourne's skyline is less distinct from above Fitzroy — the hip inner-city neighborhood for a night out: bars, street art and rooftop spots like Naked for Satan , a multi-story bar with a Brooklyn-style rooftop and city views Brighton Bathing Boxes — a line of about 100 small, brightly painted beach sheds on a quiet beach an hour out of the city by train. It is an iconic photo stop for Melbourne. St Kilda — the great beachside neighborhood for sunset and dinner. It has a large strip of restaurants, shops and you can wander around the beach in this area Great Ocean Road (Day Tour) — a popular, full-day tour from the city of Melbourne if you don't want to rent a car. The road follows the Southern Coastline of Australia and has some beautiful scenery including The Twelve Apostles . You can book the tour that I took here Kennett River — a short strip of road with a very high koala population. It is relatively easy to see one in the wild if you look very high up in the Eucalyptus trees The Twelve Apostles — the iconic sea stacks and the reason most people do this drive. The beach view and the clifftop viewpoint both show different sides of them so make sure you visit them both Loch Ard Gorge — a dramatic gorge in the same national park, with a thin orange sea stack called the Razorback and a shipwreck-survivor love story that the tour guides love to tell Apollo Bay Bakery — the classic lunch stop on the drive. Get a meat pie or a sausage roll for the road. They are famous for their seafood pies which you won't find elsewhere in Australia Melbourne Cricket Ground (MCG) — one of the largest stadiums in the world and home to the local AFL team. AFL (also known as \"Aussie Rules Football\") is the most popular sport in Australia and a high-paced, chaotic game that is fun to watch. Depending on the season, you can catch an AFL or Cricket match here. I went to a Cricket match here and it was a great way to spend an evening even if you don't know the rules going in Where to Eat & Drink Max on Hardware — a great Italian restaurant. I decided to be adventurous and try the Kangaroo. It was prepared as a tender steak lathered in gravy and it reminded me a bit of Kobe beef Schmucks Bagels — a good bagel shop; the cream cheese and Vegemite bagel is a very Melbourne thing to order Degraves Street cafés — pick any of the laneway spots for a coffee or a casual lunch; the moussaka at Euro Lane Cafe was a good order HER — an upscale bar in Melbourne. It has an artsy retro feel to it on the inside and a large outdoor rooftop Ponyfish Island — a small bar located near the Southbank Promenade . You can reach it by bridge and the whole bar lies on it's own island in the middle of the river. A fun spot to grab a drink and relax near the water Where to Stay Base yourself in the CBD near Queen Victoria Market , an easy tram ride or walk to Federation Square, the river, Fitzroy and the trains out to the farther parts like Brighton and the MCG Little Drifter Melbourne — I stayed in this hostel located right next to Queen Victoria Market. It had a large common area and was very social ATTRACTIONS 1 Queen Victoria Market 2 Degraves Street 3 Hosier Lane 4 Federation Square 5 Southbank Promenade 6 Melbourne Skydeck 7 Fitzroy 8 Naked for Satan 9 St Kilda 10 Melbourne Cricket Ground RESTAURANTS & BARS 11 Max on Hardware 12 Schmucks Bagels 13 Euro Lane Cafe 14 HER 16 Ponyfish Island ACCOMMODATION 15 Little Drifter Melbourne DAY TRIPS ↗ Great Ocean Road (Full Day) AUSTRALIA Melbourne Touch to explore Double-tap to open in Google Maps Other Places to Consider These notes cover the east-coast run and Melbourne, but Australia is enormous. There are plenty more destinations and I definitely plan to make another lengthy trip to explore: Darwin — Australia's tropical northern city and gateway to the Top End, best known for its laid-back atmosphere, spectacular sunsets, and easy access to Kakadu and Litchfield National Parks. Visit Crocosaurus Cove and swim with the behemoth saltwater crocodile Western Australia — Australia's vast and least-visited state, home to remote beaches, world-class coral reefs, dramatic gorges, and some of the country's most unforgettable road trips Perth — Western Australia's isolated capital and one of the most remote major cities in the world, separated from the east coast by a five-hour flight. With pristine beaches, sunny weather, and a relaxed lifestyle, it feels like a completely different side of Australia Esperance — famous for impossibly white sand, turquoise water, and Cape Le Grand National Park , where kangaroos regularly lounge on the beach Broome — a remote tropical town known for Cable Beach , camel rides at sunset, dinosaur footprints, and the striking red cliffs of the Kimberley coastline Uluru & the Outback — the famous Australian Outback where the iconic sandstone monolith rises from the vast desert landscape. It's a completely different Australia from the lush east coast and one of the country's most unforgettable experiences Tasmania — Australia's wild island state, renowned for dramatic hiking in Cradle Mountain-Lake St Clair National Park , exceptional fresh seafood, rugged coastlines, and the world-famous MONA museum in Hobart"},{"url":"belgium/field-notes.html","title":"Belgium Travel Guide","text":"Belgium Travel Guide General Belgium is one of the countries that surprised me the most in Europe. After having visited the Netherlands and France, I had low expectations for Belgium which were completely blown out of the water. Belgium is a tiny country sandwiched between the Netherlands, France and Germany that is divided into two distinct regions: the Dutch-speaking Flanders in the North and the French-speaking Wallonia in the South. It is extremely easy to get around due to its size and extensive train network. You can see the highlights in under a week without ever renting a car. Prepare to be amazed by the immaculate medieval cities, the best beer and chocolate in the world, and (in my case) the biggest music festival on the planet. I would recommend spending 5 to 7 days in Belgium to see the highlights. The cities are compact and close enough that you can base yourself in one and day-trip to the rest. Suggested Route Overview Getting around Trains — Belgium is tiny and only takes around 3 hours to drive from end-to-end. The size of the country and the excellent rail network makes nearly every city under an hour apart. Additionally, there are also international trains that connect Belgium to neighboring countries like the Netherlands (Amsterdam is about two hours from Brussels by direct train), France and Germany Flights — if you're coming by plane, you'll likely fly into Brussels Airport which is one of the busiest airports in all of Europe Money — the Euro is the official currency. I found Belgium to be mid-priced for Western Europe and prices were largely in-line with its neighbors France & Germany Food & Beer — Belgian food is insanely underrated. I mean who doesn't like fries, chocolate and beer?? The food was surprisingly good and was a genuine highlight for me. Although the cuisine is familiar, don't forget to try: the waffles (both the fluffy sugar-studded Liège waffle and the crisp rectangular Brussels waffle), Belgian fries (French fries were actually invented in Belgium), a pot of mussels, stoofvlees (tender beef stewed in dark beer) and some of the best chocolate on earth. Don't forget the beer! Belgium had some of the widest variety of beer that I had ever seen, from Trappist ales brewed by monks to sour lambics, each poured in its own branded glass. One of the bars I went to in Bruges called 2be Shop , offered more than 1,000 Belgian beers Language — Linguistically, Belgium is a unique country with two widely spoken official languages: Dutch (Flemish) in the north (Ghent, Bruges, Antwerp), French in the south and both languages in Brussels. English is very widely spoken so you'll have no trouble getting around Brussels 1 to 2 days recommended Brussels is the compact, slightly quirky capital, anchored by one of the grandest squares in Europe and full of beer, chocolate and comic-book history. It gets a bit overshadowed by the prettier canal cities, but it's worth a day or two and makes an easy base for day trips to Ghent and Bruges. Brussels has a slightly rough, workaday edge next to the fairytale Flemish towns, but it's central, well-connected and cheaper, which makes it a practical hub for the whole country What to Do Grand-Place — Brussels' breathtaking central square and one of the most beautiful in Europe. The compact square is surrounded by some of the most intricate and ornate architecture that I saw in Europe. The highlights are the Gothic and Baroque guildhalls and the soaring Town Hall. It can get very busy during the day so visit early in the morning or after dark to experience it without the crowds The main attraction was the magnificent facades of the buildings surrounding the square. You can also visit inside at the Brussels Town Hall or many museums located on Grand-Place like the Brussels City Museum or Belgian Brewers Museum Manneken Pis & friends — yes, one of the most famous things to do in Brussels is a tiny statue of a peeing boy. The Belgians have a unique sense of humor and it is hilariously anticlimactic. The area is usually packed and he is often dressed in one of his hundreds of costumes. Make it into a full scavenger hunt and track down his lesser-known friends, a peeing girl ( Jeanneke Pis ) and a peeing dog ( Zinneke Pis ) around the town center Belgium is the home of the comic strip and the birthplace of beloved comic characters like Tintin, The Smurfs, and Lucky Luke. It's woven right into the city on giant comic murals you'll spot on walls all over the center. There are quite a few places celebrating the iconic character around the city that you can visit: Belgian Comic Strip Center — nowhere celebrates that legacy better than this museum, housed in a beautiful Art Nouveau building designed by Victor Horta. It's an excellent introduction to Belgium's comic culture and artistic heritage. The House of Comics — a small, free gallery and shop near the Grand-Place showcasing original comic artwork, figurines, and prints. It's a quick and worthwhile stop that complements the nearby Comic Strip Center The Tintin shop — the official Tintin store, filled with books, collectibles, and memorabilia celebrating Belgium's most famous comic hero. If you grew up reading Tintin comics like me, this is an absolute must when you're in Brussels Tintin Comic Mural — one of more than 50 comic murals scattered across Brussels, depicting Tintin, Snowy, and Captain Haddock climbing down a fire escape. Hunting down these murals is a fun way to spend the afternoon Smurfs Passage — a colorful covered walkway celebrating the Smurfs, created by Belgian cartoonist Peyo in 1958. It's a quick detour near Brussels Central Station and part of the city's comic mural trail. St Michael & St Gudula Cathedral — Brussels' magnificent Gothic cathedral, known for its soaring twin towers, impressive stained-glass windows, and peaceful interior. Just a short walk uphill from the Grand-Place , it's a welcome escape from the crowds below Where to Eat and Drink WAFFELIN — the waffle stand we kept going back to, just a block away from the Grand-Place . Order the Brussels waffle and get it loaded with a variety of toppings. It only cost a few euros and was genuinely one of the best things I ate on the whole trip Delirium Café — a sprawling multi-floor bar dedicated to the world-famous brewery Delirium (the pink elephant logo). It lies down a little alley right off the center of town and once held a world record for the most beers on tap (over 2,000). A rite of passage for a first Belgian beer night and the sheer selection of beer is fun to explore Where to Stay Base yourself near the Grand-Place : the center of Brussels is compact, so everything worth seeing is walkable, and you're minutes from the main stations for easy day trips out to Ghent and Bruges MEININGER Bruxelles City Center — a big, clean hostel-hotel hybrid that is about a fifteen minute walk from the Grand-Place. It offers private rooms and dorms, a proper breakfast buffet and a bar downstairs. The amenities were clean and it is very social without being a party hostel ATTRACTIONS 1 Grand-Place 2 Manneken Pis 3 Jeanneke Pis 4 Zinneke Pis 5 Belgian Comic Strip Center 6 The House of Comics 7 The Tintin Shop 8 Tintin Comic Mural 9 Smurfs Passage 10 St Michael & St Gudula Cathedral RESTAURANTS & BARS 11 WAFFELIN 12 Delirium Café ACCOMMODATION 13 MEININGER Brussels City Center Belgium Brussels Touch to explore Double-tap to open in Google Maps Ghent 2 day recommended Ghent is Belgium's hidden gem: a lively medieval canal city that combines all the architectural beauty of Bruges with a younger, more authentic atmosphere thanks to its large student population. Grand guildhalls, winding canals, and towering churches are balanced by buzzing cafés, bars, and a vibrant local scene, making it feel far less touristy than its famous neighbor. Ghent 's old town felt like a medieval town out of a fairytale. If you only have time for one of Belgium's historic canal cities, I'd recommend choosing Ghent over others . Better yet, almost all of the city's highlights are concentrated within the compact old town, making it easy to explore on foot in as little as 1 or 2 days . What to Do Old Town — Ghent's old town is centered around the canal. You can even plan your trip around the canal itself starting with: St Michael's Bridge — the single best vantage point in Ghent where in one spot you can see all three medieval towers ( St. Nicholas , the Belfry and St. Bavo ) line up behind the guild houses along the canal. It is absolutely breathtaking and the perfect place to get your bearings before moving on On both sides of the canal lay two famous streets named Graslei and Korenlei . These twin medieval streets face each other across the old harbor in the heart of Ghent. They are both lined with a gorgeous row of stepped-gable guild houses and reflect in the water The Towers of Ghent — once a booming trade hub in Western Europe due to its canals. Ghent had one of the best skylines in Europe for centuries. If you have time, I'd recommend exploring all the towers and be sure to climb to the top for some magnificent views of the city: Belfry of Ghent — the city's 14th-century medieval bell tower and one of Belgium's best belfries, crowned by its iconic gilded dragon. Take the elevator to the upper levels to see the historic carillon bells and the massive rotating drum that once controlled their melodies, then descend via the winding staircase while enjoying panoramic views over Ghent's medieval rooftops. Visit near the top of the hour to hear the bells ring Saint Bavo's Cathedral — Ghent's magnificent Gothic cathedral is home to the Ghent Altarpiece ( The Adoration of the Mystic Lamb ) which is considered one of the greatest masterpieces of the Northern Renaissance. It is also one of the most stolen works of art in history. It was famously stolen by the Nazis and recovered by the famous \"Monuments Men\" troop. Watch the 2014 movie with George Clooney and Matt Damon before you go! St. Nicholas' Cathedral — one of Ghent's oldest landmarks and the first of the city's famous Three Towers. It was financed by the powerful medieval merchant guilds and has a more understated interior than neighboring Saint Bavo's Cathedral . If you're trying to choose between the cathedrals, I'd probably skip this one as it is the least flashy of the three Gravensteen Castle — built in 1180 as the fortress of the Counts of Flanders and remains one of Europe's best-preserved medieval castles. Complete with battlements, towers, dungeons, and a collection of medieval torture devices, it offers a fascinating glimpse into life in the Middle Ages I'm not normally a fan of audio guides, but the English guide offered at Gravensteen Castle is narrated by a Belgian comedian, is one of the best I've encountered and makes the visit genuinely entertaining. Afterwards, wander the cobbled streets of the nearby Patershol district, one of Ghent's most charming neighborhoods, filled with cozy cafés and excellent restaurants Ghent Festival — one of Europe's largest festivals, held over ten days every July and attracting more than a million visitors. The entire historic center transforms into a giant open-air celebration with free concerts by world-class DJs, street performances, theater, food stalls, and late-night festivities If your dates are flexible, it's well worth planning your trip around the festival, but book accommodation well in advance, as hotels and hostels fill up quickly. Unfortunately, it overlapped with Tomorrowland the year I was there and I arrived the day after it ended Vrijdagmarkt — the large town square that has served as Ghent's meeting and market ground for centuries and still runs a market on Fridays and Saturdays. The square is ringed with cafe terraces and is a good place to sit for an hour. Don't miss the magnificent statue of Jacob van Artevelde at the center of the Vrijdagmarkt Graffiti street — a narrow alley off the Werregarenstraat covered in graffiti. To be honest, it's a very short alleyway and I walked through it in a couple of minutes. It is only thirty seconds off the route between the Belfry and Gravensteen Castle so worth the detour if you're interested in checking it out Where to Eat Souplounge — a cheap, fast soup counter located right off of Graslei . It is popular among locals for good reason: a few euros gets you a big bowl with bread, fruit and a roll. It isn't a fancy spot, but really hit the spot on a rainy day for me Where to stay Hostel Uppelink — one of the coolest hostels I've stayed in, located in a historic medieval house right on the Graslei . My room even had a view looking straight out at St Michael's Bridge and the towers. The dorms are basic and the stairs are steep and medieval, but you are paying for the view and the prime location. There is a bar downstairs and they run walking tours from reception. Book ahead in summer, and ask for a canal-facing room when you do ATTRACTIONS 1 St Michael's Bridge 2 Graslei & Korenlei 3 Belfry of Ghent 4 Saint Bavo's Cathedral 5 St Nicholas' Church 6 Gravensteen Castle 7 Patershol 8 Vrijdagmarkt 9 Graffiti Street RESTAURANTS & BARS 10 Souplounge ACCOMMODATION 11 Hostel Uppelink Belgium Ghent Touch to explore Double-tap to open in Google Maps Bruges 2 days recommended Bruges is Belgium's most famous medieval city (and recently made more famous by the movie In Bruges ). It is a remarkably well-preserved network of canals, cobbled streets and stepped-gable houses concentrated around a compact historic center. It's undeniably touristy, but there are so many amazing sights to see here. I would recommend spending 2 days to explore this wonderful town. What to Do Church of Our Lady — one of Bruges' defining landmarks that took roughly 200 years to complete, dating back to as early as the 9th century. Inside are the elaborate tombs of Mary of Burgundy and Charles the Bold, but the star attraction is Michelangelo's white marble Madonna and Child . During World War II, Nazi forces stole the statue and hid it in an Austrian salt mine, where it was discovered and recovered by the Monuments Men in 1945 before being returned to Bruges (watch the George Clooney & Matt Damon movie before going!) Market Square — the main square of Bruges , surrounded by guild houses and anchored by the Belfry Belfry of Bruges — the mighty medieval bell tower rising over the Market Square . There is a 366-step climb up a narrowing spiral for the best view over the whole town of red roofs and canals. The view was amazing and Bruges is so picturesque that it felt like I was staring over a model town. On the way up, you'll pass a 47-bell carillon that goes off every hour There is a small daily market with the biggest being on Saturday morning. Take a quick stroll through the market for fruit, flowers and hot food. I highly recommend the rotisserie chicken and potatoes which were amazing Rosary Quay — the single most photographed spot in Bruges, and rightly so: a bend in the canal where stepped brick gables, a turret and the belfry beyond all stack up and reflect in the still water. There are beautiful willow trees here and many little boats go throughout here during the day. Time it for early morning or golden hour when the light turns everything amber. This is also where the canal boat tours push off, which are also worth doing if you haven't done them elsewhere in Belgium Fish Market — a small colonnaded market just off the Rosary Quay where fish has been sold since the 1820s. There are only a handful of stalls left and it is quiet outside the mornings, but the area itself is lovely. Go in the morning if you want to watch fish trading, but note that most stalls shut by early afternoon and all day Monday De Burg — the second of the two central squares and the older one, a quieter counterpart to the Market Square a minute away. It is home to some of the most impressive architecture in Bruges including the Basilica of the Holy Blood and the gothic City Hall side by side. This was the site of the original ninth-century fort the city grew out of Basilica of the Holy Blood — a small, but extraordinary two-level church tucked into a corner of the Burg square. It is a striking building with two distinct parts: a plain, ancient Romanesque lower chapel from the 1100s with an ornately painted upper chapel guarding a venerated relic said to hold drops of Christ's blood, brought back from the Crusades. It's free to enter, and on certain days you can join the queue to see the relic up close. It was one of my favorite sites to visit in Bruges and different from most other churches you'll visit Bruges City Hall — one of the oldest town halls in Belgium dating back to the 1370s. The outside of the building has an ornate Gothic facade covered in statues and gold detail. I only saw it from the outside, but you can also visit the Gothic Hall upstairs with its painted vaulted ceiling Kruispoort Gate — one of the surviving medieval city gates on the eastern edge of the old town. Four of the original nine gates survive, and one of the windmills still grinds flour in summer The city center tends to get crowded, especially during the day with tourists and day trippers. The edge of town where Kruispoort Gate lies is a peaceful escape from the crowds. There is a peaceful canal path here lined with huge old windmills. It is about fifteen minutes from the Market Square , almost entirely free of tourists, and easily my favorite walk in Bruges Where to Eat & Drink 2be Shop — a beer shop and canal-side bar with a wall of more than a thousand Belgian beers. The terrace out back over the water is the real draw and one of the prettiest places to drink in the town Bauhaus — the bar attached to the St Christopher's Bruges (where I stayed), and the liveliest place in Bruges after dark. There are cheap pints, a mixed crowd of travelers and locals, and it stays open when everything in the center has shut. The locals actually come to hangout here so it is a great opportunity to make friends. I had an unforgettable Karaoke night singing Green Day with a group of locals from Bruges Where to Stay Stay inside the old-town canal ring if you can: Bruges runs on day-trippers, so the real magic is in the evening and early morning when the coach crowds are gone and you almost have the town to yourself. It's small enough that anywhere central is walking distance from everything, and staying a night (rather than day-tripping) is what makes the town worth the trip St Christopher's Bruges - The Bauhaus — a cozy hostel located on the far end of town. The accommodation was nice and the atmosphere is extremely social. The hostel is right next door to the most popular bar in town called The Bauhaus which made it very social. I had a fun couple of nights here meeting backpackers from all over the world and also locals from Bruges who were also very friendly. I had no trouble sleeping on the nights when I wanted to go to bed early too. ATTRACTIONS 1 Belfry of Bruges 2 Market Square (Markt) 3 Rozenhoedkaai (Rosary Quay) 4 Basilica of the Holy Blood 5 De Burg 6 Bruges City Hall 7 Church of Our Lady 8 Fish Market 9 Kruispoort gate RESTAURANTS & BARS 10 2be Bar (The Beerwall) ACCOMMODATION 11 St Christopher's / Bauhaus Belgium Bruges Touch to explore Double-tap to open in Google Maps Tomorrowland late July · advance tickets As a huge music festival fan, Tomorrowland was one of the most incredible experiences in my life. The main Tomorrowland festival is the largest music festival in the world and the production is fantastic. They basically build an entire village every year in the town of Boom, Belgium (a tiny town between Brussels and Antwerp). It is hosted every year in late July with slightly different dates each year. In 2026, there were two weekends: July 17–19 and July 24–26. The organizers go all out on the decorations, acrobats, stages and invite all of the best Electronic music artists from all corners of the world. You feel like you're in fantasy land and I'd highly recommend it to ANYONE even if you don't listen to Electronic music. Tickets are notoriously hard to get and sell out in minutes, so you need to buy months ahead. By that, I mean wait online and keep refreshing the sites the second the tickets are released. I'll go into detail about accommodation later, but the DreamVille camping tickets give you the full experience, while regular tickets get you the day and evening sets. The basics You first need to decide on your accommodation. There are two main ways to do Tomorrowland: either camping or commuting in each day from Antwerp: DreamVille Camping — the experience camping at Tomorrowland was unmatched: the facilities were incredibly clean, it was cool being able to walk to the festival grounds every morning, and we had some really cool neighbors that we hung out with. On-site camping at Tomorrowland is called DreamVille . The big perk of staying in DreamVille regardless of tier is access to The Gathering, an exclusive Thursday night party with surprise headline DJs that non-campers cannot attend. DreamVille Camping comes in three main tiers: Magnificent Greens — the traditional bring-your-own-tent option and the most social, with the most freedom to choose your spot. This will run you €370–430 per person including the ticket Easy Tent — the most popular option where your tent is pre-pitched and ready when you arrive, with sleeping arrangements and essential accessories included. There are multiple Easy Tent configurations for 2 or more people at different price points. I did this option personally and it was a life-saver not having to carry camping gear on a longer Euro Trip. This will cost €600–700 per person for a standard 2-person unit, rising to €800–900 for the Spectacular version including the ticket Montagoe — the most premium tier, a glamping-style option with more comfort and amenities for those who want a softer festival experience, includes a pool, hot tubs and its own bar. Montagoe is the most expensive tier which starts €1,000+ including the ticket Commuting from Antwerp — a viable alternative to camping if you want a proper bed and a base to explore Belgium. Belgian Railways (SNCB) runs a special Tomorrowland Event Train Ticket which you can buy using a unique code from your Tomorrowland account A direct train from Antwerp Central to Boom takes about 30 minutes and runs every 30 minutes, costing €3–8 each way. Antwerp is probably the best base given the frequency and speed of the train Expect hotel prices in Antwerp to be slightly inflated, but it didn't seem to be that much more expensive than usual If you choose this option, you'll have to buy tickets separately which will run you €138 for a day pass and €327 for a weekend pass Getting There Boom sits between Brussels and Antwerp and the simplest way in is the official shuttle bus. Shuttles run from Antwerp, Brussels or even directly from Brussels Airport. The official shuttles are worth booking alongside your ticket and are reasonably priced at around €40 roundtrip Whichever way you arrive, there is a short walk at the other end. You'll have to walk about twenty minutes with all your luggage if you're camping. Coming out at the end, the same buses run back to Brussels, and you will want the earlier one rather than the last Dreamville DreamVille is the name of the festival grounds which runs like a small town: there is a common area where we ate and played cards through the slow afternoons, the food court out on its wooden deck, a merch store, and showers that pipe EDM at you while you're in them, which tells you everything about the place Walk out to the Magnificent Greens and there's a yoga class, a gym, tennis courts and a farmhouse breakfast spot, none of which I expected from a campsite. The mornings are the good part: everyone surfaces slowly, the music is already going somewhere in the distance, and you hear five languages before you've finished eating The Stages I've been to 15+ music festivals and the stages at Tomorrowland are on another planet compared to any other festival. We spent the first day wandering from stage to stage, just checking out how they were decorated. You'll have plenty of time to check out your favorite artists so I highly recommend exploring the different stages. Some of the highlights are: The Main Stage is a colossal fairytale set that has a different elaborate build each year. It is complete with full size waterfalls, pyro and fireworks making it an incredible way to end the night each evening. It was castle themed the year I went, but the design is always a surprise Core — out among the trees and the most visually stunning, built around an enormous head sculpture that lights up after dark. It leans house and techno with the DJ playing inside the head! It is the one stage I would plan an entire night around Youphoria — the hardstyle stage, built under giant mushrooms with a crowd to match. Even if hardstyle is not your thing, give it an hour, because the energy in there is unlike anywhere else in Tomorrowland. I spent a disproportionate amount of time here in 2023 and even met my favorite DJ at the time, MANDY, in the crowd! Crystal Garden — the house stage, designed as a giant lily pad sitting out over the water. It is one of the prettiest in daylight and a good place to land for the afternoon before the night stages open up Rave Cave — a tiny stage tucked under what looks like a stone bridge, holding maybe a hundred people. It is sweaty and packed and the complete opposite of the big builds, which is exactly why it is worth finding The Library — a big book-themed lawn and the one place you can actually sit down for a while. It is the mellow option on paper, though it still pulled one of the largest crowds I saw all weekend Elixir — a lit-up pagoda in the middle of the water with a huge dragon in front of it. More a place to stand with a drink than a stage you would plan around, but it is one of the best-looking corners of the whole site after dark Cage — the drum and bass and harder-edged stage, and covered, which makes it feel like a nightclub The Artists If you like Electronic music in any shape or form, you'll find the line-up to Tomorrowland incredible. Every year, there is a rotating selection of world-class DJs and there is almost always a good name on at any given time. The big name regulars are: Dimitri Vegas & Like Mike (Belgian, and effectively the house band at this point), Martin Garrix and Afrojack . If you like more obscure electronic music like me (Hardstyle, DnB, Techno, etc.), there will be the biggest names from every genre so there will be no shortage of artists that you want to see Where to Eat The food at Tomorrowland was a huge surprise. It was genuinely really good, especially surprising considering your average festival food. There are food stalls areas near almost every stage. The main place we ate was the main court with a huge wooden deck and 30-plus international stands. Each stand represents a different country so you'll have a huge array of food to choose from The chicken-schnitzel pita was my standout, along with Belgian loaded fries, sushi, paella and rice bowls. It isn't cheap (everything runs on Pearls, the festival's cashless currency), but it is miles better than any other festival food I've had Worth Knowing Everything inside runs on Pearls , the festival's own cashless currency, which you load onto your wristband and top up in the app. They do not convert neatly to euros, and that is the catch: after two days I genuinely could not have told you what I had spent. The prices themselves are fair (especially beers), so it is losing track that gets you rather than the cost. You need to load up pearls on to your wrist band so it is better to do it in bigger chunks so you are not lining up again every time you want a drink Be ready for weather. Maybe I got unlucky, but it rained on and off the entire weekend while I was there. It didn't really impact how incredible the festival was, but by the last morning everything I owned was damp so make sure to bring a real rain jacket and a dry bag. There's also a phone charger rental you hand back on the way out, and it's worth sorting on day one, because you won't find an outlet Give the first afternoon to walking the whole site before you commit to a stage. The map doesn't convey how far apart things are, or how much better the small stages look in person than they sound on a lineup. And pace yourself: it's four days, most of them ending late, and I left with a cold that took the next few days in Ghent to shake off Other Places to Consider If you have more time, add on one of the following cities in Belgium, all easily reachable by train: Antwerp — Belgium's stylish second city and a huge port, long the center of the world diamond trade and a serious fashion capital. Don't miss the grand cathedral-like design of its railway station, one of the most beautiful in the world, a nice old center and a great nightlife and dining scene. Located only half an hour from Brussels Leuven — a compact, charming university town built around one of the most beautiful Gothic town halls anywhere. Home to a 600-year-old university and the brewery that makes Stella Artois. It has Belgium's liveliest student nightlife, including the Oude Markt , a single square ringed entirely by bars and billed as \"the longest bar in the world.\" An easy, fun stop between Brussels and the coast The Ardennes — the forested, hilly, French-speaking southeast region of Belgium that is a complete change of pace from the flat Flemish north. Here you'll find deep woods, river valleys, storybook castles like Bouillon and Durbuy with good hiking, kayaking and caving. If you're a history buff, you might also visit for the WWII history and the location of where the Battle of the Bulge was fought"},{"url":"bosnia/field-notes.html","title":"Bosnia Travel Guide","text":"Bosnia Travel Guide General Bosnia is truly a hidden gem and one of the most underrated countries in Europe. A unique blend of Balkan and Muslim culture, Bosnia has a very unique culture accompanied by breathtaking scenery and a complex past. The country is composed of 3 different ethnic groups: Bosniaks, Serbians and Croatians and in fact has 3 presidents today. It is a fascinating country to visit to learn about the history ranging from the Austro-Hungarian empire, Ottoman empire, Yugoslavia, the Bosnian War and continuing geopolitical tensions. Bosnia's medieval sites are often overlooked and many of them felt straight out of a fantasy novel. I based myself in the capital Sarajevo for a week and explored the rest of the country via day trips. I'd recommend spending 5–6 days in the country to fully explore and understand the complexities of Bosnian culture. Bosnia Overview Transport — Sarajevo itself was very walkable. I used a local ride sharing app called mojTaxi which offered affordable rides. Outside of Sarajevo, the bus system isn't very robust with a limited schedule so I'd recommend booking day tours or renting a car Hospitality — Bosnian people were some of the most friendly people that I've come across in my travels. Whether it is a random person on the street, a taxi driver or tour guide, Bosnians were extremely open and easy to talk to. They also had a dark sense of humor I really appreciated Food — Bosnia also has by far the best food in the Balkans so make sure to branch out and try new dishes. The dishes are very similar to other countries in the Balkans, but somehow so much better. Some dishes to try are: Burek — flakey pastry stuffed with meat covered with yogurt sauce Cevapi — little spiced sausages, often served with fries Sarma — cabbage rolls stuffed with rice and meats Bosnian coffee — similar to Turkish coffee served with a cigarette Klepe — Bosnian-style dumplings Language — Bosnian is the official language (although it is essentially the same as Serbo-Croatian) and utilizes both the Latin and Cyrillic alphabet. Almost everyone I met was fluent in English and it was easy to get around Affordability — since it isn't a popular tourist destination by European standards, Bosnia was very affordable. A full meal may only cost you $5 Sarajevo 3–4 days recommended Sarajevo is one of my favorite cities in the world. Home to centuries of fascinating history, Sarajevo has changed hands many times between the Austro-Hungarian empire, Ottoman empire, Yugoslavia and Bosnia today. The city is covered in interesting historical sites and you can even see the bullet holes from the Bosnian War on many of the buildings today. The city is very walkable and easy to explore. What to Do Old Town (Baščaršija) — Ottoman-style bazaar with little cafes, copper shops and restaurants. It remains very well preserved and atmospheric Sebilj Fountain — the wooden fountain in the center of Baščaršija, always surrounded by pigeons. The classic Sarajevo photo and an important reminder of the city's Ottoman past Gazi Husrev-beg Mosque — the main mosque in old town that still operates as an active mosque City Hall (Vijećnica) — a beautiful Austro-Hungarian building with a stunning stained glass dome, located right on the river. It has rotating art and historical exhibits inside. While I was there, they had an exhibit on Srebrenica during the 30th anniversary of the genocide Take a cable car up Trebević Mountain — take the cable car from the town center up to Trebević Mountain for an incredible view overlooking the entire city 1984 Olympic Bobsled track — it was used in 1984 when Sarajevo hosted the Winter Olympics. Less than a decade later, the bobsled was being used by snipers during the Siege of Sarajevo. Now, the area is overgrown and the bobsled track is covered in moss and graffiti. You can walk for a few kilometers down the bobsled track, an experience hard to find elsewhere! While you're there, do a short hike to Bistrik Tower from the end of the bobsled track, a space observation tower from the Yugoslav era, since abandoned and filled with bullet holes from the Bosnian War Site of the Assassination of Archduke Franz Ferdinand — World War I actually started in Sarajevo when a Bosnian Serb assassin named Gavrilo Princip killed Archduke Franz Ferdinand of the Austro-Hungarian Empire. You can go to the actual site where this happened where they have imprints of his feet. The event cascaded into a series of the two most consequential wars in history so it is surreal to be in the exact spot It lies right next to the Sarajevo Museum and the Latin Bridge so visit those while you're in the area Kovači Cemetery — walk up through the military cemetery overlooking Sarajevo, characterized by the seas of traditional muslim gravestones (white pointy grave stones). It has one of the best views overlooking Sarajevo and makes for a good sunset spot Yellow Fortress — climb further up the hill for another good viewpoint and sunset spot in Sarajevo Museums Museum of Crimes Against Humanity and Genocide — the most impactful museum I've been to. It covers the Bosnian genocide 1992–1995 in brutal personal detail using actual clothing, notes and belongings of victims making the stories more real and heart-wrenching Siege of Sarajevo Museum — covers the horrific four year Siege of Sarajevo, the longest siege in history, lasting over 1,425 days. You can buy a joint ticket with the Crimes Against Humanity museum Tito Museum (Muzej Tito) — tiny 2-room museum full of Yugonostalgia and great place to learn about the still-beloved Yugoslavian strongman Josip Broz Tito. No one actually works at museum, you just pay by card, a turnstile opens, Yugoslavian music starts playing and all the lights turn on. It feels like a 1950s wonderland and was a fun, quirky museum experience Where to Eat Buregdžinica Sač — absolutely incredible Burek in Sarajevo cooked in a traditional way with a special metal pan and coals. Try the meat Burek with yogurt sauce. It is a very famous place and gets very busy so try to go early before the rush Inat Kuća (House of Spite) — restaurant moved brick by brick across the river during Austro-Hungarian construction. Get the Klepe and a Bosnian beer Sarajevo Brewery — a historic brewery built during the Austro-Hungarian empire in 1864. The building is a massive and beautifully decorated red complex. The brewery is an important historical landmark in the city as it was the only source of clean water during the 1,425 day Siege of Sarajevo ASDŽ Aščinica — cafeteria-style Bosnian home cooking. I enjoyed the buttery mash potatoes, stuffed peppers, dolma and pita. It was great value for the portion size and price Ćevabdžinica Zmaj Titova — Recommended by my local tour guide as the best Cevapi in the city. Get 10+ Cevapi, onions and bread for only $4. Cafe Slatičarna — a small cafe known for its layered chocolate cream cake called Boem Where to Stay Balkan Han Hostel — a very social hostel located near Old Town. They have a happy hour that often turns into a fun night out ATTRACTIONS 1 Old Town (Baščaršija) 2 Gazi Husrev-beg Mosque 3 City Hall (Vijećnica) 4 1984 Olympic Bobsled track 5 Bistrik Tower 6 Latin Bridge 7 Kovači Cemetery 8 Yellow Fortress 9 Museum of Crimes Against Humanity and Genocide 10 Siege of Sarajevo Museum 11 Tito Museum (Muzej Tito) RESTAURANTS & BARS 12 Buregdžinica Sač 13 Inat Kuća (House of Spite) 14 Sarajevo Brewery 15 Ćevabdžinica Zmaj Titova ACCOMMODATION 16 Balkan Han Hostel DAY TRIPS ↗ Mostar & Herzegovina Tour (Full Day) ↗ Jajce, Travnik & Central Bosnia Tour (Full Day) BOSNIA & HERZEGOVINA Sarajevo Touch to explore Double-tap to open in Google Maps Day Trips From Sarajevo, you can easily take many fascinating day trips out of the city to explore the rest of Bosnia. The country is extremely green and home to many beautiful landscapes. I went on two day trips with the tour company named MeetBosnia and I highly recommend both of them: Mostar & Herzegovina Tour — this tour takes you into the southern region of Bosnia known as \"Herzegovina,\" which is populated mostly by Croatians. It is considered the most beautiful region of the country with beautiful mountains and deep blue water. Our tour was led by a guide named Christian who was informative, hilarious and very open for discussion even with darker topics like the Bosnian Genocide or on-going racial tensions in the country. The tour is packed with a bunch of amazing stops: Mostar — a historic Bosnian city, famous for its 16th-century Ottoman bridge called Stari Most , overlooking a gorgeous blue river below. The bridge has become popular among adrenaline junkies who like to dive 25 meters off the center of the bridge (equivalent to diving off a 9-story building) Jumping off the bridge requires a special training course. Locals are known to beat up those who jump off without permission! Mostar is one of the most popular places in Bosnia so it gets very crowded as many day trippers from Croatia come here. Many people also like to spend the night here, but I felt like I saw most of the town during this day trip Konjic — a beautiful little town with a historic Ottoman-era bridge and a river filled with crystal clear mountain water Neretva Canyon — the drive from Konjic to Mostar runs through a gorgeous canyon with huge white mountains and deep blue water the whole way down Kravica Waterfall — a really nice set of waterfalls with a blue lake you can swim in upfront. It gets really busy in the summer Dervish House in Blagaj — white Ottoman house built into the base of a cliff in the middle of nowhere, next to an incredibly blue river. It was an very peaceful area and an interesting stop to learn about the Sufi mystics (a respected Islamic order during the Ottoman empire) Počitelj — a pretty hilltop town overlooking the river below. You can explore the abandoned town for hours and there weren't many tourists around Jajce, Travnik & Central Bosnia Tour — a guided day tour that takes you to two former capitals of the Bosnian Kingdom, ancient catacombs, a colorful mosque in Travnik and the best Cevapi in the country! This trip covers a lot more ground and includes a lot more driving than the Mostar trip Jajce — a magical medieval town made of a castle built on top of two waterfalls. It felt like a scene out of a fantasy movie. You can walk around the town and explore. We also stopped by a few places nearby Jajce: Pliva Lakes watermills — little medieval-looking huts with little streams and waterfalls flowing underneath, used as corn mills Bogomil catacombs — located underneath a church, we visited catacombs of the prehistoric Bogomil people. This was a pre-Islamic Bosnian religion with a cross, sun and moon carved inside Travnik — the last capital of the Bosnian Kingdom before it was taken over by the Ottoman empire in the 15th century Travnik Fortress — a medieval town-fortress with an amazing view overlooking the medieval town of Travnik. A great place to watch the sunset Šarena Džamija (Ornamented Mosque) — genuinely one of the most beautiful mosques I've seen. On the outside, there are blue domes with light blue flower paintings. Inside, there is a green, yellow and red checkered ceiling with a massive chandelier of curved lightbulbs Travnik is known to have the best Cevapi in Bosnia so make sure you stop by Ćevabdžinica Tenić . This restaurant is known for having the best Cevapi in the Balkans and Bosnians will travel across the country just to eat here Other Places to Consider If you're looking for more to do, here are some other places to consider while visiting Bosnia: Lukomir — hike to the remote mountain village of Lukomir, which has been continuously inhabited for 600 years and feels completely frozen in time. The hike is 7km and starts in the small town of Umoljani and passes through wildflower meadows with dramatic views over the canyon below. Book a guided tour from Sarajevo since the trails are poorly marked and it's only accessible May to November Višegrad and Drvengrad Tour — a 2 hour drive east of Sarajevo, Višegrad is home to a UNESCO-listed bridge with a church nearby. Drvengrad is a small traditional town on the border in western Serbia. Best done as a day trip from Sarajevo Visit the Republic of Srpska — one of two political entities that make up Bosnia and Herzegovina, the Republic of Srpska is a predominantly Serbian Orthodox region with a completely different feel from the Bosnian Federation The capital Banja Luka is worth a stop for the medieval Kastel Fortress and river rafting on the Vrbas Trebinje in the south is considered one of the most beautiful towns in the country, a quiet Ottoman-era city only 40 minutes from Dubrovnik"},{"url":"brazil/field-notes.html","title":"Brazil Travel Guide","text":"Brazil Travel Guide General Brazil is one of the most diverse countries in the world and famous for its picturesque beaches, iconic culture, and legendary nightlife. The country is enormous, being the 5th largest country in the world and home to over 200 million people. The cities feel completely different from each other. Rio de Janiero has the beautiful beaches, mountains and chaos; São Paulo is a sprawling urban megalopolis; Paraty is a quiet sea-side colonial town; Ilha Grande is an island covered in jungle with some of the best snorkeling I've ever seen. Suggested Route Overview Safety — Brazil has some of the largest wealth inequality in the world. You'll see some of the most pristine high rise apartments contrasted with a valley of Favelas across the street from each other. Although I never personally felt unsafe or had any issues, crime is a serious issue in Brazil that tourists often take too lightly . Many people from my hostels got mugged or get their phones stolen. Local Brazilians were targeted as well and they will warn you before you get to the country Be careful pulling out your phone, avoid dangerous areas and always be aware at night Transport — As mentioned before, Brazil is the 5th largest country in the world. Unless you're going to the Amazon, you'll likely be spending your time along the coast as most Brazilians live there. Budget travel days as you'll likely need a full day to travel between cities Flights — For longer distances, you may want to fly. Brazil has multiple domestic carriers including LATAM Airlines Brasil, GOL Linhas Aéreas, and Azul Brazilian Airlines that offer flights all over the country. The flights are not super affordable compared to other parts of the world Buses — For intercity travel, particularly between Rio and São Paulo, you can take a network of buses or tourist shuttles. They are very organized, new and run seamlessly; sometimes even offering hotel pick-up. I used bookaway.com to book tickets Ridesharing — Uber is available in Brazil and a great option to get around safely. The rides were pretty affordable Credit card — credit card was widely accepted everywhere for me, but keep cash on hand for smaller street vendors Language — the official language is Portuguese, but there is a distinct Brazilian Portuguese accent that is very different from the Portuguese spoken in Spain. Outside of big cities, I found that very few people spoke English or even Spanish so brush up on basic Portuguese Recommended route — If it is your first time in Brazil, I'd recommend trying the Costa Verde route between Rio de Janiero and São Paulo. Named for it's lush, tourist rainforest, it will take you to some beautiful seaside towns. The route I took was three weeks long from Rio de Janiero to Ilha Grande to Paraty to Sao Paulo Foods to try — Brazilian food is amazing and very flavorful. Some iconic dishes to try are their BBQ, Pão de Queijo (cheese bread), açaí bowls and caipirinhas Rio de Janeiro 4–5 days recommended Rio de Janeiro is hands down one of my favorite cities in the world. The landscape of Rio is gorgeous ranging from the famous white sand beaches of Copacabana to the lush green mountains and boulders surrounding the city. It is also a city of contrasts with towering skyscrapers next to favela valleys. Brazilians were very welcoming people and it was fun to experience the rich, chaotic Brazilian culture. To fully take in the city, I would recommend spending 4 – 5 days as there are so many beaches, hikes and sites that you can explore. What to Do Visit the iconic beaches of Rio de Janiero — one of the main draws for coming to brazil is to experience the beaches here. Spend a day on the beach soaking up the sun, drinking out of a fresh coconut or playing beach volleyball with locals. The sunsets are absolutely stunning so make sure you catch at least one from the beach Copacabana Beach — one of the most famous beaches in the world, lined with restaurant and bars along the sand. It very much lives up to the hype, but can get very crowded with tourists Ipanema Beach — located right next to Copacabana, it is the slightly more quiet neighbor. A great place to spend a day Leblon Beach — connected to Ipanema to the West, it is also a great place to spend a day. There is beautiful view of the city skyline as well as the Dois Irmãos boulders in the background. It was personally my favorite beach in Rio Christ the Redeemer — one of the seven wonders of the world that is worth a stop while in Rio. You can pay for a tram, hike up or take a heli ride around it. It is located on a Rock high above the city so there is a really nice view overlooking the entire city. Expect it to be really busy while you're there Sugarloaf Mountain (Pão de Açucar) — located on a peninsula and surrounded by water, Sugarloaf Mountain offers incredible views of the city. It is a great place to take in the sunset and there is a bar on top where famous DJs occasionally play. You can take an take an Uber or taxi directly to the base station and then a tram up to the top. If you're looking for an adventure, there are tours that offer a hike and climb to the top as well Hike Morro Dois Irmãos — my favorite hike in Brazil located in the Vidigal neighborhood not too far away from Leblon Beach. The hike starts at the bottom of Vidigal favela which is considered to be safe. There will be a sea of mototaxis at the bottom of the hill waiting to take you through the favela to the trailhead for about 7 reals or ~$1.40. The hike is only 3.7 miles or 6 km (full hike on AllTrails here ) . However, expect it to take around 4 hours due to the steep ascent and heat. There are a couple of viewpoints on the way up: First viewpoint faces South: you'll get a view of the small cove with Praia do Pepino. To the right, there is a sea of tiny favela houses stacked into the hillside that is quite the mesmerizing view Second viewpoint faces North: you'll be able to see the full skyline of Rio along the beach and even spot Christ the Redeemer on a clear day The hike ends at a massive rock overlooking the entire city which was the best view of the city that I experienced. It is a safe, popular hike among tourists so don't be intimidated by the fact that it starts in a favela. Hike Pedra do Telegrafo — another awesome hike with the instafamous hanging rock. Located roughly an hour and 15 minutes outside of the city, you can do this hike independently by taking a taxi to the starting point. You'll hike through the jungle for 2.3 miles (AllTrails link here ). Look out for the marmosets (little lemur-like creatures with white fluffy ears) hanging on the trees. There is a really nice view at the top overlooking a white sand coast with bright blue waters with condors circling overhead. It is also known for the famous hanging photo spot: there's a rock at the top where it looks like you're hanging off a cliff, but you're literally 2 inches off the ground. Naturally, this is pretty touristy and there will be a massive line to take a photo. On the way down, you can take a cheap mototaxi ride down from the trailhead to the main town Olympic Boulevard — completely revitalized in 2016 when Brazil hosted the Summer Olympics, this neighborhood is a fun area to explore for half a day in Rio Take a stroll down the boulevard and admire all the beautiful art installations and murals. The standout is the Ethnicities Mural by Eduardo Kobra which is one of the largest pieces of graffiti art in the world, depicting ethnic groups from different continents in vibrant geometric patterns Museum of Tomorrow (Museu do Amanhã) — a futuristic science museum with a striking mechanical white structure that sits on the boardwalk surrounded by the bay and palm trees. The outside of the building is super impressive and there is a massive fountain below. The inside of the museum has huge IMAX domes you lie down in, neon light installations and 360-degree LED panels. The exhibits explore the future of the Earth covering climate change and biodiversity. As an added bonus, there's a really cool coffee shop inside that is worth checking out Parque Lage — 1920s Italian-designed mansion nestled in a huge park right next to a hillside. It was a beautiful place to visit with a fancy restaurant and pool in the main courtyard. The park area around the Palace was gorgeous as well It was quite the Instagram influencer photo spot with a 30 minute line to get a photo in front of the pool. If you're a Hip-Hop fan, it was also used as the set for a Snoop Dogg and Pharrell music video \"Beautiful\" Watch on YouTube Escadaria Selarón — these are the famous colorful stairs in Rio. I found it to be extremely crowded with tourists (all trying to get the same photos). It is worth a quick stop for photos and get a cheap caipirinha Where to Stay The best areas to stay are right in Ipanema or Copacabana since they are the safest areas. You'll also be walking distance to the beach I was told to avoid the Lapa neighborhood. It is a popular spot for nightlife, but known to be dangerous and a few people from my hostel got mugged there More Ipanema Hostel — a very social hostel with activities every day and a really cheap bar every night. The location is also great, located right by Ipanema beach ATTRACTIONS 1 Copacabana Beach 2 Ipanema Beach 3 Leblon Beach 4 Christ the Redeemer 5 Vidigal neighborhood 6 Olympic Boulevard 7 Museum of Tomorrow 8 Parque Lage 9 Escadaria Selarón DAY TRIPS ↗ Pedra do Telégrafo (Half Day) BRAZIL Rio de Janeiro Touch to explore Double-tap to open in Google Maps Ilha Grande 2 days recommended Ilha Grande (pronounced ill-yah gran-jee ) is a beautiful island covered in jungle, located just 4 hours away from Rio. It couldn't feel more different from life in the big city and is a popular getaway for locals during the summer to spend a long weekend. The best way to get there is to book a transfer that costs roughly ~$30. They will pick you up directly from your accommodation and covers the logistics of booking both the van and boat ride to get to the island. Ilha Grande can also be visited as a day trip, but I'd recommend spending at least 2 days here to fully soak in the island. What to Do Snorkeling — some of the best snorkeling I've seen. I was amazed by the density of fish here and you can even spot some turtles if you swim away from the crowd. Tours are easily booked in the main town for the next day although many of the operators didn't speak a word of English The tour I did stopped by Lagoa Azul and Lagoa Verde . Both were super clear blue lagoons with hundreds of fish literally touching your legs while you're snorkeling Hike Across the Island — starting from the main town, you'll cross through the forest, see waterfalls and end up on remote beaches. Here is a popular trail that ends at Lopes Mendes Beach, considered one of the most beautiful beaches in Brazil. It runs 8.7 miles or kilometers and takes roughly 5 to 6 hours to complete Where to Stay HI Hollandes Hostel — a hostel located in the main town with a great outdoor courtyard. Make sure you come prepared with mosquito spray Paraty 1–2 days recommended Paraty (pronounced para-chi ) is a nice, quiet colonial town located on the Brazilian Coast. Brazil has not maintained it's old colonial architecture (you won't find any in Rio or São Paulo) so this is one of the best places to experience it. Located right in between Rio and São Paulo, the best way to get there is to book a bus transfer available on BookAway . From Ilha Grande, I took a ferry to a port town called Angra Dos Reis (a really cool stop in itself) and then a local bus for $8 to Paraty. The main activities to do here are explore the white colonial downtown, learn about the Portugese colonial history and take a boat tour. It is worth spending a couple of days here. What to do Explore the Portugese old town — The old town has cobblestone streets and white buildings with bright colored door frames (red, yellow, blue & green). The Portugese Colonial architecture is distinct from Spanish colonial towns you see all over Latin America The town rose during the gold rush as a transit route between Rio and São Paulo, then was mostly abandoned after the gold rush (population dropped to 600 people) and was only reconnected by road in the 1970's Casa da Cultura de Paraty — a nice museum with the history of Paraty, but all exhibits were in Portugese Boat Tour — you can also book boat tours to explore the coastline around Paraty. There are tons of tourist boats along the main pier. It is a very popular place for Brazilians during the summer, but not foreign tourists. My entire boat tour was full of Brazilians and I was the only foreigner. I preferred the boat tour in Ilha Grande over Paraty since the snorkeling there was unreal Where to Eat Manuê Sucos — a little cafe serving delicious dobrados (a lavash wrap with shredded beef and cheese). They also had an amazing mango and açaí shakes. One of my favorite restaurants in Brazil Batata Baroa — a traditional Brazilian restaurant. It was very affordable (~30 reais or $6) for a huge plate of steak, rice and beans Where to Stay Selina Paraty — as with any Selina hostel, it was an amazing experience. There was a pool, a coworking area and a cafe that served a great complimentary breakfast. There were barely any other backpackers while I was there São Paulo 2 days recommended São Paulo is the largest city in the Americas, home to over 21 million people and 10% of Brazil's overall population. It is a huge sprawling urban metropolis and most of the buildings were built in the last 50 years. As a tourist, there isn't much to see, but it is worth spending a couple days just to get a sense of how most Brazilians live and experiencing one of the largest cities in the world. Although the city may look modern and feel like any other western city, crime is very real. Brazilian friend was robbed at gunpoint right outside the front door of our hostel at 6am while waiting for an Uber. This was considered one of the safest neighborhoods in the São Paulo so be aware. What to Do Walking tour of the downtown — covers São Paulo's transformation from a Portuguese colony built largely by Italian immigrants. Most of the buildings downtown date from the 1920s onward, built on top of older ones. The city's growth came from coffee, gold, and natural resources. Good context if you want to understand how Brazil got to where it is today Beco do Batman — a cool graffiti alley, named after it's famous Batman mural. It started as a single mural and organically grew into an entire alley. I really enjoyed it and it takes about 20 minutes to explore Japantown (Liberdade) — Brazil, and specifically São Paulo, is home to the largest population of Japanese people outside of Japan. They are super proud of this fact (and loved to tell me about it as an Asian tourist). Explore for a few hours to see the Japanese architecture and try the brazilian-influenced Japanese food. Brazilians love cream cheese in their sushi! Dance to Forró Music — unique to Northeastern Brazil, Forró music is traditional Brazilian music that blends European polkas with Afro-Brazilian folk traditions. It is characterized by three instruments: the accordion, the zabumba (a flat bass drum), and a metal triangle. Admittedly, I'm not much of dancer, but there is a very simple dance you can learn with a partner and Brazilians will happily teach you Ó do Borogodó — we went to this bar where there was a live band playing Forró and lots of locals dancing through the night Where to Eat Galinheiro Grill — my absolute favorite restaurant in Brazil. I ordered the baby beef, rice, beans and fried polenta which was absolutely incredible. The portion size was enourmous and I had enough for close to 3 meals Where to stay Ô de Casa Hostel — an amazing hostel with a really good social vibe. They hosted lots of activities and a took us to bar to dance Forró at night. Lots of Brazilians from other parts of the country stay here and are happy to teach you about their culture ATTRACTIONS 1 Walking tour of the downtown 2 Beco do Batman 3 Japantown (Liberdade) RESTAURANTS & BARS 4 Ó do Borogodó Bar 5 Galinheiro Grill ACCOMMODATION 6 Ô de Casa Hostel BRAZIL São Paulo Touch to explore Double-tap to open in Google Maps Iguazu Falls 2 days recommended Iguazu Falls is one of the most incredible waterfalls in the world, surrounded by lush jungle making you feel like you're in Jurassic Park or Avatar. It is no surprise that it is o ne of the seven natural wonders of the world. The waterfalls are so massive that they're actually located in 3 countries: Brazil, Argentina and Paraguay. The best way to visit it is to spend 1 day on the Brazilian side and 1 day on the Argentinian side which each offer a different experience. It is very easy to cross the border, you just can take a cheap, local bus from one side to the other. Brazilian side: there are walkways through the forest to platform views of the falls from a distance. The falls stretch for miles side by side. The upper river flows peacefully then drops dramatically. The surrounding forest feels like Avatar. The waterfalls are famous for the biodiversity and is home to hundreds of species of tropical birds Argentinian side: take a boat tour here! They drive the boat directly into the falls and ram the boat into the water wall multiple times. It'll feel like a rollercoaster where you get completely soaked and shake water out of your sleeves afterwards. Bring a poncho and your GoPro How to get there — both the Brazilian side and Argentinean side have airports with regular flights to Rio, São Paulo and Buenos Aires. These flights are very affordable, roughly $30-$40 if you book in advance. It is significantly cheaper to fly to the airport on the side of the country that you're already in. Day Trip to Ciudad del Este, Paraguay If you have an extra day, also take a day trip to Ciudad del Este in Paraguay. It is quite an odd city, a popular spot for Brazilians and Argentineans to buy tax-free electronics (yes, random I know). The city is loaded with Chinese electronics stops. Visit some of the historic sites ( El Mensu History Museum and Catedral San Blas ) and stop by Maru Cafe for a traditional Paraguayan meal. You can get there by public bus. Depending on where you start, the will cross through the borders of Argentina, Brazil and Paraguay. Citizens of these cities are able to freely cross the borders. However, Foreigners are required to ask the bus drivers to stop. The bus doesn't automatically stop so make sure you ask the driver. Don't make the same mistake as me and accidently illegally cross the border... Where to stay I flew into the airport on the Brazilian side and decided to stay in the town of Puerto de Iguazu in Argentina. From the Brazilian airport, it was a simple public bus ride and quick border checkpoint to cross the border. The town of Puerto de Iguazu in Argentina has a lot more tourism infrastructure, restaurants and is the best place to base yourself in the area Tucan Hostel - one of my favorite hostel experiences. The hostel itself was very basic, but was very social and a great place to stay. I met some absolutely amazing people from all over the world and the host named Mariel was extremely friendly. Once a week, they host an absolutely legendary Asado (the weekly Argentinian tradition of having a family barbeque) complete with steak, blood sausage, pork ribs, chicken, chimichurri sauce and red wine Other Places to Consider Brazil is so large that I spent my entire 3 week trip in just a tiny portion of the country. I was recommended the following places by other travelers and am excited to visit them myself on my next trip to Brazil. Southeast Cabo Frio — a beach town in the Região dos Lagos (Lakes Region) of Rio de Janeiro state, about 3 hours from Rio. It is a popular vacation for Brazilians with white sand dunes, amazing beaches, and 17th-century Forte São Mateus. A great spot for windsurfing and kite surfing. It is also combined with a visit to Búzios and Arraial do Cabo Northeast Salvador — Brazil's first capital for two centuries, remains the center of Afro-Brazilian culture and the birthplace of Capoeira. The Pelourinho district is a UNESCO World Heritage Site with 17th- and 18th-century architecture intact. It is known for its week-long Carnival, street food, and the São Francisco Church Lençóis Maranhenses National Park — one of the most impressive landscapes in South America (that you've probably seen on Instagram). Lençóis is made of up of hundreds of miles of massive white sand dunes filled with turquoise and emerald lagoons. It is best visited May–September when the lagoons are full. It is also a bit challenging to get to: you need to first fly to São Luís in Northern Brazil, then a 4–5 hour drive to the gateway town of Barreirinhas South Florianópolis — island city in Santa Catarina with 42 beaches and a reputation as one of Brazil's safest cities. It has a strong surfing culture, world-class kitesurfing at Lagoa da Conceição , and good nightlife Amazon Manaus — city of 2.6 million sitting in the heart of the Amazon rainforest with no road connection to the rest of Brazil. It is the main gateway to the Brazilian Amazon. Book an eco-tour where you can see pink river dolphins, do jungle treks, wildlife spotting, and see the Anavilhanas archipelago, 400 river islands northwest of the city. July–September is the best season to visit"},{"url":"chile/field-notes.html","title":"Chile Travel Guide","text":"Chile Travel Guide General Chile is the long, thin country located on the western edge of South America. Stretching over 4,000km long, Chile is home to some of the most diverse terrain from the driest desert on earth to the glaciers of Patagonia . It is also the safest and one of the most developed country in Latin America. The main reason to come is the Patagonia region in the far South: Torres del Paine and its legendary W Trek are among the best hiking on the continent. I would recommend spending 1.5 to 2 weeks in Chilean Patagonia and combining it with the Argentinean side of Patagonia. You'll likely stop by the capital Santiago which is good to explore for 1 to 2 days. Suggested Route Overview Getting around Flights — the country is enormous and long, so flying between regions is the most efficient way to get around. All flights to Chile go through Santiago For Patagonia, you can fly to Punta Arenas which is cheaper and further south or Puerto Natales which is closer to Torres del Paine National Park Rent a car — the Patagonia region is one of most sparsely populated regions of the world. Roads are wide and have almost no traffic so it is very easy to drive here. Having a car gives you the flexibility to stop at viewpoints and manage your schedule Buses & shuttles — in Patagonia, regular long-distance buses linking major cities Punta Arenas , Puerto Natales and the Torres del Paine trailheads. The distances are big, so plan travel days between the cities Money — the official currency of Chile is the Chilean Peso (CLP). Chile is expensive by South American standards, but particularly the Patagonia region is one of the most expensive regions I've traveled to. Outdoor gear and restaurants are close to U.S. prices, so budget accordingly Language — Spanish is the official language, but English is much more widely spoken than in the rest of South America. Expect everyone in the Patagonia region to speak English Climate — the weather in Chile varies significantly depending on the region. The country is in the southern hemisphere so seasons are opposite of the Northern Hemisphere. Santiago has more mild South American climate Since Patagonia is so far south, the weather is quite unpredictable, never following forecasts and changing multiple times throughout the day. Plan your trip during the short Patagonian summer from December to February. Even in the summer, the weather can be rainy, cold and fiercely windy (with winds up to 60 to 100 mph or 100–160 kmph). Come prepared with real layers Food — Chilean food is very similar to the more famous Argentinean food. It is hearty and heavy. You'll have a lot of steaks, empanadas, wine and try the Patagonian calafate sour , (similar to a pisco sour made with local berries). In the south, the food is more seafood-heavy with fresh fish and king crab Punta Arenas 1–2 days recommended Punta Arenas is one of the Southernmost cities in the world and is a popular gateway to both Chilean Patagonia and Antarctica. It is commonly the departure point for voyages to Antarctica. The town is eerily quiet for a city of over 100,000 people. It felt very sparse and had an odd end-of-the-world feel. I would spend 1 to 2 days to see penguins and what life is like at the end of the world. However, I found the town quite boring even after the first day. What to Do Tierra del Fuego Day Tour — visit the southern most province in the world and see some penguins! If I only had one day in Punta Arenas , this is the activity that I would do: The tour starts with a ferry across the strait to the island of Tierra del Fuego. Even in March when I went, it was freezing cold and hard to stand outside in the morning. On the crossing, you'll likely see the black dolphins unique to this part of the world and whales spouting along the coast Pingüinos del Rey Park — the highlight of this tour was seeing a wild colony of around 120 king penguins which are the second largest species after the emperor penguins. There were orange-and-yellow necked adults and enormous fluffy brown chicks, mostly just standing around. We got to see them from a viewpoint about 400 meters away Tour to Magdalena & Marta Island — an alternative tour is to Magdalena & Marta Island where you can see little Magellanic penguins and sea lions. There is less travel time on this tour and going back, I would likely do this tour instead The tour ends in Porvenir , a strangely deserted fishing village of 5,000 people. It is dotted with colorful wooden houses and is surprising home to a large Croatian population that immigrated to this area in the late 19th century. It is a great place to learn about the indigenous Selk'nam people who used to cover themselves in whale fat to stay warm and faced a dark chapter during colonization Plaza de Armas & the Esplanade — a very European square of white cobblestone and bronze statues. Walk down to the Esplanade overlooking the Strait of Magellan Punta Arenas Cemetery — yes, one of the most exciting things to do in this town is visit the cemetery... It is home to has a grand, Italian-style filled with huge family mausoleums and elaborate stone sculptures which makes it one of the more beautiful cemeteries Museo Regional de Magallanes & Museo Maggiorino Borgatello — the Patagonia region has a distinct history from the rest of Chile. These are some museums worth exploring to learn about the history if you have extra time Where to Eat Restaurant Estilo Magallánico — this may have been the highlight of Punta Arenas. It is an upscale steak restaurant in town. I ordered little cilantro-mayo buns to start and had a juicy sirloin steak with Papas Diablas (cheesy potato wedges with bacon). It was a large meal for around $30, pricey for Chile, reasonable by home standards Where to Stay Hostal Chiloe — a very basic hostel located in the center of town. I met some interesting travelers here with people who just came back from Antarctica or on month long cycling tours around Patagonia ATTRACTIONS 1 Plaza de Armas 2 The Esplanade 3 Punta Arenas Cemetery 4 Museo Regional de Magallanes 5 Museo Maggiorino Borgatello RESTAURANTS & BARS 6 Restaurant Estilo Magallánico ACCOMMODATION 7 Hostal Chiloé DAY TRIPS ↗ Pingüino Rey Park (Full Day) ↗ Porvenir (Full Day) CHILE Punta Arenas Touch to explore Double-tap to open in Google Maps Puerto Natales 1–2 days · base for the W Trek Located about 3 hours north of Punta Arenas , Puerto Natales is the staging town for Torres del Paine. I preferred Puerto Natales over Punta Arenas as it was a lot more lively and had a better feel. I basically spent a day in here before the W Trek (getting ready) and after (recovering from the Trek). I would recommend spending a similar amount of time, 1 to 2 days , here and prioritizing spending time in Torres del Paine National Park . What to Do Gear up — it is very cold and windy in Patagonia . I was on a longer trip 4 month in South America and completely underestimated the weather here so I had to buy additional gear just for Patagonia. There are tons of outdoor shops here that carry high quality outdoor brands at similar prices to back at home. Make sure you buy or rent all the gear: gloves, a buff, waterproof pants, a down jacket and crampons. Here are some outdoor shops that I stopped by: Volkanica Outdoors and Turismo Anita Municipal Historical Museum — a small museum that comprehensively covers the history of the Patagonia region. This was the best museum in Patagonia in my opinion Where to Eat El Brisket — an amazing restaurant with really good soup, brisket, salad and a calafate sour (a pisco sour with local Calafate berries in it) Where to Stay Garden Domes — you have a choice between hexagonal style domes and private cabins overlooking the valley and waterfront. The cabin is very cozy and comes with two bedrooms, a kitchenette, big windows and a hot tub. One of the best places that I've stayed and the hot tub feels incredible after the W Trek Last Hope Hostel — a great comfortable hostel to stay at in town. It was very social and full of people who either finished the W Trek or were starting the O Trek Torres del Paine — W Trek 3 days guided · ~53 miles Hands down, one of the most impressive hikes I've done in the world. You cross through three completely different landscapes in Torres del Paine National Park . Book in advance as there is very high demand for the W Trek and the longer O Trek that follows a similar route. I booked last minute so there weren't many options. I ended up doing an expedited version of the W Trek which squeezes 4 to 5 days of hiking into just 3 days. It is intended for people who are short on time and are open to a more intense experience, but I really enjoyed it! I booked through ChileTour Patagonia and worked with an operator named Gonzalo. The housing, food and logistics were all impeccably planned. A few general tips to help you be prepared for the hike: Bring proper hiking boots with ankle support. The trails can get very muddy and the biggest mistake is not bringing proper footwear. Walking sticks are also very popular option If there's been recent snow, you'll need crampons . Rent them in town or confirm in advance that your company is providing them. I was unlucky with the first day of snowfall in the season and the trails were treacherous without cramp ons Weather is extremely unpredictable even within the same day. Book during the summer and bring many layers that can you can take on and off during the day. Winds can be extremely high and hikers die every year. Take it seriously and follow safety precautions for high winds The sunrises are the most beautiful that I have seen anywhere in the world. The sky glows a bright orange and purple color (like the Patagonia brand logo) so don't miss it! The sunrises pretty late around ~6:30AM to 7AM so make sure you wake up early to catch it Here was the itinerary for my expedited W Trek tour . We hiked the entire W Trek in just 3 days (~70km or 43 miles). It is a great option for those short on time, but I would recommend choosing a longer option since doing the hike in 3 days felt very rushed. The tour also includes an arrival day with a dinner as well as one night back in Puerto Natales , making the total trip 5 days long. As a solo traveler, it was also great to have a group to hike with and logistics planned in advance. Day 1 — Arrival in Puerto Natales Arrive to Puerto Natales and check into the accommodation for the night at Garden Domes . Settle into your lodging and use the afternoon to explore town. The tour leader does an evening briefing that walks through each day's route in great detail on a map. There are not many different trails so it is actually very hard to get lost in Torres del Paine National Park . It is followed by a welcome dinner where you get to meet the others on the trip. Rest up, because the next three days are long Day 2 — Torres Base (11 Mi / 19km, ~8hrs) The day starts with a drive to Refugio Chileno . In the parking lot, we saw quite a few guanacos, the wild llamas native to Patagonia. The first day is guided with a local hiking tour guide who does the exact same hike every day. You walk along the river through a pine forest, then up steep, wet granite. Snow came down as we climbed so the final section was icy and sketchy without crampons. The reward on the first day was the three iconic rock pillars ( Las Torres ) that tower over the bright-turquoise, Laguna Torre . If you're lucky, you'll get a clear view. However, due to the high elevation, there is constantly fog blowing over the towers so take your photos the instant the sky opens: ours closed again within two minutes The rest of the day is spent hiking back the same way to return to Refugio Chileno . The accommodation for the night was a small cabin with an amazing view of the towers in the distance. Our cabin was located next to Estancia Laguna Amarga , a grassy field with highest concentrations of Pumas in the world! Pumas are notoriously hard to track down and we weren't lucky enough to see one ourselves Day 3 — Grey Glacier (13.6mi / 22km, the longest day) Billed as the \"easy\" day due to lack of the elevation, but actually the longest. We started with a hike through a foggy valley between two mountains, past waterfalls and then to Lago Grey . It is home to the enormous Grey Glacier : a perfectly straight wall with spiky blue tops, and floating icebergs glowing blue from trapped air. There wasn't a single other hiker when we were there so we had it all to ourselves. This day was a bit of a rushed day trying to get to Grey Glacier before it closes at 3pm and trying to get back to camp before it was dark We finished the hike around 5pm. Our accommodation was pre-set camp at Refugio Paine Grande on the lake. At night, the mix of wind, cold and rain while camping outside in a tent was freezing. There is an option to stay indoors in a dorm at Refugio Paine Grande if you want to be more comfortable. The Refugio offers a buffet dinner. The food isn't great, but anything tasted amazing after a second full day of hiking Day 4 — French Valley (20.3km) The highlight of the trip was the sunrise which glows a bright orange color over the lake with the mountains in the backdrop. The sunrises later in the deep Southern Hemisphere so wake up around 6:30AM or 7AM to catch it Take the morning easy and grab breakfast from the Refugio Paine Grande . Then head out on the hike for the day: It starts with an easy flat first half through an eerie, beautiful valley of dead trees, then a long suspension bridge and a steep climb to the French Valley lookout and Mirador Británico . There glaciers on both sides with avalanches happening every 15 minutes (which sounds like a cannon being fired) and the iconic flat Torres in the background We stopped at Mirador Británico and hiked back to Campamento Italiano . Here you catch the last ferry for the day at 5:30pm across Lago Pehoé . It is a beautiful ride and takes 45 minutes to get to a stop Pudeto . We then took a 2 hour bus back to back to Puerto Natales to spend the night and had a final goodbye dinner Day 5 — Return to Puerto Natales The trip ends with a final breakfast at Garden Domes . I had one final day in Puerto Natales , mostly spent recovering from the long days of hiking. I also decided to explore the town a bit and saw the Plaza de Armas and its cathedral, and walked the lakefront for sunset. Walk out to the old broken pier named Muelle Braun & Blanchard for the classic Puerto Natales photo spot From here, you can continue on to the Argentinian side of Patagonia. From a logistics standpoint, it makes sense to cross the border from Puerto Natales to El Calafate (roughly 4 hours by bus) and do the entire Patagonia region in one trip. Read my field notes on El Calafate and El Chaltén here . Santiago 1–2 days recommended You'll likely fly through Santiago the capital of Chile if you're visiting the country. I was told not to spend much time here by other travelers and even many Chileans I met. Santiago is a bit more run-down and lacks as many historical sites compared to other South American capitals. However, I thought it was a decent stop for a day or two to check out the capital of Chile on my way back from Patagonia. What to Do Cerro Santa Lucía — the highlight of Santiago was Cerro Santa Lucía , a lush, green hilltop park in the middle of the city. It is worth exploring for a couple of hours to see the castle ruins, winding stone stairs, fountains and viewpoints The Terraza Neptuno at the top is the most beautiful part with a two-story fountain with statue of the Roman god Neptune. The fountain likes under palm trees and a huge Chilean flag and felt very European Plaza de Armas & Catedral Metropolitana — the historic heart of Santiago, founded by Spanish conquistador Pedro de Valdivia in 1541. The square is a lively open space ringed by colonial-era buildings, street performers, chess players and vendors. One of the few remaining historical parts of Santiago Centro Cultural la Moneda (CCM) — a large underground cultural center directly beneath La Moneda Palace. Hosts rotating international exhibitions across two main gallery halls and the National Film Archive La Moneda Palace — the grand neoclassical presidential palace that takes up an entire city block in the center of Santiago, originally built as a colonial mint in 1784. The courtyard is open to the public and the changing of the guard takes place on the forecourt every other day. The walk over from Plaza de Armas passes a colorful pedestrian art street called Paseo Bandera lined with murals Barrio Italia & Barrio Lastarria — two walkable neighborhoods full of cafés and restaurants if you have extra time Where to stay Park Plaza Apart Hotel — a small boutique hotel located in the heart of downtown Santiago. I booked a loft apartment for ~$50 USD which was a great value for the space ATTRACTIONS 1 Cerro Santa Lucía 2 Plaza de Armas 3 Catedral Metropolitana 4 Centro Cultural la Moneda (CCM) 5 La Moneda Palace 6 Paseo Bandera ACCOMMODATION 7 Park Plaza Apart Hotel CHILE Santiago Touch to explore Double-tap to open in Google Maps Other Places to Consider My last trip to Chile was most focused on Patagonia, but Chile stretches across almost every climate on earth. Here are some other locations worth considering: Atacama Desert — the driest desert in the world in the far north. Base yourself in the town of San Pedro de Atacama to visit the geysers, salt flats and flamingo lagoons. There is some of best stargazing here and the photos online look unreal Easter Island (Rapa Nui) — the remote Pacific island that is home to the giant moai statues. It is a five-hour flight from the mainland. I ultimately decided not to visit due to the price and time commitment Valparaíso — a colorful, bohemian port city of steep hills, funicular lifts and street art. It is an easy trip from Santiago The Lake District — located an 11 hour drive south of Santiago , visit the towns of Pucón and Puerto Varas . The Lake District is home to some impressive volcanoes, lakes and hot springs. This came most recommended by Chileans that I've met on my travels"},{"url":"colombia/field-notes.html","title":"Colombia Travel Guide","text":"Colombia Travel Guide General Colombia is one of the most rewarding countries to travel in South America and has completely reinvented itself over the last two decades. Once defined by the violence of the Pablo Escobar era, it has become one of the continent's most exciting destinations, though that recent history is still very much part of the experience. The country is enormous and incredibly diverse, running from Caribbean beaches and colonial walled cities up into the Andes Mountains and down into the Amazon Jungle. Most trips string together a few very different regions: the mountain metropolis of Medellín , the colorful Caribbean coast around Cartagena and Santa Marta , and the coffee-covered hills in between. It's affordable, the people are famously warm and the nature is genuinely gorgeous. Suggested Route Overview Getting around Flights — Colombia is a big country, so it's worth flying between distant regions to save a full day of travel. Avianca and LATAM cover the main routes along with budget carriers like Wingo and JetSmart. Build in buffer time, I experienced significant delays when flying Avianca and LATAM on almost every flight Ridesharing — Uber works well and is cheap in the big cities (Medellín, Cartagena), though it's in a legal grey area so you may be asked to sit up front. It's unreliable or unavailable in smaller towns like Santa Marta, especially at night so always have a backup plan Buses — long-distance buses connect all the major cities and are the budget option. I used BusBud to book online and there were all the major routes available For shorter hops you'll use local buses and colectivos (shared vans). In small towns, stops aren't always marked, so ask your accommodation or a local (Colombians were always very helpful!) Boats — if you're headed off to any of the Colombian Caribbean islands such as the San Bernardo Islands , you can typically take a speedboat from Cartagena's port. Boats can be booked in advance online depending on your destination. I'll provide more specific details in the San Bernardo section Money — Colombia uses the Colombian Peso (COP) and is very affordable outside of upscale restaurants. Local meals, transport and tours are all cheap. Cards are accepted in the cities, but carry cash for small towns, street vendors, markets and the islands Food — Colombian food is hearty, corn, cheese and meat heavy and cheap. A few staples to look for: Arepas — grilled corn cakes stuffed with cheese, egg or shredded beef. The cheapest meal you can find on almost every street corner Empanadas — Colombian Empanadas are fried rather than baked, which gives them a crispy, samosa-like shell Bandeja Paisa — the enormous Antioquian platter including beans, rice, fried egg, plantain, chicharrón, sausage and an arepa Mondongo — a yellow tripe soup served with rice, arepa and avocado that you mix together as you eat. Especially popular in Medellín Language — as with anywhere in Latin America, Spanish is the official language. English is very limited outside of tourist areas Safety — Colombia has come a very long way from its dangerous reputation. However, it is still important to be careful as the country has its own set of security issues and pickpocketing. The local Colombian saying is \"no dar papaya\", meaning don't give anyone the opportunity to take advantage of you. Do not wear jewelry, be very careful with your phone and stick to tourist areas since pickpockets target Western tourists. I was very cautious and had no issues personally, but many people in my hostels had their phones stolen How long to stay — Give yourself 3 to 4 weeks to comfortably cover Medellín, the Caribbean coast (Cartagena, the islands and Tayrona) and a stop in the coffee region. You could easily spend longer. Colombia combines well with Ecuador or a longer South America trip Medellín 3–4 days recommended Medellín is a city that completely exceeded my expectations. Nestled in a lush valley in the Andes, the city has transformed itself from one of the world's most dangerous cities in the 1990s into one of the best destinations in Colombia. Today, it's known for its vibrant nightlife, thriving café scene, and street art, while also offering a fascinating look into Colombia's recent history, from the legacy of Pablo Escobar to the remarkable transformation of the Comuna 13 neighborhood. Add on that the charming historic town of Guatapé is just a short day trip away. I recommend spending 3–4 days in Medellín to experience the city completely. Most visitors stay in the El Poblado neighborhood, which is safe has the best selection of hotels, restaurants, and nightlife. What to Do Learn about the dark history of Pablo Escobar — Medellín is a city shaped forever by the reign of terror of Pablo Escobar in the 1990s. To this day, locals in Medellín avoid mentioning his name and he's sometimes referred to as \"he who is not to be named.\" The best way to learn about this history is through a guided tour to have a local to explain the history to you and take you around the entire city of Medellin. I found the tour to be absolutely fascinating, and it stopped by 4 main spots tied to Pablo Escobar: Inflexión Memorial Park — he built a bomb-proof Monaco building here. It has since been demolished and a memorial park to his victims has been built here La Catedral — when Pablo Escobar was finally \"arrested\" by the Colombian government, he made an agreement with the Colombian authorities where he was allowed to build a prison for himself. He built La Catedral a massive hillside mansion where he hosted celebrity parties, beheaded employees and could leave freely. It had since been mostly destroyed, but you can visit parts of the site Cancha El Dorado — the next stop was a soccer field in his home neighborhood of Envigado . He built things all over the country and buried a stockpile of cash and weapons in this unassuming location. After he died, Colombians had a frenzy of digging holes everywhere around the country to look for his hidden stockpiles of cash Montesacro Cemetery — the final stop was the cemetery where he's buried along with his family and other famous Cocaine traffickers like Griselda Blanco. The cocaine trade today is 4 times the size of what it was when Pablo was running it. However, there are \"unofficial\" agreements with the government look away in exchange for a reduction of the level of violence Comuna 13 — spend a half day in the neighborhood of Comuna 13. It went from one of the most dangerous neighborhoods in the world to now being safe after gang leaders were arrested and the next generation moved on. It is covered in street art with break dancers, souvenir shops and former gang members performing and telling their stories. The street art is great, visit the local basketball court and the viewpoint from the top of the hill is legitimately great However, from a true social change perspective, the neighborhood felt a bit disingenuous to me. Some critics argue this clean up of Comuna 13 is largely window dressing, highlighting visible improvements to voters and tourists while poorer residents were kicked out of the area and deeper social issues of poverty and violence remained elsewhere in the city. However, it is an interesting visit to learn the stories of the locals that genuinely benefited from the changes Plaza Botero — the historic downtown plaza home to 23 bronze sculptures donated by Colombian artist Fernando Botero, set against the striking Rafael Uribe Palace of Culture . Botero is one of Colombia's most celebrated artists, known for his distinctive style of depicting people and animals with exaggerated, rounded proportions. Once you see one Botero sculptures, you'll start to notice them all over the world (I've seen them in NYC, Barcelona, Monaco and even Armenia!) Museo de Antioquia — Medellín's main art museum, right on Plaza Botero, holding the largest collection of Botero's paintings and sculptures Casa de la Memoria — a free museum exploring Colombia's decades-long armed conflict, including guerrilla warfare, paramilitary violence, and the rise of the drug cartels. Through personal stories and multimedia exhibits, it offers a sobering look at Medellín's past and the human cost behind the headlines. The exhibits are mostly in Spanish, but there is an English audio guide available San Antonio Plaza — square with the famous \"Bird of Peace\" Botero statue that was partially blown up by a bomb in the war between Pablo Escobar and the Cali Cartel. There isn't much else in this area so you should skip it if you're short on time in favor of Plaza Botero Go to a Colombian Fútbol match — Going to a Fútbol match in Latin America is a quintessential experience and Colombia is no exception! I went with a large group from our hostel to a match in the Atanasio Girardot Stadium . We watched the Deportivo Independiente Medellín team play Cali from the ultras section and it was quite an experience when the match ended with riot police shutting it down. I would highly recommend as Colombian fans bring an incredible energy to the game. Jardín Botánico / Parque Arví — a free botanical garden near the university and a huge forest reserve reached by the scenic Metrocable. Both beautiful green escapes from the bustling city of Medellín, though I didn't get to go Mirador de Las Palmas — a lookout on the road climbing out of the city, with a sweeping view over the valley. At night, the valley lights up providing for an amazing view Guatapé Day Trip — the most popular day trip from Medellín (about 2 hours each way): a really colorful colonial Spanish town downtown, beautiful waterways, and the towering Piedra del Peñol rock. It was a very pretty day trip, but expect it to be busy and a bit touristy. Here is the tour that I booked Guatapé town — one of the most colorful Spanish colonial towns that I've seen. The Guatapé is covered in beautiful little details including tile art on every building showing what the business does and a famous fountain with 4 little men in sombreros holding small hoses. A great place to wander around for a couple of hours and take pictures Boat tour around Peñol-Guatapé Reservoir — There was a short boat tour on a pontoon taking you around the Peñol-Guatapé Reservoir. It is a popular place for wealthy residents of Medellín to have vacation homes and you'll see some interesting sites including one of Pablo Escobar's many mansions Piedra del Peñol Rock — the final stop is a massive rock with over 740 steps to the top. The stone is so large that it was originally thought to be a meteorite. One man climbed it with just rope and a plank of wood over the course of 4 days, built stairs on it and it has since become a popular tourist attraction. Once you're at the top, there is a view of the valley below with the reservoir branching into the landscape, eagles circling below, and a rainbow even appeared when we were up there Where to Eat Ajiacos y Mondongos — Colombian stews are a massively underrated part of the cuisine and the best place to try them is Ajiacos y Mondongos. It was one of my favorite restaurants in Colombia. If you're feeling adventurous, try Mondongo , the local favorite yellow tripe soup with bits of beef, served with an arepa, rice and avocado Alambique — a fancy upscale cafe in El Poblado hidden in an unsuspecting building Las Monas Restaurante — a no-frills, traditional Colombian restaurant located in El Poblado Cafe 11:11 El Despertar — a small rooftop cafe with good coffee Where to Drink Parque Lleras — the heart of El Poblado's nightlife, a square ringed by bars and clubs that spills out into the surrounding streets. The go-to spot for a night out Where to Stay The best place to stay is El Poblado , a leafy, upscale neighborhood with the most hostels, restaurants and nightlife. It is very gentrified, catering to tourists with a lot of international restaurants. However, it is a very safe place to base yourself in the city Los Patios Hostel — a large hostel known for good parties and a cool rooftop. It was clean and offered a lot of tours and social events to meet other travelers Masaya Hostel — another large hostel with a better rooftop pool and bar. I had a great time visiting and the facilities seemed to be nice, complete with a coworking space ATTRACTIONS 1 Comuna 13 2 Inflexión Memorial Park 3 the viewpoint from the top of the hill 4 Plaza Botero 5 Museo de Antioquia 6 Casa de la Memoria 7 San Antonio Plaza 8 Atanasio Girardot Stadium 9 Jardín Botánico 10 Mirador de Las Palmas RESTAURANTS & BARS 11 Ajiacos y Mondongos 12 Alambique 13 Las Monas Restaurante 14 Cafe 11:11 El Despertar 15 Parque Lleras ACCOMMODATION 16 Los Patios Hostel 17 Masaya Medellín DAY TRIPS ↗ Guatapé & Piedra del Peñol (Full Day) COLOMBIA Medellín Touch to explore Double-tap to open in Google Maps Cartagena 2–3 days recommended Cartagena is Colombia's Caribbean showpiece with a walled colonial city of bright buildings, flower-draped balconies, horse carriages and some serious heat. Base yourself in the picturesque old town to explore most of the historical sites in the walled city and make your way to the nearby hip Getsemaní barrio. Cartagena is also the launch point for boat trips out to the San Bernardo Islands or longer trips to the San Blas Islands in Panama. Cartagena's old town can easily be explored in 2 days and add on extra days to make a trip to the San Bernardo Islands. What to Do Centro Histórico de Cartagena — one of the most picturesque parts of Colombia showcasing its colonial history. It is very compact and walkable and gets crowded during the day from large cruise ships. Despite the polished exterior of the city, I found it to be a bit sketchy at night with strange characters and drug dealers following you Puerta del Reloj — the iconic yellow clock-tower gate, the main entrance into the walled old town Walls of Cartagena de Indias — walk the thick 16th-century stone walls that wrap the old town. Make sure to catch the sunset from the walls and a drink at Café del Mar for the classic Cartagena moment Parque de Bolívar — a shady, palm-filled plaza with a Bolívar statue at the center of the old town. It is a good place to escape the heat Cathedral Santa Catalina de Alejandría — Cartagena's landmark cathedral, instantly recognizable by its ochre-colored bell tower rising above the rooftops of the old town Las Bóvedas — colonial dungeon vaults built into the walls, now handicraft and souvenir shops Museo del Oro Zenú — a small, free gold museum showcasing the intricate goldwork of the indigenous Zenú people Getsemaní — the hip barrio with great street art and bars. Getsemaní feels like a cross between the old town buildings and the vibe of Comuna 13. It is super compact with banners, flags and kites hanging overhead, bright colorful buildings, tons of street art. I enjoyed that it was not overcrowded, more of a locals scene Plaza de la Trinidad — the social heart of Getsemaní, locals and travelers gather on the church steps in the evening with street food and drinks Parque Centenario — right next to Puerta del Reloj is an unassuming local park. Make sure to look up to catch the sloths and monkeys playing around with each other San Felipe de Barajas Fort — the massive hilltop Spanish fortress guarding the city, with a maze of tunnels you can explore. Sunset on the wall is also incredible Convento de La Popa — a 17th-century convent on the city's highest hill with the best panoramic viewpoint over Cartagena Where to Eat Restaurante 1595 — my favorite restaurant in Cartagena. It is a hidden restaurant with an unsuspecting doorway leading to a Spanish colonial courtyard. I ordered the menu del día called Criollo. On the day I was there, it was Mote de Queso , a porridge with paneer-like cheese and bits of meat, served with rice and avocado Restaurante La Mulata San Felipe — a spot in the Getsemaní neighborhood serving Caribbean food. I got the shrimp rice with patacones (fried smashed plantain cakes) Mirador Gastro Bar — if you're looking for a good night out, this is the place to be in Cartagena. All the backpackers gathered here and there was a great DJ and view of the Clock Tower at night Where to Stay Viajero Cartagena — a great hostel that is part of the Viajero chain. There was a great pool in the courtyard and lots of social activities including a free group salsa dancing class ATTRACTIONS 1 Puerta del Reloj 2 Walls of Cartagena de Indias 3 Café del Mar 4 Parque de Bolívar 5 Cathedral Santa Catalina de Alejandría 6 Las Bóvedas 7 Museo del Oro Zenú 8 Plaza de la Trinidad 9 San Felipe de Barajas Fort 10 Convento de La Popa RESTAURANTS & BARS 11 Restaurante 1595 12 Restaurante La Mulata San Felipe 13 Mirador Gastro Bar ACCOMMODATION 14 Viajero Cartagena DAY TRIPS ↗ San Bernardo Islands (Full Day) COLOMBIA Cartagena Touch to explore Double-tap to open in Google Maps San Bernardo Islands 2 nights recommended The San Bernardo Islands are a cluster of tiny Caribbean islands a couple of hours by speedboat from Cartagena. People do day trips from Cartagena , but my friends who did these tours didn't like them. The best reason to come is Casa en el Agua , a hostel sitting alone in the middle of the city built on. You'll spend your days sunbathing, snorkeling, island-hopping and partying at night. It's completely off-grid, so come ready to disconnect. The place recently got famous on Instagram so it completely books out 2 to 3 weeks in advance (book here ). The Accommodation Casa en el Agua is a floating island hostel. It is a tiny 2 story building with both private and dorm rooms. It is surrounded by crystal clear waters and there is a common area where everyone hangs out. There are also family style dinners where a conch shell is blown before every meal to call everyone together. You'll get to know everyone staying there super well One boat arrives and departs everyday. You'll pull up to a group of people doing a silly dance (very cult-y vibes at first) and do the same for the next group of arrivals. Book your boat online with Tranq It Easy Boats and expect it to cost $50 round trip from Cartagena It is very popular so it is expensive for Colombian standards. The place runs on a wristband system where you rack up a tab for drinks, tours and extras and pay everything at the end. Expect to pay ~$50/day depending on how much you order Remember, it is a floating eco-hostel in the middle of the water so expect dry toilets, 3-minute showers 6–9pm only and no Wi-Fi. I would recommend staying 2 nights . It is very small so any more time would be boring What to Do Casa en el Agua offers a number of interesting tours to help break up the time spent just laying in the sun. They are relatively affordable so I ended up opting to do all of them: Santa Cruz del Islote — most densely populated island in the world. There are 800 people living on a tiny island roughly the size of two soccer fields. 100+ of them descendants of one man named Pepe who had 5 wives. There is one school, one bar, one doctor and the whole place runs on solar panels and rainwater collection. It is a quick hour long visit and the tour ends at their tiny concrete aquarium with nurse sharks, sea turtles and sunfish Mangrove snorkeling — take a small boat into the waterways surrounded by Mangroves nearby. The saltwater is incredibly buoyant so you barely have to even kick. It is a unique ecosystem with swim through clouds of tiny shrimp and blue coral growing off the roots of the Mangroves Plankton tour at night — a short tour done in total darkness. You can swim in the water and every time you move your hands and feet in the dark water, it looks like electricity going off your body Santa Marta & Tayrona 2–3 days recommended Santa Marta is a port city along the Caribbean Sea that most travelers use as the gateway to the famous Tayrona National Park , where the jungle tumbles straight down to Caribbean beaches. The highlight is hiking into the park and sleeping in hammocks right by the beach. I also stayed in a hostel embedded in the jungle which was an unexpected highlight of the trip. I would recommend spending 2 days in Tayrona National Park and a day in Santa Marta as a stopover. There wasn't much to see in Santa Marta, but it was nice to experience an authentic Colombian city lived in after the more touristy Cartagena. What to Do Cabo de San Juan — one of the most beautiful beaches and iconic spots in Colombia where the dense jungle of Tayrona National Park meets the Caribbean Sea. The only way to get there is to hike is 2–3 hours through the jungle, past massive grey stones and gorgeous palm-lined beaches. There are also people offering horse rides to Cabo de San Juan if you're not up for a hike When you finally get to Cabo de San Juan, there are gorgeous beaches, a few restaurants and the famous watchtower overlooking area. You can actually sleep in the National Park in the watchtower hammocks with the waves crashing in the background (although it was probably one of the worst nights of sleep I've ever had). Hammocks are available on a first-come first-serve basis so make sure you arrive before it fills up. The alternative is to stay in the many cabins nearby which is probably a lot more comfortable Spend the day walking around or relaxing on the beach. You can wake up to watch the sunrise over the water before hiking back the next day Where to Stay The Valley Tayrona Hostel — one of my favorite hostels of all time. It is a really beautiful wooden hostel sitting right over a Valley embedded right in the middle of the jungle. There are wooden platforms, hammocks and pools to relax in. It was a gorgeous place to watch the sunset over the green jungle as well. The hostel was so deeply embedded in the jungle that I was woken up to the sound of Howler Monkeys each morning! It was a fun adventure to get there as well combining both a chicken bus and moto-taxi, but well worth it (or you can just hire a taxi...). To get there take local chicken bus from Mercado Público in Santa Marta to Trompito Alto . You need to tell the bus driver to stop by \"Trompito Alto.\" I got a bit of a rush being the only foreigner on the bus going deep into the Colombian jungle! They'll drop you off on the side of the road and then there will be dirt bike moto-taxis waiting to take you to the hostel. Be prepared for an extremely bumpy ride that crosses through three creeks and a super sketchy suspension bridge missing planks. It feels like you're in the middle of nowhere in the Colombian jungle, but you'll be greeted by a very comfortable hostel with a bunch of other backpackers who also miraculously made it there. Here is the hostel's official How to get here page for more detailed instructions Viajero Santa Marta — a new Viajero hostel in the town of Santa Marta. I stayed in Viajero hostels all over South America and they were always a reliable option. It is a great place to stay before heading to Tayrona. The staff was helpful and gave solid directions for the public bus Other Places to Consider Colombia is huge and I only scratched the surface. Didn't make it to these, but they came up a lot with other travelers and are where I'd go next time: Bogotá — the high-altitude capital of Colombia; It's known for its historic La Candelaria district, the Gold Museum and the Monserrate viewpoint. However, it is less popular as a tourist destination than Medellín or Cartagena Salento & the Coffee Region — Colombia's coffee heartland ( Zona Cafetera ), is known for coffee farm tours and the towering wax palms of the Cocora Valley San Andrés Islands — a Colombian Caribbean island closer to Nicaragua, popular for its \"sea of seven colors\" and diving. To get there, take a 1.5 hour flight from Colombia and Panama City. It is known to be the most expensive place in Colombia due to its remoteness Cali — Colombia's salsa capital, known for its vibrant nightlife, world-famous salsa dancing, and warm climate. It's also a gateway to the Pacific region and offers a more local, less touristy atmosphere than Medellín or Cartagena"},{"url":"croatia/field-notes.html","title":"Croatia Travel Guide","text":"Croatia Travel Guide General I loved Croatia so much that I went twice in one summer! As my introduction to the Balkans (one of my favorite regions to travel in the world), Croatia will always have a soft spot in my heart. The Dalmatian coastline is one of the most rewarding stretches of coastline in Europe: a thin ribbon of walled medieval towns, Roman ruins, an archipelago of pine-covered islands and impossibly blue Adriatic water. It has become hugely popular (thanks in no small part to Game of Thrones ), but it's popular for good reason, and it's still easy to find quieter corners once you get off the main track. These notes cover the Dalmatian coast, where I spent my time: Split as the hub, the walled city of Dubrovnik in the south, and the island of Hvar . It's an easy region to island-hop and pairs naturally with Bosnia (an easy day trip to Mostar ) or Montenegro just across the southern border. Be sure to read my articles on those countries if you're planning to visit. Suggested Route Overview Getting around Flights — the main coastal airports are Split and Dubrovnik , with Zagreb inland. All are well connected across Europe in summer so choose whichever airport is convenient for your travel route Buses — the best way to travel along the Croatian Coast. FlixBus and Arriva run frequent, comfortable and cheap services between Split, Dubrovnik and the smaller towns. There are limited trains in this part of Europe so buses are often more practical. I use traveling.com to book buses Ferries & Catamarans — Many companies offer run car ferries and fast passenger catamarans out to the many of islands Croatia, primarily from Split and Dubrovnik . Book island catamarans in advance in peak summer as popular routes sell out. Ferryhopper was a reliable resource to book ferries Ridesharing — Uber and Bolt both work well in major cities like Split and Dubrovnik . They are usually cheap and you can avoid the hassle of haggling with taxi drivers Car rental — worth it for exploring the coast, the national parks ( Krka , Plitvice ) and the island interiors at your own pace and the coastal drives are gorgeous. The one catch is that there is limited parking in many of the cities and Croatians can be crazy drivers at times Food — Dalmatian cooking is Mediterranean and seafood-heavy, with a strong Italian influence. It was interesting to sample different dishes and there were still many of the Balkan staples like Ćevapi & Burek . Crni rižot — a black squid ink risotto and one of the most popular dishes along the coast. It's rich, but not overly fishy Pašticada — the classic Dalmatian special-occasion dish: beef marinated for a day, then slow-braised for hours in a rich, subtly sweet sauce of red wine, prošek , prunes and herbs, traditionally served over homemade gnocchi. It's my favorite Croatian dish that you won't find in other Balkan countries. Every family and restaurant has their own version of Pašticada Peka — a wonderful slow-cooked feast where lamb, veal or octopus and vegetables cook for hours under a heavy bell-shaped metal lid buried in glowing embers, leaving everything tender and faintly smoky. It's a proper occasion, usually ordered a day ahead for a group, and one of the most memorable meals you can have in Croatia Ćevapi & Burek — the cheap, delicious Balkan staples that'll fuel a budget trip: ćevapi are little grilled minced-meat sausages served in fluffy flatbread with raw onion and ajvar (red-pepper relish), and burek is a coil of flaky filo stuffed with meat, cheese or spinach. Both are filling, cost a few euros, and you'll be able to find them anywhere Language — the official language is Croatian (very similar to Serbian, Montenegrin & Bosnia). English is widely and confidently spoken all along the coast, so getting around is very easy Money — Croatia recently adopted the Euro in January 2023. The coast is noticeably pricier than the interior, and Dubrovnik and Hvar in particular get expensive in peak summer How long to stay — I'd budget 7–10 days for a coastal Croatia trip: start in Split, go to an island or two and then Dubrovnik. You can also easily combine Croatia with other countries in the Balkans like Slovenia , Bosnia or Montenegro Split 2–3 days recommended Split is the beating heart of Dalmatia and the best base on the coast: its entire old town is built inside a 1,700-year-old Roman palace, and it's the main ferry hub for the islands. It's lively, walkable and well set up for backpackers, with beaches, viewpoints and a string of good day trips right on its doorstep. There is something special about Split beyond the monuments and sights that I can't quite capture in words. I had an absolute blast the two times I visited. I would recommend spending 2 to 3 days here or longer if you just want to relax and soak in the Croatian sun. What to Do Diocletian's Palace & Old Town — built around AD 305 as the retirement residence of the Roman Emperor Diocletian , this vast palace is one of the best-preserved Roman monuments in Europe. After the fall of the Roman Empire, locals took refuge within its fortified walls, gradually transforming the palace into the city of Split. Today, ancient Roman temples, gates, and courtyards sit alongside cafés, restaurants, shops, and apartments, making it one of the most fascinating and unique old towns in Europe Cathedral of Saint Domnius — originally built as Diocletian's mausoleum nearly 1,700 years ago, it is one of the world's oldest cathedrals still in use. Climb the bell tower for sweeping views over Split's terracotta rooftops and the Adriatic Sea Split Golden Gate — the grand northern entrance to Diocletian's Palace, where Roman emperors once entered the city. Today it's one of the palace's most impressive entrances in the city and home to the towering statue of Gregory of Nin just outside the walls Riva promenade — Split's wide, palm-lined seafront promenade is the highlight of the city and runs along the harbor beneath the old palace walls. It is the social heart of the city. During the day, it is a great place for a stroll by the water. In the evening, everyone comes out for dinner along the water, an evening stroll and watch the sun set over the ferries Republic Square — while walking on the promenade, stop at a grand 19th-century square modeled after Venice's Piazza San Marco, surrounded by elegant arcaded buildings. It's a lively gathering place filled with cafés and frequently hosts concerts and festivals Marjan Hill — the big pine-forested hill and nature park rising right behind the old town, laced with walking and cycling trails, tiny hermit chapels and rocky swimming coves on its flanks. It's an easy climb up to the viewpoints for a sweeping panorama over the terracotta rooftops, harbor and islands, and it's the locals' escape for a jog, a swim or a sunset Klis Fortress — a dramatic medieval fortress straddling a rocky ridge just above Split, guarding the mountain pass inland for 2,000 years (and doubling as the city of Meereen in Game of Thrones ). Walk the ramparts and towers for sweeping views down over the city and coast, and stop at one of the nearby restaurants famous for spit-roast lamb. Located just 20 minutes outside of Old Town split, it is easy to reach by local bus or Bolt Krka National Park — a popular day trip from Split to a series of wide waterfalls tumbling through a green river canyon. It's beautiful and generally a touch less mobbed than Plitvice Lakes National Park , with boardwalks winding right past the cascades. Swimming by the main falls is no longer permitted, so come for the scenery and a short walk Blue Lagoon & Island Boat Tour — a full-day boat trip out to the Blue Lagoon , a shallow, crystal-clear turquoise bay perfect for swimming and snorkeling. Tours usually stop at the city of Trogir and other islands along the way. Book online here or you can also easily book from the harbor the day before Trogir — a tiny old town on an islet just west of Split, packed with narrow Venetian streets and a beautiful cathedral. An easy half-day trip by local bus and a common stop on the island boat tours Croatian National Theater in Split — Split's striking yellow Neo-Baroque theater, opened in 1893, hosts opera, ballet, drama, and concerts. Even if you don't catch a performance, it's one of the city's most beautiful buildings Beaches — the water of the Adriatic is incredibly blue and crystal-clear. However, expect beaches in Croatia to be pebbly, rocky or sometimes just a dock Plaža Ježinac — a quiet pebble beach just west of the old town, popular with locals and a great spot for a swim without venturing far from the city center Kasjuni Beach — Split's most scenic beach, tucked beneath the forested slopes of Marjan Hill . Its crystal-clear water, relaxed beach bars, and views of the nearby islands make it one of the city's best places to spend a summer afternoon Cliff jumping — if you're feeling more adventurous, Split is a great spot to go cliff jumping since most of the shoreline is rocky. Head to the rocks along the coast just east of the old town (a short 20-minute walk), where there are various heights for different comfort levels Where to Eat Zalogajnica Dioklecijan — my favorite restaurant in Split, run by a wonderfully sassy old lady (check the reviews). It's hard to find, tucked upstairs behind some alleyways, but worth it for genuinely authentic Croatian home cooking and an outdoor area overlooking the harbor. The stuffed bell peppers with ground beef and potatoes are excellent Mlinar — a popular bakery chain that you'll see everywhere in Croatia. It is a great place to stop for a pastry and a coffee in the morning for breakfast. In Split, there is a location right by the Golden Gate entrance to the city ST Burek — a no-frills bakery doing great, greasy burek (flaky filo coils stuffed with your choice of meat, cheese or spinach) for a couple of euros. It is the perfect cheap, filling breakfast or late-night bite. You'll learn to love Burek on any trip to the Balkans Kebab House — exactly what it says: amazing, generously stuffed and very cheap kebabs. The portions were massive for just a few euros Where to Drink Charlie's Bar — the main backpacker bar in Split, a friendly spot with cheap drinks, located right in the old town. The hostel bar crawls all funnel through here, so it gets rammed and rowdy in high season, and it's the easy place to meet people Split is known to be quite the party town. I really enjoyed Disco Club 305 A.D. and Boiler Club . Join the bar crawl if you're looking to socialize and meet other backpackers Where to Stay Booze & Snooze Social Hostel — right the middle of the old town is Booze & Snooze Hostel and a very social hostel that runs its own crawls and events. It is a true party hostel where you'll get to know everyone who is staying there. Expect it to be loud, a bit dirty and not a place to get a good night's sleep, but a had an absolutely amazing time and it felt like a little family vibe when I stayed there Cornaro Hotel — this is the exact opposite of the previous entry! Cornaro Hotel is an exquisite 5 star hotel with very comfortable rooms and a wonderful view from the rooftop, complete with a bar, jacuzzi and rooftop pool ATTRACTIONS 1 Diocletian's Palace 2 Cathedral of Saint Domnius 3 Split Golden Gate 4 Riva promenade 5 Republic Square 6 Marjan Hill 7 Croatian National Theater 8 Plaža Ježinac 9 Kasjuni Beach RESTAURANTS & BARS 10 Zalogajnica Dioklecijan 11 Mlinar 12 ST Burek 13 Kebab House 14 Charlie's Bar ACCOMMODATION 15 Booze & Snooze Social Hostel 16 Cornaro Hotel DAY TRIPS ↗ Klis Fortress (Half Day) ↗ Trogir (Half Day) ↗ Krka National Park (Full Day) ↗ Blue Lagoon Boat Tour (Full Day) Croatia Split Touch to explore Double-tap to open in Google Maps Dubrovnik 2 days recommended Dubrovnik is the \"Pearl of the Adriatic\": a perfectly preserved walled city of marble streets and terracotta roofs jutting out into the sea. It is instantly recognizable as King's Landing from Game of Thrones . Walking the walls at golden hour is one of those experiences that lives up to the hype. Dubrovnik is extremely popular nowadays so expect it to be busy, touristy and expensive. You can walk across the old town in about 20 minutes and most of the attractions are self-contained within the city walls. I would spend ~2 days here and make sure to include a short trip to the quieter island of Lokrum located right across the water. What to Do Old Town — a quick 20-minute walk end-to-end. Most of the attractions are located inside of the walled city. The Old Town of Dubrovnik is tiny so it can easily feel overcrowded. Popular attractions like the City Walls or Rector's Palace are worth visiting early or near closing to beat the heat and massive cruise-ship crowds Dubrovnik City Walls — the main highlight of visiting Dubrovnik is walking along the ancient medieval walls. On one side, you'll have a beautiful view over the city and a sweeping view of the ocean on the other. Don't miss any of the cafés and bars built right into the walls along the way Franciscan Church and Monastery — just inside the Pile Gate , worth stepping into for its serene courtyard of slender carved columns and for the Old Pharmacy, founded in 1317 and one of the oldest continuously operating pharmacies in Europe. It doubles as both an active Pharmacy and a little museum of antique jars and instruments. A quick stop off the busy main street Rector's Palace — the graceful Gothic-Renaissance palace that was the seat of the Rector who governed the independent merchant Republic of Ragusa. Now a museum, it lets you wander the elegant courtyard, the old prison cells and rooms furnished as they once were, for a sense of how this tiny city-state ran itself and stayed free for centuries Jesuit Stairs — an elegant, curving Baroque staircase (modelled on Rome's Spanish Steps). If you're a Game of Thrones fan, you'll recognize it as Cersei's \"walk of shame\". Even without the TV connection, it's a great place to stop and there are plenty of restaurants nearby Porat Dubrovnik — the picturesque Old Port of Dubrovnik, where medieval stone walls meet the Adriatic Sea. Once the heart of the Republic of Ragusa's maritime trade, it's now lined with fishing boats, cafés, and tour boats departing for Lokrum Island and worth a quick stop right by the eastern entrance to the city Fort Lovrijenac — a dramatic freestanding fortress perched on a sheer cliff just beyond the western walls (the Red Keep in Game of Thrones ). Your city-walls ticket usually covers it too, and the climb up is rewarded with the best view back across the water onto the entire walled old town Lokrum Island (Half Day Trip) — a lovely nature-reserve island a 15-minute ferry (or a kayak paddle) from the old harbor, and the perfect half-day escape from Dubrovnik's crowds. It is a much quieter than the busy town of Dubrovnik. You can hike across the island passing through shady pine and olive groves, rocky swimming spots, roaming peacocks and rabbits, a ruined monastery (another Game of Thrones set) and a small warm saltwater lake nicknamed the \"Dead Sea.\" Bring water and swim shoes and make sure to catch the last ferry back since no one is allowed to stay on the island overnight Mount Srđ viewpoint — the hill rising straight behind the old town and the source of the classic aerial postcard of Dubrovnik: the whole walled city, its red roofs and the islands laid out far below. Ride the cable car up or hike the switchback trail, ideally around sunset. The Homeland War Museum and a restaurant sit at the top Homeland War Museum — located at the top of Mount Srđ , a museum covering the 1991–92 siege of Dubrovnik during the Croatian War of Independence. A great place to learn about the lesser known Balkan Wars that occurred as recently as the 1990s and early 2000s Where to Eat Restaurant Kopun — a lovely, slightly upscale restaurant on a quiet, atmospheric old-town square, specializing in classic Dubrovnik recipes. It's a splurge by Croatian standards, but genuinely excellent and unpretentious, and the candlelit square setting makes it a memorable dinner Gil's Little Bistro — a reliable, good-value spot for a plate of ćevapčići (the little grilled minced-meat sausages with flatbread and onion) and other Balkan grill staples. A solid casual lunch or early dinner between sightseeing Mlinar — a bakery chain you'll find in every Croatian town. I ended up grabbing breakfast here most mornings Where to Drink Buža Bar — a bar built into the rocks just outside the city wall. It is completely unlabeled and reached through a literal hole in the wall. Great for a sunset drink and cliff jumping into the sea (watch for sea urchins) Bard Mala Buža — a mellower, more low-key sibling of the famous Buža Bar, a little further along the rocks outside the sea walls. It has the same magical set-up of drinks and cushions on the cliffs above the Adriatic, usually with a calmer crowd. Watching the sunset form here was actually incredible and you can also take a swim off the rocks. Make sure to bring cash and it's drinks only (no food) Revelin — one of the coolest clubs that I'd ever been to. Revelin is spectacularly set inside the cavernous stone chambers of the 16th-century Revelin fortress by the old harbor, with big touring DJs in peak season. Expect it to be pricey, but when are you ever going to see a DJ inside of a real medieval castle Where to Stay Hostel Angelina — an amazing hostel tucked inside the Old Town just steps from the city walls. It is unlabeled, but easy to navigate to using google maps. It offers a social atmosphere, clean dorms and private rooms, and an unbeatable location for exploring the city's historic center on foot. Make sure to book in advance during the summer as it fills up a couple weeks out and expect to pay a premium for the location in Old Town ATTRACTIONS 1 Dubrovnik City Walls 2 Franciscan Church and Monastery 3 Rector's Palace 4 Jesuit Stairs 5 Porat Dubrovnik 6 Fort Lovrijenac 7 Mount Srđ 8 Homeland War Museum RESTAURANTS & BARS 9 Restaurant Kopun 10 Gil's Little Bistro 11 Mlinar 12 Buža Bar 13 Bard Mala Buža ACCOMMODATION 14 Hostel Angelina DAY TRIPS ↗ Lokrum Island (Half Day) Croatia Dubrovnik Touch to explore Double-tap to open in Google Maps Hvar 2–3 days recommended Hvar is Croatia's most glamorous island, known for its elegant harbor, marble streets, luxury yachts, and vibrant nightlife. Beyond the lively waterfront, lies a slower-paced island of secluded coves, lavender fields, olive groves, and crystal-clear beaches. Rent a scooter and venture beyond Hvar Town to discover a much more relaxed side of the island, while the nearby Pakleni Islands offer some of the best swimming and beach-hopping on the Adriatic. You can easily get to Hvar by ferry from Split and Dubrovnik with the journey taking less than a few hours depending on the location. I'd recommend spending 2 to 3 days in Hvar. What to Do Hvar Fortress — hike up from the main square to this 16th-century hilltop fortress for panoramic views over Hvar Town, its harbor, and the Pakleni Islands. It's the island's best viewpoint and we were lucky enough to catch one of the most incredible sunsets here while we were in Hvar Hvar Harbor Promenade — the beautiful marble-paved waterfront curving around Hvar Town's harbor, lined with superyachts, palm trees and the terraces of bars and restaurants. It is sleepy and sun-struck by day, it transforms after dark into the glamorous, buzzing heart of the island's famous nightlife. It's the main artery of the town, with everything from the fortress climb to the clubs coming off it Rent a Scooter — rent a scooter and explore the south side of the island: pine-forest roads, lavender fields and hidden swimming coves away from the crowds Pokonji Dol Beach — Hvar Town's most popular beach, just a 15–20 minute walk from the center. This sheltered pebble beach has crystal-clear water, beach bars, and sunbed rentals, making it an ideal spot for a relaxing swim close to town Where to Eat Dalmatino — the best restaurant on the island; upscale but not pretentious, with a complimentary house brandy and polenta amuse-bouche on arrival. The pašticada (braised beef) is exceptional Dva Ribara — another great restaurant located right on the promenade; the black cuttlefish risotto is excellent: fresh and not overpoweringly fishy Where to Drink Carpe Diem Beach — Hvar's legendary beach club, located on Stipanska Bay in the nearby Pakleni Islands and reached by a short water taxi from Hvar Town. Spend the day swimming, relaxing on sunbeds, and sipping cocktails before the venue transforms into one of Croatia's most famous nightlife spots after dark Hula Hula Beach Bar — Hvar's most famous sunset bar, perched on the rocks just outside the old town. DJs start spinning laid-back electronic music from the afternoon, and by sunset the place is packed with people enjoying cocktails and watching the sun sink into the Adriatic before heading into town for dinner or nightlife Where to Stay In general, base yourself in Hvar Town to be walkable to the harbor, fortress and nightlife and you won't need to rent a car Hostel Villa Skansi — located a short walk from Hvar Town , this is an amazing hostel with a clean rooms and nice common area. It was also very social with a bar crawl when I was there ATTRACTIONS 1 Hvar Fortress 2 Hvar Harbor Promenade 3 Pokonji Dol Beach RESTAURANTS & BARS 4 Dalmatino 5 Dva Ribara 6 Carpe Diem Beach 7 Hula Hula Beach Bar ACCOMMODATION 8 Hostel Villa Skansi ACTIVITIES ✦ Island scooter rental Croatia Hvar Touch to explore Double-tap to open in Google Maps Other Places to Consider I stuck to the southern Dalmatian coast for my past couple visits to Croatia, but the country has plenty more worth adding with extra time: Plitvice Lakes National Park — Croatia's most famous natural wonder: a chain of sixteen turquoise lakes linked by waterfalls, threaded together by wooden boardwalks. Inland between Zagreb and the coast Zadar — an underrated coastal city with Roman ruins and two brilliant modern art installations on the waterfront: the Sea Organ and the Sun Salutation. Famous for its sunsets and a good alternative to the more busy Split Istria & Rovinj — the northern peninsula feels distinctly Italian, with hilltop towns, truffles, olive oil and wine. Rovinj is its picturesque coastal highlight Zagreb — the capital of Croatia that is often skipped in favor of the coast. It is worth a day or two for its café culture, museums (including the quirky Museum of Broken Relationships ) and grand Austro-Hungarian old town The Islands — Croatia is home to over 1,244 islands so there are endless possibilities that you can explore. Brač is famous for the Golden Horn Beach , Vis is the most remote and unspoiled, with the dazzling Blue Cave on nearby Biševo , and Korčula is a quieter walled island town often compared to a mini Dubrovnik"},{"url":"denmark/field-notes.html","title":"Denmark Travel Guide","text":"Denmark Travel Guide General Denmark is small, stylish and famously content. It's capital Copenhagen is simultaneously one of the most expensive and one of the most livable cities in the world: colorful canals, cutting-edge design, bikes everywhere, world-class food and a deep sense of hygge (the Danish concept of cozy contentment). The one catch is that it's genuinely expensive, so I'd keep it a trip here short and focused if you're watching your budget. I'd recommend 2 to 3 days to explore Copenhagen and add on additional days for trips throughout Denmark or a quick day trip to Malmö in Sweden. Denmark Overview Getting around Flights — fly into Copenhagen Airport (CPH) , Scandinavia's largest airport. It's just 15 minutes from the city center by metro or train Bikes — Copenhagen is one of the world's great cycling cities. Its flat terrain, extensive network of protected bike lanes, and cycling-first culture make renting a bike the best way to explore the city like a local Metro & trains — the country has a clean, fully automated metro system which is fast, frequent, and easy to use, with excellent connections across the Copenhagen and to the airport. Regional and S-trains make it just as easy to explore the surrounding area If you want to visit the nearby Swedish city of Malmö , you can take the Øresund train which crosses the bridge in about 40 minutes. I wrote a short writeup on my trip to Malmö in 2021 that you can read here Money — despite being a part of the EU, Denmark uses their own currency called the Danish Krone ( and not the euro). Denmark is expensive and almost entirely cashless, so no need to withdraw any Danish Krone unless you're curious Food — Danish food was a surprising highlight of the trip. It was fun to try different dishes like smørrebrød (open-face rye sandwiches with various toppings), flaky Danish pastries, pølser (street-cart hot dogs). Copenhagen is home to superb food halls, and the New Nordic movement that gave the world Noma (considered to be the best restaurant in the world) Language — Danish is the official language and is mutually intelligible with other Scandinavian languages like Swedish or Norwegian. English is spoken fluently almost universally Copenhagen 2–3 days recommended Copenhagen is one of my favorite cities in Scandinavia with colorful canals, world-class design, bike-friendly streets, and an unrivaled café culture. It's one of Europe's most livable cities, combining Michelin-starred restaurants and historic architecture. It's incredibly easy to explore and you'll have no issues getting around as a first-time traveler. I would recommend 2 to 3 days to explore the city. What to Do Nyhavn — the iconic postcard: a short canal lined with brightly painted 17th-century townhouses, café terraces and old wooden ships (very reminiscent of Amsterdam). The famous Danish writer Hans Christian Andersen lived in along here. The area is genuinely gorgeous in low golden light, and it's the launch point for the canal boat tours, which are the best way to see the harbor and opera house from the water. Grab a beer from a kiosk and sit on the quay with everyone else while watching the sunset Little Mermaid — Copenhagen's most famous landmark, inspired by the fairy tale by Hans Christian Andersen. The bronze statue is surprisingly small and often crowded with tour groups, so it's worth keeping your expectations in check Kastellet — a well-preserved star fortresses in Europe and still an active military site. Walk the grassy ramparts for views over the moats, historic barracks, and the iconic windmill. It's a far more rewarding stop than many visitors expect. Christiania — the \"Freetown\" called Christiania is one of the most interesting places in Denmark. It is an autonomous, car-free commune founded by squatters in an abandoned military barracks in 1971. To this day, the area still runs on its own rules. It's no surprise that there is a bit of a counter-cultural hippy vibe here with an enclave of hand-built houses, murals, workshops, cheap vegetarian cafés and live music When I was there in 2021, Christiania was infamous for drug dealing due to it's separate set of rules from the rest of Denmark. In 2024, the residents themselves cleared out the infamous \"Pusher Street\" hash trade after years of trouble Look out for Green George , a massive wooden statue of a giant troll. It was created in 2019 by world-renowned artist, Thomas Dambo and you'll find similar statues scattered throughout Copenhagen Superkilen — a wild, colorful public park in multicultural Nørrebro neighborhood. It is a park filled with abstract modern art and was designed as a celebration of the neighborhood's diversity: it's stitched together from benches, signs, fountains, playgrounds and street furniture collected from around 60 countries I particularly enjoyed the Black Square, with its swirling white lines and a Japanese octopus slide. The park was really cool and a great place to stop for photos. It's a short bike ride from the city center and you'll visit a more local, everyday side of the city Ny Carlsberg Glyptotek — one of the best museums in the city, built by the founder of Carlsberg (the Danish Beer company) to house his antiquities and particularly French art (Rodin, Degas & Gauguin). The highlight for me was the palm-filled Winter Garden under a glass dome at its heart. There is a little café here where you can sit and enjoy the greenery. It was the perfect stop on the rainy day when I was there Rosenborg Castle & King's Gardens — a fairytale Renaissance castle built by Christian IV. Today, it serves as a museum of the royal collections with the crown jewels available to view. It sits in the King's Garden ( Kongens Have ), the oldest royal garden in the country and a favorite spot for a picnic or a beer on a sunny afternoon. The Botanical Garden and its Victorian glasshouses are also right next door If you're here around noon, you can also watch the royal guard marching between here and Amalienborg Palace The Round Tower (Rundetårn) — a 17th-century observatory tower where you climb up a wide spiraling internal ramp inside. At the top is a nice view of the old town's spires and red roofs Tivoli Gardens — the second-oldest amusement park in the world (opened in 1843) and an inspiration for Walt Disney, set right in the center by the main station. To this day, it still maintains a lot of its old charm. It is a great place to visit if you have children Day Trips Malmö (Sweden) — just ~40 minutes by train across the Øresund Bridge (the one from the TV series), an easy and rewarding half-day in another country. Wander the medieval square and cobbled old town, walk the modern Western Harbor waterfront and try Swedish food. It's noticeably more relaxed and cheaper than Copenhagen. Bring your passport and check whether ID checks are running at the border. Read my full writeup on Malmö here Where to Eat Torvehallerne — the bright glass food hall by Nørreport station , packed with around 60 stalls selling everything from smørrebrød and fresh fish to coffee, cheese, pastries and porridge. It's a greatplace to graze explore way through Danish specialties in one spot Broens Gadekøkken (Bridge Street Kitchen) — a harborfront cluster of street-food stalls directly across the water from Nyhavn . It's a relaxed spot for a casual dinner with a harbour view, with everything from tacos to Danish classics plus a bar, and a lovely place to end up on a warm evening Restaurant Klubben — cuisine in Copenhagen is very international, but if you're looking to try traditional Danish food then Restaurant Klubben is the spot. Expect the food to be very heavy and hearty Smagsløget sandwiches — one of Copenhagen's most popular sandwich shops, known for generously filled gourmet sandwiches made with high-quality Danish ingredients. Expect a line at lunchtime, but it's one of the city's best-value meals Noma — I never personally visited, but this wouldn't be a good travel blog if I failed to mention that the best restaurant in the world is in Copenhagen . Noma is famous for redefining Nordic cuisine through hyper-local, seasonal ingredients and an ever-changing tasting menu. Reservations are notoriously difficult to secure and the experience comes with a hefty price tag, but it's a bucket-list meal for serious foodies Where to Stay Base yourself centrally in Indre By (the old center) or around Nørreport . These areas are both bikeable to everything and right on the metro. For a hipper, more local base with the best bars and restaurants, look at Vesterbro or Nørrebro . Accommodation isn't cheap in the city, so booking early, or staying just outside the very center, can save a lot ATTRACTIONS 1 Nyhavn 2 Rosenborg Castle 3 Botanical Garden 4 Round Tower (Rundetårn) 5 Christiania 6 Superkilen 7 Ny Carlsberg Glyptotek 8 Tivoli Gardens 9 Little Mermaid 10 Kastellet RESTAURANTS & BARS 11 Restaurant Klubben 12 Torvehallerne 13 Broens Gadekøkken DAY TRIPS ↗ Malmö, Sweden (Half Day) DENMARK Copenhagen Touch to explore Double-tap to open in Google Maps Other Places to Consider Copenhagen is the main place where most tourists visits, but Denmark has a lot more to offer Kronborg Castle — the grand Renaissance castle on the narrow sound at Helsingør . It's an easy 45-minute train north from Copenhagen The Louisiana Museum of Modern Art — one of the finest modern-art museums anywhere, strung along the wooded coast at Humlebæk about 35 minutes north of Copenhagen by train. The building is as much the draw as the art: low glass corridors opening onto a sculpture park that runs down to the sea. Give it a half-day and have lunch on the terrace Roskilde — an easy half-hour train west, best known for two things. The Viking Ship Museum displays five original 11th-century Viking ships raised from the fjord, alongside a working boatyard that builds and sails replicas. The brick cathedral is the burial place of 40-odd Danish kings and queens, a genuinely impressive royal mausoleum. In late June, the town also hosts Roskilde Festival , one of the biggest music festivals in Europe Aarhus — Denmark's lively second city, over on the Jutland peninsula (about 3 hours by train from Copenhagen ). It's a young, walkable university town with a buzzing food scene and the cobbled Latin Quarter. The headline sights are ARoS , the art museum, and Den Gamle By , an open-air museum of historic Danish houses"},{"url":"egypt/field-notes.html","title":"Egypt Travel Guide","text":"Egypt Travel Guide General Egypt is home to the most impressive historical sites on earth: the Great Pyramids of Giza, the temples of Luxor, the tombs of the Valley of the Kings, and standing among them is absolutely unforgettable. Unfortunately, it's also a very challenging country to travel, despite how many tourists go there every year. Be prepared for a chaotic, developing country with security issues and people constantly looking to take advantage of tourists. For first timers, I highly recommend following the classic route down the Nile starting with Cairo and the Giza pyramids to Luxor , a river cruise on to Aswan and finally all the way down to Abu Simbel near the border with Sudan. This whole route takes roughly 10 to 14 days to complete. Getting around Uber — only available in major cities like Alexandria and Cairo. Use it wherever you can as regular taxis (especially from the airport) will charge an exorbitant tourist tax, so make sure to haggle hard with taxi drivers where Uber isn't available Between cities — cheap domestic flights are offered by EgyptAir and Air Cairo (the budget airline. You can also take an overnight sleeper trains between Cairo, Luxor and Aswan I highly recommend taking a multi-day Nile Cruise to visit the sites between Luxor and Aswan. They are affordable and you will be able to explore all the major sites. I'll discuss this in more detail later on in this article. Guides — book a tour or private guide for the ancient historical sites. There aren't placards explaining the archeological sites so having a guide is necessary to learning the history and intricacies behind each site. Additionally, going alone leaves you swamped by persistent unofficial \"guides\" and scammers. However, guides are not always your friend. I've had tour guides hand me off to scammers and there are often stops at tourist traps selling fake souvenirs and perfumes Money — the official currency is the Egyptian Pound (EGP); Egypt is a cash-based society so carry plenty of cash and expect to pay for everything in cash. Traveling in Egypt is extremely affordable, meals were on average ~$5 - 7 and 4 star hotels ~$40 a night Food — Egyptian food is quite similar to the food you'll find elsewhere in the Middle East. However, they have an array of unique dishes: koshari (the national dish of rice, pasta, lentils and fried onion), ful medames (a fava bean dip served with pita) and taameya (Egyptian falafel), kebab and lots of sweet mint tea. Meals were extremely filling and cheap, often costing less than $6 at local restaurants Language — the Egyptian dialect of Arabic is the primary language spoken here. English is commonly spoken by those who work in the tourism industry. However, I encountered a significant language barrier as many Egyptians don't speak any English. It is helpful to learn a few phrases of Arabic Safety — to be perfectly honest, I did not feel safe in Egypt, even as a well-seasoned traveler. I encountered many aggressive and sketchy situations with locals looking to take advantage of tourists. Here were some issues I experienced: Bribes — I was asked for bribes twice while in the airport. My first experience in Egypt was being asked for a bribe by the immigration officer in the Cairo Airport who stamped my passport (with the security cameras and in front of everyone else in line). After pretending to not understand him for 5 minutes and holding up the line of impatient travelers, he finally let me off the hook. I also dealt with this when flying out of the country with a baggage handler in the same airport Baksheesh (a \"gift\") — tipping is expected everywhere which is standard for tourism in developing countries. However, street vendors or even random men on the street will follow you for 15 minutes harassing you for a few dollars. I tipped a guy and he reached into my wallet and grabbed a bigger bill immediately after. They are quite relentless and sometimes out right aggressive so don't be hesitant to be assertive in rejecting their requests Heavy Police Presence — Egypt deals with a strong threat of terrorism. There was a heavy police presence. On some longer drives, we were stopped every 15 minutes and our car was swept for bombs underneath Harassment towards women — female travelers should be aware that harassment from men is a widespread and well-documented issue in Egypt. Traveling with a female friend, I witnessed this firsthand: Egyptian men would frequently make unsolicited comments toward her and even ask to take photos with her, which was disorienting even if ultimately harmless. This can range more broadly from persistent staring and unwanted comments to being followed and touched in crowded areas. I would not recommend Egypt for solo female travelers from what I have seen Egyptians are known to have a strong culture of hospitality. However, many people see foreigners as walking ATMs and unfortunately it can ruin your experience. I strongly believe you can have a great experience here and don't want to discourage you from visiting, but I write about these issues in detail so you can be prepared for the potential challenges Egypt is a developing country that is still recovering from conflicts in the Arab Spring just over a decade ago. The country struggles with deep inequality and poverty so expect unpaved roads, stray animals, litter and a heavy police presence. It's a real developing-world experience, but the ancient sites are worth every bit of it Suggested Route Overview Cairo & Giza 2–3 days recommended Cairo is the 7th largest city in the world with over 25 million people living in the greater Cairo area. It is a sprawling, chaotic megacity with traffic unlike anywhere else I've seen in the world. On its western edge sits the Great Pyramids of Giza : the only surviving Wonder of the Ancient World. It is very impressive in person and should be on everyone's bucket-list if it isn't already I would recommend spending 2 to 3 days in Cairo. Spend your first day exploring the city center of Cairo and the next couple days in Giza visiting the Great Pyramids of Giza and the many ancient sites like the Great Sphinx driving distance from the city. What to Do Cairo — most of the sites below are all located in the same area walking distance from each other so you can visit all of them in one day Tahrir Square — the symbolic heart of modern Cairo and the site of the 2011 Arab Spring revolution, where hundreds of thousands of Egyptians gathered for 18 days until President Mubarak resigned. A Ramses II obelisk now stands at the center of the huge roundabout. The site feels tense to visit today since it is heavily monitored by police, given it's association with prior Arab Spring revolution The Egyptian Museum in Cairo — sitting directly on the edge of Tahrir Square's is the Egyptian Museum in Cairo. When I visited in 2023, it had the largest collection of Egyptian artifacts in the world. It still worth visiting for the sheer volume of artifacts. However, the best pieces have moved to the newly built Grand Egyptian Museum in Giza Islamic Cairo — a vast medieval quarter that has barely changed over the centuries. Here you'll find narrow winding alleyways lined with crumbling Mamluk palaces, Ottoman mosques and ancient minarets. The most historically dense and overwhelming part of the city Khan el-Khalili is one of the oldest bazaars in the world, a labyrinth of alleyways selling spices, textiles, gold and souvenirs A short walk away is the Citadel of Saladin , a medieval fortress built in 1176 that dominates the Cairo skyline, and inside it the Mosque of Muhammad Ali (not dedicated the boxer) with a stunning alabaster interior and sweeping views over the city Coptic Cairo — a completely different side of the city and a fascinating counterpoint to Islamic Cairo. This ancient walled quarter predates the founding of Cairo itself and was home to Egypt's Christian community long before Islam arrived Within a small neighborhood, you'll find five ancient Coptic churches including the famous Hanging Church built into the gate of a Roman fortress, the Ben Ezra Synagogue and the Coptic Museum . The area is small so about 2–3 hours is enough to see the main sites Giza — located right on the other side of the Nile river from Cairo, Giza is home to the Pyramids of Giza and many other iconic historical sites. I would recommend basing yourself here during your stay unless you plan to explore Cairo in depth Giza Necropolis — most of the historical sites in Giza are all centered on the Giza plateau. You can buy a single ticket for entry, making it easy to explore the whole area in a single day. Hire a guide to explain the engineering and history and go early morning to beat the crowds and the heat Great Pyramid of Giza — dating back 4,500 years, the Great Pyramid of Giza is only ancient wonder of the world still standing and one of the most extraordinary things you will ever see in person. No photo prepares you for the scale, each stone block is the size of a small car and the base stretches for 230 meters on each side. Walk the perimeter to let the size sink in, then enter through the low narrow tunnel that leads to the internal burial chamber The Great Pyramid held the title as the tallest man-made structure on earth for 3,800 years until it was surpassed by the Lincoln Cathedral in England surpassed it in 1311 AD The Pyramid of Khafre — the second largest and still has a cap of its original polished white limestone casing stones at the very top, a reminder that all three pyramids were once entirely smooth and gleaming white rather than the rough stepped stone you see today The Pyramid of Menkaure — the smallest of the three pyramids but has the most intact mortuary temple complex beside it The Great Sphinx — carved from a single limestone outcrop directly beside the Khafre pyramid, the Sphinx is 73 meters long and Up close it is much larger than photos suggest. It is believed to have originally had a painted face and a royal headdress now mostly eroded away Panoramic View of the Giza Pyramids — seeing all three pyramids aligned from the classic viewpoint in the desert to the southwest is one of the most iconic photos in the world. Camel rides also are available in this area. Despite being touristy, riding a camel with the pyramids as a backdrop is a genuinely unforgettable moment Grand Egyptian Museum — the largest archaeological museum in the world, opened in 2023 right beside the Pyramids of Giza . Built specifically to house Egypt's greatest treasures, including the complete collection of Tutankhamun's tomb artifacts displayed together for the first time in history. It wasn't open yet when I was in Egypt, but it looks very impressive Budget at least half a day and treat it as an essential companion to the Giza plateau. Most of the artifacts have been removed from the original archaeological sites so visiting museums are essential for seeing the golden artifacts and mummies! Saqqara & Memphis (day trip) — about 30 minutes south of Cairo and easily taken as a day trip. Well worth it for anyone who wants to go deeper into Egyptian history beyond the Giza plateau. I took this tour to visit the Great Pyramids, Saqqara and Memphis all in one day The Step Pyramid of Djoser (the world's first pyramid, 2600 BC) and the ancient capital of Memphis, with its colossal statues of Ramesses II and an alabaster sphinx Saqqara is the vast ancient burial ground where the Step Pyramid of Djoser stands which the world's first pyramid, built around 2600 BC and predating the Great Pyramid by over a century. It is surrounded by a massive funerary complex of courtyards and chapels that is far less crowded than Giza and gives a genuine sense of discovery Located just a few kilometers further is Memphis which was the ancient capital of Egypt for over a thousand years. The open-air Mit Rahina Museum there houses a colossal, 36 foot tall limestone statue of Ramesses II and a large alabaster sphinx that are worth a visit wHERE TO STAY Nine Pyramids View Hotel (Giza) — an affordable hotel located in Giza, very close to the pyramids complete with a cafe and roof with a view of the Great Pyramid of Giza. You can even get a room with a view of the pyramids for as little as ~$40 per night ATTRACTIONS 1 Great Sphinx 2 Tahrir Square 3 The Egyptian Museum in Cairo 4 Grand Egyptian Museum 5 Khan el-Khalili 6 Citadel of Saladin 7 Hanging Church ACCOMMODATION 8 Nine Pyramids View Hotel DAY TRIPS ↗ Saqqara & Memphis (Full Day) EGYPT Cairo Touch to explore Double-tap to open in Google Maps Luxor 2 days recommended After the madness of Cairo, move on to the more relaxing Luxor located 316 miles south on the Nile River. Luxor is the world's greatest open-air museum: home to the ancient city of Thebes, split by the Nile into the temples of the living on the East Bank and the royal tombs of the dead on the West. The density of monuments here is staggering and was one of my favorite stops in Egypt. I would recommending 2 to 3 days in Luxor to see all the sights. I would highly recommend taking a 3-night cruise down the Nile between Luxor and Aswan. The cruises are affordable (roughly ~$600 all inclusive), organize all the logistics for you and visit all the key archaeological sites in southern Egypt. What to Do Luxor Temple — located in right in the center of Luxor next to the riverbank is one of the sites in Egypt with the most fascinating history. It is literally layered with history. The courtyard is covered with massive ancient Egyptian pillars towering over you at 52 feet (16 meters) tall. At the end of the walkway is Abu Haggag Mosque , below it is an old Roman church and at the bottom is the ancient Egyptian Luxor Temple all stacked right on top of the original foundation Avenue of Sphinxes — at the entrance is a 1.7mi (2.7km ) ceremonial road known in ancient Egypt as \"The Path of the Gods.\" Over 1,000 sphinx statues line both sides of the avenue, some with human heads representing pharaohs as divine protectors, others with ram heads symbolizing the god Amun-Ra . The avenue was buried under sand and housing for centuries and only 650 of the original 1,350 sphinxes have been unearthed, with excavations still ongoing The Valley of the Kings — the burial ground of the New Kingdom pharaohs and one of the most impressive sites in Egypt. The area is massive with temples and there more than sixty tombs have been found here, with only a handful open to visitors. Each tomb is located unground and you'll walk through a passage wall with walls covered in colored hieroglyphics on both sides. The painted ceilings and carved walls are so vivid it's hard to believe they're thousands of years old A standard ticket can be purchased at the entrance for 750 EGP or ~$15 USD and covers three tombs. The tomb of Ramesses VI has some of the most intact painted ceilings and Tutankhamun's tomb is a separate ticket Sunrise Hot-air Balloon — take off at first light and drift over the Valley of the Kings , the West Bank temples and tombs as the sun rises over the desert. The size of the monuments is so impressive that you can see them in all the way up from the hot air balloon. One of the most extraordinary mornings of the whole trip Karnak Temple — the largest religious complex ever built. You first enter down an avenue of ram-headed sphinxes into the Hypostyle Hall, a forest of 134 giant hieroglyph-covered columns, with a massive standing obelisk still in place. Spend roughly 2 hours here to cover the place Temple of Hatshepsut — a vast terraced mortuary temple built into the cliff face for Egypt's female pharaoh. The is an gigantic ramp leading into the temple. The nearby Colossi of Memnon is also worth a quick visit with two giant seated statues of Amenhotep III where to stay Pyramisa Hotel Luxor — a nice hotel located on the banks of the Nile. It was a good price ~$60 for a room with a view of the river ATTRACTIONS 1 Luxor Temple 2 The Valley of the Kings 3 Karnak Temple 4 Temple of Hatshepsut 5 Colossi of Memnon ACCOMMODATION 6 Pyramisa Hotel Luxor EGYPT Luxor Touch to explore Double-tap to open in Google Maps Aswan 2 days recommended Aswan is the laid-back southern gateway on a beautiful stretch of the Nile: the base for a felucca sail, the island temple of Philae and the epic monuments of Abu Simbel near the Sudanese border. One of the reasons to take the multi-day cruise is to stop by the sites in Edfu and Kom Ombo , both situated on the banks of the Nile between Luxor and Aswan. In this section, I'll cover all the attractions located South of Luxor from Edfu to Kom Ombo to Aswan and all the way to the south in Abu Simbel . What to Do Temple of Horus at Edfu — the best-preserved ancient temple in Egypt and the one that gives you the clearest sense of what these places actually looked like when they were active. Built over 180 years between 237 and 57 BC during the Ptolemaic dynasty, it was buried under centuries of sand and silt after pagan worship was banned. The hieroglyphs covering every surface are legible enough to read over 2,000 years later Kom Ombo — one of Egypt's most unusual temples, built simultaneously for two gods with completely opposing associations: Horus the falcon god of the sky on one side and Sobek the crocodile god of the Nile on the other. The temple is architecturally symmetrical, with two of everything (two sanctuaries, two hypostyle halls, two entrances), divided right down the middle. We experienced sunset here and it was incredible One of the walls is covered in a set of hieroglyphs that archaeologists believe depicts surgical instruments including scalpels, forceps, bone saws and dental tools, suggesting the temple may have doubled as a center for medicine. The small museum next door contains dozens of mummified crocodiles excavated from the site Philae Temple (near Aswan) — a temple dedicated to the goddess Isis on a small island in the Nile near Aswan, reached by a short boat ride. The temple was completely dismantled block by block in the 1970s and reassembled on higher ground to save it from the rising waters of Lake Nasser after the construction of the Aswan High Dam. Go in the evening for the sound and light show when the entire complex is lit up in color Abu Simbel — you can reach Abu Simbel by a 3-hour drive (or short flight) south all the way to the border with Sudan. The complex is home to two temples carved into a cliff by Ramesses II, fronted by four 20-meter seated statues of the pharaoh, with a smaller temple to his queen Nefertari beside it. I visited it last and Abu Simbel was one of my favorite sites in Egypt. It is absolutely worth the trip to the far south of the country Where to stay Obelisk Nile Hotel Aswan — a great, affordable four star hotel located right on the Nile river. There was a great restaurant in-house with a wonderful view of the boats sailing past during sunset My Nile Cruise Itinerary 4 days, Luxor to Aswan The highlight of my time in Egypt was the Nile cruise: three nights on the river between Luxor and Aswan , sailing past the temples, palm groves and villages that have lined its banks for thousands of years. It's the easiest and most scenic way to string together the great sites of the south: the boat handles all the logistics while you wake up somewhere new each morning. I did the standard four-day, three-night route from Luxor down to Aswan. Almost every boat runs the same itinerary and stops at the same temples, so the price mostly comes down to the boat itself. The version I booked cost ~$600 all inclusive. The quarters on the boat were rundown with water leaking from the ceiling so I'd recommend booking a higher tier one. However, I met some incredible people and the itinerary was perfect. Here's how the days broke down: Day 1 — Karnak, Luxor Temple & boarding the cruise . I met a local guide for Luxor's East Bank. The first stop was Karnak Temple is the largest religious complex ever built with an avenue of ram-headed sphinxes. Then over to Luxor Temple , where layers of history stack right on top of each other, with a working mosque and an old Roman church built into the ancient Egyptian stone Around midday I boarded my Nile cruise boat, which would be home for the next three nights. The cabins were a bit run down, but the common areas of the boat were great. Most boats have a sundeck, a small pool, and a communal dining room. The food was 6/10, but there was a lot of variety between meals Day 2 — Balloon at dawn & the Valley of the Kings . We woke up at 4am, took a short felucca across the Nile in the dark, and then up in a hot-air balloon over the West Bank as the sun broke over the desert and lit up the temples and tombs below. Easily one of the best mornings of the whole trip. Back on the ground we saw the Colossi of Memnon and the cliff-carved Temple of Hatshepsut . The day was spent in the Valley of the Kings where we visited a few of the tombs which had impressive painted ceilings and carved walls. That afternoon the boat pushed off and sailed south toward Edfu . Day 3 — Edfu & Kom Ombo — we took a horse-drawn buggy from the dock to the Temple of Horus at Edfu, the best-preserved temple in Egypt, only fully dug out of the sand in the 1800s and still crisp enough to show you exactly how these places once looked. Then a long, lazy sail up the river to Kom Ombo . The last stop was the temple of Kom Ombo which was one of my favorite stops to explore. We watched the sunset from here over the Nile river Day 4 — Abu Simbel & Aswan — the earliest start of them all, we took a 3AM van south through the desert to Abu Simbel , right near the Sudanese border on the shore of Lake Nasser . There were four enormous seated statues of Ramesses II guard the entrance, with the smaller temple to his queen Nefertari beside it. The scale in person is staggering The cruise heads back to Aswan at night, I ended the day with a felucca sail on the calmest, prettiest stretch of the Nile I'd seen, right at sunset. The cruise disembarks here the next morning, leaving you well placed to explore Aswan or fly onward to your next destination Other Places to Consider The Nile circuit is the classic trip and perfect for the first visit. Egypt has plenty more to explore including: The Red Sea coast — world-class diving and snorkeling along the Red Sea which is one of the world's most vibrant and thriving marine ecosystems. The laid-back Dahab is the backpacker favorite and the freediving capital of the world (with the famous Blue Hole ). There are also bigger resort towns of Hurghada and Sharm el-Sheikh , popular with European holiday makers Alexandria — the Mediterranean city with loads of Greek and Roman history. It was famously home to Library of Alexandria in Egypt, known to be the greatest repository of knowledge in the classical world. However, it was destroyed over the centuries. You can now visit the Bibliotheca Alexandrina which has a distinctly modern feel The White Desert — home to surreal wind-carved chalk formations. You can camp among under the stars, out in the Western Desert. It is remote so independent travel is not allowed and a tour is required Mount Sinai — the biblical mountain located on the Sinai Peninsula . Take pre-dawn hike to the summit for sunrise, above the ancient St. Catherine's Monastery"},{"url":"estonia/field-notes.html","title":"Estonia Travel Guide","text":"Estonia Travel Guide General Estonia is a tiny country located in northern Europe that most people don't get around to. It was a pleasant surprise and my favorite out of the Baltic. The capital, Tallinn , is an incredibly beautiful city with one of the best-preserved medieval old towns in Europe. Just a few decades ago Estonia was part of the Soviet Union, but it has since modernized rapidly, earning the nickname e-Estonia for it's tech-forward mindset. Almost 100% of the government is digital: you can vote, pay taxes and even submit your marriage certificate online through e-estonia.com (yes this is the government website)! It compact, affordable and you can get anywhere in the country in under 4 hours. I would recommend spending at least 2 to 4 days in the country with the majority of the time spent in Tallinn . Estonia is best visited as part of a greater Baltics trip (along with Latvia or Lithuania). You can also take a ferry from Helsinki or Stockholm , both a couple of hours across the water. Estonia Overview Getting around Tallinn — the walled old town is small and entirely walkable. Public transport like trams and buses are easy to navigate, and the whole country is famously digital (you can do almost everything by app) Ridesharing — Bolt , the European version of Uber, is widely available and affordable in Estonia Ferries — There are cheap ferries that run cross to Helsinki in ~2 hours and to Stockholm overnight. It is popular for Estonians to go to Helsinki for just a day if you want to buy a day pass Long-distance Buses — I would hardly call any bus ride in Estonia long distance! There are comfortable long-distance buses that connect down through Riga , Latvia and the rest of the Baltics that are perfect to continue your journey Money — the Euro is the official currency here. Despite being right across the water from Finland, it is noticeably cheaper than the Nordics Food — Estonian food is hearty and northern-European. Some of the dishes that I tried were warming stews, smoked fish, pork, sauerkraut, black rye bread and smoked fish and, plus baked goods like samsa (a flaky meat pastry) reflecting the region's mix of influences Language — Estonian is a Uralic language that is closely related to Finnish. Since the breakup of the Soviet Union, Estonia has pivoted hard towards the West. Over 80% to 90% of younger Estonians are fluent in English and it is widely spoken in Tallinn Tallinn 2-3 days recommended It may come as a surprise to many, but Tallinn is one of my favorite cities in Europe. Tallinn has a few different facades, each representing a different aspect of it's history. It is home to a mix of the most well-preserved medieval old town in Europe, a hip creative district full of modern art and modern buildings showing the country's rapid economic growth. Spend a couple days exploring the old medieval town and its cobbled lanes, city walls, castles and even eat in a medieval themed restaurant where the waiters speak to you in Ye Olde English . Additionally, the city has another side to it: visit the a occupation museum exploring both Soviet and Nazi occupation. Finally, explore the modern day Estonia with modern buildings and a hip creative district. Tallinn is a perfect few day city break and I strongly encourage you to come to a corner of Europe often forgotten about. What to Do Vanalinn (Old Town) — the medieval old town packed with attractions and one of the best remaining in Europe. Everything below sits within a 15-minute walk, so there's no need to plan a route: just start wandering and mark off places so you don't miss anything. The cobbled lanes, merchant houses and church spires haven't changed much in 500 years, and it's easy to spend a full day here Start in the Town Square (Raekoja plats) which is the heart of the old town. It is a wide cobbled square lined with bright, pastel merchant houses and anchored by the Gothic Town Hall. In December, it hosts one of the oldest Christmas markets on the continent Town Hall Pharmacy — one of the oldest continuously operating pharmacies in Europe, dating back to the 1400s and still a working pharmacy today. The back room is a tiny free museum of medieval remedies. It only takes a few minutes to visit, but it's a fun spot to take a peek while you're on the square III Draakon — a dark medieval tavern tucked into the side of the Town Hall, lit only by candles and staffed by waiters who dress and speak like it is the medieval ages. The menu is classic medieval fare: bowls of hot elk soup, savory pies and spiced wine. It's fun place to stop for dinner and surprisingly not too expensive House of the Blackheads — an ornate guildhall once used by the Brotherhood of Blackheads, an association of medieval Baltic merchants and ship-owners. The green, red and gold Renaissance facade, studded with coats of arms, is one of the most photographed in the old town. The interior only opens for concerts and events so stop by if you're passing for a photo. There is also another version in Riga that is worth a visit Churches — there are tons of churches to choose from in Tallinn. My favorites were St. Olaf's Church (for the view) and Alexander Nevsky Cathedral (for the golden avantgarde interior) St. Olaf's Church — a soaring Lutheran church which was once the tallest building in the world in the 1500s. For a few euros, you can climb the narrow, spiraling stairs to a viewing platform for a great view over Tallinn 's red rooftops and the harbor Holy Spirit Church — a small white medieval Lutheran church just off the square, best known for the ornate blue-and-gold clock on its facade, the oldest public clock in Tallinn. Step inside for the intricately carved wooden interior and one of the oldest painted altarpieces in the country. It's quick to visit and rarely crowded St. Catherine's Church / St. Catherine's Passage — a narrow, partly covered medieval lane running alongside the ruined St. Catherine's Church, its walls set with old carved tombstones. Today it's home to the St. Catherine's Guild, a row of open workshops where you can watch classic potters, glassblowers and hatmakers at work St. Nicholas' Church & Museum — a classic Baltic church that has been beautifully restored and serves today as a museum of religious art The Tallinn City Walls & towers — Tallinn still has almost two kilometers of its medieval wall standing. You can walk a stretch of the ramparts and climb inside several of the towers which is well worth it Viru Gate — the pair of twin-turreted medieval towers that mark the main entrance into the old town from the modern city Hellemann Tower & Town Wall Walkway — one of the best places to walk the walls and climb the Hellemann Tower. On one side, you'll see the old town on one side and on the other are the gardens. It was a very cool experience being able to explore and there is a small museum inside of the tower to learn about the Medieval History Towers' Square — a grassy park hugging the northern stretch of the city wall, with a photogenic row of red-roofed towers lined up along it. There is a beautiful garden nearby with flower beds in the summer Toompea Hill — the upper section old town sits on Toompea Hill . It's a short, but steep walk up (the Lühike Jalg Lane is the prettiest way). This neighborhood is home to the castle, cathedrals and the best viewpoints in the city Kohtuotsa , Patkuli and Bishop's Garden are the three lookout platforms up on Toompea Hill , each with a different angle over the red-roofed old town, the spires and the harbor beyond. All three viewpoints are located within a few minutes of each other, so it is easy to string them together as you're walking up the hill Kiek in de Kök Fortification Museum — a 15th-century artillery tower which now operates a fortifications museum. You can also access the Bastion Passages which are the tunnels dug beneath Toompea, used as air-raid shelters and a Soviet-era hangout Alexander Nevsky Cathedral — the black-domed Russian Orthodox cathedral that sits at the top of Toompea Hill . The inside cathedral is absolutely covered in gold mosaics, icons and hanging lamps. As my first time inside a Russian Orthodox church I was thoroughly impressed. Be warned that photos aren't allowed inside. The lady working there almost slapped my phone out of my hand Toompea Castle & Pikk Hermann — the Toompea Castle is pink baroque building which now serves as the seat of the Estonian parliament. Rising beside it is Pikk Hermann , the tall tower that flies the national flag. Unfortunately, you can't go inside the working parliament, but the exterior and the tower are worth the short walk St. Mary's Cathedral — also called the Dome Church, this whitewashed cathedral is the oldest church in mainland Estonia, its walls densely hung with the carved and painted coats of arms of the noble families buried here. Worth a look if you're passing, but honestly skippable given how many churches you've probably already visited by this point Vabamu Museum of Occupations and Freedom — one of the best museums in Estonia, a country that you probably didn't know much about before visiting. It tells the story of Estonia's 20th century through the Nazi and Soviet occupations and the long road to independence in 1991. It doesn't shy away from the human cost: tens of thousands of Estonians were deported to Siberian gulags, and their testimonies anchor the exhibits. The included audio guide is exceptional, so give yourself a couple of hours and don't rush it Hotel Viru & KGB Museum — for more Soviet history with a stranger twist. This was Tallinn's first high-rise hotel, built by the state for foreign visitors, and its secret top floor hid a KGB radio-surveillance station that bugged the rooms below. Locals joked it was built \"of micro-concrete\": concrete and microphones. You can only visit on a guided tour, which is well worth booking ahead here Telliskivi Creative City — after exploring the medieval old town, head to the most vibrant area in the city called Telliskivi Creative City . The neighborhood consists of converted industrial buildings filled with of murals, modern art, shops and good restaurants. Wander the neighborhood to explore all the murals and sculptures scattered about Balti Jaam Turg — a large renovated market hall right next to Tallinn's main train station with nearly 300 vendors across three floors. The ground floor has fresh fish, meat and produce alongside about 20 street food stalls including Uzbek dumplings and Georgian food. Upper floors have Estonian design, vintage clothing and antiques. A good mix of locals and tourists and a 10 minute walk from Old Town Fotografiska — the Tallinn outpost of Stockholm 's famous contemporary-photography museum with a strong programme of exhibitions that changes every few months. Even if photography isn't your thing, the top-floor restaurant and bar is one of the better spots in the area for a drink or dinner, and it stays open late Sveta Baar — an atmospheric, red-lit bar in Telliskivi that slowly turns into a techno club after midnight. Local DJs will spin for hours and I had a great time when I was there Kadriorg Park — a grand Baroque park and palace commissioned by Peter the Great and named for his wife Catherine, a short tram ride east of the center of Tallinn. It's a peaceful, leafy sprawl of formal gardens, ponds and the pink palace (now an art museum ). On the far side sits KUMU , the excellent national art museum and easily worth an hour or two Estonian Open Air Museum — a large open-air museum on the wooded coast west of the city, where historic Estonian farmhouses, windmills, a wooden church and a village inn have been relocated. In summer there are costumed demonstrations, horse carts and folk dancing, and the on-site tavern serves old-fashioned Estonian food. It takes a bus or a Bolt to reach, but it's a nice half-day and a complete change of pace from the medieval core Where to Eat & Drink Kooker Raekoja Plats — a tiny window stand serving fresh, tiny Estonian pancakes ( pannkoogid ), thin and made to order in both sweet and savory versions, from ham and cheese to jam or Nutella. You'll find it just off the Town Square Munga Kelder — a medieval cellar restaurant lit by stained glass and candles, one of the more atmospheric places to try traditional Estonian food. I had a slow-roasted pork that fell apart at the fork, with mild sauerkraut and a dark, faintly sweet cranberry brea. It was one of my better meals in the city Pulla Bakery — a cozy little bakery-cafe with a lovely sweet poppyseed roll alongside cinnamon buns, pastries and good coffee Lido Baltic Buffet (Ülemiste mall) — a cheap, cheerful self-service canteen in the Ülemiste mall where you slide a tray along and point at what you want: borscht, fried green beans, sausages, crepe-wrapped pork rolls and a long line of other Baltic comfort food. It a cheap and authentic way to sample a variety of Estonia foods Whisper Sister — a hidden speakeasy-style cocktail bar with no real sign, so you'll need to find the unmarked door and just walk in. Inside it's dim, intimate and quietly cool, with a short menu of excellent, inventive cocktails Where to Stay Base yourself in Vanalinn or Old Town as everything is walkable from here The Monk's Bunk Hostel & Bar — a hostel with basic bunks that is located right in old town. I found it very social and the ability to walk anywhere was perfect ATTRACTIONS 1 Town Square 2 St. Olaf's Church 3 House of the Blackheads 4 St. Nicholas' Church 5 Kiek in de Kök 6 Alexander Nevsky Cathedral 7 Toompea Castle 8 Kohtuotsa Viewpoint 9 Vabamu Museum 10 Telliskivi Creative City RESTAURANTS & BARS 11 Munga Kelder 12 Sveta Baar 13 Whisper Sister ACCOMMODATION 14 Lai 22 ESTONIA Tallinn Touch to explore Double-tap to open in Google Maps Other Places to Consider Tallinn is the primary stop for most travelers, but Estonia has more to offer besides the capital: Tartu — Estonia's second city, built around the University of Tartu, one of the oldest universities in Northern Europe. It has a different feel from Tallinn : younger, more relaxed and more authentically Estonian. Located about 2.5 hours from Tallinn by bus and worth a night or two Lahemaa National Park — an easy hour's drive east of Tallinn and the best place in Estonia to experience the country's natural landscape. The park covers a dramatic stretch of Baltic coastline indented with peninsulas and bays, backed by ancient boreal forest, raised bogs and lakes Saaremaa — Estonia's largest island and a peaceful world away from the mainland. Reached by a 30 minute ferry from Virtsu , the island is known for its windmills, juniper heath landscapes, medieval Kuressaare Castle and a string of spa hotels that attract Estonians for weekend breaks. A good option if you want to slow down and spend a couple of days outside the cities"},{"url":"finland/field-notes.html","title":"Finland Travel Guide","text":"Finland Travel Guide General Finland is the calm, clean, design-forward corner of the Nordics: a country of forests, lakes and islands, with a compact, elegant capital in Helsinki and the Arctic wilds of Lapland far to the north. I'll be honest: I only visited Helsinki and wasn't very impressed with the city (maybe I got unlucky or completely missed something ) . I wouldn't recommend visiting the city on its own, but it's a pairs naturally with the snowy Lapland region in the far North or a ferry across to Tallinn , Estonia or Stockholm , Sweden. Finland Overview Getting around Helsinki — I'll give it to Helsinki. It is one of cleanest, well-organized cities that I've ever visited. Using the metro network is a breeze to use and it covers the compact city center. There are also many ferries that run out to the many islands right off the coast of the city International Ferries — Helsinki is a Baltic hub with ferries connecting it to Tallinn (~2 hours) and Stockholm (an overnight ferry), making it easy to combine Finland with other countries. Finns often go to Estonia by ferry for the day for a night out or even avoid high sales taxes Long Distance Trains & Buses — Finland has an extremely well-connected transport system. You can get almost anywhere by train or bus Money — the official currency is the Euro. Like all the Nordic countries, Finland is very expensive, so budget accordingly Food — Finnish food was very interesting to try and I personally found it similar to other Nordic cuisines. If you're feeling adventurous, try the reindeer with lingonberries and mashed potato (the classic dish). Other popular dishes are salmon, the savory rice-filled karjalanpiirakka pie, and cardamom-spiced pastries. Finns drink more coffee per capita than almost anyone in the world, and it's excellent Language — Finnish is a Uralic language and famous for its complexity. Finns also speak some Swedish and English is spoken fluently almost everywhere (+90% people are conversational or fluent in English) When to go — you'll get two completely different experiences if depending on the season that you visit Finland: summer brings near-endless daylight (\"white nights\") while winter is for the northern lights, huskies and snow up in Lapland How long to stay — 2 days is enough for Helsinki and add several more days for a Lapland adventure Helsinki 1–2 days recommended Helsinki is a capital of neoclassical squares and Baltic islands: easy to cover on foot in a couple of days, with a sea fortress just offshore as the highlight. To be frank: it is far from my favorite European capital. I found it to be almost eerily quiet and more relaxing than thrilling. Helsinki is worth 1 to 2 days to fully explore, especially as part of a longer trip. What to Do Senate Square — the center of Helsinki and worth a few hours to explore the following historical monuments. The architecture surprisingly reminded me of American government buildings in Washington D.C. as most of the government buildings in Helsinki were built in the 1800s Helsinki Cathedral — the gleaming white, green-domed neoclassical cathedral standing at the top of the steps above Senate Square, the heart of old Helsinki laid out in the early 1800s when the Russians made it the capital. It's quick to see and free to step inside and the cathedral steps are a favorite spot to sit in the sun Presidential Palace — the official residence of Finland's president, sitting right on the Market Square waterfront. It began as a merchant's mansion in the 1810s and was rebuilt into the restrained neoclassical palace you see today. You can't go inside, but it is worth a glance from the square as you pass, especially when the ceremonial guard is posted out front Finnish House of Nobility — Ritarihuone , a striking red-brick neo-Gothic hall a couple of blocks from Senate Square, built in the 1860s as the assembly house for Finland's nobility back when the country was a Russian grand duchy. It also isn't usually open to visitors, but the ornate facade studded with coats of arms is a nice detour on the walk between the cathedral and the water Market Square harbor — visit the open-air market (Kauppatori) on the waterfront at the ferry port. There is a seaside market with a cluster of orange tents selling berries and produce, crafts and cheap hot food. Grab a coffee and try the traditional karjalanpiirakka , a thin rye pastry boat filled with rice porridge and topped with egg butter, or a plate of fried vendace (little lake fish) Suomenlinna Sea Fortress — only a 15-minute public ferry from the Market Square , Suomenlinna was the highlight of Helsinki. Take the ferry out to the sea fortress spread across a cluster of islands. It was built by the Swedes in the 1700s and later held by Russia before Finland was ever independent. It's still a lived-in place, with a few hundred residents with cafés and small museums tucked among the ramparts. Give it a couple of hours to walk the shoreline, climb over the old bastions and cannons and poke into the dry dock and tunnels. I enjoy how peaceful the area was; the view back over Helsinki's island-dotted harbor from the ferry deck is the best in the city Allas Pool — a floating pool and sauna complex right on the harbor by the Market Square, with a heated freshwater pool, a cold Baltic seawater pool and saunas, all open-air looking straight out over the water. It is a very Finnish way to spend a couple of hours: sweat in the sauna, then plunge into the sea Temppeliaukio Church — the Church of the Rock, a Lutheran church from 1969 blasted straight into a granite outcrop, with rough stone walls, a huge copper dome and a ring of skylights that pour daylight inside. It is small and there is a modest entry fee, but it is unique and an easy walk from the center Seurasaari — a wooded island just northwest of the center that works as both a quiet nature escape and an open-air museum. The area is home to old wooden farmhouses, cottages and a church, all of which have been moved here from around Finland. They are scattered among the trees, with easy trails linking them. A good half-day if you want some nature and a slower pace Day Trips Porvoo — an easy 1-hour bus east of Helsinki and Finland's second-oldest town. It is a great place to experience a traditional Finnish town with cobbled lanes, a hilltop medieval stone church and the famous row of rust-red wooden shore houses lining the river, once used to store merchants' goods. Porvoo is small and made for slow wandering, with craft shops, cafés and old-fashioned sweet shops. Have a coffee or a local lager at a riverside spot and soak up the gentle pace before heading back. Porvoo is worth a half or full day to explore at a more relaxed pace Where to Eat Ravintola Kolme Kruunua — a classic old-school Finnish restaurant that has been serving home cooking since the 1950s. Come for the traditional stuff done well: Finnish meatballs, liver and sauteed reindeer in a cozy, slightly time-warped dining room. A reliable spot for proper Finnish comfort food without any fuss Lappi Ravintola — a Lapland-themed restaurant near the center done up like a northern log cabin, all timber and antlers. It leans hard into Arctic ingredients: sauteed reindeer , elk, Arctic char, creamy salmon soup and cloudberries for dessert. It is not cheap, but the food is genuinely good It is a great place to try sautéed reindeer ( poronkäristys ) served with lingonberries and mashed potato. The reindeer meat was preapred as thin shavings of gamey, rich meat that feel almost like a warm gyro Where to Stay Stay central near the Market Square or around Kamppi and the central train station . Helsinki is compact enough that almost anywhere downtown leaves you a short walk or tram ride from everything. It's a Nordic capital, so expect rooms to be expensive The Yard Hostel — a clean, modern, well-run hostel a short walk from the central station and Kamppi . The location is handy for the trams and an easy stroll down to the Market Square and the Suomenlinna ferry . There are great common spaces and a solid budget base in an otherwise pricey city ATTRACTIONS 1 Suomenlinna Fortress 2 Senate Square 3 Presidential Palace 4 House of Nobility 5 Market Square 6 Allas Sea Pool 7 Temppeliaukio Church 8 Seurasaari Island RESTAURANTS & BARS 9 Kolme Kruunua 10 Lappi Ravintola ACCOMMODATION 11 The Yard Hostel DAY TRIPS ↗ Porvoo (Full Day) FINLAND Helsinki Touch to explore Double-tap to open in Google Maps Other Places to Consider If I were to do it again, I would visit more than just Helsinki . Finland's real magic is in the far north and on the water: Lapland — the Arctic north is a whole different Finland reached by an overnight train or a short flight. Rovaniemi , on the Arctic Circle, is the main city and gateway. In the winter, you can experience northern lights, husky and reindeer sledding, snowmobiling and nights in glass igloos. It is also the \"official\" hometown of Santa Claus, with a year-round Santa Claus Village. If you visit during the summer, you'll experience the midnight sun and endless daylight The Finnish Lakeland — the vast maze of forest and interlinked lakes around Saimaa in the east, the classic Finnish summer escape. Every summer Finns head out to the Lakeland for two things: the mökki (a simple lakeside cabin) and the sauna Turku & the Archipelago — a couple of hours from Helsinki by train, Turku is the former capital on the southwest coast, a relaxed river city with a medieval castle and cathedral. Its real draw is as the gateway to the Turku archipelago, one of the largest in the world: thousands of rocky, forested islands you can explore on the ferries by car or bike, hopping between tiny island villages"},{"url":"georgia/field-notes.html","title":"Georgia Travel Guide","text":"Georgia Travel Guide General Georgia is one of the most underrated countries in the world and is starting to become very popular in the backpacker community. The small country is located in the Southern Caucasus lodged between Russia, Turkey and its other smaller neighbors Armenia and Azerbaijan. Georgia hosts jaw-dropping mountain scenery, ancient churches as the first Christian nation in the world, an incredible cuisine and Soviet Era history all packed into a small country. It's safe, affordable and welcoming to foreigners, yet still nowhere near as touristed as it deserves to be. Suggested Route Overview Getting around Flights — there are non-stop flights to Tbilisi from 32 countries including most major European cities and key hubs like Istanbul, Dubai and Qatar. You can also fly into Kutaisi and Batumi Ridesharing — Bolt and Yandex both work well for taxis and are super cheap. A 30-minute ride can run you less than 15 Georgian Lari or $6 USD Public Transport — despite how small the country is, it takes surprisingly long to get around and much of it is covered in mountainous terrain Shared Marshrutka (Minibus) — the cheapest way to get around Georgia is the \"Marshrutka\" or a shared Minibus that leaves when it is full. Find times online on Wander Lush 's Transport Tips section (the absolute best travel blog on Georgia), marshrutka.info , or ask a local! Budget travel time with Marshrutkas as they aren't known for their timeliness Trains — Georgia has a train network connecting its major cities. There are a mix of ultra modern trains that were built in the last few years and old Soviet Trains that move at a snails pace. View schedules online at the official Georgian Railway website GoTrip — a unique private taxi service that is surprisingly affordable and allows you unlimited stops along the way. I used this service to from Kutaisi to Tbilisi and made 4 stops along the way. I highly recommend this option if you're short on time and want to pack your day with activities. Expect to pay ~$100 per day Day Tours — these are a great way to avoid travel logistics and there are many that go to Georgia's more remote mountains regions like Kazbegi or Svaneti . Tours are generally very affordable from $20 - $30 Food — Georgian food is incredible, unlike the food I've had elsewhere and one of the best reasons to come. Here are a few of the highlights: Khinkali — large soup dumplings stuffed with lamb and beef. Grab them by the topknot, bite a hole, sip the broth Khachapuri — a bread boat of with pool of cheese and an egg cracked on top. Break off the pieces of the bread and dip them in the cheese to eat them Kubdari (or \"Svan Pie\") — a large meat pie stuffed with tenderized beef or pork, onions, garlic, and spices Wine — Georgia is considered the birthplace of wine and still uses its own ancient method of fermenting in clay pots (qvevri) buried in the ground. The amber \"orange\" wines are especially unique and the main type of wine they're famous for Chacha — is the local grape brandy which is very strong at 40% to 60% ABV. It is rude to refuse Chacha when it is offered to you and may be the reasons why Georgians drink the second most in the world! Language — Georgian has its own beautiful alphabet. There is tremendous ethnic diversity within Georgians themselves so there are 4 different Georgian languages with many local dialects on top of that. A lot of Georgians know Russian and English is common enough with younger people Money — Georgia is extremely affordable for tourists. I found Georgians also extremely fair with no \"tourist tax\" or scams that you'll find in other countries Safety — Georgia today is very safe and the country has made tremendous strides from the 1990's when it struggled with organized crime. However, Georgia has continuously had territorial disputes with separatist groups supported by Russia. Over 20% of its land is occupied since the 2008 Russo-Georgian War. When I visited, these areas were very well defined and fortified so there wasn't any fear of another conflict breaking out How to long to stay — for first timers, I'd recommend at least 10 to 14 days to thoroughly explore the country. You can also combine Georgia with a trip to Armenia ( read my guide here ) which is only a three hour bus ride or overnight train from Tbilisi Tbilisi 3 days recommended and add on additional days for day trips Tbilisi is one of my favorite cities in the world. It is the type of place where you could just spend days wandering or relaxing in a cafe. Officially founded in the 5th century AD, Tbilisi is one of the world's oldest cities and important hub on the Silk Road. Ancient churches, Soviet brutalism, ultra-modern sculptures and great restaurants are all within walking distance of each other. I would dedicate at least 3 days to exploring the city . It is also a great place to base yourself for day tours around the country so add on extra days here for each day tour. What to Do Old Town Tbilisi — a very pretty neighborhood, with cobblestone streets, carved wooden balconies and ancient churches tucked everywhere. The best place to stay to be walking distance from most major sites Clock Tower — a charming, crooked tower designed by Georgian artist Rezo Gabriadze, covered in intricate hand-painted tile mosaics. Visit Anchiskhati Basilica right next door Anchiskhati Basilica — right next door to the clock tower is one of the oldest churches in Tbilisi. It has small, dark, flickering candles and a polyphonic choir that performs daily at 10AM Dry Bridge Flea Market — a daily open-air market on the Dry Bridge where local vendors lay out old Soviet memorabilia, paintings, jewelry and other antiques on blankets and tables. Great place to buy souvenirs and make sure to negotiate Georgian National Museum — the national museum with the history of Georgia from prehistoric to modern times. The Soviet occupation hall is worth your time Queen Darejan Palace & Balcony — on the other side of the Mtkvari river, you'll find a Queen Darejan Palace terrace with a beautiful view of old town Right below the balcony by the river is Capela Sfântului Abo , a hidden shrine tucked away in a cave in the hillside with beautiful golden mosaics. Often missed by tourists Holy Trinity Cathedral — the largest and most impressive cathedrals in Georgia, the spiritual heart of Georgia. The gold dome towers over the entire city and is visible from almost everywhere. The interior is grand and solemn with towering vaulted ceilings, and the courtyard is lined with enormous stone crosses covered in intricate carvings Rike Park — a modern riverside park with bizarre alien-shaped sculptures and the futuristic, wavy Peace Bridge . A cool contrast to the old town right across the water. The beginning of the cable car up to the next location called Sololaki Street Sololaki Street — located on a hill overlooking old town. You can hike up here or take the cable car from Rike Park . Spend an afternoon walking down the Sololaki Street and visiting all the attractions on top of the hill. Mother of Georgia — a Soviet era silver statue of a lady watching over Tbilisi. She a perfect encapsulation of the Georgian national character: holding a bowl of wine in her left hand to greet friends and a sword in her right to ward off her enemies Tabor Monastery & Viewpoint — it is a rewarding climb up through an old Georgian neighborhood that most tourists skip entirely. There's a brand new boardwalk-style pathway and an almost 360 view at the top. In my opinion, the absolute best place to watch sunset Betlemi Rise Viewpoint — another great place to watch the sunset over old town. The walk up passes through the old Betlemi neighborhood with its wooden balconied houses National Botanical Garden — a 128 hectare garden tucked directly behind Narikala Fortress, with a history stretching back over 400 years to the royal gardens of the Georgian kings. The main draw is the 22-meter Leghvtakhevi Waterfall with a 19th-century wooden bridge crossing over it Soviet-era relics — Tbilisi is defined by both the Ancient Georgian kingdoms history and also the more recent Soviet history. Explore the architecture and art that defined this era Chronicles of Georgia — a massive, unfinished Soviet monument covered in metal biblical reliefs. Walk through the courtyard with huge Egyptian-like hieroglyphic pillars towering over you. It was absolutely mesmerizing and I caught a televised traditional Georgian dance performance at the top. It is a 20 minute ride from Old Town, but absolutely worth the trek and one of the highlights of Tbilisi Soviet Mosaics are scattered throughout the whole city, often cover the entire face of tall buildings. Some are hidden away and hunting them down is half the fun: Emergency Management Mural — an impressive Soviet-era mosaic on the side of the active fire station. The best view is from the balcony of the Central Bus Station or the parking lot next door Laboratory of the Ministry of Forestry Mural — a stunning Tree of Life mural that stretches 5 stories tall and is covered in vibrant colors. It is located in the neighborhood of Saburtalo Brutalist Architecture — I know brutalist architecture is an acquired taste (...and not for everyone). Tbilisi is home to some of the most famous examples including: Nutsubidze Skybridge — a checkered skybridge connecting two massive Soviet-Era apartment towers. Take the original coin-operated elevator and admire the striking geometric shapes. It feels completely forgotten by time. Located a short car ride from old town Palace of Rituals and Bank of Georgia are also striking Brutalist architecture sites in the city Fabrika — a converted Soviet clothing factory that has been remodeled into a street art area. There is a hostel, coffee shop, hip clothing shops, bars and street art. A great stop for a morning coffee Where to Eat Racha — a no-frills spot for khinkali, popular with locals. It was extremely affordable and I found myself eating here multiple times while I was in the city Cafe Daphna — an upscale restaurant serving some of the best beef khinkali in Tbilisi Puri Guliani — a modern restaurant located right next to the river. Get the Khachapuri and sample local wines here Pasanauri — another great restaurant with a great deer stew with pomegranate seeds, served with bread. One of my favorite meals in Georgia Sasadilo Canteen — hidden inside a warehouse market near the main train station. They had an amazing spread of bread with dips and cheese dumplings in a herb-oil sauce Amra — Abkhazian cuisine with unique regional dishes that are hard to find elsewhere in Georgia Where to Drink Shavi Coffee Roasters — the best coffee in the city, in a super trendy space inside an old building Apotheka — a popular bar in old town with an old pharmacy theme and great cocktails Wine Factory N1 — a good spot to try through a range of Georgian wines Graminea (\"Wet Fig\") — a wine shop in old town with a great selection. A relaxed place to sit and try a few glasses of Georgian wine Where to Stay Envoy Hostel Tbilisi — a hostel located right in Old Town Tbilisi, with an amazing rooftop overlooking the city. It is walking distance from all major historical sites. They also offer a number of affordable tours including unique one-way transfer tour to Yerevan from Tbilisi with a lot of interesting stops along the way ATTRACTIONS 1 Old Town Tbilisi 2 Clock Tower 3 Anchiskhati Basilica 4 Georgian National Museum 5 Capela Sfântului Abo 6 Holy Trinity Cathedral 7 Rike Park 8 Sololaki Street 9 Mother of Georgia 10 Tabor Monastery 11 Betlemi Rise Viewpoint RESTAURANTS & BARS 12 Racha 13 Cafe Daphna 14 Puri Guliani 15 Pasanauri ACCOMMODATION 16 Envoy Hostel & Tours DAY TRIPS ↗ Kazbegi (Full Day) ↗ Mtskheta, Gori and Uplistsikhe (Full Day) ↗ Kakheti Wine Region (Full Day) Georgia Tbilisi Touch to explore Double-tap to open in Google Maps Day Trips from Tbilisi Tbilisi is a great spot to base yourself for a variety of day trips throughout the country. Georgia is a relatively small country so it is easy to explore vastly different parts of the country by day trip. I've written about these trips in order of my favorite in case you're struggling to decide. Kazbegi — the Northern mountain region of Georgia located right on the border with Russia. The drive through the Georgian countryside alone is worth the trip: snow-peaked mountains, green valleys, herds of horses and sheep. Book a group tour from Tbilisi for about $20. Here are some key stops on the trip: Gergeti Trinity Church — perched high on a hill above the clouds with snow-capped peaks behind it. One of the most iconic images in Georgia and amazing to wander around for a few hours Georgian-Russian Friendship Monument — a circular fresco on top of a mountain pass built during Soviet times. It is very colorful with depictions of Georgian warriors on one side and Soviet soldiers on the other. It was a very pretty stop along the way, built completely in the middle of nowhere Zhinvali Reservoir & Ananuri — an ancient church from the Georgian golden age surrounded by a turquoise reservoir, with castle walls you can climb Mtskheta, Gori and Uplistsikhe — venture out to central Georgia with a historic tour of Mtskheta (the former capital of Georgia), Gori (Stalin's hometown) and Uplistsikhe (an ancient cave town). I did this trip independently since there are many public transit connections, but there are also day tours from Tbilisi Mtskheta — the ancient capital of Georgia located at the center of where three rivers meet. It lies only 20 minutes from Tbilisi with frequent connections so it is easily done as a half day to full day trip. The main thing to see in Mtskheta are the many churches. Here were my two favorites: Svetitskhoveli Cathedral — one of the largest and most impressive churches in Georgia. Locals come from all over Georgia to pray here. The cathedral has a massive yard, high vaulted ceilings and many gold frescos Jvari Monastery — built around 500–600 AD on a hilltop. There is an amazing view over the confluence of the three rivers, making it a great place to watch the sunset Gori — The infamous Soviet dictator, Stalin, was actually Georgian. He was born in Gori under the name Ioseb Jughashvili, later changing his name to the more Russian Joseph Vissarionovich Stalin. His hometown is a very interesting historical visit to learn more about the dictator's life Stalin Museum — a surprisingly well-curated museum where you can learn about Stalin's life. Take the guided tour for the best explanations. He was born to a poor Georgian family in Gori. As a young man he robbed banks and eventually transformed himself to the authoritarian leader of the communist party as well as one of the most important figures in history. You can visit his private train car and his childhood home here as well Gori Fortress — a broken down fortress in pretty bad shape, but a decent view of the city. At the bottom of the hill lies the Memorial of Georgian War Heroes . It is a striking WWII monument with a circle of knights each missing a body part, an intentional artistic choice Uplistsikhe — an ancient cave city carved directly into the sandstone cliffs, with a maze of tunnels, pagan temples, wine cellars, and dwellings dating back to the Iron Age. Once a major political and religious center on the Silk Road, it was later abandoned after the Mongol invasions. Today you can freely wander through its interconnected caves and climb to the highest point for sweeping views over the Mtkvari River valley Kakheti Wine Region Take a trip to Kakheti , Georgia's wine region in the country that invented wine! It is an easy day trip located only 2 hours east of Tbilisi. Here you'll find rolling vineyards, hilltop towns and family wineries still practicing the ancient Georgian tradition of fermenting wine underground in clay pots. Here is the tour I booked from Tbilisi with the following stops: Traditional Bread Baking — most tours start at a small family house where an old woman makes Georgian bread in a wood-fired oven, pressing the dough straight onto the walls without gloves. You eat it in the garden with salty Georgian cheese and sweet red \"breakfast wine\" Bodbe Monastery — a beautiful nunnery overlooking a huge valley, with two chapels (one modern, one from the Georgian golden age). The garden here is gorgeous and it is considered one of the best preserved monasteries in all of Georgia Sighnaghi — the Georgian \"city of love\" perched on a hilltop with castle walls wrapping right around it. It is a quaint little town where you can explore the cobblestone streets or walk the walls for great views over the valley. The Sighnaghi Viewpoint also has some great views of the town Find the Toastmaster (Tamada) statue in the main park. In Georgian culture, the Toastmaster or Tamada serves an important role in every feast. They give a toast and everyone drinks a liter of wine from a horn. Supposedly just touching the statue gives you better chugging ability Family winery in Kvareli — the most interesting stop where you see the ancient Georgian method of fermenting wine in clay pots buried in the ground. Make sure to try the local orange wines and a chacha tasting is usually included The final stop is the KTW Wine House where you explore the modern side of the Georgian wine industry. There is a tour through a modern wine warehouse with hundreds of huge metal storage containers. The tour leaders keep the wine flowing with unlimited pours. Our whole tour had a blast and it was a great chance to get to know the other people on the tour Svaneti Region 3+ days · fly or full-day drive from Tbilisi Svaneti was one of the most incredible mountain regions in the world and my personal highlight of Georgia. It is a remote mountain region covered in mysterious medieval stone towers, lush green valleys, dotted with colorful wildflowers and massive glaciers. It is an astounding place to hike and felt like a different world. Visit in the summer as the region since the roads are closed during the winter. Mestia is the main town and transport hub in the Svaneti region where you'll likely base yourself. There are many of smaller villages dotting the mountain valleys that are worth visiting to get a taste of traditional Georgian mountain life. Ushguli is one of the longest continuously inhabited settlements in Europe and one of the most popular to visit. Spend at least 3 days here , you won't regret it! How to Get There No matter how close it looks on the map, the journey to Mestia will be long and tough to figure out. The roads are particularly rough and transport options are limited. It is 1000% worth it when you get there, but just be prepared! Driving — Most Georgians would not recommend driving yourself since the roads are treacherous. As you get deeper in the mountains, they become one-way dirt roads with locals driving at break-neck speeds around blind corners Shared Marshrutka (Minibus) — this is the cheapest, but most challenging option to get to Mestia. Direct marshrutkas depart daily from Didube Bus Station in Tbilisi at around 7 AM and the journey takes 9–10 hours total and costs at ~50 GEL or ~$18 USD Train / Bus + Transfer via Kutaisi — the option I choose . I first took a train from Tbilisi to Kutaisi (~4 hours). I spent the night in Kutaisi and booked a transfer with BudgetGeorgia to Mestia for 80 GEL or $30 USD. We stopped on a few stops along the way with the drive taking 6 hours, but it was nice not having to deal with logistics Train / Bus + Marshrutka via Zugdidi — take the train from Tbilisi Central Station (once a day from 8:15AM to 2:20AM). From Zugdidi, catch a marshrutka to Mestia which takes another 3–4 hours. It can be difficult to time this transfer in the same day as marshrutkas from Zugdidi to Mestia are infrequent Private Transfer — the most comfortable, but expensive option. You can use a driver from GoTrip and expect to pay around 350–400 GEL ($125–145) for a minivan of up to 6 people one way. Journey takes around 7–8 hours. A great option if you can split with others or are traveling heavy bags Flight with Vanilla Sky — by far the fastest option at around 40–60 minutes and costs around 90 GEL (~$33) one way. These flights are in tiny 17 seater planes. The catch is that the flights are often cancelled due to weather (flying into the mountains in a tiny plane), the website is borderline non-functional and it sells out almost instantaneously. Best of luck if you try this option! What to Do Mestia Town — a tiny mountain town studded with Svan defensive towers. Walk the river, wander the side streets and just take it all in. The local region is inhabited by the Svan people who have their own language and rich cultural heritage. Each family is in charge of maintaining their own medieval tower (dating back to the 8th and 9th centuries) that was used to protect against invaders and avalanches Mikheil Khergiani House Museum — a charming museum run by a local family dedicated to a legendary Soviet climber Mikheil Khergiani. It is located on the edge of town. Climb to the roof of the tower for one of the best views in the whole region! Standing on top of a tower is a bit sketchy, but worth it Chalaadi Glacier hike — a short ~45-minute hike through forest and red and white rocks to the glacier. Hire a 4WD driver from Seti square to take you to the head of the trail or book a group hiking tour for 80 GEL Ushguli — one of the most beautiful places I've ever visited. A cluster of four medieval villages at 2,200m with ancient Svan towers rising above roaming horses and green hills covered in colorful wildflowers, and the massive white peaks of the Caucasus forming the backdrop. The whole place feels completely frozen in time. It is a 1.5 hour drive from Mestia and I booked this day tour Queen Tamar Castle — climb up to this viewpoint above the village for the best view in Ushguli. You can see the full valley with towers below and huge white mountains behind. The hillside covered in wildflowers just below the tower is one of the most beautiful spots on the whole trip Lamaria Church — a 12th century church perched on a hill above the village. Walk around the outside rather than just going in since the views back down over the valley are stunning Mestia to Ushguli hike — Georgia's most famous multi-day trek and considered one of the best hikes in the Caucasus. The full route covers about 57km over 3–4 days through high mountain valleys, medieval Svan villages and some of the most dramatic scenery in the region, passing under peaks that top 5,000m. In each village, you stay at family-run guesthouses that provide a bed and home-cooked meals Where to Eat Cafe Laila (Mestia) — the most popular restaurant in Mestia. Get the local Svan specialties including the Kubdari (a huge pita stuffed with beef and onion) and a mulled wine Ine's Corner (Mestia) — a tiny restaurant run by an old woman and her daughter. A great spot for breakfast Agra Cafe (Ushguli) — a small cafe inside of a traditional Svan house. Try the Matsoni soup, a white cheesy soup served with a side of bread Where to Stay Latour Mestia — a wonderful family-owned hotel with a brand new wooden lodge interior. Located in a quiet area and a short walk from the center of Mestia. The owner was extremely friendly and helpful Other Places to Consider Georgia is small and packed, so it's easy to string together more stops depending on how much time you have: Chiatura — a fascinating former Soviet mining town tucked into a narrow river valley. The town is full of old apartment blocks, rusting industrial infrastructure, and dramatic cliffs connected by cable cars, giving it an unmistakably post-Soviet atmosphere Cable cars — originally built in the 1950s to transport miners and residents across the steep valley, Chiatura's cable car network is one of the most unusual public transport systems in the world that is still used by locals today. Ride the modern gondola for panoramic views over the town, then seek out one of the surviving retro cable cars with their distinctive bubble windows The Mines — at the top of the cable cars lie the abandoned remnants of Chiatura's once-massive mining industry. One of the highlights is a gigantic excavator , with hard hats, documents, and equipment still scattered inside the operator's cabin Katskhi Pillar (near Kutaisi) — a towering 40-meter limestone monolith supports a tiny monastery perched impossibly on its summit. For centuries it served as a retreat for solitary monks seeking isolation, and even today only the resident monk is permitted to climb to the top. It is located close to Kutaisi, but is not worth going out of your way to see Kutaisi — the second largest city in Georgia and worth a stop mainly as a base for the surrounding area. The real draws are the day trips: Gelati Monastery, Prometheus Cave, Martvili and Okatse Canyons and Chiatura Batumi — Georgia's Black Sea resort city, sometimes called the \"Las Vegas of the Black Sea\" for its casinos, glitzy skyscrapers, nightlife and popularity among Russian gamblers. The seafront boulevard is the heart of the city and great for walking. Other highlights include the charming old town, the Argo Cable Car and the rotating Ali and Nino statue. Modern and very different from anywhere else in Georgia"},{"url":"germany/field-notes.html","title":"Germany","text":"Germany General Germany is a country where regional differences are more noticeable than you might expect: Bavaria in the South feels distinctly different from Berlin, Hamburg, or the Rhineland, with its own traditions, food, architecture, and festivals. I've visited roughly four times, although several trips were either brief or quite a while ago, so these notes focus primarily on my most recent visit to Munich and Oktoberfest . Munich is a large city in southern Germany's Bavaria province with plenty to see year-round, but for two weeks every September and October it becomes the center of the world's attention as millions of visitors descend for Oktoberfest. You'll often hear Germans recommend smaller regional Volksfests instead, which can be cheaper and feel more local like Stuttgart 's Cannstatter Volksfest . However, I went into Oktoberfest expecting an overhyped tourist spectacle and ended up having an absolute blast. It's worth experiencing at least once. I spent five days at Oktoberfest, which was way too much . I'd recommend around 2 days at the festival , followed by another 2–3 days exploring Munich and the surrounding Bavarian countryside . That gives you enough time to experience the chaos without letting the festival completely take over your trip. Suggested Route Overview Getting around Trains — German rail deserves its reputation. The ICE high-speed network links every major city, and from Munich you can be in Salzburg , Nuremberg or Garmisch in around two hours, which makes day trips into Bavaria easy Flights — Munich Airport is well connected to the rest of Europe with budget carriers offering flights for less than 50 Euros. One thing to plan for: the airport sits well outside the city, so the S-Bahn into the center takes about 45 minutes Getting around Munich — the U-Bahn and S-Bahn lines cover everything you need and run late into the night, which matters during Oktoberfest. The festival grounds have their own stop, and the trains back into town at the end of the night are absolutely rammed. Munich is also flat and very walkable, so I ended up on foot more than underground Money — as a member of the EU, the Euro is the official currency of Germany. Germany is mid-priced for Western Europe. Munich outside of festival season is reasonable, but Oktoberfest is its own economy where everything is marked up For Oktoberfest specifically, a Maß (the one-liter stein of beer) runs about €15 before you have tipped, food inside the tents is roughly €17–€30 for a typical meal, and the lederhosen I bought from a shop outside the center cost €120, which I was told was a fair price Food — the food in Munich is Bavarian and unapologetically heavy. Munich is a very international city and you'll find a variety of international food options around the city. I had really good Asian and Turkish food there when I wanted to take a break from German food. Here are some local Bavarian dishes that are worth trying when you're in Munich: Weißwurst is the one to try first: a white veal sausage served floating in its own broth, traditionally eaten before noon and never with the skin on Beyond that it is pretzels the size of your head, schnitzel, roast pork with dumplings, and currywurst and bratwurst from street stands. The beer gardens are the real institution though, and an afternoon at a big one like Augustiner Keller is worth a visit Language — unsurprisingly, they speak German in Germany. English is common in Munich and you will get by fine pretty much in the entire country. Learn danke , bitte and ein Maß bitte and you will get a warmer reception When to go — despite it's name, Oktoberfest is mainly in September! It actually runs from mid or late September into the first weekend of October The festival has special ceremonies on the first and last few days which are completely worth planning your trip around. Every year, Oktoberfest opens on a Saturday when the mayor taps the first keg at noon in the Schottenhamel tent, and the costume parade is the next morning Both are worth planning around, though we managed to miss the parade entirely by getting comfortable at a table and losing track of time. Outside the festival, late spring and summer are the best months to visit Munich for the beer gardens and the English Garden Munich 2–3 days recommended Munich is Bavaria's bustling capital, where grand architecture, traditional beer halls and sprawling parks give the city a distinctly southern German character. The historic center is compact and easy to explore on foot, centered around the imposing Marienplatz and its surrounding churches, palaces and old streets. Outside the center, the city has a more modern side, from the enormous English Garden and its famous river surfers to some of Germany's best museums and galleries. Munich also makes an excellent base for exploring Bavaria , with the Alps, lakes, castles and smaller towns all within easy reach. I've actually visited Munich a couple times: once as a kid and more recently for Oktoberfest. I'd recommend spending 3 to 5 days here with 2 days dedicated to Oktoberfest if you're visiting around that time. The City Marienplatz — the main square and heart of the old town. It is a great place to begin your journey in Munich with a plethora of historic buildings and busy shopping streets Neues Rathaus (New Town Hall) — the enormous neo-Gothic building dominating Marienplatz . At 11am everyday, people gather for the Glockenspiel show , where life-size figures come out of the mechanical clock and start dancing. I didn't find the show to be particularly impressive compared to other mechanical clocks that I'd seen in Switzerland . You can also tour the building, but there wasn't much inside either St. Peter's Church & Tower — Munich's oldest parish church with a really tower overlooking the city. It is 306 steps up to the top of the tower (with no elevator), but it is well worth the climb since it opens onto the best view in the city: straight down onto Marienplatz and the Neues Rathaus , and on a clear day all the way to the Alps Viktualienmarkt — the daily food market just off Marienplatz that has been running since 1807. Explore the various stalls selling cheese, sausage, bread, spices and produce around a painted maypole. The real draw is the beer garden in the middle of it, which is shaded, central and open to anyone, and is where I ended up over curry sausage and a beer on my last night in the city Asamkirche — a tiny, avantgarde Baroque church wedged between shopfronts on a busy street. The entrance is so narrow you can walk past the door without noticing it. The Asam brothers built it as their own private chapel and every surface inside is gilded, painted or carved. It is definitely worth a stop since it is free and is very quick to explore Munich Residence — the Wittelsbach family's city palace and the largest in Germany, a sprawl of ten courtyards and 130 rooms right in the center. The Antiquarium is a barrel-vaulted Renaissance hall covered in frescoes which is the single most impressive room in the city, and the treasury next door is worth the combined ticket English Garden — one of the largest urban parks in the world (bigger than New York's Central Park) and a green space locals will frequent during the summer. Here you'll find beer gardens under the trees, green fields for sunbathing, and long paths along the streams. Don't miss the Eisbach , a standing wave on a river channel by the south entrance where wetsuited surfers queue up and ride right in the middle of the city, year-round. It's mesmerizing to watch even if you never get in the water Take a swim in the Isar River — if you're up for a bit of a cold swim, hop into the Isar River that flows right through the English Garden . It is a fast, cold alpine river so be prepared to for the cold temperatures and to fly down the river. It is a popular activity among locals. Even just walking or cycling the leafy banks is a lovely way to spend an afternoon if you don't want to hop into freezing water Odeonsplatz & Karlsplatz — two grand open squares respectively at the north and west end of the old town. They're connected to the pedestrian shopping streets that run straight through to Marienplatz so you'll probably walk by and it is worth taking a minute to admire these squares Where to Eat Augustiner Biergarten — the classic Munich beer garden and the one I would send anyone to: enormous, shaded by chestnut trees and seating a few thousand people without ever feeling crowded. We took over three tables here with people from the hostel and stayed all afternoon into the evening. In the self-service section, you are allowed to bring your own food and just buy the beer, which is a bonus Hofbräuhaus München — the 16th-century state beer hall and the most famous drinking room in the world, complete with vaulted ceilings, an oompah band and liter steins carried six at a time. It is thoroughly touristy and locals will tell you so, but I still really enjoyed the food here Khanittha Im Werksviertel — a genuinely good Thai place out in the Werksviertel . If you're staying in the area and are craving Asian food, this place was amazing. I stayed in the hostel next door and ended up having it twice. A good Thai meal really hit the spot after traveling through Europe for 3 months Where to Stay Stay central, in the Altstadt (old town) or near the Hauptbahnhof (main station) , for the easiest transit around the city and walkability. If you're planning to go to Oktoberfest, book months ahead and expect prices to double or more. The whole city fills up, and even hostel beds and the campsites out by the fairground go fast Wombat's Munich Werksviertel — a big, well-run hostel in the Werksviertel neighborhood . It is a the converted industrial quarter that is now full of bars and street food. It is a little out of the old town, but you can easily get to Altstadt (old town) by train in just 20 minutes. It was a nice hostel, but I would chose something closer to old town if you have the option ATTRACTIONS 1 Augustiner-Bräu 2 Hacker-Pschorr 3 Hofbräu 4 Marienplatz 5 English Garden 6 St Peter's Church & Tower 7 Viktualienmarkt 8 Asamkirche 9 Karlsplatz (Stachus) 10 Odeonsplatz 11 Munich Residence RESTAURANTS & BARS 12 Augustiner Biergarten 13 Hofbräuhaus München 14 Khanittha Im Werksviertel ACCOMMODATION 15 Wombat's Werksviertel DAY TRIPS ↗ Isar River (Half Day) Germany Munich Touch to explore Double-tap to open in Google Maps Oktoberfest 2 days recommended For two weeks from late September, the legendary Oktoberfest is celebrated in Munich . It is known world-wide as a massive beer-drinking festival, but originated from a deep Bavarian tradition of celebrating the harvest. Around six million people come through the Theresienwiese (the festival grounds), the whole city puts on Tracht (traditional clothing like the lederhosen and dirndl ), and the tents run from mid-morning until late every day. You do not need a ticket and entry is free. What you need is a table (which means turning up early) and a desire to drink beer! Below are some tips to make sure you'll have an enjoyable time: The Tents The grounds — the festival sprawls across the Theresienwiese (\"the Wies'n\"), an enormous fairground of 14-odd giant beer tents, each run by one of Munich's historic breweries. Each one of the 14 tents is massive, has a different theme and seats thousands. You can also wander around the fairgrounds to enjoy carnival rides, games and food booths. Entry is free, but you pay for the beer and the rides. Every tent has its own distinct crowd and feel, so which one you pick genuinely matters: Schottenhamel — the historic tent where the Mayor of Munich taps the very first keg with a shout of \"O'zapft is!\" to open the festival. It is near-impossible to get into on the opening weekend, but is worth a stop since it is one of the traditional tents Augustiner-Bräu — the local favorite and most traditional tent, still serving its beer from old wooden barrels. It draws more Müncheners than tourists and has arguably the warmest atmosphere of the lot. It's popular for exactly that reason. Make sure to arrive before noon to ensure you have a table (especially on the first few days or weekends) Hacker-Pschorr — the one for a full-blown party: a great live band that pivots from oompah tunes to pop-song singalongs as the day goes on. There was a very pretty \"Bavarian heaven\" ceiling when I was there, with a young crowd standing on the benches by mid-afternoon. Less about tradition, more about the atmosphere, and a reliably brilliant time Hofbräu — the big international party tent and the most touristy of the bunch, but still a lot of fun. The large outdoor area is often less packed if you can't get a seat inside. The Beer — served only in a Maß , a full 1-liter stein. During Oktoberfest, each brewery serves special Oktoberfest beer that is brewed specifically for the festival. The serving size is huge and at around 6% ABV, so one or two land harder than you expect! You're typically at Oktoberfest for a whole 8 to 12 hours so eat as you go and pace yourself appropriately. Expect beers to cost €15 each Clothing — rent a Dirndl or Lederhosen ! It was really fun to dress up (even if you think you look silly at first. Almost everyone dresses up and you'll feel out of place in regular clothes. I bought a lederhosen for €120, which I was told was a fair price Rides & recovery — it's a full-blown fairground as much as a beer festival, with old-school carnival rides, a big wheel and haunted houses (the chain swing ride out over the city lights after dark is the one to do). Be wary of the grassy slope outside the tents, affectionately known by locals as \"Vomit Hill,\" is the local institution for people who get way to drunk to lie down and sleep it off in the afternoon sun What to Eat Currywurst — sliced grilled sausage drowned in a tangy curry-spiced tomato sauce and dusted with more curry powder, usually served with fries or a bread roll. A popular German street-food sold at Imbiss (snack stands) all over the city Bratwurst — the grilled pork sausage that's everywhere. There are many different varieties sold at the food stalls. The skinny Nürnberger-style ones from the Oktoberfest grills, tucked into a crusty roll with a smear of sweet mustard was incredible Steak Onion Sandwich — the late-night Oktoberfest staple: a griddled steak roll piled with fried onions from the stands outside the tents. It was an amazing snack when the beer halls empty out and you're on your way home Other Places to Consider These notes focus on Munich and Bavaria, but Germany is a huge country with plenty more to explore. I've been to some of these places ( Berlin , Cologne & Frankfurt ) briefly and would love to comeback for another visit: Berlin — the edgy, endlessly layered capital and a total contrast to buttoned-up Munich. It's soaked in 20th-century history (surviving stretches of the Berlin Wall and the East Side Gallery , the Brandenburg Gate , the sobering Holocaust Memorial , Checkpoint Charlie ), stacked with world-class collections on Museum Island , and home to some of the most legendary nightlife on earth. Give it several days of its own Neuschwanstein Castle — the white hilltop castle built by \"Mad\" King Ludwig II that inspired the Disney logo, set against the Bavarian Alps about two hours south of Munich. It's a very doable day trip from Munich : book timed-entry tickets well ahead, and walk up to the Marienbrücke bridge for the classic view of the castle floating above the forests and lakes The Rhine Valley — the dramatic stretch of the Rhine between Koblenz and Rüdesheim (roughly between Cologne and Frankfurt ), where terraced vineyards and dozens of medieval castles crowd the steep hills above the river. It's a beautiful landscape best seen slowly from the deck of a river cruise, hopping off at wine villages like Bacharach or below the legendary Lorelei rock Hamburg — Germany's maritime city in the north, built around one of Europe's biggest ports and threaded with canals (it has more bridges than Venice and Amsterdam combined). The wave-roofed Elbphilharmonie concert hall is the modern landmark, the red-brick Speicherstadt warehouse district is a highlight, and the Reeperbahn in St. Pauli is the famously rowdy nightlife strip Cologne (Köln) — a laid-back Rhineland city whose reason to visit towers over everything: the vast, soot-blackened Gothic Kölner Dom cathedral, which rises straight up beside the main station the moment you step out. The old town itself is small, a few squares of colorful gabled houses, but the riverside is lovely: walk out onto the Hohenzollern Bridge , blanketed in thousands of love locks, for a gorgeous view back over the cathedral and the Rhine. I enjoyed my visit in 2023, but wouldn't recommend going out of your way to visit Cologne Frankfurt — Germany's banking capital and the site of its busiest airport, so there's a fair chance you'll pass through. It's smaller than I expected and was completely flattened in WWII. There is a nice rebuilt town center The real reason to linger is the food: cross the river to the Sachsenhausen district. I had a wonderful meal at Daheim im Lorsbacher Thal , approved by my local German friend. It is a traditional German restaurant specializing in local Apfelwein (a dry, tart cider) and the local Grüne Soße, a cold sauce of seven fresh herbs, usually served with schnitzel. It was a solid way to spend a long layover, but I also wouldn't go out of your way to visit Frankfurt"},{"url":"greece/field-notes.html","title":"Greece Travel Guide","text":"Greece Travel Guide General Suggested Route Overview Greece is one of the most visited countries in the world (and rightfully so)! Home to one of the most influential ancient civilizations, beautiful beaches, amazing food and some of the most friendly people in the world, Greece has everything you could ask for in a vacation destination. It is also a lot more affordable than many other popular European destinations Getting around Intercity bus system (KTEL) — a cheap and reliable way to get around the country. It provides connections all throughout the country Island hopping by ferry — if you're visiting the Greek Islands, ferries are some of the best ways to get around. Purchase your tickets in advance since popular routes often sell out during the summer. Ferryhopper or directferries are great resources to find routes and book tickets Flights — there are a lot of affordable domestic flights from Athens to most of the islands. Ferries can often get expensive so check for cheaper flights Food — Greek food is one of my favorite cuisines and there is so much more than just street gyros. It can be extremely affordable at local spots: a full meal at a local taverna is usually under 10€. Here are some dishes that are worth trying: Spanakopita — a savory, flaky pastry typically made of spinach and feta Moussaka — a baked casserole features layers of eggplant, potatoes, and spiced ground meat, all topped with a thick, creamy layer of béchamel sauce Souvlaki & Gyros — grilled meats often served with fries. Available almost everywhere and always a quick cheap option Greek Salad (Horiatiki) — a fresh, vibrant dish made with chunky tomatoes, cucumbers, kalamata olives, onions, and a thick block of feta cheese, dressed with olive oil and oregano Dolmades — tender grape leaves tightly rolled and stuffed with a savory filling of seasoned rice and herbs, sometimes mixed with ground meat Baklava — a rich, sweet pastry made of layers of phyllo dough filled with chopped nuts and sweetened with honey syrup Athens 2–3 days recommended Athens is one of the oldest cities in the world stretching all the way back 5,000 to 7,000 years ago. You can feel this when you're here; the history is literally everywhere from ancient ruins sitting in the middle of neighborhoods to columns visible through metro station floors. However, it is grittier than you might expect so set your expectations accordingly. I'd recommend spending 2 - 3 days here or even longer if you're a history buff. Make sure you stay near the Plaka or Monastiraki Square as everything is walkable from here. Some neighborhoods in Athens are dodgy and extremely run down so make sure you double check before booking. What to Do Acropolis — the most iconic spot in all of Greece. Situated on the top of a large hill overlooking the city, you can see the Acropolis from almost anywhere and it even lights up at night. Buy the Athens City pass which is the combined ticket which gets you into several other archaeological sites. Give yourself 2–3 hours and go early since it can get very crowded by midday. The temples are impressively intact for their age and the views over the entire city from the top are excellent Ancient Agora — a huge park with statues and columns scattered throughout and the birthplace of democracy. The temple at the top of the hill is one of the best-preserved ancient temples in Greece. The museum inside has a great artifact collection Syntagma Square & Changing of the Guard — the square where the Parliment of Greece is located. Everyday at 11am there is a changing of the guard ceremony. A marching band in modern military dress, followed by the Evzone guards in traditional Greek uniforms perform a ceremonial march that is great to watch Plaka neighborhood — one of the nicest areas in Athens, filled with winding streets, neoclassical buildings, restaurants, and souvenir shops. One of the best areas to stay as well Monastiraki Square — a lively square with a great view up to the Acropolis Hadrian's Library — an ancient Greek library built by Emperor Hadrian in 132AD, complete with a reading room, gardens and lecture halls. The ruins are pretty minimal today, mostly just the outer wall and some columns. I would skip this in favor of the other historical sites in Athens Bolivar Beach Club — there are beaches in Athens too! If you're craving a beach day, you can head 45 minutes from the city center by bus to Akti Iliou beach . Bolivar Beach Club has nice chairs, umbrellas and clear blue water and is less of a party vibe than your traditional beach club Where to Eat Eatery Bairaktaris Aiolou 29 — my favorite restaurant in athens serving traditional Greek food. It is affordable and located right by Monastiraki Square The Plaka neighborhood near the Acropolis is lined with restaurants so wander around and you'll stumble upon a place to eat Where to Stay Mosaikon Glostel - one of the nicest hostels I've ever stayed at with a rooftop bar, view of the Acropolis and great location. Expect to pay more since it is a premium hostel YellowSquare Athens — a clean hostel that is very organized and a walkable location, but not located in the nicest neighborhood. They have a rooftop where you can see the Acropolis ATTRACTIONS 1 Acropolis 2 Ancient Agora 3 Syntagma Square 4 Monastiraki Square RESTAURANTS & BARS 5 Eatery Bairaktaris Aiolou 29 ACCOMMODATION 6 YellowSquare Athens 7 Mosaikon Glostel Greece Athens Touch to explore Double-tap to open in Google Maps Meteora 2 days recommended Meteora is home to famous monasteries perched on top of massive rock pillars rising straight out of a green valley. It was one of the most impressive landscapes I've ever seen and a must if you're ever in Greece. Although there are day tours from Athens, I would recommend staying at least 1 night to fully experience Meteora and hike in the area. There are two main towns that you can stay in to visit Meteora: Kalambaka — this is the most popular town for tourists visiting Meteora. It is based around a small square with lots of accommodation options and restaurants Kastraki — located only 5 minutes away from Kalambaka, it is a small village right at the base of the rocks. I would recommend staying here as it is much more peaceful, has better views and everything is a 5 minutes walk away. You can also hike to the monasteries directly from the town Located in the mountains of Northern Greece, it is a bit difficult to get to so bake in a day for transport. By bus, it is located 6 hours from Athens and 4 hours from Thessaloniki (with a transfer in Trikala). Book your tickets here . What to Do Sunset Viewpoints — there are two viewpoints that are just huge rocks called Viewpoint Meteora and Main Observation Deck of Meteora on Google Maps. You'll have unobstructed views down into the valley and see all the monasteries from here. I prefered the \"Viewpoint Meteora\", but views are incredible from both. Plan to arrive 30 minutes before sunset as the viewpoints get very crowded Rent an E-Bike — this was my favorite way to get around. The e-bikes make the hills a breeze and bombing the downhills on the way back was so fun. There isn't much traffic on the roads. Expect to pay roughly 15€ for 2 hours or 25€ for the day. There are shops both in Kastraki and Kalambaka Hike between the monasteries — spend a day hiking between the monasteries (~11 miles or 17km round trip). You'll have the trail completely to yourself as most tourists come by tour bus. Get a paper map from your accommodation and ask them to walk you through the trails since the trails are not on any app and not clearly marked Monasteries require you to be covered so bring long pants or use the cloth wrap provided at each monastery entrance Visit the 6 Monasteries — you can visit all 6 monasteries with each of them closed on a different day of the week and some close midday (so check hours)! Only certain portions of each monestary will be open to the public so some of them are very quick visits (10 - 15 minutes). Don't feel the need to visit all of them. I would chose 2 - 3 to focus on (Great Meteoron and Roussanou were my favorite). Each monestary costs 3€ to 5€ to enter Great Meteoron — the biggest and oldest monastery (founded in the 14th century). It has a wine cellar, museum with Byzantine manuscripts and an old church with impressive frescoes. The monks here make both wine and beer here! Varlaam — the most castle-like from the outside with a circular wall surrounding the entire complex. Has a famous 17th century frescoed church and an old wooden winch that was historically used to haul up both supplies and visitors in a net Roussanou — a nunnery with a beautiful small prayer room inside and stunning frescoes depicting scenes of Christian martyrdom. A very small monestary, but well worth it Holy Trinity (Agia Triada) — the most dramatic setting of all six, perched on a freestanding pillar with a 140-step tunnel carved directly into the rock leading up to the entrance. Featured in the James Bond film For Your Eyes Only St. Stephen (Agios Stefanos) — the most accessible monastery since you enter by a bridge rather than stairs. Now a nunnery run by an order of nuns known for their intricate embroidery work, which you can see and buy inside St. Nicholas Anapafsas (Agios Nikolaos) — the smallest of the six but has some of the best-preserved 16th century frescoes Holy Spirit Rock hike — a 40-minute hike up to the top of a massive boulder with the best view of Kastraki below. There is a tiny white church embedded in the side of a rock. You'll almost certainly have it entirely to yourself, the view is very rewarding and you might spot some turtles on the way. The hike is not online, but here is a detailed guide on how to navigate Where to Eat Kastraki Taverna Gardenia (Kastraki) — the best restaurant in Kastraki with great moussaka and a free Lemonopita dessert. They also sell a local beer made by the local monks which is very interesting to try Kofi Hub — a wonderful little coffee shop located on the main street in Kastraki Αρτοποιείο Μπαταλογιάννης Ευάγγελος — small bakery run by an old man where you can grab spiral feta rolls and spanakopita for breakfast or snack Kalambaka Restaurant Meteora Gkertsou Family — an incredible restaurant with amazing lamb cooked in red wine with rice. It is a bit more expensive, but portion sizes were huge Octo Coffee & Breakfast — a brunch spot with incredible homemade juices Where to Stay I would suggest staying in Kastraki over Kalambaka. The same bus from Trikala to Kalambaka will often continue on to Kastraki or you can take a taxi for just 5€ Thalia Rooms (run by Ritsa) is a nice affordable option. The host named Ritsa was extremely friendly and helpful! She'll give you a paper map, show you the hiking trails and help you plan your itinerary on arrival ATTRACTIONS 1 Great Meteoron 2 Varlaam 3 Roussanou 4 St. Nicholas Anapafsas 5 Holy Trinity (Agia Triada) 6 St. Stephen (Agios Stefanos) 7 Viewpoint Meteora 8 Main Observation Deck of Meteora 9 Holy Spirit Rock hike RESTAURANTS & BARS 10 Taverna Gardenia 11 Kofi Hub 12 Batalogiannis Bakery 13 Restaurant Meteora Gkertsou Family 14 Octo Coffee & Breakfast ACCOMMODATION 15 Thalia Rooms Greece Meteora Touch to explore Double-tap to open in Google Maps Santorini 3–4 days recommended The most iconic island in Greece known for the famous blue domes and white-washed buildings, jagged black cliffs and caldera views. It gets extremely crowded in peak season. Book accommodation well in advance. There are plenty of activities that you can do over the course of 3 - 4 days. I personally prefer other Greek Islands over Santorini as the crowds can be a bit overwhelming. There are two main places to stay on the island: Oia is the more famous end of the island covered in the iconic white buildings with blue domes. It is based around one hillside that is covered with little honeymoon suites and a view overlooking the ocean. It is a great place for sunset and where all the fancy restaurants are. It tends to be the more expensive option and gets extremely crowded Fira (also known as Thira) is the main town on the island. I enjoyed being here more as it was less busy and much more affordable. I would recommend staying here as you can always walk or take a bus to Oia What to Do Hike from Fira to Oia — a great hike along the coastline of Santorini and a great way to explore the island. It takes roughly 2–3 hours and runs about 6.5 miles or 10.5km from end to end, but is very managable. It is a well-labeled trail that mixes paved city roads, hairpin mountain paths and dirt tracks. You'll have a nice view of the oceans and see many tiny one-room churches dot the route. Oia at the end is more polished with better blue-domed churches. Take the bus back to Fira Watch the Sunset at the Castle of Oia — the famous one. Gets absolutely packed — arrive at least an hour early and find a bar with a view before the crowd fills in. Standing in the crush is chaotic; a seat at a reasonably priced bar makes it much better Karavolades Stairs & Donkey Ride — you can either walk 30 minutes down a set of windy stairs from Thera to the marina along the caldera rim ...or you can ride a donkey down and enjoy the view. The donkeys are a bit wild, starting and stopping abruptly. It is a fun experience and only costs $10 one way Panoramic View Fira — this is one of the best viewpoints in Fira Three Bells of Fira — a famous blue domed church located right in Fira town Perissa Beach — the black sand beach on the south side of the island if you're looking to relax on the beach. However, it is not a spectacular beach so don't worry if you miss it Boat tour around the Caldera — this is a boat tour that typically departs from the Fira marina that includes a visit to the volcanic island, mud baths and hot springs. The fancier versions include dinner, drinks and sunset views. Unfortunately, I was sick and wasn't able to go, but heard it was worth it from other travelers Where to Eat Svoronos Bakery — an amazing bakery located in Thira Taverna El Greco — solid brunch spot with a great iced coffee and Greek omelette Vero Latte Gelato Santorini — a really good gelato shop in Fira Zafora Bar — a bar overlooking the old town of Fira. Cheap beers and a good atmosphere at night Where to Stay Fira Backpackers Place — a hostel located right in Fira town. I met some great people here. Many of the hostels are located from Thira or Fira so choose based on location ATTRACTIONS 1 Castle of Oia 2 Karavolades Stairs 3 Panoramic View Fira 4 Three Bells of Fira RESTAURANTS & BARS 5 Svoronos Bakery 6 Taverna El Greco 7 Vero Latte Gelato Santorini 8 Zafora Bar ACCOMMODATION 9 Fira Backpackers Place ACTIVITIES ✦ Caldera Boat Tour (Half Day) Greece Santorini Touch to explore Double-tap to open in Google Maps Ios 2–3 days recommended I went to Ios on a whim after hearing two Australian guys rave about it and it ended up being my favorite island in Greece. It has everything you could want including: beautiful beaches, some of the best sunsets in Greece, amazing nightlife, great food and a charming old town perched on the hill above the port. I'd recommend it over more popular spots like Santorini or Mykonos What to Do Chora — the charming old town perched on top of the hill with white-washed buildings and blue domes. This is the best place to stay since most of the attractions, restaurants and hotels were here. It was very calm during the day, but came alive at night Church of Panagia Gremniotissa — located at the very top of the mountain above Chora town with palm trees and smaller white chapels on the hill above. It is a great sunset spot as you have a complete view of the coastline below Mylopotas — stay in this area if you want quick access to the beach. There were also plenty of restaurants, hotels and shops here FarOut Beach Club — one of the most lively beach clubs in Ios. They also have a hostel where you can stay Little Gem — an unlabeled spot on the cliffs near Harmony Ios restaurant. A beautiful viewpoint to look at the water that is blue-green and completely transparent below Pathos Bar — hands down one of the best places to watch the sunset in Greece. It is a huge open-air bar built into the mountainside overlooking the sea. The place is covered in modern art sculptures, two waterfront pools, a DJ inside a circular spiral and a pier out over the water. I went here two days in a row to watch the sunset which was absolutely incredible ATV around the island — the best way to explore the island. Rent an ATV and head out of the old town and explore the island. Ios feels pretty remote once you leave old town. There is also no traffic besides a few local Greek farmers, but the roads can be a bit windy. Expect to pay about 70€ for a full day or split with a friend. I would suggest going from Chora to Mylopotas beach and then on to some of the following more remote locations: Agios Ioannis Church — remote hilltop church with a large open courtyard and bells. Almost no visitors while I was there and it was very serene and peaceful Loretzaina — small secluded beach recommended by a local. Very clear water and almost no one there Paralia Gialos — the main beach near the port. Good for a relaxed afternoon Magganari Beach — supposedly the nicest beach on the island. Take the boat taxi from the port as it is too far for an ATV Where to Eat Kabouris Restaurant — solid Greek food in the old town. Try the moussaka — eggplant, meat and mashed potato, heavy and very good Salt — right on Paralia Milopotas beach. Great Greek salads with large croutons Beach House Ios — right on the beach near the port with excellent seafood Nightlife It is no secret that Ios is a party island. Most fo the nightlife is concentrated along one small road in Chora so it is really easy to hop around to different spots. Ios doesn't have much public transport or taxi's so most people stay in Chora at night. Here are some spots worth visiting (also stops on the local bar crawl): Sweet Irish Dream — cheap and lively with fire shots. Good place to start a night out Shush Silent Disco — genuinely fun silent disco Lost Boys — more of a bar/lounge vibe Others Pathos Bar — one of the best places to grab a drink and watch the sunset. However, it closes down relatively early and is located far from the main town of Chora FarOut Beach Club — known for day-time beach parties, located on Mylopotas so only popular at night for people staying in the area Where to Stay Francesco's Hostel — all the way up on the hill with great views over the water. Pool, bar and a great social atmosphere. The go-to hostel on the island ATTRACTIONS 1 Church of Panagia Gremniotissa 2 Mylopotas 3 FarOut Beach Club 4 Little Gem 5 Pathos Bar 6 Loretzaina 7 Paralia Gialos RESTAURANTS & BARS 8 Sweet Irish Dream 9 Shush Silent Disco 10 Lost Boys ACCOMMODATION 11 Francesco's Hostel Greece Ios Touch to explore Double-tap to open in Google Maps Mykonos 2–3 days recommended Mykonos is known to be the party island of Greece. I went during the first week of offseason so I found the beach clubs to be a bit strange, but I know a lot of my friends had a great time there. I enjoyed the other aspects of the island including the beautiful old town, iconic windmills and good beaches. Mykonos is a very popular island so the benefit is there are tons of restaurants and shops to choose from. What to Do Old Town — a classic Greek old town dotted with churches featuring distinctive red domes. Located right next to the old port, this is a great place to stay. The area itself isn't huge so it is easy to cover in a couple of hours The Windmills of Mykonos — there are four huge white windmills right next to each other overlooking the sea. The wind on this island is genuinely very strong compared to the other islands. This is a great place to watch the sunset Little Venice — a charming little strip with bars and restaurants built right over the water. It is great for a coffee or drink with a view and one of the most picturesque places on the island Beach Clubs / Nightlife Tropicana Beach Bar — one of the most popular beach clubs in Mykonos, known for their beach party that stretches on into the night. There is a steep 20€ cover that includes a free drink Cavo Paradiso — one of the most famous nightclubs in Greece, right next to Tropicana Skandinavian Bar — a popular bar in the old town with a large courtyard. A good place to hang out if you're looking for a more chill night out away from the clubs Where to Eat Attica Bakery — the best bakery on the island with excellent Greek pastries and excellent iced coffee. I went here almost every morning Souvlaki Story — known to be the best gyros in town with chicken or lamb and beef options. Very cheap and high quality food Niko's Taverna — a solid and affordable Greek sit-down spot. Try the Pasticcio (lasagna made with short pasta noodles instead of sheets) Where to Stay Mykocoon Hostel — one of the nicest hostels I stayed in with a super modern with a rooftop pool, balcony and very comfortable beds. I also met some amazing people here. It was very expensive at ~$90 per dorm bed. However, it is the only hostel on the island ATTRACTIONS 1 Old Town 2 The Windmills of Mykonos 3 Little Venice 4 Tropicana Beach Bar 5 Cavo Paradiso 6 Skandinavian Bar RESTAURANTS & BARS 7 Attica Bakery 8 Souvlaki Story 9 Niko's Taverna ACCOMMODATION 10 Mykocoon Hostel Greece Mykonos Touch to explore Double-tap to open in Google Maps Naxos 2–3 days recommended Naxos is a popular island in the Cyclades. It is bigger than the other islands, much more local-feeling and with better food than anywhere else I went in Greece. Expect a much more quiet vibe than the more famous Islands of Santorini or Mykonos. Naxos wasn't my favorite island and I'd recommend choosing others unless you are looking for a quiet getaway What to Do Temple of Apollo (Portara) — once an ancient Greek temple dedicated to Apollo, the only thing that remains is a massive ancient marble doorway standing alone on a rock peninsula right at the port. It somehow felt magical and looks like it's coming out of the sky. It is worth visiting at sunset and you can capture a photo of the sun setting through the portal Old Town — much more quaint and relaxed than Santorini old town. It has some souvenir shops and markets in the alleyways, but far fewer tourists giving it a more authentic feel Venetian Castle — a small marble castle at the top of the old town. The building itself wasn't impressive, but there are good views over old town and the island from here Agios Georgios Beach — the main town beach that is an easy walk from the port Boat tour to Koufonisia — a boat tour to a smaller neighboring island of Koufonisia. I didn't make this one due to the weather, but locals say it has the most beautiful beaches in all of Greece Where to Eat Menu με νου — my favorite restaurant in Greece. It was a fancier sit-down restaurant near the harbor. I had the most incredible set of lamb chops with potatoes and a sweet purée. Don't miss this and make sure to try their house wine Where to Stay Like many Greek Islands, there are no hostels on Naxos. There are primarily small family-run hotels like Hotel Kymata where I stayed ATTRACTIONS 1 Temple of Apollo (Portara) 2 Venetian Castle 3 Agios Georgios Beach RESTAURANTS & BARS 4 Menu με νου ACCOMMODATION 5 Hotel Kymata Greece Naxos Touch to explore Double-tap to open in Google Maps Thessaloniki 1–2 days While passing through Northern Greece, I spent a couple days in Thessaloniki, the second largest city in Greece. It is more of a real city where Greeks live rather than a tourist one. There is a nice waterfront and the skyline is lined with massive apartment complexes. Embedded between these massive buildings are ancient churches and archaeological sites from the Ancient Greek, Byzantine and Ottoman periods. To be blunt it isn't particularly pretty, but worth stopping for 1 - 2 days if you're going to Meteora or particularly interested in history. What to Do White Tower of Thessaloniki and Museum — the symbol of the city and the best thing to do in Thessaloniki. A tall white Castle Tower located right on the waterfront, you can't miss it. The inside of the tower has been repurposed as a museum where each floor covers a different aspect of Thessaloniki's history: Byzantine, Ottoman, Jewish communities and the modern city. Get the English audio guide since everything inside is labeled only in Greek. There is a nice view once you make it to the top Thessaloniki retains much more of it's Byzantine than Ancient Greek history Both the Hagia Sophia of Thessaloniki and Holy Church of St. Demetrius are beautiful churches from the Byzantine area with impressive gold mosaics and painted icons Platia Aristotelous — the main walking street with gardens leading down to the waterfront. It is worth a stroll and is the nicest area in the city Kapani Market — an open-air market that felt very authentically Greek selling everything from goat heads, fresh fish to produce. It was fun to walk around and didn't feel touristy at all Arch of Galerius — impressive Roman arch with detailed marble carvings, a quick stop Where to Eat Τα μικρά Καλύβια — local homestyle cafeteria run by a mother and two brothers. All the food is pre-cooked so you can just point at what you want. I got a full meal for just 4.5€ which was insanely cheap ATTRACTIONS 1 White Tower of Thessaloniki and Museum 2 Hagia Sophia of Thessaloniki 3 Platia Aristotelous 4 Kapani Market 5 Arch of Galerius RESTAURANTS & BARS 6 Τα μικρά Καλύβια Greece Thessaloniki Touch to explore Double-tap to open in Google Maps Other Places to Consider There are so many amazing islands in Greece that the hardest part is choosing which ones to visit. Here are some other options that I've researched: Crete — the largest Greek island. Balos and Elafonissi are two of the most beautiful beaches in the country, the Samaria Gorge is a famous hike, and Chania old town is one of the prettiest in Greece Rhodes — located right off the coast of Türkiye, Rhodes has a beautifully preserved medieval old town (UNESCO World Heritage), Lindos village and good beaches in the south of the island Milos — home to the unique Sarakiniko white rock formations (looks like the moon!) Paros — charming whitewashed villages, great beaches and a more relaxed pace than Santorini or Mykonos. Good base for a day trip to neighboring Antiparos Corfu — lush green island in the Ionian Sea with a Venetian-influenced old town and good beaches like Paleokastritsa Zakynthos — home to Navagio shipwreck beach , one of the most photographed spots in all of Greece"},{"url":"hungary/field-notes.html","title":"Hungary Travel Guide","text":"Hungary Travel Guide General Hungary sits in the heart of Central Europe and for most travelers the country is really about one city: Budapest. Split by the Danube river, Budapest is actually the combination of two cities: the hilly, historic Buda and flat, urban Pest. The city is a grand, slightly faded imperial capital of the Austro-Hungarian empire, known for its thermal baths, ruin bars, and some of the best river views in Europe. Budapest is easy to reach and easy to combine with Vienna or the rest of Central Europe. Most people spend their time in the city, but the lakes and small towns beyond it are worth adding on if you have extra time. Hungary Overview Getting around — Budapest's airport (BUD) connects to most of Europe. The city has an excellent metro, tram and bus network, and the center is compact enough to walk much of it. Trains link Budapest to Vienna , Bratislava and beyond in a few hours Money — Hungary is in the EU but not the Eurozone, so it uses the Hungarian Forint (HUF). It's noticeably cheaper than Western Europe. Cards are widely accepted, but keep some cash for markets and ruin bars Food — very hearty and they love their paprika: Goulash (Hungarian stew served with tiny dumplings), Chicken Paprikás , Lángos (huge piece of fried dough topped with sour cream and cheese) and Halászlé (Fisherman's Stew). Save room for strudel and visit the historic coffee houses Language — Hungarian (Magyar) is unlike any of its neighbors' languages and famously complex. You'll have no problem getting around with English especially in Budapest and tourist areas Safety — Budapest felt very safe day and night; just watch for the usual tourist-area pickpocketing and overpriced taxis How long to stay — 4 to 5 days are enough for Budapest with time to slow down. Add more time if you want to explore beyond and visit Lake Balaton or the Danube Bend Budapest 3–4 days recommended Budapest is two former cities facing each other across the Danube River: hilly, historic Buda on the west bank and flat, grand Pest on the east. The city is built for wandering, with imperial architecture, thermal baths, and a nightlife scene centered on its famous ruin bars. Budapest is large, but the sites are very walkable. I would spend 3–4 days there and pick a neighborhood to focus on each day. What to Do Buda — most of the highlights are all centered around Castle Hill and easily visited together Buda Castle — a palace complex on the hill (despite the name). It's less impressive inside than from across the river. The views over the city and Parliament are the main draw, and the whole castle district is worth an hour of wandering Fisherman's Bastion — a neo-Romanesque terrace with 8 towers overlooking the river, with a café embedded in one tower. The views of Parliament and the river are great from here Matthias Church — right next to Fisherman's Bastion, strikingly decorated both inside and out. The patterned colored-tile roof is its signature Danube River Cruise — take a 1.5-hour evening cruise and catch the sunset from the river. It passes all the major monuments including Parliament. Many tours include unlimited Prosecco (and they keep it flowing). It was probably my favorite activity in Budapest and a very good value at only ~17 Euros. I took \"Elegant Cruise\" with Duna Cruises. Book it online here Citadella — a 19th century Habsburg fortress on top of Gellért Hill with the best panoramic views in Budapest. The 14-meter Liberty Statue at the entrance is one of Budapest's most recognizable landmarks. Reopened in April 2026 after years of renovation with a new immersive history museum inside Széchenyi Chain Bridge — the most beautiful bridge in Budapest, connecting Buda and Pest across the Danube Pest Hungarian Parliament — across the Danube in Pest, one of the most intricate and impressive buildings that I've seen. Take a guided tour inside ; the night view from across the river is spectacular Liberty Square — nearby Parliament, you'll find Liberty Square where there is the Citizens' Holocaust Memorial and statues of Ronald Reagan and George H.W. Bush . They are celebrated in Hungary for bringing down the Iron Curtain (a quirky, disorienting sight for me as an American) Széchenyi Thermal Baths — Budapest is known to have some of the most beautiful thermal baths in all of Europe. Located in the city park, the Széchenyi Thermal Baths is perhaps the largest and most grand. Spend a day relaxing here and explore the different pools (two hot, one cooler) Saturday Spa Party (\"Sparty\") — an outdoor thermal bath party on Saturday evenings with DJs, fire performers and dancers, across the three pools. It came recommended to us as one of the best parties in Europe. However, I personally had a very negative experience with inappropriate behavior toward the women we were with. That said, if you're still interested buy tickets in advance as it typically sells out House of Terror — a museum in the former headquarters of the Nazi Arrow Cross and later the ÁVO (Hungarian secret police). The audio guide is excellent, covering the Fascist occupation and then the Communist terror in vivid detail. One of the most powerful museums in Budapest Central Market Hall — right at the end of the Liberty Bridge , visit a 3-story market with fresh produce, meat, spices, and souvenir stalls. A good place to explore and try some fresh foods Jewish Quarter (District VII) — wander the old Jewish quarter in Budapest and learn about the impact of WWII on the city. It has been revived and is now home to many of the ruin bars Carl Lutz Rakpart — the riverfront promenade on the Pest side Where to Eat Café Kör — my favorite restaurant in Budapest serving traditional Hungarian cuisine. Order the Chicken Paprikás with bread dumplings here. It was the best dish I had in Budapest: a creamy paprika chicken sauce with bread dumplings that soak it all up Horgásztanya Vendéglő — a traditional Hungarian restaurant that I went to multiple times. Make sure to try their stews, either the Hungarian national dish Goulash (a thick paprika-and-beef soup) or the restaurant's signature dish Halászlé (Fisherman's Stew) Nor/ma Scandinavian Bakery — located near the Central Market. I had a delicious strawberry cheese strudel and coffee here Where to Drink Szimpla Kert — the original Budapest ruin bar located in the Jewish Quarter. Budapest is famous for its ruin bars, which are old, abandoned buildings that have been converted into lively bars. Ruin bars are now the heart of nightlife in the city and an essential Budapest experience. Szimpla Kert is two stories and has many rooms, each with a different theme and music Instant-Fogas — the largest ruins bar in Budapest with 7 clubs all embedded in one building. It is a fun night making your way through them all Mazel Tov — a wine bar with vines and fairy lights overhead in the Jewish Quarter. Beautiful and a great spot for a date night Where to Stay Monastery Boutique Hotel — a fancy, boutique hotel set in a former monastery, centrally located in Pest and within walking distance of the main sights ATTRACTIONS 1 Buda Castle 2 Fisherman's Bastion 3 Matthias Church 4 Citadella 5 Széchenyi Chain Bridge 6 Hungarian Parliament 7 Liberty Square 8 House of Terror 9 Central Market Hall 10 Jewish Quarter (District VII) 11 Carl Lutz Rakpart RESTAURANTS & BARS 12 Café Kör 13 Horgásztanya Vendéglő 14 Nor/ma Scandinavian Bakery 15 Szimpla Kert 16 Instant-Fogas ACCOMMODATION 17 Monastery Boutique Hotel Hungary Budapest Touch to explore Double-tap to open in Google Maps Other Places to Consider Almost everyone sticks to Budapest, but if you have extra days, Hungary has plenty more worth adding on: Lake Balaton — Central Europe's largest lake and Hungary's summer beach destination, a couple of hours southwest of Budapest Szentendre — a small riverside art town on the Danube Bend, an easy day trip from Budapest Eger — a historic town known for its castle, baroque streets and the \"Bull's Blood\" red wine Danube Bend — a scenic curve of the river north of Budapest, with hilltop castles at Visegrád and Hungary's largest basilica at Esztergom Pécs — a warm southern city with early Christian tombs, Ottoman-era architecture and a lively university city"},{"url":"india/field-notes.html","title":"India Travel Guide","text":"India Travel Guide General There is no place on Earth like India. It is simultaneously the most overwhelming and most unforgettable place I've traveled. When you first hit the ground here, it'll be sensory overload from the first moment. India operates in extremes: chaotic streets, sacred cows wandering everywhere, staggeringly intricate monuments and deep layered cultural traditions. I would not recommend India for all travelers. Be honest with yourself on your level of comfort with cleanliness and aggressive touts. I wanted the full, raw India backpacker experience with third-class trains, hostels and independent travel. However, there are definitely more comfortable ways to travel with tours and private drivers (all of which are affordable). I say this not to discourage travel to India, but to make sure you're prepared and not caught off guard. India rewards you enormously if you go in mentally prepared and keep an open mind to roll with the chaos. As I said earlier, there is no place on Earth like India. For my first time in India, I did the \"Golden Triangle\" circuit. This is a classic route in Northern India covering: the Capital of Delhi , the Taj Mahal in Agra and the Pink City of Jaipur . I added on the holy city of Varanasi on the Ganges which came highly recommended by other solo travelers. If you're doing a similar route, I would suggest spending 10 to 14 weeks since these places are all located relatively close to each other. Suggested Route Overview Safety — India is very safe when it comes to violent crimes and pickpocketing. However, there are relentless scammers, especially at popular tourist sites, that don't respect personal boundaries. On many occasions, I was followed for 10+ minutes by taxi drivers and tour guides, which was exhausting even as an experienced solo traveler. The majority of Indians were very friendly. Just come prepared and don't let these people ruin it for you I only can speak from a male perspective. Unfortunately, women need to take additional precautions and here is an article describing an experience of a solo woman. I did meet a number of solo women traveling in India and got a range of experiences from no issues to stories of harassment Getting around Uber — it is widely available in India and an absolute lifesaver. Tuk-tuk and taxi drivers can be very aggressive and it is helpful to have the security of knowing exactly where your driver is taking you. Just take Uber or use their prices to bargain when it's available avoid unnecessary friction Trains — India is home to one of the most well-connected train systems and can get you almost anywhere around the country extremely affordably. There is a huge difference among train classes with names like 1A, 2A, 3A all the way down to the lowest sleeper classes Indians typically recommend just buying the highest tier as it is still affordable. I did one trip in 3rd Class and it was quite the adventure. Use an aggregator like 12GO to book train tickets Buses — I took an overnight 10 hour sleeper bus from Varanasi to Agra and it was surprisingly very comfortable. I also booked online with 12GO Domestic Flights — for longer journeys, there are a lot of domestic flights available on local airlines. Flights are extremely affordable. I flew from Delhi to Varanasi on Indigo for just $30 Money — India might be the cheapest place I've ever traveled to. Meals, taxis, hostels and train tickets were sometimes a few cents ranging to up to $5. The official currency is the Indian Rupee and make sure to carry cash at all times Food — Indian food is incredible so don't be afraid of trying new dishes! I could barely identify a lot of the food I was eating and really enjoyed the element of surprise. There are a lot of nuances to regional cuisines in India, stretching far beyond your typical Butter Chicken and cheese naan order at home You might be tempted to try every street food cart. However, I would air on the side of caution and mainly stick to busy chain restaurants and upscale restaurants early on until you get a feel for what's safe. As a foreigner, food poisoning is a real issue to watch out for since our stomachs aren't used to local food. I met other travelers who were stuck in the hospital for two weeks on end and that's really not how you want to spend your vacation Culture — with over 1.4 billion people and ~18% of the world's population, India is truly its own world. There is tremendous diversity in religions, languages and cultures Keeping this in mind, don't expect cultural norms to align with what is acceptable in the West. If you look like a foreigner, random people will want to take photos with you (like a celebrity!). If you stay in a hostel, personal space is treated very differently. Expect people turn on the lights or have calls at 5AM while you're sleeping Language — India is famous for having the second most English speakers in the world. English is widely spoken in big cities like Delhi . However, many people like taxi drivers and waiters outside of big cities didn't speak a word of English and were challenging to communicate with. You'll be able to get around, but be prepared for a bit of pointing and sign language Delhi 2 days recommended If you're flying into Northern India, the first place you'll likely be is Delhi . Home to over 35 million people, it is quite an overwhelming introduction to India. Explore the nation's layered capital with government buildings, Mughal forts and tombs, vast modern temples and some of the most chaotic markets on earth, all at once. I had a great time here and it was the perfect introduction to the country. I would recommend spending 2 days here to explore the tourist sites. A tip to get around is: the Delhi Metro is very clean, safe and cheap (~$0.30 a ride). It is a great way to get around and the best way to skip the city's intense traffic. What to Do Akshardham Temple — a colossal modern Hindu temple complex. Every surface is intricately hand-carved with thousands of figures, deities and intricate floral patterns. The main area is a courtyard of lotus fountains with 10-foot statues. Akshardham Temple was arguably the most impressive temple of the whole trip. There is intense security before you enter with a strict cameras policy. The full complex is 100 acres so allow at least 3 hours to fully explore it Humayun's Tomb — a stunning Mughal tomb that directly inspired the Taj Mahal. A stunning red sandstone and white marble mausoleum with near-perfect symmetry, set in formal Persian gardens with a long waterway leading to the entrance. I found it to be one of the most underrated monuments in India and it had a fraction of the crowds of the Taj Mahal Red Fort — the massive red-sandstone Mughal fort which served as the seat of the Mughal empire for over 2000 years. Stretching over 250 acres in the heart of Old Delhi, inside the towering red walls are white marble palaces, ornate royal halls, an arched bazaar and a museum dedicated to Indian independence fighters. Allow 2–3 hours and combine with Chandni Chowk right across the street Chandni Chowk — one of the busiest markets in the entire world, located right across from the Red Fort. A dense bazaar packed shoulder-to-shoulder with electronics stalls, cloth merchants, marigold sellers and street food vendors. The smell, color and noise hit you all at once. Navigate by instinct and try the chaat, jalebi and paranthe along the way. The most chaotic street you will ever walk and completely unforgettable India Gate — a war memorial at the center of a large city park, built in 1931 to honor Indian soldiers killed in WWI. It feels a bit like the Arc de Triomphe in Paris, with the Parliament building and Presidential Palace in the distance. Nice at sunset when families come out and street food stalls set up around the park Where to Eat Haldiram's — a chain you'll find all over India with cafeteria-style food that is extremely cheap and food safe for Westerners. It probably isn't considered the best food in India, but it was a reliable spot to stop by if you're in a rush. I tried the Puri Sabzi (a potato curry with huge puffed bread, ~$2.40) for breakfast, and the thali combo (naans, several curries, rice and yogurt, ~$3.60) is an enormous lunch Bhalla Papdi — the street-snack of crunchy crackers and smashed potato under mint and mango chutney, yogurt and pomegranate. It is simultaneously sweet and savory and you can find it all over the city Where to stay Hindustan Hostel — a barebones hostel that I stayed in while in Delhi. It was located in a sketchy area where I would not walk around at night. There are probably better places to stay in Delhi... ATTRACTIONS 1 Akshardham Temple 2 Humayun's Tomb 3 Red Fort 4 Chandni Chowk 5 India Gate RESTAURANTS & BARS 6 Haldiram's ACCOMMODATION 7 Hindustan Hostel India Delhi Touch to explore Double-tap to open in Google Maps Agra 1–2 days recommended Agra is a city in Northern India and home to the Taj Mahal . The Taj Mahal is one of my favorite seven wonders of the world with awe-inspiring architecture and an incredible story to match. Don't miss Agra Fort while you're here. Most people do a day tour from New Delhi, but it is definitely worth spending a full day here so you're not in a rush. What to Do Taj Mahal — built out of solid white marble imported from Italy, the Taj Mahal is the most perfectly symmetrical building on earth. Every inch of the walls is inlaid with flowers of precious gem stones (green from China, turquoise from Tibet, sapphire from Sri Lanka) and the entire Quran is inscribed in black marble all throughout the buildings. Taking 22 years to build, Shah Jahan built the Taj Mahal for his wife who died in childbirth and completely bankrupting the Mughal Kingdom in the process. Crowds — go at sunrise if you want to beat the crowds and get the best pictures. The Taj Mahal was so massive that the crowds didn't seem to be much of an issue even during peak times Tour Guide — there is a beautiful love story behind the Taj Mahal and a lot of fascinating details you'll miss without a guide. I would suggest hiring one to pick up on all the details. There are plenty of guides standing outside of the complex. I paid $20 for a whole day with a private guide named Ashif. He was very knowledgeable, friendly, took me to a local restaurant and gave me a ride to Agra Fort for free after Photographer — inside the courtyard of the Taj Mahal, there will also be a ton of professional photographers offering to take your picture. If you're interested, agree on a price and number of photos beforehand. I paid ~2,000 rupees or $25 USD for 30 shots. Photographers can range up to $80 online if you book in advance. They know all the best angles and spots for photos Watch out for Scammers — embarrassingly, I fell for a scam here with a random guy approaching me, claiming to be the brother of my guide, Ashif (and even named him). He took me to a gift shop and tried to sell me a some plates. It was a harmless scam that only costed me a 10 minutes of my time, but just another thing to be aware of Enter from the East Entrance — if you enter from the original Mughal Taj Mahal east gate , every gate in a single flawless row. The Taj Mahal was built with an extreme level of attention to detail. The \"Diana bench\" on the main platform, where Princess Diana had her famous photo, is one of the most popular photo spots from here, but always has a line Agra Fort — a huge red-sandstone fort a 20-minute tuk-tuk from the Taj Mahal. It is often overlooked by tourists, but has a grand Mughal palace inside. After Shah Jahan bankrupted the Mughal Kingdom building the Taj Mahal, he planned to build an identical building made of Black Marble across the river for 20 times as much. His sons decided to arrest him to save the kingdom and he was imprisoned in Agra Fort for the rest of his life, with a direct of the Taj he built Where to stay Joey's Hostel Agra — a great hostel in Agra with an incredible view of Agra from the roof ATTRACTIONS 1 Taj Mahal 2 Agra Fort 3 Taj Mahal east gate ACCOMMODATION 4 Joey's Hostel India Agra Touch to explore Double-tap to open in Google Maps Jaipur 2-3 days recommended Jaipur is the \"Pink City\" and the third point of the Golden Triangle with Delhi and Agra. It is the capital of the Indian State of Rajasthan. It was by far my favorite stop in India due to its unique architecture and it was noticeably more cleaner and less chaotic than the other cities. The old city is walled and painted a warm terracotta pink. You entered through grand arched gates and arrive in the old city that is packed with forts, palaces and bazaars. Two to three full days was enough time to explore the city. I would plan separate days to explore the old town (the palaces and observatory) and then the forts up on the surrounding hills. Getting around While exploring the old town, most sights are within walking distance from each other. You can also call Ubers or easily hail a Tuk-Tuk for longer distances The forts ( Amber , Jaigarh and Nahargarh Fort ) are up in the hills and hard to get rides back from. It's worth hiring a driver for the full day (~2,100 rupees / $24). You can use Uber Rental in India to hire a driver affordably for the full day or by the hour What to Do Old Town Jaipur — enter the walled Pink City through Ajmeri Gate , a huge three-arched gate characterized by the bright pink colors and detailed white paintings lining the outside of the city. Enclosed in the gates is the old city which is home to many attractions that are all walking distance from each other and easily explored in a day Hawa Mahal — a palace built in 1799 by Maharaja Sawai Pratap Singh, the Hawa Mahal stands today as the symbol of Jaipur . The five-story \"Palace of Winds\" has a awe-inspiring honeycomb facade of pink gridded windows, white outlines and tiny green doors. Inside, you climb all five levels through a series of chambers to a courtyard looking out over the other highlights of the city including the City Palace , Jantar Mantar observatory and Jaigarh Fort The Hawa Mahal is more impressive from the outside. The best place to view intricate facade is across the street at the Wind View Cafe . There is a cover charge, but you can use it on food, so order a chai or lassi and enjoy the view Jantar Mantar — just a five-minute walk from the Hawa Mahal is an astronomical observation site built in the early 18th century. The Jantar Mantar is an open-air collection of giant yellow astronomy instruments built by a Maharaja who was obsessed with astronomy and astrology The giant yellow instruments are beautiful aesthetically, but hire a guide for ~400 rupees or $5 USD to provide background on how they actually work. There is a marble bowl used for reading the constellations, sighting holes for finding the North Star and a massive sundial that tells local Jaipur time to within two seconds. A very unique place to visit City Palace — right next to the observatory is the City Palace , complete with a series of huge courtyards painted bright yellow and pink. The palace is home to a variety of exhibits on textiles, Indian polo, miniature paintings of Hindu gods, and old photographs of the city The standout feature here are the doorways, each covered in flamboyant designs including the four porcelain gateways (the peacock gate is the famous one) and an immaculate four-story pink-and-white doorway Budget a half day to spend here. We lingered here far longer than originally planned Johari Bazaar — located right by Ajmeri Gate , the bazaar is mostly the same clothing and souvenirs stall after stall, so it's more about soaking in the streetscape than actually shopping The Many Forts of Jaipur — get a driver and plan a day to explore the many forts located in the hills overlooking Jaipur Amber Fort — the massive hilltop fort just outside the city and one of the highlights of Jaipur. Right on the outside, stop first at the lake viewpoint out front, where a zig-zag path climbs the hill and the elephants begin their ascent up the hill to the fortress Inside are enormous courtyards, a jewel-covered mirror palace and a hilltop Hindu temple that will take a couple hours to explore. Stop by the balconies with sweeping views over the city and admire the wall snaking along the ridge (said to be one of the longest in the world after the Great Wall) You'll see painted elephants coming through the main gate. However, riding them is not considered ethical, given the poor treatment of the elephants Panna Meena ka Kund (step well) — on the way up to Amber Fort, make sure to stop by the step well. Originally used as a water well by locals, this is one of the best photo stops with symmetrical criss-cross staircases that look like an optical illusion. The green water still has turtles and fish in it if you look closely enough Jaigarh Fort — a more red and run-down than Amber Fort . However, it has great views and is home to the Jaivana , once the largest cannon in the world that was fired a grand total of one time. Watch for the big black-faced monkeys and hunt down the \"secret\" courtyard for the best view back over Amber Fort and the city of Jaipur in the valley below Nahargarh Fort — another fort you can visit in Jaipur and the best sunset spot of the three. Head to the restaurant on the edge for a view over the whole sprawl of Jaipur. The foggy haze turned the sunset a deep orange the evening we went Jal Mahal (Water Palace) — a yellow palace sitting half-submerged in the middle of a lake, best seen at sunset. You can't actually visit it (the boat tours are suspended indefinitely), so it's a quick photo stop from the shore. Honestly a little underwhelming compared to the other forts, and the lakeshore itself was run-down and covered with trash Where to Eat Govindam — my favorite dining experience in India. Govindam is an upscale vegetarian restaurant near the Hawa Mahal . Get the Thali sampler: rice, naan and a row of curries, including a Rajasthani daal you crush cornmeal balls into. The food was incredible and we ended up paying ~$15 for the full meal where to stay Fairfield by Marriott Jaipur — an amazing 4 star hotel in Jaipur that was very clean and a nice break from the heat. It was only ~$50 - 60 (not bad for a 4 star hotel!) ATTRACTIONS 1 Ajmeri Gate 2 Hawa Mahal 3 Wind View Cafe 4 Jantar Mantar 5 City Palace 6 Johari Bazaar 7 Nahargarh Fort 8 Jal Mahal RESTAURANTS & BARS 10 Govindam Retreat ACCOMMODATION 9 Fairfield by Marriott Jaipur India Jaipur Touch to explore Double-tap to open in Google Maps Varanasi 2 days recommended Varanasi is one of the holiest cities in India and one of the oldest living cities on Earth. It is the spiritual heart of India, important to Hindus and Buddhists, and revered across multiple faiths. People come from all over India to bathe on the banks of the sacred Ganges River. There are sacred rituals performed by Brahmin priests both in the early morning and late evening The city is also home to a unique cremation tradition where it is believed that dying or being cremated in Varanasi grants moksha , or liberation from the cycle of rebirth. Many Indians save up their entire life to be cremated here and have their ashes scattered into the Ganges River. Hundreds of people are cremated here daily. The city is fascinating, intense, chaotic and utterly unlike anywhere else I've been in the world. I would recommend spending at least 2 days here to learn about the traditions that have been going on for thousands of years. What to Do Walk the Ghats — the ghats are a series of stone steps leading down to the Ganges River and the spiritual centerpiece of Varanasi. There are over 80 ghats each with its own purpose including bathing, meditation, yoga and cremation. Two of the ghats, Manikarnika and Harishchandra , have funeral pyres burning 24 hours a day, 365 days a year The Unexpected Guide — I was wandering around solo watching the cremation ceremony at Manikarnika ghat from a distance when a man named Papu introduced himself and offered to explain the cremation ceremony for free. He claimed to doing these tours on a donation basis for underprivileged families so I reluctantly agreed ( keeping in the back of my mind that I would only stay in public places ) He explained to me the cremation ceremony in great detail from the family members wearing all white, head shaving ceremony, the untouchables looking for gold in the ashes, cracking the skull to release the spirit and much more. I won't go into all the details, but it was absolutely fascinating. I even walked with him into the Manikarnika Ghat and the cremation ceremonies were happening just a few feet away from us. It was one of the most surreal experiences ever I ended up donating about 1,000 rupees or $10 for his tour. I have been told after the fact by my friends from India that this may have been a scam. Keep your wits about you if you are offered a similar tour Watch the Ganga Aarti ceremony — everyday the Dashashwamedh Ghat hosts the evening Ganga Aarti fire ceremony starting around dusk. Brahmin priests train their entire lives and the most highly qualified ones are allowed to perform this ceremony. It last a few hours with the Priests dancing while holding heavy golden candelabras, playing the drums and chanting religious hymns. It was truly magic and an spectacular ceremony to witness. These ceremonies are free to attend and get very crowded so show up early to reserve a good seat Boat ride on the Ganges — take a boat for sunset along the Ganges river and pass by all the ghats in Varanasi. You'll see puja rituals, devotees bathing and cremation ceremonies at Manikarnika Ghat . One of the most interesting experiences to witness from the water and watch the set over the Ganges. I booked this Mysticism Tour with Boat Ride & Ganga Aarti tour for ~$20. The guide was knowledgeable and provided a lot of the cultural background explaining the traditions Kashi Vishwanath Temple (Golden Temple) — the most sacred Shiva temple in India. Entry is restricted for non-Hindus, but the maze of alleys around it with marigold sellers, chai stalls and pilgrims is an experience in itself Aghori subculture — a small, controversial Hindu sect who have made Varanasi their home for centuries. Their philosophy is built around the rejection of all social norms and the belief that nothing is impure, demonstrated through extreme practices including meditating on human corpses, covering their bodies in cremation ash and carrying human skulls as bowls. You can spot many of them wandering around Varanasi, known to have dreads, minimal clothing and covered in white ash Where to Eat Blue Lassi Shop — apparently the considered the best Lassi in India. Stop by for a thick mango and strawberry lassi topped with nuts. The restaurant was pretty cool with thousands of visitor photos. It is a very famous place in India and absolutely worth waiting in line Aadha-Aadha Café — a nice rooftop cafe with great Paneer Masala and Chai with a great view of the river and ghats below Where to stay Wander Station Varanasi — a great hostel in Varanasi with a rooftop, cafe and common area. They also offer a variety of tours. I booked the temple tour which took us through many different neighborhoods of the city. A lot of domestic Indian tourists stay here so it is a great place to make friends with locals ATTRACTIONS 1 Dashashwamedh Ghat 2 Kashi Vishwanath Temple RESTAURANTS & BARS 3 Blue Lassi Shop 4 Aadha-Aadha Café ACCOMMODATION 5 Wander Station Varanasi ACTIVITIES ✦ Ganga Aarti ceremony ✦ Boat ride on the Ganges India Varanasi Touch to explore Double-tap to open in Google Maps Other Places to Consider These notes cover the northern Golden Triangle and Varanasi, but India is a whole subcontinent with much more to explore. Here are the spots highest on my list for a return trip: North India Udaipur — the romantic \"City of Lakes\" with its floating palaces located in the state of Rajasthan Jodhpur — another city located in Rajasthan known as the \"blue city\" and the gateway to the desert forts of the northwest Ladakh — the high-altitude desert in the far-northern Himalayas, a region of Buddhist monasteries, turquoise lakes and dramatic mountain passes, and a bucket-list spot for motorbiking the world's highest roads Rishikesh — the town in the Himalayan foothills located on the Ganges River. It is popular for white-water rafting and ashrams (yoga retreat centers). You can pair it with the Golden Temple at Amritsar South India Goa — the most popular beach destination in the country located on the West Coast of India. It is known for it's simultaneously laid-back and party atmosphere, a change of pace from the northern intensity Kerala — located in the far south. Stay on the houseboats parked on palm-lined backwaters and visit the tea plantations for a gentler, greener India"},{"url":"indonesia/field-notes.html","title":"Indonesia Travel Guide","text":"Indonesia Travel Guide General Indonesia is a country of over 17,000 islands. However, for most first trips (including mine) it means visiting Bali . Bali alone packs in beach clubs, rice terraces, cliff temples, world-class surf and some of the best value travel anywhere. It's easy, cheap and photogenic, with a distinct Hindu culture that sets it apart from the rest of Muslim-majority Indonesia. I found Bali to be very touristy which has it's upsides like tourism infrastructure, but be prepared to deal with large crowds at popular sights. I would recommend spending a 7 to 10 days in Bali and add on extra days to explore the nearby Nusa Penida or Gili islands . These notes cover Bali by zone: the beach-club west ( Canggu & Seminyak ), cultural Ubud , the clifftop south around Uluwatu , and the quiet, temple-dotted north. Suggested Route Overview Getting around Grab — Southeast Asia's version of Uber works for both cars and scooter taxis. If you're looking for a thrill, hop on the back of a GrabBike (scooter taxi). It is faster, dirt cheap (~$1.80 for 20 min) and a fun way to cut through the traffic. You can also call a regular car and rides are also extremely affordable Private driver — for full-day trips around the island, I would recommend hiring a driver is very reasonable. It will run you ~$30–50 for the day for the entire car. They will handle all the logistics and may even give you recommendations on what to do Flights — fly into Denpasar International Airport (DPS) which is Bali's single airport in the south. Visa on Arrival (VoA) costs $35. It was a very smooth process here Money — the official currency is the Indonesian Rupiah. You'll be able to use credit card at most touristy spots. Carry cash for warungs (local eateries), drivers and temples. Overall, Bali is very affordable, with excellent food and activities that won't break the budget Food — Indonesian food is cheap and delicious. Try the Nasi Goreng (fried rice) and Mie Goreng (fried noodles). Other great dishes are the chicken satay, beef rendang and fresh grilled fish There are a ton of restaurants in Bali serving high quality international cuisine too! If you're in the more tourist-heavy areas of Canggu & Seminyak, you might actually have trouble finding Indonesian food On days where you're feeling lazy, you can order food on Grab and they'll bring it straight to your accommodation. Even with food delivery fees, prices are cheap Etiquette — dress modestly at temples. In general, everyone is expected to wear a sarong (waist wrap) given at temples and cover exposed shoulders. Some more sacred areas restrict entry for people with open wounds or menstruating women. Remember that Bali is deeply religious and it is important to respect local traditions When to go — the dry season (roughly April–October) is best. I went during wet season which I would not recommend due to the heavy downpours. However, the silver lining was smaller crowds Canggu & Seminyak 1–2 days recommended On the Southwest coast of Bali lies Canggu and Seminyak . These two neighborhoods are home to Bali's beach clubs and are the most Westernized part of the island. I even had a hard time finding Indonesian food here (in Indonesia!). That said, it the best place on the island for nightlife and hip cafés. There are also some great sunset spots here as the sun sets in the West. This area is the closest to the airport. I would recommend spending time here as your first day in Bali or if you want to spend time at the beach clubs. What to Do Beach Clubs - Bali has some of the world's best beach clubs. They have very aesthetic design & architecture and world-class DJs come to play in Bali. They're relatively chill during the day and come alive at night. Expect to pay premium prices at the more popular clubs Potato Head Beach Club — the iconic massive beach club, with a woven-basket facade and an infinity pool facing the ocean. I went here during the day and had a very chill day just lounging here and swimming in the pool. The food was amazing, but expect western prices. There's a table minimum (drinks & food included). It's the best beach club for sunset Finns Beach Club — a very popular beach club with two huge ocean-facing pools, a main stage and dance floor, and day beds throughout. Go in the evening for a proper night out Café-hopping — the area is full of high-design hipster cafés Foal Cafe (formerly Mr. Sista ) - hipster western cafe with good brunch, healthy food and coffee here Mowies - a lowkey cafe with a pool (and a few digital nomads). The food and smoothies here were great Tanah Lot — located about an hour North of Seminyak , Tanah Lot is a temple perched on a rock just offshore. You can only cross to the temple at low tide across the black-sand beach at low tide. However, foreigners aren't allowed in so you can only admire it from the viewpoints. Bali has some stiff competition for temples so I'd say this is only worth it if you're already driving past ATTRACTIONS 1 Tanah Lot 2 Finns Beach Club 3 Potato Head Beach Club RESTAURANTS & BARS 4 Foal Cafe 5 Mowies Indonesia Canggu & Seminyak Touch to explore Double-tap to open in Google Maps Ubud 2–3 days recommended Ubud is Bali's cultural and spiritual center, home to many temples, art markets, yoga and emerald rice terraces. Located roughly an hour and a half from Seminyak , it is a small town that lies in the lush green hills. The town of Ubud runs at a much a slower pace than the beach-club coast. However, there are still plenty of restaurants and places to stay here. This was my favorite part of Bali as it had the most beautiful scenery and interesting temples to visit. I would recommend spending the majority of your time here since it has a very central location on the island, but you only need 2 to 3 days to explore the nearby sights. What to Do Sacred Monkey Forest Sanctuary — a lush, mystical rainforest where hundreds of monkeys roam free. The whole place feels like the set of Tomb Raider set with a river temple wrapped in enormous banyan vines and a mossy cremation temple of demon and skull statues in the back. Spend a half day to explore the complex Jatiluwih Rice Terraces — the iconic rice paddies just north of Ubud. Go early morning before the crowds and the heat to walk around and admire the rice paddies and watch the workers Ubud Palace & Market — the center of town, with traditional art, clothing and souvenir stalls and daily Balinese dance performances in the evening. Ubud Palace was extremely crowded when I was there Lekeleke Waterfall - a tall, narrow waterfall hidden in a small cliffside. You walk down 10 minutes into the jungle from the main entrance. It was not busy while we were there so we almost had it to ourselves Southern Bali 1–2 days recommended The southern Bukit Peninsula of Bali is home to dramatic limestone headlands, world-class surf and the island's most famous temple. I visited with a private driver and it is best strung together as a loop if you're not staying in the area. What to Do Uluwatu Temple — a 10th-century temple perched on the edge of a sheer sea cliff. Walk along the walkway on top of the cliff and watch the sunset from the south viewpoint and stay for the Kecak fire dance performed in the outdoor amphitheater. This was my favorite temple in all of Bali The resident monkeys are aggressive and stole my water bottle. GWK Cultural Park — built in 2018, GWK Cultural Park is a huge, modern statue complex. It is famously home to a 32-story statue of Garuda Wisnu Kencana is visible from across the island. The rest of the park is filled with other statues and is worth spending at least a half day exploring Nusa Dua beach — a long beach with consistent surf. Stop at the blowhole and the little sea temple ( Pura Bias Tugel ) on the rocky peninsula just to the south Savaya ( formerly Omnia ) — the best club in all of Bali located on a cliffside near Uluwatu . The environment is immaculate with two enormous infinity pools, a large glowing cube overlooking the stage and a huge dance floor. The most famous DJs often play here including Calvin Harris, John Summit, Carl Cox and Peggy Gou play here. Come before sunset to catch the sun setting over the ocean. The table minimum is steep (~$200). Just buy cover entry if you're not in a larger group ATTRACTIONS 1 Uluwatu Temple 2 GWK Cultural Park 3 Savaya (beach club) 4 Nusa Dua Beach 5 Pura Bias Tugel Indonesia Southern Bali Touch to explore Double-tap to open in Google Maps North Bali day trip from Ubud The North of Bali is far more untouched than the South of the Island. It is cooler, greener and home to many fantastic temples as well as waterfalls and crater lakes. It is best done as separate day trips from Ubud and the drive is very scenic through rice fields and small farms. What to Do Ulun Danu Beratan Temple — Bali's most recognizable temple, its tiered meru shrines appearing to float on the surface of Lake Beratan . It is one of the most aesthetic temples in Bali. The cheap (~$12) speedboat tour of the lake is fun, and the captain will usually let you drive Tirta Gangga Temple — a relaxing temple with a maze of manicured gardens, tiered fountains, ornate stone statues and koi ponds set against the backdrop of Mount Agung. The main draw is the stepping stone path across the water where dozens of giant golden koi swim beneath your feet. About 2 hours from Ubud and best combined with Lempuyang Temple (the famous Gates of Heaven) nearby. 50,000 IDR or $2.50 USD entry Penataran Agung Lempuyang Temple — the famous heaven gates photo you've seen on Instagram. The temple complex has been transformed into a bit of a Instagram factory. You are given a number and have to wait in line ~45 minutes for a picture. Spoiler: the reflection is actually a camera trick with a mirror! There isn't much to see in the area so I would only go if you're looking for the famous photo. Coffee Plantation Tour — Bali is famous for it's \"cat poop\" coffee. Famous as some of the most expensive coffee in the world, a strange creature called a civet eats coffee beans and then it is made into coffee. You'll be able to try some civet coffee, a variety of teas and they'll show you around the coffee plantation. It is a good stop as you'll probably drive past one on your way to the temples Where to eat Wayan Restaurant — a restaurant on the far East side of the island, this was some of the best Indonesian food that I had in Bali Other Places to Consider I will definitely be back to Indonesia and I'm glad to explore more of the islands. There are over 17,000 islands. Here are some of the more popular ones recommended by friends: Islands nearby Bali The Nusa Islands — Nusa Penida and Nusa Lembongan, a short fast-boat from Bali, for the famous Kelingking \"T-Rex\" cliff, snorkeling with manta rays and quieter beaches The Gili Islands — three tiny car-free islands off Lombok (Gili T for the party, Air and Meno for calm), with turtles and great snorkeling Lombok — Bali's rawer neighbor, with the Mount Rinjani volcano trek and empty surf beaches in the south Komodo National Park — book a 3 to 4 night sail from Labuan Bajo on Flores to see Komodo dragons. You can also dive some of the best reefs in the world and hike Padar Island for the most iconic views in Indonesia. The park limits visitors to 1,000 per day so book in advance Borneo — one of the last places on earth where you can see wild orangutans. The main draw is a multi-day river cruise through Tanjung Puting National Park on a traditional wooden houseboat called a klotok Jakarta — one of the most populous city in the world with over 42 million people. Most travelers skip it, but highlights include Kota Tua (the Dutch colonial old town), the National Monument and the Istiqlal Mosque , the largest in Southeast Asia Yogyakarta & Java — the cultural heart of Java and the base for Borobudur (a 9th century Buddhist temple pyramid, best at sunrise), the towering Hindu temples of Prambanan and the volcanic sunrise views of Mount Bromo"},{"url":"kosovo/field-notes.html","title":"Kosovo Travel Guide","text":"Kosovo Travel Guide General A small country located in the heart of the Balkans, located in between Serbia, Albania, Montenegro, and North Macedonia. From a modern geopolitical lens, it was fascinating to visit. It is also an easy to add a few days another country to visit Kosovo. Kosovo was also by far the cheapest place I've been in Europe with breakfast for 3 euros and a fancy dinner 8 euros Controversy - The country remains at the heart of a lot of controversy and is a product of the Balkan Wars in the 1990's. Kosovo only declared independence in 2008. Despite being autonomously governed, Serbia claims that Kosovo is part of their territory and was taken from them by NATO bombings in the 1990s. This has caused a lot of international tensions including Kosovo only being recognized as a country by 110 out of 197 U.N. member states The list of countries that don't recognize Kosovo includes some important global players like Spain, Greece, China, India and Brazil It is also one of the most pro-American places you'll ever visit. There were U.S. flags everywhere, streets named after Bill Clinton and random U.S. senators. One of the only places in the world where people are actually excited to see Americans Border with Serbia - The border with Serbia is one-way. You can enter Kosovo from Serbia, but can't return the opposite way without crossing into another neighboring country. It depends on the border guard, but be careful entering Serbia if you only have only have a Kosovo stamp in your passport without a Serbian stamp Safety - despite the controversy and on-going tension with Serbia, Kosovo felt very safe. The country was suprisingly more modern than I expected due to lots of European investment. There are also constant patrols of KFOR NATO peacekeeping troops stationed there to prevent any ongoing border disputes. My experience felt the same as visiting any other European country Time - It only takes a maximum of 3 hours to drive across Kosovo so you only need limited time to visit this tiny country. I would recommend 3 - 4 days total to explore the entire country: a half day in Prishtina, two days in Prizren and tack on a day to visit Peja or Gjakova as a bonus Suggested Route Overview Prishtina Half day recommended Prishtina is the capital and the largest city in Kosovo with over 200,000 inhabitants. The city is very modern and a key transit hub while traveling in Kosovo. Prishtina isn't very touristy, but there are some quirky sites that are worth seeing Most of the sites are located close together so a half day is enough to cover the key highlights What to Do Bill Clinton Statue — most people are shocked and amused to find a larger-than-life statue of Bill Clinton in the middle of Kosovo. Located on Bill Klinton Boulevard in front of a communist-era building, the statue has a bizzare \"Welcome to Prishtina\" poster with Bill Clinton similing in the background. The statue was built in honor of his support in NATO of the bombings in 1999 which helped found Kosovo You'll find a lot of American flags throughout the country and there's also a bust of Kansas Senator Bob Dole not too far away from the Bill Clinton Statue Kosovo National Library — the national library stands out in the middle of the city as a wild brutalist building with boxy shapes, white hexagonal domes and metal netting on the exterior. There is a small exhibit dedicated to the little-known Kosovo War which took place in the late 1990's. Inside there's also an America Corner with a merged U.S./Kosovo flag and Bill Clinton's biography Mother Teresa Church & Bell Tower — the largest church in Prishtina is dedicated to Mother Teresa who was Kosovar - Albanian by heritage. The church is pretty and make sure you don't miss the bell tower which has one of the best views in the city ATTRACTIONS 1 Bill Clinton Statue 2 Kosovo National Library 3 Mother Teresa Church & Bell Tower Kosovo Prishtina Touch to explore Double-tap to open in Google Maps Prizren 2 days recommended Prizren is the cultural capital of Albanian and the real reason to come to Kosovo. It is home to a small Ottoman old town with a beautiful river flowing through, a fortress with incredible views and a genuinely great vibe at night The old town is relatively small, but packed with different attractions. It is worth spending at least a night here to get a sense of the culture of Kosovo. I really enjoyed the pace of life here. The town square was buzzing with locals filling the cafes and bars at night, even on a weekday What to Do Prizren Fortress — overlooking the town is the Prizren Fortress. It is a steep walk (roughly 20 minutes) up a cobblestone hill, but the view from the top is well worth it. Go at sunset, bring a beer and enjoy the views Shatërvan (Town Square) - this is the center of old town. Sit here in the morning and sip a coffee or enjoy in the evenings when locals fill the square and the city comes alive at night Free walking tour — I highly recommend a free walking tour. The local guide that I had took us to all the important historical sites, taught us about history of Kosovo and was very candid about the on-going tensions in the country. This tour was especially informative in Kosovo given political tensions and dispute with Serbia Albanian League of Prizren — this is where Albanian independence from the Ottoman empire was first organized. It is a small, well-maintained complex with a small museum of traditional Albanian outfits and nationalist paintings Sinan Pasha Mosque — the main mosque in Prizren located right next to the river. It has an Art Deco-style painted walls inside and a hidden Star of David. The architectural style is unusual compared to other mosques in the region For a nice view and photo spot, head to the Old Stone Bridge where there is a beautiful view of the mosque and river Serbian Orthodox Cathedral of St. George — a historic catherdral in Prizren that is often visited by Serbians. It was attacked during riots in 2023 and was guarded by police 24/7 when I was there. It is worth seeing to understand the tensions Agim (Avdi) Shala monument - one of the many military statues you'll find along the river. These militaristic statues were very common in Kosovo Archaeological Museum — a small museum with some old prehistoric, Roman and Ottoman artifacts. There is also a clock tower you can climb with a view of the city. Only worth going if you have extra time Where to Eat Steakhouse Sarajeva — a fancy restaurant by the water that was surprisingly cheap. Get the Balkan burger here! It was one of the best things I had in Kosovo Restaurant Te Syla — a traditional Albanian restaurant by the river. Get the Qebap (their name for Cevapi) Te Kinezi — a great spot to sit outside and enjoy the local craft beer. A great spot to meet locals at night Where to Stay Ura Hostel - an amazing brand new hostel located right in old town ATTRACTIONS 1 Prizren Fortress 2 Shatërvan (Town Square) 3 Albanian League of Prizren 4 Serbian Orthodox Cathedral of St. George 5 Agim (Avdi) Shala monument 6 Archaeological Museum RESTAURANTS & BARS 7 Te Kinezi ACCOMMODATION 8 Ura Hostel Kosovo Prizren Touch to explore Double-tap to open in Google Maps Other Places to Consider Peja — a town with great nature and hiking located near Montenegro (more detailed guide here ) Gjakova – a small town close to the Albania border with an old bazaar and traditional Ottoman architecture (more detailed guide here ) Mitrovica – a highly contested town in Northern Kosovo. The Albanian and Serbian neighborhoods are located on opposite sides of the river and there are high ethnic tensions here. It is a fascinating place, but be careful if you visit"},{"url":"latvia/field-notes.html","title":"Latvia Travel Guide","text":"Latvia Travel Guide General Latvia is a small Baltic country located in Northeastern Europe between Estonia to the north and Lithuania to the south. The main attraction in the country is its capital Riga ( which is definitely way prettier than whatever you pictured as the capital of Latvia ). The city has its own unique character from the other Baltic capitals with a mix of both old medieval and decadent Art Nouveau architecture. Riga genuinely surprised me and was a great place to learn about Latvia's struggle for independence, complex history as a former Soviet Republic and its on-going struggle to craft its own identity. Most people pass through Latvia as part of a wider Baltics trip, and Riga sits right between Tallinn and Vilnius , so it's easy to string all three capitals together by bus. I'd recommend 2 days to see the old town, the Art Nouveau quarter and the Central Market at a comfortable pace. Latvia Overview Getting around Riga — the old town and central districts are compact and walkable, with trams and buses as reliable options if you want to explore beyond the city center Ridesharing — Bolt , the European version of Uber, is widely available and affordable in the city Long Distance Buses — comfortable long-distance buses run all throughout the country. You can also easily get up to Tallinn and down to Vilnius (each around 4 hours), which makes linking the three Baltic capitals easy Money — the official currency in Latvia is the Euro. Latvia is great value and noticeably cheaper than Western Europe, especially at the markets and bakeries Food — the food is classic Baltic comfort food: rye bread, pork, smoked fish and hearty soups. Expect every meal to be very affordable and filling. They have a strong bakery culture so you'll find one on almost every corner Language — The primarily language is Latvian, spoken by 2/3 of the population. There is also a large Russian-speaking population. You'll have no trouble getting around with English Riga 2 days recommended Riga is the biggest of the Baltic capitals. The city is home to a medieval old town, the greatest concentration of Art Nouveau architecture anywhere in Europe, and a massive food market, all packed into a compact, walkable center. Riga is grittier and less polished than Tallinn , but it's cheaper and has more of a lived-in, real-city feel to it. Throw in the enormous Central Market and a genuinely fun bar scene at night, and Riga is worth 2 days to comfortably explore the city. What to Do Old Town — known as Vecrīga in Latvian, the medieval old town dates back to 12th century and is now the center of modern day Riga . All of the attractions are walking distance from each other making it easy to explore in a day House of the Blackheads — an extravagantly ornate guildhall built by a medieval merchants' brotherhood. The original was destroyed in WWII and fully reconstructed, so it looks almost brand new. This was my favorite building in Riga with it's ornate exterior to the lavish halls and rooms inside St. Peter's Church & Observation Deck — the main cathedral in old town Riga. The real highlight is the Observation Deck in the clock tower that has the best panoramic view over Riga's red rooftops and the Daugava river below Museum of the Occupation of Latvia — covers immense suffering that Latvia endured under the Nazi and Soviet occupations in harrowing detail. The country lost between 25% to 33% of it's entire population during WWII. The museum is very well done and often rated even more impactful than Tallinn 's version. It is worth an hour or two to learn about the country's dark past and how it shapes Latvia today Three Brothers — the most iconic photo in Riga with three distinct medieval stone houses. Each represents a different architectural era: Gothic, Dutch Mannerist and Baroque, giving you three centuries of evolution in a single glance. The houses are now home to the Latvian Museum of Architecture. However, it didn't have much inside so it is only worth a stop from the outside, unless you're specifically interested in Architecture Cat House — this building is easy to miss, but it is one of the most charming and talked-about buildings in Riga, a custard yellow Art Nouveau building topped with two black cat sculptures with dramatically arched backs and raised tails. Worth a quick photo stop Riga Castle — a medieval fortress on the banks of the Daugava River, founded in 1330 by the Livonian Order and one of the most historically layered buildings in the Baltics (changing hands between the Polish, Swedish and Russians over the centuries). The castle now houses the Latvian National Museum of History and the Presidential Palace Riga Central Market — the largest food market in Europe, housed in four huge converted WWI hangars with open-air stalls spilling out around them. There are a lot of food stands frequented by locals. A great spot to grab a quick and affordable lunch The Art Nouveau Quarter — some of the most intricately designed buildings anywhere in Europe, their facades crawling with carved faces and figures. The street named Alberta iela is lined with Art Nouveau buildings, and the museum inside one of the buildings has a re-created Art Nouveau apartment worth a look to get a taste of how life was inside Where to Eat The Riga Central Market Food Stalls — go early and sample different foods across various stands. It's by far the best-value meal in the city and a great way to quickly learn about local cuisine Moods.lv — a stylish library-themed lounge bar in Old Town with cozy sofas and good cocktails. Good spot for a relaxed evening drink Skyline Bar — rooftop bar on the 26th floor of the Radisson Blu Latvija Hotel with panoramic views over the entire city. A great place to visit at sunset to admire the view Where to Stay Cinnamon Sally Backpackers Hostel — a cozy hostel with a nice common room and very social vibes. I really enjoyed my stay here ATTRACTIONS 1 House of the Blackheads 2 St. Peter's Church 3 Museum of the Occupation 4 Three Brothers 5 Cat House 6 Riga Castle 7 Riga Central Market 8 Art Nouveau Quarter RESTAURANTS & BARS 9 Moods.lv 10 Skyline Bar ACCOMMODATION 11 Cinnamon Sally Hostel LATVIA Riga Touch to explore Double-tap to open in Google Maps Other Places to Consider Riga is usually the main stop for travelers. If you have a few extra days, here are some other places in Latvia that you can explore: Jūrmala — a long white-sand beach resort just west of Riga, lined with old wooden villas. It's a quick train ride from the city and a popular spot for locals during the summer Sigulda & Gauja National Park — located just an hour outside of Riga, this is a forested river valley dotted with medieval castles and viewpoints. Best in the fall for the colors Rundāle Palace — a grand Baroque palace and gardens south of Riga that is considered the most beautiful palace in Latvia"},{"url":"mexico/field-notes.html","title":"Mexico Travel Guide","text":"Mexico Travel Guide General There is so much more to Mexico than the inside of an all-inclusive resort. I went to Mexico for the third time and finally felt like I was able to explore this amazing country. Mexico is home to gorgeous colonial cities, amazing cuisine, beautiful beaches and untapped historical sites. From what we see in the media, many people are too afraid to explore, but it is well worth it. The food alone justifies the trip, but the mix of pre-Hispanic history, gorgeous colonial cities and a genuinely social backpacker scene is what makes it special. For my last trip, I spent about three weeks going through central Mexico from Mexico City → Puebla → Oaxaca → Puerto Escondido and am going to focus on these locations here. Suggested Route Overview Getting around — Uber is everywhere in Mexico City and cheap, but the traffic can be absolutely brutal. Between cities, I took coach buses that are comfortable and affordable. I booked online with Busbud and the company ADO was very reliable. Local buses within towns are dirt cheap (~10 pesos) and a chaotic, very authentic ride Safety — This is the biggest concern for most people going to Mexico outside of resort areas. Mexico definitely has security issues with the cartels. However, the unfortunate reality is that tourists are protected much more than locals. I felt perfectly safe in the tourist and backpacker areas that I visited, but was cautious and followed basic safety precautions The level of security varies greatly state by state so check the U.S. Travel Advisory for their specific state-based ratings. They normally eer on the conservative side, but this is a helpful resource for Mexico Food — I don't think I was disappointed by a single meal in Mexico. Don't get me wrong, the street tacos were amazing, but there is so much more to Mexican food than we know about. Every region has its own specialty and it is worth branching out to try: Mexico City — the Al Pastor Tacos were amazing here and try Pulque (a creamy cactus based alcohol) and mezcal (a smoky Mexican spirit) Puebla — Cemitas (a sandwich with a crunchy bun and soft, tender meat inside), tacos árabes (a traditional fusion of Middle Eastern shawarma and Mexican tacos, actually the precursor to Al Pastor) and Chalupas (little fried tortillas with red and green sauce on top) Oaxaca — famous for its Mole (a rich, savory chocolate-based sauce), there were actually a ton of different dishes that I wasn't familiar with: Tlayudas (a large crunchy tortilla covered in black beans and a ton of different toppings), Memelas (little corn cakes topped with black beans and cheese) and the best mezcal in the world. I'd recommend going on a walking tour and your guide will show you all the local dishes Puerto Escondido — located along the Pacific Coast, this little seaside town was filled with fresh seafood. I had some unreal fish and shrimp tacos here Language — You'll have no trouble with just English in Mexico City. Once you get to smaller cities, a bit of Spanish goes a long way Money — Mexico was incredibly cheap. A full street-taco meal ran a few dollars, happy-hour beers were 15 pesos (~$0.75) and a long distance bus was about 100 pesos ($6 - $7). ATMs are easy to find in large cities, but carry cash for street vendors When to go — The best time to visit Mexico is during dry season from December to April . However, it is a huge country with diverse terrain so weather will vary greatly. It can feel like a completely different season in Mexico City vs on the Pacific Coast Mexico City 4–5 days recommended Mexico City is the second largest city in the Americas and home to over 23 million people. The city, formerly known as Tenochtitlán, was built by the Aztecs on a lake with over 70 volcanoes surrounding it. Mexico City played an important role in the Spanish Conquest of the Americas and has continued expanding since. The city is enormous and it sprawls further than anywhere else that I've been. Mexico City is packed with things to do so spend at least 4–5 days here . Neighborhoods Zócalo — the historic center of Mexico city, made up of a huge plaza facing the Mexico City Metropolitan Cathedral and the biggest flag I've ever seen flying overhead. Many historical sites and museums are based around here, but I wouldn't recommend it as a place to stay Roma Norte — the most popular neighborhood to stay. It is lined with classical European architecture, covered in trees and full of coffee shops, restaurants and bars. It is known to be very safe and a central location to visit sites around Mexico City La Condesa — located right next to Roma Norte, you'll find similar architecture. However, it is a bit quieter and cheaper than the more popular Roma neighborhood while still benefiting from the central location Polanco — an upscale neighborhood with more of the fancy hotels in Mexico City. It lies next to both Roma Norte and La Condesa Coyoacán — located further south from the other neighborhoods, Coyoacán is characterized by its bohemian architecture and home to the Frida Kahlo museum What to Do Teotihuacán Pyramids — as the former capital of the Aztec Empire before the Spanish Inquisition, Mexico City is home to some of the largest pyramids left from the Aztecs. The best way to visit is by sunrise hot air balloon tour . You'll float over the whole complex before anyone's there, surrounded by volcanoes and see the temples below in the early morning haze. The Pyramids are located an hour outside of Mexico City so it is an easy day trip Bosque de Chapultepec — in the middle of Mexico city lies a huge oak forest park with small Aztec ruins and old fountains scattered through it. There are a few famous attractions inside of it including: Anthropology Museum — one of the best Anthropology museums in Latin America. It is an enormous complex with thousands of Olmec, Aztec and Maya artifacts plus a room for each region of Mexico. It would take a whole day to see every single artifact so don't be afraid to skip rooms unless you're a huge anthropology fan Don't miss the Danza de los Voladores right outside of the museum! This is an ancient Mesoamerican ritual where 5 men dressed in traditional garb and climb a 100 foot pole and spin off the sides using just rope. They also play the drums and flute while sitting high up in the air Chapultepec Castle — a Spanish Colonial castle in the middle of Chapultepec park. The line can be brutal so line up early or book tickets in advance; I skipped it after seeing it wrap around the block Palacio de Bellas Artes — a stunning Art Nouveau building with a white exterior and gold dome. It is the country's premier art museum and full of murals The Diego Rivera mural inside is the standout. There is a sorcerer figure in the center with communists and capitalists fighting for power on either side Floating Gardens of Xochimilco — ride a colorful trajinera boat through the ancient Aztec canals. There are two ways you can do it: a peaceful, sightseeing tour or party boat . I ended up on one of the party boats and it was a great time with open bar, a hype person, and mariachi bands randomly hopping onto our boat. It is a great way to spend an afternoon and expect to pay ~$50 for each option Lucha Libre — going to a Mexican masked wrestling is a fun experience even if you don't care about wrestling. I went on a guided tour with my hostel at Arena México where our guide handed out masks and taught us the chants. Be prepared for total chaos and some impressive acrobatics Mercado de la Merced — a huge local market near the Zócalo, packed with locals selling clothes, food and shoes. A very local non-touristy experience Frida Kahlo Museum (Casa Azul) — a popular visit for many who come to Mexico City. Tickets sell out 2 weeks in advance so make sure you book ahead of time Basilica of Our Lady of Guadalupe — located roughly 30 minutes away from the city center, this church is the most-visited Catholic site in the world after the Vatican Biblioteca Vasconcelos — one of the most beautiful, modern libraries in the world UNAM Campus — the National University of Mexico with beautiful murals and a botanical garden Where to Eat \"Montezuma's Revenge\" — a popular joke about tourists getting food poisoning when visiting Mexico. Watch out for street food if you have a sensitive stomach, but I didn't personally encounter any issues Street Tacos — having late night street tacos is a quintessential experience on your trip to Mexico and will even beat most sit-down spots Taquería Orinoco — a super famous taqueria in Roma Norte with a retro red-and-white theme (Dua Lipa even did a collab with them). Get the Super Taco which is the size of three regular tacos, served with a tray of six different salsas Tacos Tlaquepaque — a lowkey spot serving Al Pastor tacos near the Zócalo Máximo — a fancier fine-dining restaurant and one of the best in the city if you're looking for a nicer meal Where to Drink Mecate Club — a live music venue with a live band, small tables around a stage. I went on a Tuesday night and it was packed. Try Pulque here, a fermented cactus drink that tastes like alcoholic horchata Bar Las Brujas — a nice cocktail bar in Roma Norte with great mezcal cocktails Teclán Mezcalería — rated one of the top 20 bars in the world with a nice dimly lit vibe with a red glow. Personally, I didn't think the cocktails were mind blowing, but worth trying if there is no wait Where to stay Wanderlust District — a hostel located on the edge of the upscale Roma Norte neighborhood. The facilities and roof were great. They also organized a lot of social activities including trip to a wrestling show ATTRACTIONS 1 Zócalo 2 Roma Norte 3 La Condesa 4 Polanco 5 Bosque de Chapultepec 6 Chapultepec Castle 7 Palacio de Bellas Artes 8 Lucha Libre 9 Mercado de la Merced RESTAURANTS & BARS 10 Taquería Orinoco 11 Tacos Tlaquepaque 12 Máximo 13 Bar Las Brujas ACCOMMODATION 14 Wanderlust District Mexico Mexico City Touch to explore Double-tap to open in Google Maps Puebla 2–3 days recommended Puebla is the fourth largest city in Mexico and located just 2 hours away. It is popular among Mexican tourists, but has largely remained undiscovered by Western tourists unlike Mexico City. The city was gorgeous with cobblestone streets, bright-colored buildings and a beautifully maintained colonial old town. Puebla played an important role in Mexican history as the site of the famous Battle of Puebla on Cinco de Mayo, where Mexican forces defeated the French Army in 1862. They are also famous for their regional dishes throughout Mexico so definitely worth trying. I would spend two days in Puebla combined with a quick day trip to the Pueblo Mágico of Cholula . What to Do Zócalo de Puebla — the gorgeous old town square in Puebla facing city hall and surrounded by local restaurants. Most historical sites are walking distance from here Free Walking Tour — the best way to cover the highlights: the neighborhoods, the historical murals, and context for why Puebla played such an important role in the Mexican Revolution Biblioteca Palafoxiana — located right in the town center, this is the oldest library in the Americas dating back to 1646. The library is a small room covered floor to ceiling in over 40,000 books and all labeled in Latin Pasaje Histórico 5 de Mayo — there are underground tunnels underneath the city of Puebla that were an important part of the Battle of Cinco de Mayo. They have been converted into a museum today and will drop you into a neighborhood full of murals named Xanenetla with a viewpoint over the city Loreto Fort Museum — located in Xanenetla neighborhood on the hill overlooking Puebla, Loreto Fort is a bright-orange fort used in the actual Battle of Cinco de Mayo. Explore the museum inside that covers the battle Museo Regional de la Revolución Mexicana — the original house where the Serdán brothers plotted the Mexican Revolution. It is still full of bullet holes in the walls from that time period. If you're lucky you might be able to catch a free, live performance here with traditional Mexican dances Ex-Convento de San Francisco — one of Puebla's most famous churches. Locals bring their newly bought cars here to be blessed, so there's usually a line of open hoods out front. Inside there's also a wax-covered mummy of a Spanish missionary Chapel of the Rosary, St. Dominic’s Temple — an avant-garde church covered in gold floral patterns Day Trip to Cholula Pueblo Mágico of Cholula — one of the best things to do in Puebla is to take a day trip 40 minutes away to the town of Cholula. It has been given the special designation of \"Pueblo Mágico\" by the Mexican government meaning that it is one of the most important cultural heritage sites in the country Santuario de la Virgen de los Remedios — the main draw is a bright orange 16th-century Spanish church built on top of what is actually the largest pyramid in the world (its base is four times bigger than the Egyptian pyramids). There is an amazing view from the top and you can see an active volcano in the background of the church San Francisco Acatepec — the most intricate church exterior I saw in Mexico, covered in tile mosaics with baroque gold inside Bike Tour — I did a bike tour through the city and it was a fun, quick way to see the city. Your tour guide will explain all the stops. This only takes 3-4 hours so you'll still have the full day to explore. I booked it offline with Casa Pepe Hostel for only ~$20, but it is also available on Getyourguide Centro San Pedro Cholula — Cholula has a charming town square with restaurants, churches and live performances on the weekends Terraza Cholula — stop by this rooftop terrace cafe for a great view of the church in the distance Where to Eat Cemitas Americas — a lowkey restaurant serving some of the best Cemitas in Puebla (delicious pork sandwiches between crunchy pieces of bread). It is very popular among locals Comal — a fancy restaurant where you can sit facing the cathedral. The mole enchiladas plate came three enchiladas, each with a different sauce; the dark, chocolatey mole is the standout El Gran Zamora — Puebla invented a dish called Tacos Árabes: a flour tortilla loaded with Al Pastor. Meaning \"Arab Tacos\" they actually were influenced by Lebanese immigrants who came to Mexico and are the precursor to the more famous tacos Al Pastor Fonda Típica La Poblana — a traditional Mexican restaurant serving regional specialties, very affordable Chalupas from street vendors — all around the city you'll see street vendors frying little red and green tortillas with a bit of chicken. It is a popular snack for locals and worth trying once Where to stay Casa Pepe Hostel Boutique Puebla — a hostel located in old town Puebla embedded in a historic 18th century house ATTRACTIONS 1 Zócalo de Puebla 2 Biblioteca Palafoxiana 3 Pasaje Histórico 5 de Mayo 4 Loreto Fort Museum 5 Ex-Convento de San Francisco 6 Chapel of the Rosary, St. Dominic’s Temple RESTAURANTS & BARS 7 Cemitas Americas 8 Comal 9 Fonda Típica La Poblana ACCOMMODATION 10 Casa Pepe Hostel Boutique DAY TRIPS ↗ Cholula (Half Day) Mexico Puebla Touch to explore Double-tap to open in Google Maps Oaxaca 4 days recommended Oaxaca (pronounced woa-ha-ca ) is one of my favorite cities in Mexico blending authentic Mexican culture, a unique local food culture, well preserved colonial architecture and a beautiful desert aesthetic. It also has the best mezcal in the world. It is considered by many to be the \"Food Capital of Mexico\" due to unparalleled variety of dishes and complex flavors. For a first time visit, give it at least four days and your days will be packed with interesting activities. What to Do Food tour — the number one thing to do in Oaxaca is by far the food tour. You can do all the research you want, but there is nothing like a local guide to show you Oaxacan food. Over the course of the tour which typically lasts 2 hours, your guide will make sure you're stuffed: Memelas (tortilla with refried beans and tomatoes), cactus-and-beef tostadas, Jamaica juice, a steak torta and ice cream. I did it right when I arrived and it was the perfect primer on Oaxacan specialties Templo de Santo Domingo de Guzmán — one of the main churches in Oaxaca. It actually took over 150 years to complete due to numerous earthquakes and the massive scale of the project. There are a few very interesting sites you can visit inside of the church: Jardín Botánico — attached to Templo de Santo Domingo, this is Oaxaca's famous botanical garden. You have to visit by tour and tours are only in Spanish. It has a striking desert aesthetic and the hallway of pipe cactuses reflected in the water at the end is the best part Museum of Cultures of Oaxaca — also in the same complex. A museum showcasing local Oaxacan culture. Some interesting exhibits include: machete-carved wood sculptures and a jade skull mask from Monte Albán Hierve el Agua — petrified \"waterfalls\" with turquoise pools at the top that look like infinity pools. You can swim to the edge and look over a valley of agave farms. Book a day tour from Oaxaca to avoid all the logistics of getting there Mezcal distillery tour — often paired with the Hierve el Agua tour, you can visit one of Oaxaca's many Mezcal distilleries. You see the full process: stone-wheel crushing, the underground smoke pit, barrel fermentation and then taste 20+ mezcals Monte Albán — Zapotec ruins on a hilltop outside the city. They are one of the many civilizations that existed at the same time as the Aztecs and Maya. Take the bus from town for only 100 pesos round trip. It is a huge complex of ruins with a ball court. They were alright, though not spectacular if you've already seen other ruins in Mexico. They are located only 20-30 minutes outside of central Oaxaca so it is a quick half day visit Mirador viewpoint — for sunset, head up to the mirador viewpoint where you can see the entirety of Oaxaca spread out across the valley and surrounded by mountains Where to Eat Mercado 20 de Noviembre — likely a stop on any food tour, this is the local market and a great place to order mole La Popular — a classic, affordable restaurant serving local Oaxacan Cuisine Roy's Tacos — a popular taco shop that is known for their Al Pastor tacos and pozole (a Mexican soup with chicken, potatoes and corn) Nono Cafe — a trendy coffee shop with great coffee, pastry and breakfast options Pan de Madre — a nice bakery for breakfast Where to Stay Casa Angel Hostel — a great hostel with a great rooftop and daily activities. It was super social and I met some amazing people here ATTRACTIONS 1 Templo de Santo Domingo de Guzmán 2 Museum of Cultures of Oaxaca RESTAURANTS & BARS 3 Mercado 20 de Noviembre 4 La Popular 5 Roy's Tacos 6 Nono Cafe ACCOMMODATION 7 Casa Angel Hostel DAY TRIPS ↗ Food Tour (Half Day) ↗ Hierve el Agua (Full Day) ↗ Mezcal Distillery Tour (Half Day) ↗ Monte Albán (Half Day) Mexico Oaxaca Touch to explore Double-tap to open in Google Maps Puerto Escondido 2–3 days recommended Puerto Escondido is a small surfer town on the Pacific coast of Mexico that has just one main dirt road lined with shops and restaurants. I didn't expect to even go here, but ended up following some friends here and had a blast. Puerto Escondido is a popular backpacker town and gets busy during peak season. The main beach is a popular surf spot, a great place to relax and watch the sunset. The main things to do in town are surf and party so plan your trip accordingly! I would recommend 2 to 3 days depending on your preferences. What to Do La Punta Zicatela (the Main beach) — a popular surf spot and a great place to just relax. Most of the shops and restaurants are centered around here, making it the best area to stay in as well Punta Bar — located right on the sand, this beach bar was a fun place to spend the day and one of the best sunset spots in town Baby Sea Turtle Release — line up at sunset for about an hour, then release a baby turtle on the sand. They slowly crawl toward the ocean (led by the magnetic field). The gorgeous sunset combined with the baby turtle going into the ocean for the first time made for a genuinely magical experience Where to Eat Fish Shack — a small shack down a sandy alleyway that served some of the best fried fish tacos and shrimp tacos that I've ever had. A must if you're in Puerto Escondido Ola Taquería — right next to Fish Shack, a traditional Mexican restaurant with really cheap al pastor tacos Malagua Café — an upscale restaurant that served some amazing brunch food and smoothies Nightlife The main strip where all the restaurants are has bars, but they all close at 11PM. The whole town takes taxis out to the clubs that are located on the outskirts of the city Some of my favorite spots were Xcaanda , Cactus and Mar & Wana Where to Stay Hostels book up quick during the peak season so try to book in advance Viajero Puerto Escondido — a part of the popular Viajero Puerto Escondido chain that I stayed at all over Latin America. This location is relatively basic, but has a pool If you're looking for a different vibe, there are many other small beach towns along the coast, each with their own personality: Mazunte (smaller and quieter) and Zipolite (hippy vibes & a nude beach). ATTRACTIONS 1 La Punta Zicatela (the Main beach) 2 Baby Sea Turtle Release RESTAURANTS & BARS 3 Malagua Café 4 Xcaanda 5 Fish Shack 6 Ola Taquería 8 Cactus 9 Mar y Wana ACCOMMODATION 7 Viajero Puerto Escondido Mexico Puerto Escondido Touch to explore Double-tap to open in Google Maps Other Places to Consider Here are the spots in Mexico that I'm excited to visit next time: Guanajuato & San Miguel de Allende — two of the prettiest colonial cities in the central highlands. Guanajuato is considered one of the most beautiful towns in Mexico with brightly painted houses, and San Miguel de Allende is a short hop away with cobblestone streets, a pink neo-Gothic church and a big expat and food scene San Cristóbal de las Casas (Chiapas) — a colonial town high in the misty Chiapas highlands. It's the base for Sumidero Canyon , the surrounding Indigenous villages, and the jungle-wrapped Palenque Ruins a few hours away. Many people I met heading that way loved it and it is a popular spot before continuing down to Guatemala Yucatán — one of the most popular vacation destinations in Mexico. Visit the city of Mérida or the smaller colonial town of Valladolid to reach Chichén Itzá and swim in the cenotes, then drop down to the Caribbean coast for Tulum 's beaches and the turquoise lagoon at Bacalar"},{"url":"montenegro/field-notes.html","title":"Montenegro Travel Guide","text":"Montenegro Travel Guide General Montenegro is a tiny Balkan country on the Adriatic Sea. Located just south of Croatia, it feels like Croatia's quieter, cheaper and less-polished cousin. For how small it is, the country has one of the most dramatic changes in elevation between the towering mountain peaks in Durmitor National Park to the pristine waters of the Adriatic Coast. The highlight is the Bay of Kotor , a dramatic, fjord-like inlet ringed by mountains with a walled medieval old town. The country is easy to tack onto a Croatia or Albania trip. The bus from Dubrovnik, Croatia or Shkodër, Albania only takes a few hours. I would recommend exploring the Bay of Kotor and adding on time to explore the rest of the country. Montenegro Overview Getting around — most people arrive by bus from Croatia or Albania. Book your tickets on traveling.com which has the most connections. You also can fly into the airport in the capital Podgorica or Tivat as well Local buses — they're available and connect the coastal towns, but are unreliable. Sometimes there are no actual bus stops (ask a local where to stand) and schedules are loose. For day trips, a boat tour or a taxi is far easier than deciphering the bus routes Money — Montenegro uses the Euro even though it isn't in the EU. It's noticeably cheaper than Croatia, but is starting to get more expensive as it gains in popularity Food — I found Montenegrin food to be very similar to Italian food with fresh fish, risotto and pasta everywhere. They also had a few Balkan classics like Cevapi and Burek Language — Montenegrin is a South Slavic language written in both the Latin and Cyrillic alphabets and mutually intelligible with Serbian. I had no problem getting around with English, especially in tourist towns like Kotor Safety — Montenegro felt very safe and easygoing throughout, day and night. No issues here at all Kotor 2 days recommended Kotor is a historic town dating back to the 5th century, nestled in the very back of the Bay of Kotor, where the reflective water sits between steep grey mountains. Kotor has changed hands between many empires over the course of history, but shows notable influence from the Venetian Kingdoms which defines the architectural style in the walled old town. I would suggest spending at least 2 days here: one to explore the old town and hike the fortress above and a boat tour around the bay on the second day. What to Do Kotor Old Town — a beautiful old town that takes 20 minutes to walk end-to-end. I would start at the main square by Cathedral of Saint Tryphon , wander the streets, climb on to the Kotor town walls to visit Kampana Tower and end at the North Gate , where a stream of clear, green-tinted water runs right alongside the wall On the main street, right outside the walls, there is the Kotor Food Market where you can sample local Montenegrin flavors Kotor is covered in friendly cats, so spot them all over town while you're at it! Hike up to the Castle of San Giovanni — a climb up a set of steep switchback stairs from the old town to an old fortress high above the bay. The fortress is a bit rundown and overgrown, but the view is unmatched If you're up for an adventure, go for sunrise: you beat both the crowds and the heat, catch the whole town lit up on the way, and get the scenic view straight down the bay. I set out around 5 AM and we nearly had it to ourselves Bay of Kotor boat tour — the best way to explore the Bay of Kotor. It starts in Old town and loops around the bay all the way to the Adriatic sea making a few amazing stops along the way. You can book the tour I did here Our Lady of the Rocks — the iconic light blue domed church built on a man-made island in the bay. The boat docks so you can walk around the little church and its stairs. The neighboring island is home to Saint George Catholic Monastery is also popular to visit, but was closed for construction when I visited Blue Cave — a small sea cave with startlingly bright blue water. The boat pulls up right outside and you can jump in and swim Austro-Hungarian submarine tunnels — your tour will likely stop by these submarine tunnels hidden in the mountainside. We visited one featured in a James Bond film that was hidden behind a fake rock face. It is a cool, quick stop Where to Eat Konoba Roma — a restaurant located right by the town square. I ended up eating here twice: a Montenegrin breakfast (eggs, tomato, cheese, bread) and a carbonara later Cesare Old Town Restaurant — a decent sit-down spot ( with bad online reviews ). I had the Montenegrin pasta (steak and pasta), an espresso and a cream cake to finish Where to Stay Old Town Hostel Kotor — a bare-bones hostel, located right in the middle of Old Town Kotor. They also host a boat party and BBQ everyday ATTRACTIONS 1 Cathedral of Saint Tryphon 2 Kotor Food Market 3 Castle of San Giovanni RESTAURANTS & BARS 4 Konoba Roma 5 Cesare Old Town Restaurant ACCOMMODATION 6 Old Town Hostel Kotor DAY TRIPS ↗ Bay of Kotor Boat Tour (Full Day) ↗ Perast (Half Day) Montenegro Kotor Touch to explore Double-tap to open in Google Maps Perast Half-day trip from Kotor Perast is a tiny, beautiful town strung along the water about 25 minutes up the bay from Kotor. Take the local bus from Kotor. There is no official bus stop so ask locals where to stand along the road. The bus along the coast runs every hour, but it is up to an hour late (so be prepared to wait)! The town of Perast is incredibly charming and where rich tourists stay in the area. What to Do Wander the waterfront — the docks double as restaurant seating and the whole promenade is built for a nice lunch by the water. You can also stroll around and get ice cream, do a wine tasting and watch the sunset on a bench Climb to the Fort of the Holy Cross — a fort above town that is totally abandoned, with overgrown trails and little upkeep. It was a fun little adventure and the views back over the bay are worth the scramble Our Lady of the Rocks — small boats run out to the island church from the Perast waterfront if you didn't already stop there on a bay tour Other Places to Consider I only had a couple of days in the Bay of Kotor, so I'd definitely want to spend more time in Montenegro. Here were some places recommended by other travelers: Budva — a seaside town with cliffs towering above the ocean and the country's main beach and nightlife destination Sveti Stefan — the famous fortified islet resort just 15 minutes south of Budva. Iconic to photograph from the shore or hill nearby even if you're not staying at the (very pricey) hotel Durmitor National Park — Montenegro's rugged north: the Black Lake, the Tara Canyon and world-class hiking. A full day or more from the coast, but the country's best mountain scenery. My friends really enjoyed the hut-to-hut hiking here Lovćen National Park — the mountain directly above Kotor, with the Njegoš Mausoleum at the top and huge views back down over the bay. Reachable by the switchback road out of Kotor Podgorica — the capital and main airport hub. I went through here for a flight, but heard it wasn't the prettiest city or really place to spend time as a tourist"},{"url":"netherlands/field-notes.html","title":"Netherlands Travel Guide","text":"Netherlands Travel Guide General The Netherlands is one of Europe's most effortlessly enjoyable countries to explore. Beyond its iconic windmills, canals, and gabled houses lies a nation built around cycling, world-class museums, charming historic towns and a remarkably relaxed way of life. Most visitors base themselves in Amsterdam , but thanks to the country's compact size and excellent public transport, it's easy to venture beyond the capital to discover quieter cities, picturesque villages, and a more local side of the Netherlands. Suggested Route Overview Getting around Flights — fly into Amsterdam Airport Schiphol (AMS) , one of Europe's busiest and best-connected airports. Frequent trains reach Amsterdam Central in around 15–20 minutes Trains — the Netherlands has one of Europe's best rail networks, with fast, frequent, and reliable services. Most major cities (including Rotterdam , Utrecht , The Hague , and Haarlem ) are within one to two hours of Amsterdam Bikes — the Netherlands is the cycling capital of the world, and there's no better way to experience Amsterdam than by bike. An extensive network of dedicated cycle paths makes getting around easy Money — as a member of the European Union, the Euro is the official currency of the Netherlands. I found the country mid-to-high priced by European standards, with Amsterdam being the most expensive part Food — food in the Netherlands is very international and you can find cuisines from all over the world. I would encourage you to try some classic Dutch food. It snacky, satisfying and fun to sample. Some highlights include fresh stroopwafels (thin caramel-filled waffles) hot off a market griddle, aged cheeses like Gouda and plenty of fried foods like a cone of fries with mayo or curry ketchup, currywurst , frikandel and bitterballen. If you're feeling a bit more adventurous, try theraw herring eaten by the tail! Language — Dutch is the official language and one of the closest Germanic languages to English. However, English is spoken almost universally and fluently: one of the easiest countries anywhere for an English speaker, making it easy to connect with locals People & Culture — I have probably met more Dutch people traveling abroad than in the Netherlands itself! I really get along with Dutch people and find them very friendly, curious and down to Earth. They are famously very blunt and willing to speak their minds, but I never found it off putting or rude. As a Northern European culture, you'll find things are more familiar than they are different in the Netherlands How long to stay — For first-timers, I'd recommend spending 3–4 days in Amsterdam and adding on a day trip or two Amsterdam 3–4 days recommended Amsterdam is one of Europe's most distinctive capitals: a city of UNESCO-listed canals, narrow gabled merchant houses, world-class museums, and a famously liberal, easygoing culture. It's compact, endlessly walkable (or bikeable), and full of character. Amsterdam has become the home and capital of Electronic Music, making it an amazing place to see your favorite artists or attend festivals. Spend 3 to 4 days wandering the canal belt, cycling through leafy neighborhoods, or relaxing at a waterside café. The historic center can feel crowded and over touristed, especially around Dam Square , so I'd stay just outside the busiest areas and visit the major sights early in the day. What to Do Canal Ring Walks — one of the first things that comes to mind when visiting Amsterdam are the 17th-century ring canals are surround the city. Simply wandering them is the best thing to do in Amsterdam. They're everywhere and hard to miss The Jordaan neighborhood and the four grand canals of the Grachtengordel are the most photogenic, lined with narrow gabled merchant houses, houseboats and hump-backed bridges Canal Boat Tour — I know it is touristy, but one of the best ways to visit the canals is to join a boat tour. It is cheap, running you about ~15 to 20 euros, and lasts about an hour. It's a relaxing ride through the canals, you'll pass by all the famous sites and you might even learn some history along the way Dam Square & the Royal Palace — Dam Square is the broad historic heart of the city, anchored by the grand 17th-century Royal Palace and the tall white National Monument War Memorial . It's always thick with crowds, trams and street performers, so it's more a landmark to pass through and get your bearings by than a place to linger Albert Cuyp Market — the biggest daily street market in the country. Albert Cuyp Market is a long run of stalls through the De Pijp neighborhood selling cheese, fish, flowers, clothes and almost everything else. Come hungry since it is a great place to grab a bite and sample Dutch specialties: I had the most heavenly warm and soft stroopwafel pressed fresh off the iron, tried a raw herring sandwich with onions, and had a few hot poffertjes or mini-pancakes NDSM Neighborhood — hop the free ferry from behind Centraal Station across the river to Amsterdam Noord and the NDSM wharf. It is one of my favorite areas in the city. Once a gritty former shipyard, it has since been reinvented as a creative playground of warehouses, murals, studios and festivals. It is a fun area to wander around and see a sharp contrast to the classic old town across the water STRAAT Museum — by far the best thing to do in NDSM is the STRAAT Museum . It is a giant hangar and museum of street art and graffiti with huge works by artists from around the world. There are some very impressive pieces here even if you're not particularly into graffiti. Stick around for the industrial-chic cafés and restaurants: grab bitterballen and a beer at a waterside spot and watch the ferries cross. The best place to spend free half-day in the city Rijksmuseum — the great national museum of the Netherlands and one of the best art museums in ,Europe located in a palace-like building. You'll find a hall of famous Dutch Golden Age artists including Rembrandt, Vermeer and Hals. Book a timed ticket ahead to skip the queues, give it a couple of hours or longer if you're into classical art Vondelpark — the city's big, leafy central park and its collective back garden. On the first warm day of the year, all of Amsterdam decamps here to cycle, jog, picnic, drink and sprawl on the grass. It's the perfect place to slow down for an afternoon with a book, with a couple of café terraces and an open-air theater in summer. A lovely, free escape from the touristy, busy center of the city The Red Light District — if you're curious like I was, the Red Light District (or formally the De Wallen district ) is worth walking through once after dark. There is a sharp contrast between the neon-lit windows and sex shops threaded around some of the oldest, prettiest canals in the city. It's crowded and touristy, and make sure to be respectful and never photograph the windows Anne Frank House — the actual canal house and secret annex behind a hinged bookcase where Anne Frank and her family hid for two years. It is now a deeply moving museum built around her diary. It is extremely popular; tickets are released online only a few weeks ahead and vanish within minutes. You'll need to plan advance to book a visit and you cannot just turn up if you're interested in visiting Heineken Experience — a tourist staple and brewery tour through the Heineken factory in Amsterdam. I found it a bit too touristy for my own taste and it felt like an hour long Heineken advertisement, but go if you're interested Day Trips & Festivals Utrecht — just 20 minutes by train from Amsterdam lies Utrecht , the 4th largest city in the Netherlands. I personally enjoyed Utrecht , more than Amsterdam . It felt like a smaller, less-touristed Amsterdam without the madness and grittiness of the weed shops and stag parties. Its signature split-level canals are now full of café terraces and you can climb a big Gothic cathedral tower. I really enjoyed the lively Vredenburg Market (only on Wednesday, Friday & Saturday). You can enjoy the poffertje (mini-pancake coated in powdered sugar) stalls and a laid-back university-town energy. It's a charming day trip from Amsterdam , or an easy alternative base Festivals — the Netherlands has one of the best festival cultures in the world. Almost every town, no matter how big, has its own festival during the summer so there is no shortage to choose from. Here are some of the largest festivals in the country that are worth visiting: Amsterdam Dance Event (ADE) — the world's largest electronic music festival and conference, held every October. For five days, Amsterdam transforms into the global capital of electronic music. It is not your traditional festival where there are a bunch of stages in one location. Instead, it operates a tons of separate venues across the city; hundreds of clubs, warehouses, and concert venues host continuous sets from world-class DJs for the entire week. I went in 2021 and had a great time at the popular night club called Jimmy Woo Koningsdag (\"Kings Day\") — celebrated every 27 April , the Netherlands' biggest national holiday is Koningsdag (\"Kings Day\"). During the holiday, you'll see Amsterdam erupt into a citywide street party. Canals fill with boats, parks become giant flea markets, and almost everyone dresses head-to-toe in orange (in classic Dutch fashion) to celebrate the King's birthday Where to Eat The food in Amsterdam is very international. On my longer trip here, I found myself eating international cuisine like Turkish food and Indonesian food. If you're looking to try local Dutch food, the Albert Cuyp Market is your best bet where you can wander around the various food stalls and try some fresh stroopwafels and bitterballen The Pancake Bakery — serves big classic sweet and savory Dutch pancakes in an atmospheric canal-side cellar. The pancakes were fantastic. I later found out from my Dutch friends that they don't actually eat pancakes anymore than we do (despite what your online guidebook will have you believe...) Where to Stay The Hoxton, Amsterdam — the Hoxton is one of my favorite hotel chains. The location in Amsterdam is a stylish boutique hotel set across a row of historic canal houses in the central Jordaan neighborhood . Its central location, character-filled rooms, and lively lobby make it one of the best places to stay in the city Hyatt Regency Amsterdam — a modern, upscale hotel in the quieter Plantage neighborhood , offering spacious rooms, excellent service, and easy access to the canal belt, museums, and public transport. A great choice if you want to stay just outside the busiest tourist areas The Flying Pig — a well-known, backpacker hostel with two branches in Amsterdam (one by the main train station and one farther out by Vondelpark ). Be warned that the Flying Pig Downtown is a full-on party hostel (probably one of the most famous party hostels in all of Europe, in case that isn't the vibe you're looking for. Other than that, the location is fantastic and easily walkable to most tourist sites ATTRACTIONS 1 Jordaan 2 Rijksmuseum 3 Anne Frank House 4 Vondelpark 5 Dam Square 6 Albert Cuyp Market 7 NDSM 8 Red Light District 13 Royal Palace 14 STRAAT Museum 15 Heineken Experience RESTAURANTS & BARS 9 The Pancake Bakery 16 Jimmy Woo ACCOMMODATION 10 The Flying Pig 11 The Hoxton, Amsterdam 12 Hyatt Regency Amsterdam DAY TRIPS ↗ Utrecht (Half Day) Netherlands Amsterdam Touch to explore Double-tap to open in Google Maps Other Places to Consider The Netherlands is compact and exceptionally well connected, making it easy to explore beyond Amsterdam. Many of the country's highlights are just a short train ride away: Rotterdam — Amsterdam's bold, modern competition. Rotterdam was flattened in WWII and rebuilt with modern architecture including the tilted yellow Cube Houses and the pencil tower to the vast arched Markthal food hall with its painted ceiling. It is also Europe's biggest port and a gritty-cool arts scene The Hague — the stately seat of Dutch government and the international courts, it is greener and more buttoned-up than Amsterdam. The highlights are the art museum, Mauritshuis and the grand parliament buildings and, in summer, the wide sandy beach and pier in Scheveningen Keukenhof & the tulip fields — the world's largest flower garden. It is only open for about eight weeks each spring (roughly late March to mid-May), when seven million tulips, daffodils and hyacinths bloom. If your trip lines up with the season, it's unforgettable, but there is not much to see the rest of the year Giethoorn — known as the \"Venice of the North,\" Giethoorn is a village where thatched farmhouses sit on their own little islands linked only by canals and arched wooden footbridges, with no roads through the old center. You can explore by whisper-boat or on foot over the bridges. It's tiny and gets swamped with tour groups midday, so come early Kinderdijk — a row of nineteen 18th-century windmills lined up along the polder canals, built to pump water off the low-lying land and now a UNESCO site. You can walk or cycle the dyke between them, step inside a working mill to see how the millers lived, and take a boat through the reeds. An easy, photogenic half-day from Rotterdam"},{"url":"north-macedonia/field-notes.html","title":"North Macedonia Travel Guide","text":"North Macedonia Travel Guide General I came into North Macedonia with relatively low expectations, but was very pleasantly surprised. The country has a lot of beautiful natural sights and fascinating history. It is an underrated country with very few tourists outside of some famous spots (even compared to the rest of the Balkans). You'll often have historical sites almost entirely to yourself It is a very small country that is very well connected by their bus system. The rides are usually less than 3 hours and there are regular connections from the major cities English is widely spoken, especially among younger people It was very affordable compared to the rest of Europe and even other Balkan countries. Meals were very cheap and nice Airbnbs/hostels run cheap Suggested Route Overview Foods (similar to most other Balkan countries) Tavče Gravče (national dish) - baked beans Burek - crumbly Balkan pastry stuffed with meat, cheese or spinach Ayran - salted milk drink like Kefir Skopje 2 days recommended Recommended time: 2 days This is the capital of North Macedonia and by far the largest city with over 500,000 residents. A lot of the city was destroyed in an earthquake in 1963 so it is mostly modern, but has a lot of interesting statues built as part of the Skopje 2014 project (more on that below). The city center is pretty small and the major tourist sites are walkable. Skopje 2014 / Statues All Over the City — Skopje has the most statues in the world with over 130+ statues, all built in the early 2010s. They're all around the center of town including on bridges, in doorways, and in random parks. The highlights are the giant Alexander the Great statue in the main square, abandoned pirate ships, but there are statues literally everywhere and it is bizarre… City Center The Bridge of Civilizations in Macedonia Stone Bridge Alexander the Great Statue Macedonia Gate Woman-Warrior Park Old Bazaar — a historic Bazaar with a very Ottoman feel (cobblestone streets and wooden buildings). One of the largest Bazaars in the Balkans. Lots of old shops largely run by Turkish and Albanian shopkeepers. Good place to buy souvenirs or get Kebap (Macedonian-style Ćevapi) Archbishop Cathedral of St. Clement of Ohrid — a block from the main square and one of the most unique churches I've ever seen. Brutalist exterior with stunning gold mosaics inside on a deep blue background. Don't miss this The Post Office — if you're into brutalism, this is a pretty cool visit close to the city center. It is a super dystopian building Kale Fortress (aka Skopje Fortress) — a large castle that overlooks the city Mother Teresa Memorial House — A small museum about Mother Teresa who was born in Skopje. A super quick visit since it is only a few rooms Free walking tour — the history here is fascinating and very unique even for the Balkans (Yugoslav breakup, the Greece naming dispute, the Albanian minority conflict, tensions with Bulgaria) and worth having a guide explain it to you. The tour I did was a 7/10, but covers a lot of ground while giving you the history Where to eat Restaurant Skopski Merak (Debar Maalo neighborhood) — a super popular with locals that serves traditional Macedonian food. It felt very upscale, but still affordable Kaj Гоце — tiny local spot in the Old Bazaar with a friendly owner and good Kebap Where to Stay Stay anywhere near the city center or in the Bohemian Debar Maalo neighborhood. The city is very walkable ATTRACTIONS 1 The Bridge of Civilizations in Macedonia 2 Stone Bridge 3 Alexander the Great Statue 4 Macedonia Gate 5 Woman-Warrior Park 6 Old Bazaar 7 Archbishop Cathedral of St. Clement of Ohrid 8 The Post Office 9 Kale Fortress (aka Skopje Fortress) 10 Mother Teresa Memorial House RESTAURANTS & BARS 11 Restaurant Skopski Merak 12 Kaj Гоце North Macedonia Skopje Touch to explore Double-tap to open in Google Maps Ohrid 2-3 days recommended Recommended time: 2-3 full days to see the highlights (or longer if you want to relax) This is a must when in Macedonia and was one of the highlights of the whole region. However, this is by far the most popular place in North Macedonia so expect large tour groups coming for day trips from neighboring countries The old town sits on a hill above a stunning lake. The water is so clear you can literally see all the way to the bottom. There is lots of wildlife like birds and little fish Old Town — beautifully restored Ottoman-style architecture with marble streets and a really nice place to wander around. I would spend half a day to wander and check out all the sites. Everything is very close St. John Kaneo Church — this is the iconic church you see in most photographs of Ohrid. It is perched on a cliff over the lake and you can walk here from Old Town. The view from the surrounding area is better than the church itself Old Bazaar Street – main part of old town Samuel's Fortress – best place to get a view of the city Old Swimming Court – best place along the water to look at Old Town Labino Vista Point – a peaceful viewpoint away from the tourist crowds Ancient Macedonian Theatre of Lychnidos – an old theatre near the fortress Lake boat tour — I highly recommend doing one and you can find lots of operators along the promenade offering tours ranging from an hour to full day. The tour I went on was more expensive (link here ), but covered all the sites around the lake, included a fantastic BBQ lunch and lasted a full day St. Naum Monastery and Springs — a monastery complex on lake Ohrid near the Albanian border. The main way to get there is by water taxi, but you can also drive there. The church itself was very busy, but make sure you go to the springs next to it. You can hire a row boat for 5 Euros. The water is insanely clear here and you can even see the plants on the bottom of the springs. This was my favorite experience in Ohrid The Bay of Bones Museum – I didn't go here personally, but this is also a popular stop. It is a modern recreation of a floating city. You might need to take a boat here. Where to Stay Old Town Hostel Ohrid – This was my favorite hostel in Macedonia. Really good vibes and the staff is very helpful. It is also located right in the middle of Old Town ATTRACTIONS 1 St. John Kaneo Church 2 Ancient Macedonian Theatre of Lychnidos 3 Samuel's Fortress 4 Old Bazaar Street 5 Old Swimming Court 6 Labino Vista Point ACCOMMODATION 7 Old Town Hostel Ohrid DAY TRIPS ↗ Lake Boat Tour (Full Day) North Macedonia Ohrid Touch to explore Double-tap to open in Google Maps Krushevo 1-2 days recommended Recommended time: 1-2 full days This is easily one of my favorite places on the whole trip. It is a tiny mountain town (4,000 people) perched in the mountains and surrounded by green hills and pine forests. I'd recommend it if you're looking for a taste of Macedonian mountain life. However, it is a bit hard to get to requiring a bus connection and a full travel day. There were also almost no tourists when I was there It is a very small town so the main thing to do is to wander around and explore. It is very serene and the people were extremely friendly Makedonium — A Soviet-era monument that looks like a spaceship/pine cone/virus sitting on a hilltop. Built to commemorate the 1903 Ilinden Uprising where locals held the Republic of Krushevo for 10 days before the Ottomans crushed it. The inside is completely white with organic-shaped relief sculptures and colored stained glass. Very interesting monument and there's almost no one there Mechkin Kamen — 2 hour hike from town through forest to another monument to the uprising. Easy trail and a nice way to see the landscape Krushevska Odaja — this is the best restaurant in town serving traditional Macedonian food Where to stay Hotel Montana Palace – If you have the budget, this is by far the best place to stay in town. There is a beautiful view of the town below from the balcony of the room and it is cheap for a 4 star hotel Bitola 1 day Definitely worth a 1 day stop, especially if you're crossing into Greece from here. It isn't much of a tourist city, but the downtown is gorgeous with a cobblestone walking street lined with warm yellow historic consulate buildings. Very different vibe from Skopje Old Bazaar — this more of an everyday working bazaar than a tourist one. Lots of Ottoman charm and big mosques with snow-capped mountains visible behind them Heraclea Lyncestis — Roman ruins about 30 minutes walk from downtown. Impressive mosaics, a theater, and a bathhouse. Almost no tourists NI Institute and Museum Bitola — has a whole wing dedicated to Atatürk, the founder of modern Türkiye who went to military school here, but not the most impressive museum that I've been to"},{"url":"peru/field-notes.html","title":"Peru Travel Guide","text":"Peru Travel Guide General Peru is one of the most fascinating countries in South America. It is the ultimate adventure destination with ancient Incan sites, world-class treks and a culture still heavily influenced by indigenous heritage. It is my favorite destination on the continent and one I always recommend for anyone looking for a safe, cheap, and interesting trip. Suggested Route Overview Transport Flights — all international flights go in and out of Lima, so plan accordingly Ridesharing — Uber works throughout the country and is a safe, convenient way to get around Buses — long distance buses are surprisingly nice. My night bus from Puerto Maldonado to Cusco had reclining sofa-style seats, a TV screen and a curtain. Your ears will pop the whole way as the elevation climbs (~9 hours) Practical Info Safety — Peru is super safe, especially in touristy areas. Practice standard safety precautions, but there isn't much to worry about. Peruvians are friendly and helpful Altitude — popular locations including Cusco, Machu Picchu and Sacred Valley are all at very high elevation. You will immediately feel shortness of breath, so give yourself a day or two to acclimate before heading off on any hikes. Many hotels offer coca leaves, Manzanilla Tea (chamomile) and candies that will help your body acclimate Budget & Cash — Peru is probably the cheapest South American country I visited. It's important to always carry cash, but most touristy restaurants and attractions take card Food — one of the most unique aspects of Peru is the cuisine. Worth branching out to try Ceviche, Lomo Saltado, a sweet purple corn drink called Chicha Morada and \"Cuy\" (Guinea Pig) for the adventurous How Long to Spend — for a first timer, I would recommend 2–3 weeks to see the key sites Cusco 2 days in the city + additional days for day trips Cusco was one of my favorite cities in South America and the perfect base for exploring Peruvian culture. The city is absolutely packed with activities and historical sites. On every street corner you can feel the rich cultural heritage, from a local musician playing ancient Incan instruments to magnificent Spanish colonial architecture. What to Do In Cusco City Boleto Turístico — perhaps the most useful ticket to purchase in Peru. An all-inclusive ticket for many sites in Cusco and Sacred Valley, lasting 14 days. Here is a full list of sites . Must be purchased in person at the main tourism office Plaza de Armas / Cusco Cathedral — the town center, surrounded by Spanish colonial architecture. In the center there is a fountain with a gold statue of the last Incan emperor Don't miss the local parade every Sunday morning around 11am: military, teachers, lawyers, government workers and groups in wild colorful traditional costumes Free walking tour of the historic center — highly recommended. Covers Plaza de Armas, Incan stone walls, San Blas viewpoint and a local fruit tasting at San Blas Market. About 2 hours Saqsaywaman — pronounced like \"sexy woman\", ancient Incan ruins at the top of the hill with llamas, an ancient slide and a nice view of the city. No mortar used anywhere — just perfectly stacked boulders that puzzle archaeologists to this day San Blas Market — mini food market with super cheap food. Try local fruits: Granadilla (like passion fruit), Aguaymanto (yellow cherry, tastes like sour candy), Tuna (sweet cactus fruit) and Chirimoya (creamy, similar to soursop) Pro Tip: There is also a food court here with a \"Menu del Dia\" served by local women, basically a 3 course meal for around 8 soles / ~$2 Viewpoints of the city Mirador de Plaza San Cristóbal — the best viewpoint in Cusco, in the courtyard of a church. On a clear day you can see Plaza de Armas below and the mountains across the city Mirador desde el Cristo Blanco — white Jesus statue similar to Christ the Redeemer in Rio, right next to Saqsaywaman. Quick stop San Blas Viewpoint Siete Borreguitos — famous Instagrammable street in San Blas District lined with flower pots Q'enco Archaeological Complex — ancient Incan burial ground about 20 minutes walk from Saqsaywaman. Main feature is a series of underground caverns Sapantiana Aqueduct — colonial-era irrigation system in San Blas neighborhood. Quick stop Museums Regional Historical Museum of Cusco — covers pre-Incan civilizations through the Spanish Inquisition. Highlights: a glyptodont skeleton (giant armadillo ancestor, about 4 feet long) and an exhibit on Tupac Amaru, a failed Peruvian revolutionary against Spanish rule Inka Museum — main Incan museum in Cusco. Doesn't take too long and has English descriptions everywhere Day Trips from Cusco Most day trips from Cusco start extremely early — 3AM–5AM wake up times are normal, so plan to go to sleep early Rainbow Mountain Day Trip — a tour to the famous 7-color Rainbow Mountain. Tours start at 3AM with a buffet breakfast included on the way. The hike reaches extremely high elevation (5,200m / 17,060ft) — you'll need to stop every 10 minutes to catch your breath. There's also the option to take a horse up. Expect to pay ~$49 for the full day trip Don't miss the bonus hike to Red Valley on the side, much less crowded and just as beautiful. Go early before the lines get long Humantay Lake Day Trip — hike to a beautiful bright blue lake surrounded by mountains. Only ~$24 for a full tour. Early start, high elevation, option to take a horse up Machu Picchu (as a day trip) — possible but not advised unless you are very short on time. The area around Machu Picchu is gorgeous and worth spending a few days Sacred Valley (as a day trip) — I'd recommend spending a few days here, but a day tour is also viable ( Sacred Valley Tour or Moray and Maras Salt Mines tour ) Where to Eat Mr. Cuy Restaurant — great place to try guinea pig. Order the Cuy al Horno (baked guinea pig) — it comes topped with a hat and Peruvian blanket. Tastes like a saltier Peking duck, all dark meat with super crispy skin. Comes with a complimentary pisco sour and sides: Peruvian corn, potatoes, papa rellana, sweet tamale and green herbal sauce Chira Restaurante — popular with locals. Famous for anticuchos (traditional Andean skewers — one chicken, one beef heart) in a spicy sauce served with large kernel Peruvian corn Xapiri Ground — the best coffee shop in Cusco with a little museum inside Qosqo Maki Panadería — modern upscale bakery, great for breakfast Café Panam — good carne empanadas with a yellow corn casing (different from the Argentinian breaded version) Los Toldos Chicken — popular fast food spot for locals. Try the Salchipapa (fried hotdog on fries) and fried chicken. ~14 soles / ~$4 Where to Stay Stay anywhere in the historic center walking distance to Plaza de Armas. San Blas neighborhood is also a popular option, nice and close to downtown, but uphill Viajero Kokopelli — nice hostel in the Centro Histórico. Part of the larger Viajero chain; offers tours, laundry service and complimentary coca leaf tea for altitude adjustment Note that people wake up very early for tours (4AM–5AM) so keep this in mind if you book a dorm ATTRACTIONS 1 Plaza de Armas 2 Saqsaywaman 3 San Blas Market 4 Mirador de Plaza San Cristóbal 5 Mirador desde el Cristo Blanco 6 San Blas Viewpoint 7 Siete Borreguitos 8 Q'enco Archaeological Complex 9 Sapantiana Aqueduct 10 Regional Historical Museum of Cusco 11 Inka Museum RESTAURANTS & BARS 12 Chira Restaurante 13 Xapiri Ground 14 Qosqo Maki Panadería 15 Café Panam ACCOMMODATION 16 Viajero Kokopelli Cusco DAY TRIPS ↗ Rainbow Mountain (Full Day) ↗ Humantay Lake (Full Day) ↗ Sacred Valley (Full Day) ↗ Machu Picchu (Full Day) Peru Cusco Touch to explore Double-tap to open in Google Maps Machu Picchu One of the seven wonders of the world and an absolute must while in Peru. Buy your tickets well in advance — the most popular options sell out and you'll need to wait at the ticket office the night before in Aguas Calientes if you don't. Avoid the rainy season (November to March) — many people make the mistake of traveling all the way there and not being able to see it due to the weather. I would recommend a multi-day trek over a single day trip since it is much more rewarding: Multi-Day Options Inca Trail (4 days) — the most popular option. You arrive through the \"Sun Gate,\" the traditional Incan entrance with one of the best views. Book 6 months in advance as it consistently sells out Salkantay Trail (5 days) — considered more beautiful than the Inca Trail, but also more challenging Inca Jungle Trail (4 days) — an alternative route mixing 4 adventure sports: hiking through the Peruvian jungle, biking 50km downhill through clouds, white water rafting on the Lucumayo River with a stop at a hidden waterfall, and ziplining. I did this and had a blast Machu Picchu Reservations — the company I booked with. By far the cheapest prices, but be prepared for very barebones accommodation Single Day Option Stay in Aguas Calientes town the night before and walk up the stairs to the main entrance or take a bus for $10. Arrive early before the crowds from Cusco. The town itself is gorgeous with cute shops and restaurants Or arrange a single day tour from Cusco — the fastest option Tickets Buy in advance on the government website — they sell out quickly and it is very important to choose the right circuits Buy Circuit 1 or 2 tickets — this has the traditional view of Machu Picchu. You won't see much if you choose the other circuits If you're up for a workout, add Circuit 4 and Waynapicchu, climbing stairs for 45 minutes to an hour, but gives you a bird's eye view of the entire complex Sacred Valley 1–2 days recommended The Sacred Valley is often overlooked for Machu Picchu. It is home to a variety of ancient Incan towns still inhabited by their descendants, and there aren't many tourists here which adds to the mystical feel. Hire a driver to hit all of these in a single day (~180 soles / ~$50). Each site takes 30 min to 1 hour with driving in between. You can also explore via public transport or tour. What to Do Ollantaytambo — where the train goes to Machu Picchu town, so consider spending the night here. The ruins have a cool sun temple complex overlooking the town Maras Salt Mines — beautiful salt mines with white pools embedded in a valley. Great viewpoint overlooking the area Moray — circular Inca crop circles. Similar to rice terraces across Asia, the Incans used these alien-looking structures for agriculture Chinchero — small colonial town with a Spanish church built on Incan ruins Pisac — I didn't personally go but people love it. More hippy vibes and popular for Ayahuasca ceremonies Where to Eat Apu Veronica Restaurant (Ollantaytambo) — one of my favorite restaurants in Peru, right next to a river Where to Stay Casa Samay Mountain View — very lowkey hostel with almost no other travelers. The roof is perfect for stargazing at night ATTRACTIONS 1 Ollantaytambo 2 Maras Salt Mines 3 Moray 4 Chinchero 5 Pisac RESTAURANTS & BARS 6 Apu Veronica Restaurant ACCOMMODATION 7 Casa Samay Mountain View Peru Sacred Valley Touch to explore Double-tap to open in Google Maps Lima 2–3 days recommended Lima is Peru's capital on the Pacific Coast. Often skipped in favor of Cusco and Machu Picchu, it has a number of unique attractions worth visiting. The city reminds me a lot of Santa Monica with the seaside bluffs and highway along the ocean. What to Do Walk along Malecón de Miraflores — path along the bluffs from Miraflores to Barranco. Strong Santa Monica vibes. Stop by Love Park , Larcomar and the Navy Lighthouse along the way Swim with Sea Lions on Palomino Islands — my favorite thing to do in Lima. Sea lions are normally aggressive toward humans but on the Palomino Islands they are playful and will swim right up to you. The water is cold so they give you a wetsuit and life jacket. ~$75 and takes the whole day Lima Basílica and Convent of San Francisco — church with catacombs beneath with 70,000 people buried there. One of the oldest surviving buildings in all of Latin America. Guided tour required Paragliding over the Coast Verde — great view of Lima and the coast. Offered on a \"trike\" (go-kart with a huge fan on the back). Only ~$50 Larco Museum — cool museum with tons of pre-Incan pottery. The erotic pottery collection is funny Barranco Neighborhood — the bohemian neighborhood with historic buildings, parks, churches and street art Federico Villarreal Park Bridge of Sighs Barranco Municipal Park Bajada de Baños Huaca Pucllana — ruins from the Lima civilization right in the center of Miraflores. Guided tour required Where to Eat Popular de aquí y de allá — solid Peruvian restaurant in Larcomar. Try the Tiger's Eye Ceviche Especiale Ice Cream — amazing ice cream shop in Barranco Where to Stay Lima isn't very walkable outside of specific neighborhoods — rely on Uber to get around Miraflores neighborhood — most modern and safe, central location for most tourist attractions Rainbow Hostel — popular, well-kept and social Barranco neighborhood — the bohemian option, popular with younger travelers ATTRACTIONS 1 Walk along Malecón de Miraflores 2 Barranco Neighborhood 3 Bridge of Sighs 4 Barranco Municipal Park 5 Bajada de Baños 6 Huaca Pucllana RESTAURANTS & BARS 7 Popular de aquí y de allá ACCOMMODATION 8 Rainbow Hostel Peru Lima Touch to explore Double-tap to open in Google Maps Puerto Maldonado (Amazon Jungle) 3–4 day tour There are two main spots to visit the Amazon in Peru: Puerto Maldonado in the south and Iquitos in the north. Puerto Maldonado is better connected and the more affordable option. Book a tour for 3–4 days. Get there via a short flight from Lima or Cusco, or the night bus from Cusco (~9 hours, reclining sofa-style seats). What to Do Paradise Yakari Amazon Tours — I did a 4 day tour and absolutely loved it. $330 all-inclusive for 4 days. Nice lodge on the Rio Los Dios with great food and an incredibly knowledgeable guide named Bryan ( Instagram ). Here's what the days look like: Day 1: Farm tour of the lodge grounds (cacao, papaya, achiote, termite nests), Monkey Island by kayak (feed brown and white capuchin monkeys), night animal hunt by boat (capybaras and baby white caimans) Day 2: Macaw Clay Lick at 4:25am — macaws and parakeets eat clay from riverside cliffs for minerals. White sloths in the trees on the way back. Canopy walk, suspension bridges and zipline above the rainforest. Lake Sandoval — paddle a canoe through a jungle channel to a beautiful reflective lake, look for giant river otters, squirrel monkeys and howler monkeys Day 3: Piranha fishing (harder than it sounds; they just nibble). Native village visit — face painting, traditional songs, fire-making demo, bow and arrow Day 4 add-on: Taricaya Ecoreserve animal sanctuary (~70 soles / ~$18 extra). Rescues animals from captivity. Saw toucans, emperor tamarin monkey, baby river otter, spectacled bear, small black jaguar and spider monkeys. Definitely worth adding Where to Stay Tambopata Hostel — basic and cheap. Loud, hot and very humid. Passable for a night before or after your tour if you just need somewhere to sleep Where to Eat Burgos's — best restaurant in town. Try the Pollo en Salsa de Sachaculantro (chicken breast in green cream sauce) Meysis Garden — try the Marina Tres: ceviche, chaufa (local fried rice) and fried squid Other Places to Consider I'll definitely be planning another trip to Peru. Here are some destinations recommended by other travelers: Huaraz — the capital for hiking in northern Peru. Home to the famous Laguna 69, Santa Cruz Trek and Cordillera Huayhuash Arequipa — the second largest city in Peru with beautiful colonial architecture Huacachina — a small oasis town in southern Peru surrounded by massive sand dunes. Famous for dune buggies and sandboarding"},{"url":"philippines/field-notes.html","title":"Philippines Travel Guide","text":"Philippines Travel Guide General Suggested Route Overview The Philippines is one of my favorite countries on the planet. With the clearest blue waters and some of the nicest people in the world, it is the ultimate travel destination whether you're looking for a relaxing vacation or adventure. Writing this guide made me want to book a flight back to the Philippines... Filipinos are probably the most laid-back and friendly people I've met. Outside of the capital, Manila, expect things to run on island time. Everyone speaks English so it is super easy to get around and connect with locals Safety — I felt extremely safe in the Philippines, despite its reputation for being a more dangerous location in Asia. Mindanao and some islands in the South are considered dangerous, but you're likely not planning to go there anyways. If you're sticking to major tourist hotspots, there is nothing to worry about Transport Manila airport connections — if you're connecting from an international to a domestic flight in Manila, budget at least 2–3 hours. The terminals are separate and require a bus or taxi transfer. Grab works well in Manila but make sure to agree on the price beforehand, airport taxi scams are common. A ride to the domestic terminal should be a few dollars max Tuk-Tuks — the primary way to get around on the islands. In El Nido the standard rate is 100 pesos (~$2) per ride in and out of town; you can negotiate for longer trips. Always a fixed rate, just confirm before you get in Buses / Vans between towns — shared vans are the standard for longer overland routes. They run pretty cheap (under $10 for a 5 hour ride). I used bookaway.com to book some buses or ask at your local accommodation and they'd be happy to book a ride for you. Bus stations are often poorly marked, check online or ask at your hostel exactly where to go and confirm which company runs your route How long to spend For a first time trip to the Philippines, I would suggest spending 2 - 3 weeks. Each island has a different personality and you'll be able to experience 2 to 3 of them within a couple weeks. Getting between islands is time-consuming so make sure to take that in account while planning Flights between islands always connect through Manila or Cebu City so plan for a full travel day when switching between islands. The flight prices increase a lot last minute so it is difficult to be spontaneous here Check the weather before you book , the Philippines is huge and weather varies significantly by island and season. Since it is an island nation, I would not recommend going during wet season, especially typhoon season. The infrastructure does not hold up very well (flights cancelled for days, roads flood, etc.). For example, Palawan (Western Philippines) dry season runs November to May Siargao (Eastern Philippines) dry season runs March to October Cash is used almost everywhere, except a few tourist destinations where credit card is suggested. ATMs are not available in more remote locations so make sure you stock up on cash. Many boat tours and bus companies are cash-only Tours — tours are significantly cheaper if you book in person. You can easily book through your accommodation or tour agencies located along the main road Food — I found Filipino food to be extremely underrated! The cuisine is extremely simple and the ingredients were extremely fresh. Here are some dishes that are worth trying: Chicken adobo — the iconic Filipino dish made of chicken braised in soy and vinegar, usually with a thick glaze. It is made in a different way by every restaurant Lechon — roast pork with cripsy edges, often served with rice Lumpia — fried spring rolls Pork Sisig — crispy pork bits with egg, served on a sizzling plate Tapsilog — sweet teriyaki beef with garlic rice and fried egg Halo-halo — shaved ice dessert with candied bananas Banana Ketchup — an interesting take on Ketchup Coron 2–3 days recommended Coron is known to have some of the most beautiful beaches in the Philippines and a great place to start your trip to the Philippines. The town itself is a bit run down so focus your time on the boat tours that depart from here What to Do Coron town — I would dedicate a half day to explore the town. It is an authentic Filipino island town and wasn't too touristy as you get off the main strip. Mount Tapyas viewpoint — hike up to the sign at the top of the hill (721 steps to the top). At the summit there's a Hollywood-style \"Coron\" sign and a large illuminated cross. Good place to watch the sunset, even on cloudy days the light breaking through the clouds is impressive Explore the Town — follow the main road all the way to the port. You'll pass the town's main Catholic church (with a small shrine to the Virgin Mary), a traditional local market with super low ceilings and stands selling fruits and meats and a basketball court. The port area gets rough (don't wander too far into the slum near the water) Boat tours This is an absolute must while in Coron, you'll see some of the most beautiful spots in the world. Boat tours are sometimes available online, but are up to 50% cheaper to book in person . They are easy to book at your hostel or on the street the night before. They run about $20–30 for a full day trip including lunch Boat tour pickups are chaotic. Expect a van from your hostel followed by 45–90 minutes of waiting at the dock while guides sort out groups. They'll always make sure you're on the right tour, but be patient I'd recommend the Super Ultimate Tour which includes a lot of interesting sites: Skeleton Wreck — a Japanese WWII warship sunk during the war. The water is insanely clear with a beautiful green tint. Snorkel over the bow covered in coral; divers can go deeper down the hull Coral Garden (Las Isla De Coral) — the best snorkeling spot on the tour and probably the best I've been to anywhere. Very shallow so you can see everything: giant clams, rainbow parrotfish, massive walls of yellow fish, vibrant coral. For me, it was even more beautiful than snorkeling the Great Barrier Reef CYC Beach — small beach with super white sand and turquoise water Twin Lagoon — One of the most beautiful places I've ever swam 70% fresh water, 30% saltwater, giving it a distinctive bright green tint. You can swim through two connected lagoons with towering jagged grey limestone cliffs covered in trees Kayangan Lake — a large salt/freshwater lake surrounded on all sides by towering grey stone cliffs. It has a darker blue tint than Twin Lagoon Barracuda Lake — not always included in standard packages. One of the most famous lakes in the area, but I felt that the other lagoons are worth prioritizing over this one Where to Eat Island Brasserie Restaurant — a nice cafe off the main road. The chicken adobo was excellent and even better when paired with a fresh mango smoothie Umamikusina — order the pork sisig. It arrives on a huge sizzling fajita-style plate, bits of crunchy fried pork with an egg in the middle. Incredible if you've never had it before Island Boy Grill — near the water with neon lights and a live band performing covers of American pop songs (they take requests). Great for a group dinner — order family style: chicken adobo, deep fried pork, tuna ceviche, garlic rice and calamari. Wash it down with buckets of Red Horse Strongs Where to Stay MyGuide Traveller Hostel — bare bones, but cheap at ~$12/night. Free breakfast if you preorder the night before (pancakes are actually good). Conveniently books boat tours and can organize airport pickups ATTRACTIONS 1 Mount Tapyas viewpoint 2 Skeleton Wreck 3 Coral Garden (Las Isla De Coral) 4 CYC Beach 5 Twin Lagoon 6 Kayangan 7 Barracuda Lake RESTAURANTS & BARS 8 Island Brasserie Restaurant 9 Umamikusina 10 Island Boy Grill ACCOMMODATION 11 MyGuide Traveller Hostel Philippines Coron Touch to explore Double-tap to open in Google Maps Coron to El Nido Boat Tour 3 days, 2 nights This boat tour was the highlight of my trip to the Philippines. It is a 3-day, 2-night excursion on a small boat with 20–30 other backpackers stopping at remote beaches and snorkeling spots with no one else around. The beaches here are unmatched and untouched by mass tourism. We stayed on remote islands in beach huts which were surprisingly nice. There was no feeling like falling asleep to the sound of the waves and waking up to the sunrise at your feet. There are many variations of this tour (the opposite direction and different amount of days), but the two main providers are Keelooma and Tao Expeditions. Make sure you book 2 - 3 weeks in advance to secure a spot. Keelooma — this is the company I went with. The experience was incredible. The boat guides were extremely friendly, the food was incredible and the accomodation was great. It is the cheaper option at 17,100 Philippine Pesos or ~$275 Tao Expeditions — the more famous tour company with their own private island. I heard their tour is much more luxurious, but more than twice the price at ~$585 What to Expect Day 1 — snorkeling stops and a sandbar dive spot, then a 2.5 - hour sail to your first overnight camp. Keelooma's camp ( Patoyo Island ) is a remote island between Coron and El Nido. The beach camp looks like a scene straight off Survivor (don't worry you'll have a comfortable hut to spend the night). There is a pure jungle palm treeline, huts with palm roofs, volleyball and basketball courts, hammocks and beanbags Day 2 — This highlight was a cliff dive at Linacapan . The crew helps you up via rope, one of the best things I did on the whole trip. Outstanding snorkeling with plankton that look like mini jellyfish, huge sardine schools making shapes in the water, clownfish in purple anemone, flatfish that looked like seaweed and vibrant purple/yellow/blue coral. Overnight at beachfront huts with the front wall open so you wake up looking directly at the beach Day 3 — Little Maosanon Island was one of the most photogenic spots on the tour and has a 700m sandbar extending into crystal green water. We also snorkeled by Darocotan Island (Tao's private island) with stunning water that shifts from light green near shore to deep blue further out and it's own shipwreck. The tour ended with a bus ride back to El Nido which was an adventure in itself. The tour conveniently ends in El Nido, a great location for continuing your journey Food — all meals were included and I was amazed by the quality of the food that they were able to cook on the back of the boat. It was served in family-style spreads: chicken adobo, crab, garlic rice, pancit and fresh fish caught earlier in the day. Night 3 often features a Boodle fight: a traditional Filipino communal feast arranged on a huge banana leaf Tips Make sure the boat doesn't leave without you... Believe it or not, this happened to my friend while we were snorkeling Bring a separate small dry bag for each island night since your main pack stays on the boat They provide snorkels. Many of them are old and leaky so test them before you hop off the boat. You can also bring your own if you have one Bring a good GoPro or underwater camera — the snorkeling spots are extraordinary A 50% deposit is paid online, but the final payment is cash only so make sure you bring enough pesos from Coron El Nido 3–4 days recommended Perhaps the most famous spot in the Philippines, El Nido is home to some of the most beautiful spots in the Philippines and it truly lives up to the hype. The town is much more modern than Coron and has a lot more fancy hotels, nightlife and western restaurants. It is a great place to base yourself for 3 - 4 days to take more boat tours and relax on the beach. What to Do Boat tours — the main thing to do and I promise you won't get tired of spending time on boats. The scenery is gorgeous, but be prepared for many more tourists than Coron. Similar to Coron, Tours are standardized throughout each agency with fixed paths named Tour A, B, C, etc. Tour A — this is the most popular tour in El Nido which included some of following the highlights: Big Lagoon — you can kayak to the end of this beautiful lagoon area with stops at small coves Entalula Beach — brightest blue water I've seen anywhere, set against dark grey cliffs. It is a popular spot for filming Hollywood blockbusters including The Bourne Legacy, Avatar and part of the beach was closed for filming while I was there! Seven Commandos Beach — a wide coastline lined with palm trees, great for relaxing on the beach, volleyball and naps Frendz Hostel - this is the best tour company in El Nido. The tours are very fun with super lively tour guides and loud music. They take you to all the best spots in El Nido El Nido Zipline at Las Cabanas Beach — an amazing ziplining experience across the bay over the green and blue water and lands on a small island covered in trees. You walk back across the sandbar at low tide. The views from the top are incredible. It is an affordable experience (600 pesos or ~$12) that only takes half a day. El Nido town — a buzzing area with lots of restaurants, bars and souvenir shops. A good place to meet other backpackers and enjoy the nightlife. The beach here is mainly used as docking for boat tours so don't expect to relax here Nacpan Beach — a great spot if you're looking for a peaceful getaway from the buzzing town of El Nido. It is an enormous beach located 40 min from town by tuktuk. There are restaurants and a few accommodation options here Twin Beach / Celiteng Beach — a great place to watch the sunset in the area. Find a spot along the sand to watch the sunset like Phoenix Bar & Restaurant Where to Eat Inasal Eats Co — Filipino chain full of locals. For only 200 pesos or ~$4, comes with unlimited rice and a huge piece of BBQ chicken. The chicken is slightly sweet with a nice char and eat it with the vinegar and soy sauce provided Big Bad Thai — a popular dinner spot in the main town. It is usually busy so expect a wait Bars / Clubs Frendz Hostel rooftop bar — a great place to hangout and visit for drinks after the boat tour even if you're not staying there Sava Beach Bar — rooftop balcony overlooking the dance floor and beach Amigos — a club popular with Filipinos (they love their American pop music!). Super lively Where to Stay Frendz Hostel — a super modern hostel with a rooftop pool, bar and hosts a bunch of tours. This is the best place to stay to meet people. It often books out so book in advance Big Paul's (Corong Corong Beach) — located about a 10-min tuktuk from the main town (100 pesos each way). It was a solid and cheap option with unlimited free rum and coke from 7–11pm and pet parakeets Mad Monkey Nacpan Beach — located in Nacpan Beach (45 minutes away from El Nido town), a great place if you're looking for a more relaxing stay away from the madness of El Nido town ATTRACTIONS 1 Seven Commandos Beach 2 El Nido Zipline at Las Cabanas Beach RESTAURANTS & BARS 3 Inasal Eats Co 4 Big Bad Thai 5 Frendz Hostel rooftop bar 6 Sava Beach Bar 7 Amigos ACCOMMODATION 8 Big Paul's (Corong Corong Beach) 9 Frendz Hostel 10 Mad Monkey El Nido DAY TRIPS ↗ Boat Tour A (Full Day) Philippines El Nido Touch to explore Double-tap to open in Google Maps Port Barton 2–3 days recommended Port Barton is a popular backpacker town with a nice laidback vibe that feels like the real Philippines. Made up of mostly unpaved roads and only about 7 blocks along the beach, it is a really small town where everything is walkable. It is a nice place to spend 2 to 3 days to decompress from El Nido You can reach Port Barton by bus from El Nido. It is a 5 hour ride costing about $9. There are a lot of stray dogs, but they are completely harmless. They might just follow you around for food. What to Do Port Barton Beach — this is the main beach in town and a great place to chill. There are some restaurants and bars on the beach and it is a great place to watch the sunset White Beach / Coconut Beach — these are considered some of the nicest beaches in the Philippines, that are reachable by boat from the main beach. White Beach is 300 pesos (~$6) by water taxi and is secluded, with few tourists, brilliant white sand and bright blue water with coconuts scattered on the ground. From there, Coconut Beach is walkable from White Beach via a dirt road through the forest. It is only about 1km away. However, the road isn't on Google Maps and no signs, just follow the road. It is a bit more developed, but very still quiet. You can walk back to town from there through the jungle Snorkeling with turtles — the most popular activity in Port Barton since the town has one of the largest population of sea turtles and there a lot of local organizations focused on protecting the local populations Where to Eat Barton Bistro — the main beach bar in town. A great place for drinks in the evening. They have bean bags along the sand where you can relax and watch the sunset Raquel's Canteen — a true local mom-and-pop spot where many locals eat. I came across this place since they were grilling chicken out front and wandered inside. I recommend the sweet grilled chicken served with rice and green beans MGM Food House — a solid restaurant serving Filipino food Where to Stay Dam Dam Hostel — a very basic hostel that fits vibe of the town perfectly. They have a huge open-air wooden deck out front with a small cafe and rooms in the back. The food is pretty good here ATTRACTIONS 1 Port Barton Beach 2 Coconut Beach RESTAURANTS & BARS 3 Barton Bistro 4 Raquel's Canteen 5 MGM Food House ACCOMMODATION 6 Dam Dam Hostel Philippines Port Barton Touch to explore Double-tap to open in Google Maps Siargao 4–5 days recommended Siargao has recently risen in popularity as the \"most beautiful island in Asia.\" Famous for its surf at Cloud 9, it has developed a lot in recent years and is home to a variety of different activities. You'll need to fly here from Manila or Cebu and it is worth spending 4 to 5 days here. I would recommend visiting before it gets too popular. I mainly spent time on the more popular \"General Luna\" side of the island so most of my recommendations come from here. There are other spots to explore on the island, but they are much more secluded. What to Do Cloud 9 — this is a world famous surf spot. It is extremely rocky here and is not great for beginners. There is a long bamboo pier extends 800m out over the water, lined with colorful flags where you can go watch the surfers. If you're not planning to surf here, you can walk along the beachside and check out the restaurants and shops out front Surf lessons — by far the most popular activity in town. You can get cheap, private surf lessons for $10 - $15 per hour. Depending on your level, they'll take you to an appropriate spot Explore General Luna Downtown — this is the main downtown with tons of restaurants, bars and cool surf shops. The town is built around a local school and church with western restaurants along the main road. This is a good place to base yourself if you're looking for a more vibrant downtown or for nights out Sohoton Tour — this full day boat tour takes you to another island, right off the coast of Siargao. The main draw is the Jellyfish sanctuary which is one of the only places in the world where you can swim in a sea of clear, harmless Jellyfish. They also take you to a variety of nice coves, secret caves and cliff diving spots. It comes with a colorful Boodle flight lunch as well. Book through a travel agency in General Luna the day before and expect to spend ~$50 Land Tour — Siargao is known for being covered in a sea of thousands of palm trees. I didn't personally take this tour due to the weather, but it takes you to the coconut grove , a famous hanging coconut tree swing and Magpupungko Rock Pools Siargao Wakepark — located roughly 30 minutes from General Luna, this is a great part to go wakeboarding. Wakeboarding is a water sport where you stand on a board and hold on to a handle of a rope system that pulls you around. As a pure beginner, the staff were super welcoming and helped explain exactly how to stand and hold. It is a great first-timer experience since it is much easier than ocean wakeboarding behind a boat. It was ~$20 and a great way to spend half a day Sunset Bridge — the best place to watch sunset from. During sunset, it is packed with locals and tourists shoulder to shoulder watching the sunset, food carts and skaters on the bridge. Roughly a 20-minute walk from Cloud 9 Where to Eat Sana Bowl — an amazing poke restaurant in general Luna Kurvada — cheap cafeteria-style Filipino restaurant on the main road, popular among locals. There are tons of pots with different foods lined up, you point at what you want, take a photo of your plate and pay at the end Backyard Steakhouse — the nicer option in General Luna if you're looking for Western food (steaks, burgers and pasta) Big Mama's Cafe & Laundry — a nice cafe in General Luna. They have a great brunch and you can also drop off your laundry here Felix Surf Club — a nice laidback bar near the Cloud 9 pier. A good place to have a drink and watch the surfers Nightlife Explorers' Bar — the main nightclub in Siargao with a huge venue with a DJ running pop mashup sets. It weirdly closes at 10pm, but there are other places open nearby Siargao Beach Club — a great open-air venue, sometimes has foam parties, beer pong and a stage. Good for a late-night spot after Explorer Bar closes Where to Stay Mad Monkey Siargao — a great social hostel to stay at in Siargao. It had a great atmosphere, a pool, a bar area, regular events (pub quiz, booze cruises) and the easiest place to meet people. I spent ~4 nights here and met some amazing people Kayan Siargao — a lowkey one-room hostel embedded in a resort. It was pretty nice and located right in General Luna, but there wasn't a single other tourist while I was there. I preferred the Mad Monkey in Siargao ATTRACTIONS 1 Cloud 9 2 Explore General Luna Downtown 3 Siargao Wakepark 4 Sunset Bridge RESTAURANTS & BARS 5 Sana Bowl 6 Kurvada 7 Backyard Steakhouse 8 Big Mama's Cafe & Laundry 9 Felix Surf Club ACCOMMODATION 10 Mad Monkey Siargao 11 Kayan Siargao Philippines Siargao Touch to explore Double-tap to open in Google Maps Manila 1 day recommended Manila is the capital and largest city in the Philippines. The city was completely destroyed in WWII and completely rebuilt with modern buildings, but is some interesting historical sites. However, I would recommend spending only 1 day in Manila and prioritizing your time on the other islands. You're bound to fly through here (at least 1 time) so it is worth stopping by. Manila's neighborhoods are not very walkable. You can use ride sharing apps like Grab to get around the city The best neighborhoods to stay in are Intramuros (the historic center) or Bonifacio Global City (BGC). Manila is a large city with a lot of traffic so it is best to stay close to the main attractions What to Do Intramuros & Fort Santiago — the historic center of the city. Most was destroyed during WWII, but there's still a lot of interesting history and some museums. There's a strong Spanish Colonial influence in this area and it reminded me a lot of similar places in Latin America Fort Santiago — large courtyard with Spanish forts repurposed as American barracks, cannons, a Jose Rizal monument and museum. The museum details the WWII history of Manila including the former Japanese prison dungeons and imprisonment of freedom fighters during the Battle of Manila San Agustin Church — the best-preserved building in Intramuros. Characterized by a tall bell tower with incredibly intricate carved wooden doors on the exterior and elaborate golden centerpiece Manila Cathedral — an old spanish colonial style church. It is active and very well maintained Baluarte de San Diego — old Spanish city wall turret. Walk along the wall, see leftover Spanish and American-era cannons, admire the garden. Casa Manila — a preserved Spanish colonial house showing what life looked like under colonial rule. An interesting visit with a lovely courtyard surrounded by cafes Manila 1945 Historical Marker and Memorial — a memorial for Filipinos who died under Japanese occupation National Museum of Anthropology — a 4-story museum that is a short walk from Intramuros. Standout exhibits include: prehistoric clay burial pots (found in a massive cave, Indiana Jones-style), displays on the Muslim minority of the southern Philippines and the Negrito indigenous people who have Polynesian rather than East Asian roots Rizal Park — large park with statues of Filipino heroes, a big reflecting pool, and an obelisk memorial at the end Mall of Asia — one of the largest malls in Asia that is very modern inside. You might just see the Jonas Brothers there (like I did) Where to Eat Mang Inasal — a popular Filipino fast food chain, 99 pesos (~$1.70) for chicken inasal and rice. The chicken is perfectly grilled and marinated with coconut vinegar, soy sauce and brown sugar. It includes a dessert called halo-halo which is shaved ice with candied bananas Patio de Conchita Restaurant — a self-serve style restaurant inside Intramuros. I had beef stew, chicken adobo and rice. Good and convenient for a lunch break mid-sightseeing Where to Stay Ola Hostel — a basic hostel located a 30–40 min walk from Intramuros. It wasn't the most walkable neighborhood ATTRACTIONS 1 San Agustin Church 2 Manila Cathedral 3 Baluarte de San Diego 4 Casa Manila 5 Manila 1945 Historical Marker and Memorial 6 National Museum of Anthropology 7 Rizal Park 8 Mall of Asia RESTAURANTS & BARS 9 Mang Inasal 10 Patio de Conchita Restaurant ACCOMMODATION 11 Ola Hostel Philippines Manila Touch to explore Double-tap to open in Google Maps Other Places to Consider Siquijor - a small island near Cebu with amazing caves, waterfalls and beaches Cebu - home to the second largest city in the Philippines. However, the highlights are Oslob (swimming with Whale Sharks) and Moalboal (famous for its year round Sardine Run) Bohol - an island near Cebu famous for the Chocolate Hills and the strange looking Tarsier (one of the world's smallest primates)"},{"url":"serbia/field-notes.html","title":"Serbia Travel Guide","text":"Serbia Travel Guide General I only spent an 8-hour layover in Belgrade so most of these tips were from a Serbian friend who lives in Belgrade I found Serbians to be really warm and down to earth. Every taxi driver and waiter was very welcoming and fun to talk to The level of English is very high and I had no trouble getting around at all. The Serbian language has two alphabets. Cyrillic is used for more formal situations and Latin is increasingly common. Both are used on signs everywhere so it is easy to navigate I was initially a bit hesitant due to the ongoing student protests at the time, but it felt very safe and I had no issues with the politics. Don't talk about Kosovo since it remains a contentious issue. You can only enter Serbia from Kosovo, but not the other way around Serbia Overview Belgrade Recommended time: 2-3 days General This is the capital of Serbia and one of the largest cities in the Balkans with over 1.2 million people. Belgrade is super clean & modern and has very organized public transport Belgrade in particular is considered one of the best party cities in Europe and the nightlife is supposedly world-class. Plan to go on a weekend if you can Car:Go and YandexGo are the local ridesharing apps since Uber doesn't operate in Serbia What to Do Church of Saint Sava — this is the iconic Serbian Orthodox church in the city center. It is an enormous white church with towering green domes. The inside is completely covered in gold mosaics and the dome alone cost $10M. It was probably one of the most impressive churches that I have seen Kneza Mihaila / Skadarlija walking streets — these are beautiful pedestrian streets in the city center. Kneza Mihaila is very modern, polished and lined with different shops and restaurants. Skadarija is more historic and also has a lot of restaurants and shops Republic Square - the center of the city connected to the National Museum of Serbia and Kneza Mihaila walking street Belgrade Fortress (Kalemegdan) — a fortress in a park overlooking the intersection of two rivers (Danube and the Sava). The moat is lined with old tanks, cannons and missile launchers. The \"Despot's Gate\" entrance with two massive towers is worth visiting Museum of Yugoslavia - Belgrade was the capital of Yugoslavia and this museum is where the former leader of Yugoslavia, Josip Broz Tito is buried. The history of Yugoslavia is very recent, interesting and definitely worth a visit Nikola Tesla Museum - a museum dedicated to the famous scientist who was ethnically Serbian Avala - located 30 minutes outside the city, this is the famous TV tower which provides a view overlooking Belgrade. There are also a number of monuments and hiking in this area Ada Ciganlija - a popular spot in the summertime for local Serbians to go to the beach, sunbathe and swim Gardoš Tower - a historic tower overlooking the river, located across the river from central Belgrade Kosančićev Venac — a charming historic street with a nice view overlooking the river 25. Maj - the river front promenade which is popular for locals to walk along What to eat Restaurants Restoran Vuk - a traditional Serbian restaurant located in the city center Restoran Šaran Zemun - a fancy Serbian restaurant located right by the waterfront Zora Sweets & Desserts - a pastry shop recommended by a local Hotel Moskva - a historic 5 star hotel in Belgrade that is famous for their Moskva Šnit, a layered, almond sponge cake filled with a cream and cherries Bars Druid bar - cocktail bar in the city center Riddle Bar - cocktail bar in the city center Serbian Foods to Try Burek - flaky Balkan pastry filled with meat, cheese, potatoes or spinach. You can find this at almost any bakery Cevapi - little spiced meat sausages found all over the Balkans, served typically with fries Sarma - cabbage leaves stuffed with rice and minced meats Moskva Šnit from Hotel Moskva - a sweet layered sponge cake Where to Stay Balkan Soul Hostel - considered the best hostel in Belgrade Yugodom - an old retro hotel with a Yugoslav theme if you want to experience a hotel room from the Yugoslav times ATTRACTIONS 1 Kneza Mihaila 2 Republic Square 3 Belgrade Fortress (Kalemegdan) 4 Museum of Yugoslavia 5 Nikola Tesla Museum 6 Gardoš Tower 7 Kosančićev Venac 8 25. Maj RESTAURANTS & BARS 9 Restoran Šaran Zemun 10 Restoran Vuk 11 Hotel Moskva 12 Riddle Bar 13 Zora Sweets & Desserts ACCOMMODATION 14 Balkan Soul Hostel 15 Yugodom Serbia Belgrade Touch to explore Double-tap to open in Google Maps Other Places to Go in Serbia Novi Sad - the second largest city in Serbia, only 1.5 hours from Belgrade Sombor - a beautiful, historic city in the north of Serbia close to the Hungarian and Croatian Border (Nikola Jokić is from here) Krupajsko vrelo - a beautiful waterfall with very clear water in Central Serbia Manasija Monastery - considered one of the prettiest monasteries in the country, located in Central Serbia Kopaonik - considered the best place to ski in Serbia and great for hiking in the summertime. Located far South along the border with Kosovo"},{"url":"slovenia/field-notes.html","title":"Slovenia Travel Guide","text":"Slovenia Travel Guide General Slovenia is one of Europe's great little surprises: a tiny, green country wedged between the Alps and the Adriatic. Home to a storybook lake, a laid-back capital and dramatic mountains and caves, all within an hour or two of each other. Slovenia is an easy addition to a trip to Croatia, Italy or Austria trip. For first-time visitors, I would recommend spending about 4 to 5 days exploring the highlights of Lake Bled and Ljubljana . Suggested Route Overview Getting around Buses & trains — Slovenia is a small country so everything is close. The two highlights of Bled and Ljubljana are less than an hour by bus or train. The rest of the country is extremely well connected by public transport so you won't need to rent a car unless you're exploring deep into the national parks Car — it is worth renting if you want to explore the alpine valleys, the coast and the caves at your own pace. You can fly into Ljubljana Airport and rent a car from one of the many agencies there Money — the Euro is the official currency there. Slovenia is good value and a tiny bit cheaper than neighboring Italy, Austria or Croatia Food — Slovenian food is a delicious crossroads between Germanic, Balkan and Italian food. Some of my favorite dishes were: hearty sausages and sauerkraut, cheap and excellent burek (a Balkan staple of filled filo pastry), štruklji dumplings, the famous Bled cream cake, and surprisingly good local wine & Laško lagers Language — the official language here is Slovenian (similar to other Southern Slavic languages spoken in the Balkans). English is very widely and confidently spoken so you'll have no trouble getting around or even striking up a conversation with locals Lake Bled 2–3 days recommended Lake Bled is Slovenia's premier destination that you might recognize from photos: a crystal-clear turquoise alpine lake with a tiny, charming church perched on an island. The area also includes a medieval castle clinging to the cliffs above, and the Julian Alps rising in the background combine to create one of Europe's most picturesque landscapes. The best way to experience Lake Bled is simple: walk the lakeshore, hike to one of the viewpoints, rent a traditional row boat or take a swim to the island. I would recommend at least 2 to 3 days to enjoy Lake Bled with some addition time just to relax. What to Do Walk around the Lake Bled — a flat, paved path loops the entire lake in about 90 easy minutes, passing swimming spots, cafés and constantly shifting views of the island. In the evening, the you for a stroll and watch the sun set over the picturesque lake. One of the loveliest free things to do in Slovenia Mala Osojnica Viewpoint — the best viewpoint for Lake Bled . The Mala Osojnica viewpoint is a short, but very steep hike up the wooded hill on the west side of the lake. Once you get to the top, you'll see the iconic bird's-eye view of Bled Island, the castle and the impossibly turquoise water far below. Go early for soft light and fewer people, and wear proper shoes, since it gets slippery when wet Some other viewpoints are Velika Osojnica and Ojstrica , but I felt like Mala Osojnica was the best view Bled Island — after admiring the little church and island from shore, the next thing to do is to make your way over there. The best way to get there is to rent a classic wooden rowboat from the shore and paddle your way there. You can also take a traditional pletna boat where a local guide rows for you or swim directly to the island (roughly 300m) On the island, you'll find 99 steps that will take you to the Church of the Assumption of the Blessed Virgin Mary . The church is pretty small and the whole island takes only 20 minutes to see, so the leisurely row out and back across the glassy water is really the experience Swim in the lake — fed by mountain springs and thermal sources, the water is so clean it's basically like swimming in drinking water. During the summer, it makes for the perfect place for a swim. You can pretty much swim anywhere along the lake with the grassy shore making it easy to just climb in. If you're looking for more formal swimming spots, you can head to the wooden docks near the village or Velika Zaka which was a beach popular among locals Bled Castle — the oldest castle in Slovenia, perched on a cliff right above the water and reached by a short uphill walk from the main town. Inside is a small museum, a working replica print shop and a wine cellar. There is an amazing view of the lake below along with the iconic church and island. It makes for a good alternative viewpoint if you don't want to do the climb up to the Mala Osojnica Viewpoint . There's a café terrace up top for a drink with the panoramic view Where to Eat Gostilna Pri Planincu — a traditional Slovenian restaurant near Lake Bled serving hearty local dishes at reasonable prices. The restaurant's setting feels like a classic Slovenian Inn with a cozy wooden dining room and a small outdoor dining tables. It's a great place to try regional specialties such as štruklji , žganci , and Slovenian sausages Kremšnita (cream cake) — Bled is famous all over Slovenia for their cream cake! A fat square of vanilla custard and whipped cream between sheets of flaky pastry. It was originally invented at the lakeside Hotel Park and now sold by every café in town. My favorite place to try it was Spica . It's worth trying once with a coffee and a lake view Pizzeria Rustika — one of the best meals I had in Lake Bled, serving excellent wood-fired pizzas and a good selection of Slovenian craft beers with generous portion sizes Mega Burger — a no-frills burger joints with lowkey one of the best burgers I had anywhere in Europe (coming from an American) . It's a funny thing to rave about in a lakeside resort town, but after a day of hiking and swimming it absolutely hit the spot Where to Stay Stay in Bled Village on the eastern end of the lake. Most of the restaurants and accommodation options are located here. It's also walking distance from the rowboat docks, the lakeside path, the castle climb and the bus and train connections, making it the most convenient location in town Ace of Spades Hostel — a basic hostel besides the lake. I found the dorms to be regular, but the environment when I was there was extremely social. Everyone is in Bled to do the same thing so it is easy to find a group to join you ATTRACTIONS 1 Mala Osojnica 2 Bled Island 3 Bled Castle 6 Velika Osojnica 7 Ojstrica 8 Church of the Assumption of the Blessed Virgin Mary 9 Velika Zaka RESTAURANTS & BARS 4 Mega Burger 10 Gostilna Pri Planincu 11 Spica 12 Pizzeria Rustika ACCOMMODATION 5 Ace of Spades Hostel Slovenia Lake Bled Touch to explore Double-tap to open in Google Maps Ljubljana 2 days recommended One of Europe's most overlooked capitals, Ljubljana (pronounced loo-BLEE-ah-nuh ) is definitely worth a visit. It is a charming, compact city of pastel Baroque facades, dragon-adorned bridges, and lively riverside cafés, all with a medieval hilltop castle towering over. It's remarkably green, effortlessly walkable, and has a relaxed atmosphere that makes it easy to slow down and simply enjoy the city. Despite being a capital, Ljubljana feels intimate and isn't overcrowded with tourists. I would spend 2 days in Ljubljana . What to Do Ljubljana Castle — the hilltop fortress watching over old town Ljubljana . It is only a 10-minute walk up or it can be reached by a quick funicular. The included audio guide runs through the city's history, the viewing tower supposedly takes in a third of the country on a clear day, and there's a little museum of Slovenian puppetry tucked inside. It's a lovely spot for a coffee or a summer evening Old Town — a charming European old town based around the small Ljubljana river. You'll find lots of bridges and churches. You can take a walking tour if you're interested in history or simply wander around and get lost Prešeren Square — Ljubljana's lively main square and the heart of the city, named after Slovenia's greatest poet, France Prešeren . It is the best place to start and framed by colorful historic landmarks including: Franciscan Church — the first building to strike you will probably be the pink Franciscan Church. It is a striking salmon-pink Baroque church and one of Ljubljana's most recognizable landmarks Triple Bridge (Tromostovje) — the quirky three-in-one bridge at the heart of the old town, the signature work of architect Jože Plečnik, who shaped much of the city St. Nicholas Cathedral — Ljubljana's beautiful Baroque cathedral is worth visiting for its ornate interior, but don't miss the extraordinary bronze doors Dragon Bridge (Zmajski most) — the most photographed bridge in the city, an elegant bridge guarded at each corner by a fierce green-bronze dragon. The dragon is Ljubljana's emblem, tied to an ancient legend. You'll notice dragons everywhere throughout the city including the city flag, the manhole covers and half the souvenirs in town. The bridge is worth the short walk for the photo The Ljubljanica River cafés — the real pleasure of Ljubljana is simply sitting by the river and admiring how green the city is. There are many café and bar terraces, packed and buzzing on any warm evening. Grab a spritz or a local Union beer and watch the world drift by, or rent a kayak or paddleboard to see the willow-draped banks and bridges from the water Metelkova Art District — located a 15 minute walk from Prešeren Square , the Metelkova Art District is an anarchic autonomous arts complex. Every surface plastered in murals, mosaics and creepy sculptures. By day, it's a fun stop with colorful more modern art and a total contrast to the pretty old town. By night, it becomes one of the city's alternative nightlife hubs, grungy and fun, but a bit sketchy. There were some odd characters roaming around this area Where to Eat Loni-Pek Pekarstvo — I think I've recommended Burek in every single one of my Balkan travel guides. This spot in particular was recommended by my half-Slovenian friend who used to spend summers in Slovenia growing up. This local bakery was very affordable and located right by the river Klobasarna — a tiny, no-frills local counter dedicated to kranjska klobasa . It is a unique Slovenian dish with a sausage, served simply with mustard, horseradish and bread, alongside a warming bowl of jota (bean-and-sauerkraut soup). It's cheap, traditional and authentically Slovenian Where to Stay Stay in the old town along the river: Ljubljana is tiny and very walkable ibis Styles Ljubljana / The Fuzzy Log — one of the strangest hostels I stayed in... but not in a bad way. This ibis location offers either a rocket ship themed pod or an outdoor fuzzy log cabin, both of which seemed like they were designed by a 10 year old for a sleepover. I stayed in the rocket ship pod and it was very comfortable. Quite an interesting place to stay ATTRACTIONS 1 Ljubljana Castle 2 Triple Bridge 3 Dragon Bridge 4 Ljubljanica River 5 Metelkova 8 Prešeren Square 9 Franciscan Church 10 St. Nicholas Cathedral RESTAURANTS & BARS 6 Klobasarna 11 Loni-Pek Pekarstvo ACCOMMODATION 7 ibis Styles Ljubljana / The Fuzzy Log Slovenia Ljubljana Touch to explore Double-tap to open in Google Maps Other Places to Consider Slovenia packs a huge amount into such a small country. I didn't budget enough time on my first trip for the country. Here are some other highlights that I plan to visit on my next trip to Slovenia: Triglav National Park — Slovenia's greatest alpine national park, centered around the country's highest peak, Mount Triglav. The park is famous for hut-to-hut hiking through dramatic mountain scenery, where you can spend several days crossing valleys, pristine mountain streams, passes, and peaks while staying in traditional mountain huts Lake Bohinj — Bled's bigger, wilder and quieter neighbor. A long glacial lake deep in the Julian Alps inside Triglav National Park , ringed by peaks and forest that is much less developed than Lake Bled . It's the place to swim, kayak and hike, or ride the cable car up for the views. Pair it with the Vintgar Gorge , a spectacular boardwalk pinned to the cliffs above a rushing emerald river Piran — a gorgeous little Venetian-Gothic town packed onto a point at the tip of Slovenia's tiny 46km stretch of Adriatic coast. I resembles the seaside towns in Croatia with all terracotta roofs, a marble square and narrow lanes tumbling down to the sea Postojna Cave & Predjama Castle — one of the largest and most spectacular cave systems in Europe. It is big that you board an electric train that takes you couple of kilometers into the mountain before you walk among vast chambers of dripping formations. Pair it with nearby Predjama Castle , a dramatic Renaissance fortress built right into the mouth of a cliff cave. Both are easy stops between Ljubljana and the coast The Soča Valley — an achingly beautiful alpine valley following the electric-blue Soča river as it cuts through the Julian Alps, and Slovenia's outdoor-adventure heartland: whitewater rafting and kayaking, canyoning, hiking and via ferrata around the hubs of Bovec and Kobarid . Best explored with a car"},{"url":"sweden/field-notes.html","title":"Sweden Travel Guide","text":"Sweden Travel Guide General Sweden is where Scandinavian design, historic charm, and nature come together. Its capital, Stockholm , is one of my favorite cities in northern Europe. The city is spread across 14 islands connected by elegant bridges, giving it one of the most beautiful settings of any European city. Although Sweden is an expensive destination, a few days is enough to experience Stockholm's highlights, and it combines easily with nearby cities including Copenhagen , Tallinn , or Helsinki . Suggested Route Overview Getting around Stockholm — Sweden an has one of the best metro systems that is easily navigable even as a first-time tourist in the city. It is famous for its cave-like and hand-painted \"art stations\", trams and buses. Additionally, Stockholm is built on 14 islands, so ferries double as scenic public transit Trains, Planes & Ferries — fast long-distance trains link the main cities, and overnight ferries connect Stockholm to Helsinki and the Baltics. If you're traveling from farther, fly into Stockholm Arlanda Airport Money — despite being a member of the EU, Sweden uses it's own currency called the Swedish Krona and not the euro. However, Sweden is close to cashless so you might not even have to withdraw cash. Expect it to be expensive as Scandinavian countries usually are Food — Swedish cuisine is surprisingly tasty and widely known. You'll need to try the famous Swedish meatballs covered in a thick layer of gravy and served with lingonberries ( don't even dare compare it to IKEA ). Other dishes to try are the cured salmon ( gravlax ), pickled herring and fika (the sacred coffee-and-cinnamon-bun combo). Swedish pastries are rated some of the best in the world and I can confirm from first hand experience Language — The primary language is Swedish (mutually intelligible with Danish and Norwegian). Sweden also has the highest English fluency rate for a non-native speaking country. Almost everyone you meet will be fluent in English. Scandinavians are known to be reserved. However, the Swedish people I've met during my travels have been very social and open How long to stay — 2–3 days is plenty for Stockholm; add time to explore the archipelago or other cities in summer Stockholm 2–3 days recommended Stockholm is a city of 14 islands where medieval old towns, royal palaces and design-forward neighborhoods all sit on the water. It really surprised me as one of the prettiest capitals that I've visited in Europe. It is very easy to explore on foot, public transport and by ferry. It felt like a very international and livable city (despite the high cost of living) . I would recommend spending 2 to 3 days to fully explore the Stockholm . What to Do The best way to explore Stockholm is exploring by neighborhood in the city center. Here they are from North to South: Östermalm & Norrmalm , Gamla Stan , Djurgården and Södermalm . I've organized the attractions below by neighborhood and be sure to explore the city map below to orient yourself: Östermalm & Norrmalm — the city's most upscale neighborhoods, full of wide 19th-century boulevards, designer boutiques and grand stone apartment blocks. Östermalm is worth a stroll for the architecture, waterfront, and it is home to the excellent food hall below Östermalms Saluhall — a beautiful red-brick indoor food hall from the 1880s, where Stockholm has bought and sold its fish, game, cheese and bread for generations. It's high-end and not cheap, but it's a lovely place to sample Swedish cuisine: pull up at one of the counters for excellent Swedish meatballs, fresh prawns or a smörgås (open-faced sandwich), and browse the deli stalls Strandvägen — one of Stockholm's grandest waterfront boulevards, lined with ornate late-1800s facades and moored boats, looking straight across to the neighborhood of Djurgården (the museum island) Stockholm City Hall — not technically in Östermalm , but just further east in the neighborhood of Kungsholmen . The red-brick Stadshuset is where the Nobel Prize banquet is held each December, and you can climb the tower for one of the best views back over the old town Helgeandsholmen — a tiny island lodged between the nearby neighborhood of Norrmalm and the old town of Gamla Stan . You can visit it by foot-bridge and it is mostly filled by the Parliament House , with a quiet strip of park and a terraced walkway around its edge. It's an easy place to pause: the surrounding bridges and quays frame one of the best open-water views in the city Gamla Stan (Old Town) — the highlight of Stockholm for me was the old town called Gamla Stan in Swedish. Stockholm composed of 14 islands today, but Gamla Stan sits on the original island. It hosts one of the best-preserved medieval centers in Europe, consisting of a tight maze of bright red and yellow facades, cobbled lanes and hidden courtyards that are photogenic Stortorget — the picturesque square that lies at the center of Gamla Stan , lined with colorful 17th-century gabled merchant houses. It's Stockholm's most photographed square and the perfect place to stop for a coffee or simply soak up the atmosphere Royal Palace — one of the largest palaces in Europe still used by a reigning monarch, featuring lavish state apartments, royal museums, and a daily changing of the guard ceremony Mårten Trotzigs Gränd — Stockholm's narrowest alley, squeezing down to just 90 cm (35 in) at its narrowest point. Tucked away in the winding streets of Gamla Stan , it's a fun photo stop and an easy landmark to miss if you aren't looking for it Djurgården — Stockholm's green museum island that is a short walk or ferry from the center. It packs most of the city's big museums into one leafy park alongside walking paths and water, so it is easy to spend a full day here drifting between the sights Nordiska Museet (Nordic Museum) — a grand, castle-like museum on the museum island of Djurgården telling the story of Swedish everyday life over the last 500 years. I explores everything from fashion, folk traditions, Sámi culture to the ritual of table settings. It sits among Djurgården's other famous museums, so pair it with the extraordinary Vasa Museum (a fully intact 17th-century warship raised from the harbour) or the ABBA Museum next door ABBA Museum — an interactive, unapologetically kitschy tribute to Sweden's most famous export, ABBA. Here you can sing, mix tracks and share a stage with holograms of the band. It is genuinely fun if you have any love for ABBA. Book a timed ticket online to skip the line. It books up far in advance so make sure to look into tickets ahead of time (I wasn't able to make it since I didn't know how popular the ABBA Museum is) Skansen — the world's oldest open-air museum, a hillside of historic wooden buildings brought here from all over Sweden and staffed by people in period dress, plus a small zoo of Nordic animals like bears, wolves and moose. It is a solid half-day and one of the better things to do in the city to learn more about traditional Swedish culture Södermalm — the hip, slightly grungy island just south of Gamla Stan , and more of a fun neighborhood to visit for food & drinks than historical sites. It is full of vintage shops, coffee spots, bars and viewpoints, with far fewer tourists than the old town Fotografiska Museum Stockholm — a first-rate contemporary photography museum in an old brick customs house on the waterfront, with rotating world-class exhibitions. The top-floor café has one of the best views in the city and it stays open late, so it makes a good evening option Mariaberget — a pocket of steep lanes and old wooden houses on the northwest edge of Södermalm , with a clifftop path ( Monteliusvägen ) that looks straight across the water to City Hall and Gamla Stan . Go around sunset for a spectacular view Explore the Stockholm Archipelago — home to over 30,000 islands, skerries and rocks scattered across the Baltic Sea. They are a popular Stockholm summer escape as they are right off the city and easily visited by cheap public ferries. Within a day, you can reach a red-cottage islands like Vaxholm , Grinda or Sandhamn . Visiting the islands is very popular among locals during the summer months from June to August for a swim off the rocks, a forest walk and a seafood lunch Where to Eat & Drink Restaurant Akkurat (Södermalm) — a great restaurant in Södermalm serving great Mussels. They also have a wide collection of beer and whiskey to complement your meal TAK — a slick rooftop bar and restaurant high above Norrmalm , with strong cocktails and a wraparound terrace over the city. Go for sunset, and book ahead if you want a table outside Omnipollos Hatt — the buzzy taproom from cult Swedish brewery Omnipollo, pairing creative craft beers with excellent sourdough pizza. It is small and popular amoung locals Djurgårdsbron floating bar — a tiny bar in a little wooden room literally floating on the water by the Djurgården bridge, with ducks and swans paddling past the deck and boats bobbing alongside. A fun spot to stop by on your way to or from the Djurgården museums Where to Stay Base yourself anywhere in downtown ( Östermalm , Norrmalm , Gamla Stan , and Södermalm ). Stockholm is extremely walkable so just base yourself for wherever your budget allows City Backpackers Hostel — a clean, social and well-run hostel a short walk from the central station , complete with a sauna, free pasta and a good mix of travelers. I really enjoyed staying here ÖSTERMALM 1 Östermalms Saluhall NORRMALM 12 TAK 16 City Backpackers GAMLA STAN 2 Stortorget 3 Royal Palace 4 Mårten Trotzigs gränd 5 City Hall DJURGÅRDEN 6 Nordiska Museet 7 Vasa Museum 8 ABBA Museum 9 Skansen 15 Djurgårdsbron Bar SÖDERMALM 10 Fotografiska 11 Mariaberget 13 Akkurat 14 Omnipollos Hatt DAY TRIPS ↗ Stockholm Archipelago (Full Day) SWEDEN Stockholm Touch to explore Double-tap to open in Google Maps Malmö 1 to 2 days or a day trip from Copenhagen Malmö is Sweden's diverse, design-forward third city, right at the country's southern tip. It's actually closer to Copenhagen than Stockholm, just ~40 minutes by train over the Øresund Bridge . Therefore, many people fold it into a Denmark visit as a day trip (as I did back in 2021). It is a relaxed mix of medieval old town, modern architecture and multicultural food. The best way to visit is a day trip from Copenhagen or spend 1 to 2 days to fully explore the city . It was an interesting first visit to Sweden for me, but not a must-visit destination by any means What to Do Lilla Torg — the cozy, cobbled little square at the heart of the old town, lined with 16th- and 17th-century half-timbered houses. Malmö is mostly a modern city so this is the perfect place to get a sense of a classical Swedish city There are also many café and restaurant terraces that spill out under the umbrellas in summer. It's the great place to sit with a coffee or a beer and watch the town drift by, and it opens onto the larger Stortorget Square just around the corner Malmö Castle (Malmöhus) — a 16th-century fortress with a moat that is the oldest surviving Renaissance castle in Scandinavia. Once serving as a prison, Malmö Castle now packs the city's art, natural-history and local museums under one ticket. The grounds are the nicest part: the pretty Slottsträdgården gardens and a windmill sit right alongside, good for a wander Form/Design Center — a small, free hub of Scandinavian design and architecture set around a light-filled courtyard building, with rotating exhibitions and a nice café. It is a good, quick dip into the Nordic design world Where to Eat Bullen Två Krögare — a wonderfully old-school restaurant that's been serving proper Swedish home cooking since 1893, the spot for classic Swedish meatballs or fried herring with mash in an unchanged, cozy dining room Konditori Katarina — a lovely traditional bakery-café and a great place to try out Scandinavian pastries. The Swedes actually have a word called fika which means the dedicated break time (similar to a siesta ) specifically to enjoy a coffee and a fresh cinnamon or cardamom bun ATTRACTIONS 1 Lilla Torg 2 Malmö Castle 3 Slottsträdgården 4 Form/Design Center RESTAURANTS & BARS 5 Bullen Två Krögare 6 Konditori Katarina SWEDEN Malmö Touch to explore Double-tap to open in Google Maps Other Places to Consider Sweden is a huge country ( by European standards ) that stretches deep into the Arctic. There is plenty more to explore beyond Stockholm and Malmö : Gothenburg — Sweden's laid-back second city on the west coast, about three hours from Stockholm by fast train. It is mainly university town known for its Dutch-style canals, a serious café culture (Swedes take fika seriously here), a lively food scene built on fresh seafood from the fish market, and the big Liseberg amusement park Swedish Lapland ( Abisko & Kiruna ) — the Arctic far north, that can be reached by an overnight train or a flight from Stockholm. This is northern-lights country in winter. Abisko National Park famous for some of the clearest aurora skies anywhere in the world, plus the original ICEHOTEL (rebuilt from the frozen river each year) at Jukkasjärvi and dog-sledding through the snow. You can visit during the summer as well with the midnight sun and hiking the Kungsleden trail Gotland — a large Baltic island a ferry ride off the east coast, and a beloved Swedish summer escape. Its walled medieval town of Visby is a UNESCO-listed gem of cobbled lanes, church ruins and a famous rose-draped ring wall. It is packed in high summer, especially during the medieval-week festival. Beyond it are pale limestone sea stacks, quiet beaches, farm cafés and long light evenings"},{"url":"switzerland/field-notes.html","title":"Switzerland Travel Guide","text":"Switzerland Travel Guide General Switzerland is one of the most beautiful countries in the world that I've ever visited. It truly is the ultimate Alpine playground. In the summer, Switzerland has some of the best hiking with lush green valleys, turquoise lakes, roaring waterfalls and charming medieval towns accompanied by snow-capped peaks as the backdrop. In the winter, the country transforms into arguably the best place for winter sports in the world. The catch is that it's also one of the most absurdly expensive places you'll ever travel to. If you can afford it, the scenery is worth every Franc. I'll provide tips on my experience in Switzerland during the summer. Most first-time trips center on the Bernese Highlands around Interlaken (the hiking and adventure hub) with the charming cities of Bern and Lucerne an easy train ride away. Suggested Route Overview Getting around Flights — Switzerland is extremely well-connected internationally with the two main hubs being: Zurich Airport (ZRH) and Geneva Airport (GVA) . Basel Mulhouse Freiburg Airport (BSL) is the cheapest way to get into the country since it serves budget airlines and is actually located in both France and Switzerland Trains — Switzerland has arguably the best rail network in the world: spotless, punctual to the minute, and reaching almost everywhere. Many of the scenic routes are attractions in themselves. If you're moving around a lot, look into a Swiss Travel Pass or Half Fare Card , since individual tickets are pricey. A 3 hour ride will cost on average between CHF 80 and CHF 135 ($90–$150 USD) There are also many easy options to come to Switzerland by train. I typically use an aggregator like TrainLine to plan routes and timing and then book through the train operator Cable cars, funiculars & mountain railways — for every famous hiking trail, there are plenty of cable cars for older tourists, disabled people or tired hikers who just want to take the cable car down. They are a convenient way to reach the peaks or car-free villages. However, they are also expensive ranging from CHF 20 to CHF 100+ ($22 to $110+ USD), depending on the popularity or length of the ride Money — Switzerland uses the Swiss Franc (CHF), not the Euro, and is one of the most expensive countries in the world. Even coming from overpriced San Francisco, I felt sticker shock here, especially with the restaurant prices If you're on a budget, I would recommend saving money by doing groceries for most meals and limiting restaurant meals. Even Swiss people dine out infrequently because it is so expensive! Food — the Swiss food is basically German food with more famous chocolates and cheeses. Popular dishes include Fondue, Raclette, Bratwurst and Rösti Look out for the Bauernladen , the honor-system farm fridges on the sides of the road in rural towns. They are completely unlocked and operate on the honor system where you take whatever you want and deposit cash in a basket. The products are often farm fresh and the cheese and sausages are exceptional! Language — Switzerland has four national languages: German (Swiss German) in the center and east (Interlaken, Bern, Lucerne, Zurich), French in the west (Geneva, Lausanne), Italian in the south (Lugano) and Romansh in a few mountain valleys. Everyone in Switzerland is multilingual (including English!) and it is very straightforward to get around Safety — Switzerland is one of the safest countries in the world. The main hazards are nature (weather, altitude and steep trails) rather than crime How long to stay — 5 to 7 days is enough to explore Interlaken for the mountains and then add on a couple days for Bern and Lucerne each. For first-timers, I'd recommend 1 to 2 weeks in Switzerland (or however long your budget can stretch). Add more time if you want to reach Zermatt or beyond Interlaken 3–4 days recommended Interlaken is the adventure capital of Switzerland that sits right between the two bright blue, alpine lakes of Thun and Brienz with the Alps in the backdrop. The town is a great base for hiking, paragliding and exploring the jaw-dropping Lauterbrunnen valley . The scenery around this area is absolutely incredible and I wish I spent more time there. I would recommend basing yourself there for at least 3 to 4 days to explore different hikes and day trips. Its central location makes a great base to take day trips to the Jungfrau Region (one of the most beautiful alpine regions in Switzerland) or Bern (the \"unofficial\" capital of Switzerland). What to Do Harder Kulm hike — meaning \"harder climb\" in German, this hike starts from the town of Interlaken and goes up to the main viewpoint above. It is only 5.1 miles or 8.2km roundtrip ( Alltrails link here ), but it is straight uphill and will take 5 hours to complete. The view at the top is extraordinary and at the summit there's a triangular viewing platform where you get one of the best views of both lakes (Thun and Brienz) and the entire valley below. You can reward yourself with a snack at the summit café The viewpoint is also accessible by funicular up if you'd rather skip the climb Hardergrat hike — one of the most famous and most dangerous hikes in Switzerland. A 15-mile (or 24 km) ridge run from Interlaken to Brienzer Rothorn with jaw-dropping views of the Eiger , Mönch and Jungfrau above Lake Brienz Most of the trail is on a narrow grassy ridge with steep drops on either side and cables are installed along the most exposed sections. The hike is not technical, but recommended for experienced hikers only as there are some dangerous sections. Budget a full 10–12 hours to complete it Extreme Sports — Interlaken (dubbed \"the adventure capital of Europe\") has pretty much every extreme sport you can think of ranging from paragliding over the lakes, skydiving from a helicopter at 13,000ft, canyoning, white water rafting, bungee jumping, canyon swing and jetboating on Lake Brienz. Most activities run April to October and sell out fast during summer Jungfraujoch — a peak known as the \"Top of Europe\" and home to the highest railway station on the continent. Located 1.5 - 2 hours from Interlaken, it can be reached by train. The Jungfraujoch is very touristy so expect the train to be very pricey (~130 CHF) and there to be a line at the top. My friends who went said it was unforgettable on a clear day Bike Around the Lakes — rent a bike in town to embark on a ride around one of Interlaken's two turquoise glacial lakes. E-Bikes are also available for rent in town if you want a little boost. Lake Brienz Bike Loop ( ~35km or about 3–4 hours ) — the path starts right in town at the train station, Interlaken Ost . The turquoise glacial water is stunning, and the path passes through the charming village of Iseltwald and the Giessbach waterfall , which appears out of nowhere along the southern shore Lake Thun Bike Loop ( ~50km or about 4–5 hours ) — a longer ~50km loop that rewards you with deep navy-blue water and panoramic views of the mountain peaks of Eiger , Mönch and Jungfrau A day trip to the Lauterbrunnen Valley — located only 20 minutes from Interlaken, take the train to Lauterbrunnen and walk the main road through the valley. This was one of the spectacular walks that I've been on with 72+ waterfalls cascading down from towering cliffs on both sides with the Alps in the background. Wing-suiters and parachuters constantly drop from the cliffs randomly throughout the day Make sure you stop by the Bauernladen farm fridges along the side of the road for a taste of farm-fresh cheeses, sausages and honey. There are no attendants and they operate completely on an honor system Grindelwald — a scenic village near Interlaken with views of the Eiger . Visit the street festival during the summer (every Wednesday from July to mid-August) Gimmelwald — a tiny car-free village above Lauterbrunnen that can only be reached by cable car. It is considered one of the most peaceful spots in Switzerland. My friend loved staying at the Mountain Hostel Gimmelwald which had stunning views of the mountains from the balcony Where to Eat Spatz — a cafe with a river-view from our table. The brunch was great with prosciutto, four types of cheese, bread and jam Where to Stay Balmer's Hostel — one of my favorite hostels in the world and hands down the best place to stay in Interlaken. Dating back to 1907, Balmer's Hostel was built inside a gorgeous traditional Swiss wooden chalet with a beautiful courtyard, beer garden and mountain views. The staff organizes daily activities (sunset swims, waterfall hikes, ski trips), outdoor games, chill rooms, a cosy bar, and even an underground nightclub. The place has a legendary reputation among backpackers and for good reason ATTRACTIONS 1 Interlaken 2 Jungfraujoch 3 Eiger 4 Lauterbrunnen Valley 5 Grindelwald 6 Gimmelwald RESTAURANTS & BARS 7 Spatz ACCOMMODATION 8 Balmer's Hostel Switzerland Interlaken Touch to explore Double-tap to open in Google Maps Bern 1 day recommended Bern is Switzerland's charming medieval capital, built on a peninsula in a dramatic bend of the Aare River. In summer, locals actually float down the river to commute home from work after a long day. The old town is one of the best-preserved medieval city centers in Europe and filled with whimsical statues from fairytales . The city is compact making it easy to wander around and explore in a day What to Do Kramgasse — the main street of Bern dotted with shops and dozens of small fountains, each topped with a colorful statue of a medieval figure Zytglogge (Astronomical Clock) — a massive medieval clock tower embedded in an arch in the middle of the main street, originally built in the 13th century as a watchtower and city gate. On the hour, spinning statues of a joker with drums, dressed-up bears, a lion and a rooster come to life. The whole performance lasts about a minute. You can also take a guided tour inside the tower to see the original clockwork mechanism Einstein House — the modest apartment on Kramgasse where Albert Einstein lived from 1903 to 1905 while working as a patent clerk at the Bern Patent Office and developing his Special Theory of Relativity. The apartment has been restored to how it looked when he lived there. A quick, but interesting visit Bear Pit (Bärengraben) — Bern is named after bears and has kept them in the city since 1513, making this one of the oldest zoos in the world. Three bears currently live in a large cliff-side enclosure right next to the old town near the Nydegg Bridge . The river bends around the old town here making it one of the best spots to relax by the river If you visit during rush hour, you can watch locals floating down the Aare River to commute home. One of the more uniquely Bernese things you'll ever see Rosengarten — a terraced rose garden on the hill above the old town with a sweeping panoramic view looking down over Bern. An easy 15-minute walk up from the Bear Pit Berner Münster — Switzerland's tallest cathedral, a stunning Gothic sandstone building in the heart of the old town dating back to the 15th century. The entrance portal has an elaborate carving depicting the Last Judgement with over 200 figures. Climb the 344 steps to the top of the spire for one of the best views in the city. Free to enter the cathedral with a small fee to climb the tower ATTRACTIONS 1 Kramgasse 2 Zytglogge (Astronomical Clock) 3 Einstein House 4 Bear Pit (Bärengraben) 5 Rosengarten 6 Berner Münster Switzerland Bern Touch to explore Double-tap to open in Google Maps Lucerne 1–2 days recommended Lucerne is a postcard-perfect lakeside city where a medieval old town meets the water beneath mountain peaks. It's compact, walkable and one of the most photogenic cities in Switzerland. Spend 1–2 days here to explore the town at a relaxed pace What to Do Chapel Bridge (Kapellbrücke) — the oldest wooden bridge in the city, a covered walkway over the Reuss River lined with colorful flowers and connected to an octagonal water tower. The most photographed spot in Lucerne Spreuerbrücke — Lucerne's second covered wooden bridge, far less crowded than Chapel Bridge. The ceiling is lined with a unique medieval painting depicting death arriving for people of every class. Worth crossing slowly while looking up Museggmauer (City Walls) — medieval walls with several accessible towers overlooking the city. Walk the wall and climb the towers along the way. Look out for whimsical medieval paintings along the walls Zytturm — the most distinctive Musegg Wall tower. Houses the oldest clock in central Switzerland (1535) with a face large enough to be read by fishermen on the lake. There is also a large mural of two large red giants holding up the clock and Lucerne's coat of arms Lake Lucerne Boat Tour — a 1 hour sightseeing cruise on a yacht-style boat. The lake was the birthplace of the Swiss Confederation, and the audio guide covers the history of the four founding cantons. A relaxing way to end the day. The tour should run you ~$35 Bourbaki Panorama Museum — a massive circular panorama painting of Swiss troops rescuing frozen French soldiers during the Franco-Prussian War, one of the first Red Cross operations. I'd never seen a Panorama painting before so it really surprised me! It genuinely looks 3D and the iPad audio guide is excellent Lion Monument — a wounded lion carved directly into a cliff face above a reflecting pool in a small forested park, honoring the Swiss Guards who died defending Louis XVI during the French Revolution Swiss Museum of Transport — 30 min walk from old town, this is the country's most visited museum covering every form of transport across 20,000 square meters with loads of interactive simulators, a planetarium, and the Lindt Chocolate Adventure. Budget at least half a day to explore the whole museum Where to Eat Rathaus Brauerei — microbrewery and restaurant right on the Reuss River with outdoor tables looking directly at Chapel Bridge. They brew their own beer on site. Get the veal bratwurst or the Brewer's Platter Restaurant Fritschi — historic Swiss restaurant in a quiet old town square serving traditional food since 1602. The building is covered in a gorgeous painted Carnival mural. Get the cheese fondue or the Rösti with bratwurst Where to Stay Backpackers Lucerne — a laid-back budget hostel a short 15-minute walk from the old town, but located right on the lake. It was not super social when I was there ATTRACTIONS 1 Chapel Bridge (Kapellbrücke) 2 Spreuerbrücke 3 Museggmauer (City Walls) 4 Zytturm 5 Bourbaki Panorama Museum 6 Lion Monument 7 Swiss Museum of Transport RESTAURANTS & BARS 8 Rathaus Brauerei 9 Restaurant Fritschi ACCOMMODATION 10 Backpackers Lucerne Switzerland Lucerne Touch to explore Double-tap to open in Google Maps Other Places to Consider Switzerland is small, but packed with wonderful sites to visit. There's far more beyond the small region that I visited. Here are a few other places recommended by my friends: Zermatt & the Matterhorn — an alpine resort town at the foot of Switzerland's most iconic peak, the Matterhorn. A popular place during the winter for skiers and snowboarders Zurich — Switzerland's largest city, situated on the shores of a picturesque lake, with a lively old town, delicious food and nightlife scene Geneva — the French-speaking, international city in the west, home to the UN and near the terraced Lavaux vineyards Lugano — the Italian-speaking city in southern Switzerland. It is the meeting of cultures with more of a Mediterranean feel on a palm-lined lake"},{"url":"tanzania/field-notes.html","title":"Tanzania Travel Guide","text":"Tanzania Travel Guide General Tanzania is East Africa at its best! Home to the vast plains of the Serengeti and the Ngorongoro Crater in the North for the ultimate safari, the spice island of Zanzibar in the east, famous for its white-sand beaches, and Mt. Kilimanjaro , the highest peak in Africa and one of the most iconic climbs in the world. I would recommend spending 2 to 3 weeks in Tanzania depending on which of these 3 main activities you're looking to do. You can easily combine two of these into a two week trip. For example, I comfortably did a safari and relaxed on the beaches of Zanzibar in two weeks. Suggested Route Overview Getting around Flights For safaris or Mt. Kilimanjaro, you'll want to fly into the Kilimanjaro (JRO) airport located in Northern Tanzania. Zanzibar has its own airport called Abeid Amani Karume International Airport (ZNZ) . Alternatively, you can fly into the largest city, Dar es Salaam and take a ferry to Zanzibar. However, I don't think this is worth the hassle as there are many cheap domestic flights Public Transport Long-distance buses — available for routes across the mainland of Tanzania. They're affordable and reliable. Dar Express is the premier operator and you can book in advance online Dala Dalas — these are the small shared minibuses used by locals on Zanzibar. They are as cheap and chaotic as you'd expect, with no fixed schedule and always crowded. Fun to ride one as an adventure Ridesharing — as of August 2025, Bolt is available in Tanzania. When I visited, I used taxis for long day trips. The drivers were honest and rides were affordable after some light negotiation Money — the Tanzanian Shilling (TZS) is the official currency. US dollars are also widely used for safaris, park fees and hotels. Make sure to carry cash since you'll need it everywhere Food — due to its long history of being on key trade routes along the Indian Ocean, Tanzanian food is heavily influenced by Indian cuisine, which was a pleasant surprise. On Zanzibar, you'll get pilau and biryani rice, fresh chapati, grilled seafood and the island's famous spices. On the mainland, the food is more traditionally African with Ugali (a fluffy white corn meal) and Nyama Choma (grilled meat) Safety — as this was my first time in East Africa, I was a bit concerned about going to Tanzania. Personally, I had a very good experience with no issues and all the Tanzanians I met were extremely friendly. Generally, the country is considered one of the safest in East Africa and a good \"beginner\" country for exploring the region Backpacking Scene — I wasn't expecting many backpackers in Tanzania and there are nowhere near as many as Southeast Asia or Central America. However, the backpackers here had some of the most interesting stories from embarking on 9-month solo journeys through Africa, taking the infamous TAZARA Railway or working at NGOs. You'll definitely meet some memorable people who are a notch more adventurous than the rest of us Language — the native language is Swahili which is spoken all over East Africa. As a former British colony, English is widely spoken and used in tourism. I had no issues getting around at all Safari on the Serengeti 3–4 days recommended A safari in Africa is truly a once-in-a-lifetime experience. Northern Tanzania is home to some of the best safaris in the world with the endless golden plains of the Serengeti and the wildlife-packed Ngorongoro Crater , home to some of the densest concentrations of animals on earth. I would recommend setting aside 3–4 days in Tanzania to go on a safari. Time it for the Great Migration (roughly July–October) if you can, when millions of wildebeest and zebra move across the plains. People often see safaris as a \"rich person's\" activity, but it can be done very affordably as well. Almost all safaris follow the same route, visit the same parks and even combine tours, so the difference in price comes down to lodging: Budget / Camping (~$250 - $500) — if you're fine sleeping in public campsites, this is the way to go. I chose this option with Wise Safari Tanzania and the experience was incredible. I thought it was cool to sleep under the stars with wild animals roaming around at night and have a bush dinner cooked by our guides Mid-Range (~$500 - $800) — this will provide you with the full safari lodge experience. At the higher end, you can get a private 4x4 vehicle and guide Luxury ($850 - $1,500+) — these are the super premium lodges you see on Instagram with pools, exclusive vehicles, and fly-in options Bring plenty of cash since tour companies often make you pay up to 50% of the tour cost in cash. They typically take USD, but I had to withdraw a massive stack of Tanzanian Shillings to cover the difference. Tipping the guide and cook at the end is customary and expected, so budget for it separately from the tour price. The Highlights There are tons of different safaris that you can do. Here are some of the highlights in Tanzania that I visited to give you some inspiration: Spot the Big Five — it goes without saying that the holy grail of a safari experience is to spot the Big Five. This is the lion, leopard, elephant, buffalo and rhino. The rhino and the leopard are definitely hard to spot. There are tons of other cool animals to see including flamingos, warthogs, hippos and hyenas Serengeti National Park — the world's most iconic safari destination with flat golden plains dotted with acacia trees and covered with herds of animals. The Serengeti is home to every safari animal imaginable: lions, cheetahs, leopards, elephants, giraffes, hippos and vast herds of zebra and wildebeest Ngorongoro Crater — going on a safari inside a 20km-wide volcanic crater was unreal! The walls of the caldera act as a natural enclosure for an entire ecosystem, making it one of the highest wildlife densities in Africa. The first view from the Ngorongoro rim on the way in is staggering Maasai Villages — many tours include a stop at a Maasai village, known for the jumping dance ceremony and intricate beaded jewelry. I opted not to do it, but it's a worthwhile cultural experience if it appeals to you The Classic 3-Day Itinerary In 2023, I did the standard northern-circuit safari, which lasted 3 days and 2 nights. It was a loop starting from Arusha , up through the highlands to the Serengeti , and then a day down inside the Ngorongoro Crater on the way back. I did the budget camping version with a knowledgeable guide named Sylus in a shared 8-person Land Cruiser. It was hands-down the highlight of my time in Tanzania. You might be tempted to book a longer safari, but I felt like 3 days was the sweet spot since you already spend a lot of that time driving. Here's how the days actually broke down: Day 1 — Arusha to the Serengeti — an early pickup in Arusha , breakfast, and then the long drive up to the Ngorongoro rim viewpoint . The first look down into the crater is staggering. We passed Maasai villages herding goats along the road the whole way and had a family-style lunch at the Serengeti gate . We were barely inside the park before we found three lions sleeping under a tree. As the sun set over the plains, a ton of animals started to come out including elephants, cheetahs, giraffes, warthogs and huge herds of zebra. The sky started to turn different shades of pink, making for a beautiful sight! We spent the night at a bare-bones bush camp near Seronera in the central Serengeti Day 2 — Serengeti Game Drive & Ngorongoro Crater — the next day was a full day of game drives across the Serengeti. I was lucky enough to go during the Great Migration in October. We saw a pride of lions stalking a herd of well over 1,000 wildebeest and spotted four of the Big Five in a single day We drove back up to the crater rim for the night at Simba Campsite , which sits right on the edge overlooking the crater. Zebras wandered straight through the campsite overnight and I could hear them from inside my tent Day 3 — Ngorongoro Crater & back to Arusha — an early 5:45am start to descend into the Ngorongoro Crater through thick fog. The floor of the crater was packed, with impalas and zebras roaming the plains while flamingos and hippos crowded the lake. The morning ended in a mad rush of 20+ jeeps to see rhinos far off in the distance, rounding out the Big Five. The crater was genuinely my favorite part of the whole safari. There were so many different biomes packed into one caldera and almost no driving between sightings. We went back to Arusha for a final group lunch and the tour even took me back to the airport for my early evening flight Zanzibar 5–6 days recommended Zanzibar is a spice island in the Indian Ocean with an identity all its own, a place that feels completely unlike anywhere else in Africa. The historic Stone Town is a dense labyrinth of narrow alleyways, carved wooden doorways, mosques and spice markets that reflects centuries of Arab, Persian, Indian and Portuguese influence. The island was the center of the East African spice and slave trade for hundreds of years, and that history is visible in every corner of the old city. Beyond Stone Town, the northern and eastern coasts have some of the most stunning beaches in the world, making Zanzibar a popular honeymoon destination. The beaches have powder-white sand, turquoise shallow water that stretches for miles and a warm Indian Ocean that's swimmable year round. I would spend 2 to 3 days in Stone Town to explore the history and then another few days on one of Zanzibar's beaches to relax. What to Do Wander around Stone Town — Stone Town was one of the most unique towns that I've been to with a diverse set of influences over centuries. Admire the historic white buildings with intricate wooden doorways. Fun fact: Stone Town is mostly built out of coral cut from the seabed, which acts as a natural insulator in the tropical heat! Explore on your own or take a guided walking tour for more historical background Old Fort — a large coral stone fortress right in the center of Stone Town that is free to access. There isn't too much to see there besides the craft shops, a cafe and an open-air amphitheater that hosts live music in the evenings House of Wonders — the most striking building on the Stone Town waterfront, a grand white colonial palace with enormous carved doors, cast iron columns and wide verandas overlooking the seafront. It earned its name by being the first building in East Africa to have electricity and an elevator Old Dispensary — one of the most beautiful buildings in Stone Town with an ornate four-story facade covered in intricate carved woodwork, decorative green and white ironwork balconies that define Zanzibari architecture. It still functions as a community center today and is worth stopping to look at even just from the street Darajani Bazaar — visit Stone Town's main market to get a taste of daily life on the island. Stalls here sell everything from fresh fish, spices, tropical fruit, meat and vegetables. This is where locals actually shop, a stark contrast to the tourist-facing parts of Stone Town Locals jumping off the docks at sunset — every evening as the sun goes down, local boys gather at the old dhow harbor and spend the hour taking turns launching themselves off the dock into the water. Go to Forodhani Gardens around sunset to watch East Africa Slave Trade Exhibition — Zanzibar has a dark past as the gateway for the slave trade on the Indian Ocean. The Slave Market Memorial is a sobering reminder of this. Today, an Anglican Cathedral sits on the site of the former slave market. However, the underground holding cells are preserved and it is worth a stop to learn the history of the town Day Trips from Stone Town Spice Farm Tour — Zanzibar was once the world's largest producer of cloves and still earns the nickname \"Spice Island\" for good reason. A half-day tour at a working farm lets you taste and smell vanilla, nutmeg, cardamom, cinnamon and cloves growing straight from the source. You can book a formal tour online , or do what I did and grab a taxi driver to take you directly to Siso Spice Farm Prison Island (Changuu Island) — a 20 minute boat ride from Stone Town to a small coral island originally built as a prison that was never actually used as one. The main draw is a colony of giant Aldabra tortoises that roam freely around the island (some over 100 years old and weighing up to 250kg). The surrounding coral reef is great for snorkeling with clear, shallow water and plenty of fish. An easy half-day trip from Stone Town (book a tour here ) Jozani Forest — Zanzibar's only national park, about 35km south of Stone Town. You can visit the endangered Zanzibar Red Colobus Monkey, a species found nowhere else on earth. The forest itself is beautiful with ancient mahogany trees and a mangrove boardwalk. It is a quick stop and easy to combine with a visit to the east coast beaches Relax on one of Zanzibar's world-famous beaches — there are many to choose from, all with a slightly different vibe. Here is an overview to help you decide: Paje — on the east coast of Zanzibar, lies the village of Paje, the backpacker and kitesurfing hotspot on the island. Paje sits on a wide beach that stretches for miles with white sand and clear blue water. It was gorgeous and has a laid-back village atmosphere with a bunch of sailboats and villagers roaming the beach I ended up staying here and absolutely loved it. My hostel (called Your Zanzibar Place ) was a set of bungalows located right on the beach. It was very social and I met some interesting, adventurous backpackers there. Internet was also intermittent which is a good thing, making it a great place to disconnect for a few days Nungwi — the most popular beach area on the island with blindingly white sand and dramatic water colors. There is a wide range of accommodation and a lively bar and restaurant scene. It faces west for good sunsets Kendwa — located just south of Nungwi with calmer, clearer water and powdery white sand. It is widely considered the most beautiful beach on the island. More expensive and quieter than Nungwi, geared toward couples and honeymooners Where to Eat Forodhani Gardens Night Market — the perfect place to sample local Zanzibari food. Every night around sunset, tons of local vendors set up carts selling street food. Try the local favorite Urojo (a yellow potato soup with egg and crispy fritters), plus fresh grilled seafood and sugarcane juice Visit Mister Mango at his stall to try Zanzibari Pizza , a chapati stuffed with spiced minced meat, egg, cheese and vegetables. He was even featured on an episode of Anthony Bourdain's Parts Unknown Lukmaan Swahili Restaurant — the best spot in Stone Town recommended by locals with Zanzibari curry, pilau, biryani and fresh chapati. Order several dishes and share with a friend. It was also surprisingly affordable for how busy the place gets Where to stay Stone Town House (Stone Town) — a nice hostel walking distance from all the major attractions. The owner was very helpful and offers tours as well Your Zanzibar Place (Paje) — a beach hostel, consisting of a set of small bungalows right on the sand. It was very social with a restaurant and bar embedded in it. They operate on a tab system and the food included was amazing and affordable ATTRACTIONS 1 Stone Town 2 Old Fort 3 House of Wonders 4 Old Dispensary 5 Darajani Bazaar 6 Forodhani Gardens 7 East Africa Slave Trade Exhibition RESTAURANTS & BARS 8 Forodhani Gardens Night Market 9 Lukmaan Swahili Restaurant ACCOMMODATION 10 Stone Town House 11 Your Zanzibar Place DAY TRIPS ↗ Spice Farm Tour (Half Day) ↗ Prison Island (Full Day) ↗ Jozani Forest (Full Day) Tanzania Stone Town, Zanzibar Touch to explore Double-tap to open in Google Maps Other Places to Consider Tanzania has so much more than just the parts I visited. Here are some other spots recommended by fellow travelers: Mount Kilimanjaro — the highest peak on the continent, known as the \"Roof of Africa\". Most people enjoy doing the multi-day treks with the Machame and Marangu routes being the most popular Nyerere National Park — a vast, wild and less-visited reserve in the south for boat safaris and a remoter experience Mafia Island — a quieter alternative to Zanzibar, with superb diving and the chance to swim with whale sharks"},{"url":"turkiye/field-notes.html","title":"Türkiye Travel Guide","text":"Türkiye Travel Guide General Suggested Route Overview Türkiye is a fascinating country at the intersection of Europe and Asia. With its long history as part of the Silk Road and as the capital of the Byzantine and Ottoman Empires, the country has a unique, rich cultural heritage. It is also home to ancient wonders like Cappadocia and pristine beaches on the Turquoise Coast Transport Ridesharing — download Uber or YandexGo before you land. Taxis are known to overcharge tourists, particularly from Istanbul airport Public transport — buses and metros are well organized, clean, and run on time. Easy to navigate Flights — Istanbul is one of the most visited airports in the world. Domestic carriers like Pegasus and AJet offer affordable flights connecting other parts of the country Food — Turkish food is one of my favorites. Dishes worth trying: Doner Kebap — the most famous Turkish dish. Lamb and beef shaved off a rotating spit, served on pita with fresh vegetables and yogurt sauce. Reliable, cheap, and available on almost any corner Çay (Black Tea) — the most popular drink in Turkey. Small black tea in a tulip-shaped glass with a sugar cube. Available everywhere and very cheap Turkish Coffee — traditionally brewed over hot sand. Distinct taste since the grounds are left inside Iskender Kebap — probably my favorite. Doner meat on bread, covered in tomato sauce Manti — dumplings stuffed with meat, served with yogurt sauce Menemen — Turkish scrambled eggs mixed with tomatoes, served with bread Turkish Breakfast — meze-style spread of simit (circular sesame bread), eggs, cheese, olives and tomatoes Cash — credit cards are widely accepted in large cities and major tourist areas, but carry cash for street vendors On my second visit, Turkey was no longer a cheap destination, prices were comparable to Greece The country has experienced significant inflation. The largest bill is 200 Turkish Lira (~$4), so you end up carrying a lot of cash. Plan accordingly at ATMs Istanbul 3–5 days recommended Give it at least 3 days. Istanbul is one of the great cities in the world and home to over 15 million people. There are plenty of sites and day trips to explore Neighborhoods / Where to Stay Istanbul is a massive city (spanning two continents) so plan your visit and daily activities based on the neighborhood you’re staying in. The European and Asian sides each have a completely different vibe. Most tourist sites are on the European side; the Asian side is more representative of how modern Turkish people actually live I recommend staying on the European side (Sultanahmet or Beyoğlu neighborhoods) for 3–5 days and only adding time on the Asian side if you plan to stay longer. Here is a basic overview of the neighborhoods: Sultanahmet (The Old City — European Side) — best neighborhood to stay since it is walkable from most major historical sites. Prices may be higher Cheers Hostel — great location right in the middle of old town with a good balcony view Beyoğlu — the New City on the European side, still very walkable. Worth splitting time between Sultanahmet and Beyoğlu. Sub-neighborhoods include Galata, Karaköy and Taksim The Central House Istanbul Taksim — right by Taksim Square, very modern facilities. Good stay but not particularly social Kadıköy (The Asian Side) — where the majority of people live. A great choice if you have more time and want a slice of modern Turkish life. Much more affordable but further from tourist sites What to Do Sultanahmet Area Hagia Sophia — the most famous building in Istanbul. Originally a Byzantine cathedral, converted to a mosque, then a museum, now a mosque again. The interior dome is very impressive. Gets very busy — go early to avoid crowds and bring something to cover your shoulders/head Blue Mosque (Sultan Ahmed Mosque) — right across from Hagia Sophia. Six minarets and stunning blue Iznik tile interior. Active mosque — closes during prayer times, plan accordingly Basilica Cistern — underground Byzantine cistern beneath the city. You walk along a walkway above the water with columns towering above you and statues scattered throughout Grand Bazaar — one of the oldest and largest covered markets in the world with 4,000+ vendors selling everything from spices to gold to leather. Go to browse, buy souvenirs and absorb the atmosphere. Don’t be afraid to bargain aggressively — prices are heavily inflated for tourists Nuruosmaniye Mosque — stunning baroque Ottoman mosque right next to the Grand Bazaar. Often overlooked, but really beautiful inside Balat — former Jewish neighborhood on the European side with colorful houses on steep cobblestone streets. One of the most photogenic neighborhoods in the city with great cafes and antique shops Fish sandwiches by the Galata Bridge — iconic Istanbul street food. Traditional Turkish boats with golden roofs along the Golden Horn grill fresh mackerel on deck and serve them in bread. Not mind-blowing, but worth trying. Watch for the bones Topkapi Palace — the primary residence of Ottoman sultans for 400 years. An enormous complex with multiple courtyards, treasury, harem and incredible Bosphorus views. At least half a day to fully explore. The treasury with the Spoonmaker’s Diamond and Topkapi Dagger is the standout Way too crowded with tourists (people pushing to get around) when I went; go in the morning before the crowds show up Beyoğlu / Karaköy Area Galata Tower — medieval stone tower in Karaköy. Great views from the top, but the real draw is the neighborhood below with good coffee shops, restaurants and street life Karaköy neighborhood — the trendiest area in Istanbul right now. Great coffee, street food, and a mix of old Ottoman buildings and new design studios. Walk here from the Galata Tower Bosphorus — the strait dividing Europe and Asia is a great place to take a ferry ride during sunset. You can take a boat ride tour or cheap public ferries which run constantly Day Trips Prince Islands — a set of islands close to Istanbul, known for their wooden Ottoman houses. You can ride a bike around or visit the beaches. I didn’t get the chance to visit, but I heard it’s a good day trip. Access via public ferry from the major ports in Istanbul Where to Eat Coffee Restarting and Co. — modern coffee shop in Karaköy. Best coffee I had in Istanbul ATTRACTIONS 1 Beyoğlu 2 Kadıköy (The Asian Side) 3 Hagia Sophia 4 Blue Mosque (Sultan Ahmed Mosque) 5 Basilica Cistern 6 Grand Bazaar 7 Nuruosmaniye Mosque 8 Balat 9 Galata Bridge 10 Topkapi Palace 11 Galata Tower RESTAURANTS & BARS 12 Coffee Restarting and Co. DAY TRIPS ↗ Prince Islands (Full Day) Türkiye Istanbul Touch to explore Double-tap to open in Google Maps Cappadocia Cappadocia is genuinely one of the most magical places in the world with surreal landscapes, fascinating history and the iconic hot air balloon ride. No matter how touristy it is, it is absolutely worth the trip How long to spend 2 full days minimum if you’re short on time 1 day for the early morning hot air balloon ride and exploring historical sites, 1 day for hiking The hot air balloon ride often gets cancelled in bad weather (rain and high winds); plan extra time in the area to make sure you don’t miss it How to get there Stay in the town of Göreme — it’s the main base and has the best access to everything Most people fly to Nevşehir Kapadokya Airport (NAV) or Kayseri Erkilet Airport (ASR) , both 45–60 minutes from Göreme. Multiple flights a day from Istanbul, ~$70–$100 round trip What to Do Sunrise Hot Air Balloon Ride — no trip to Cappadocia is complete without the iconic hot air balloon ride. Balloons launch at sunrise and float over the fairy chimneys and valleys. Over 300 balloons are launched every morning in Cappadocia. Genuinely one of the most spectacular experiences and worth every penny Expect to wake up at 4am–6am (depending on the season) to be driven to the launch spot for sunrise. The ride lasts about 1–2 hours Book in advance — reputable operators fill up weeks out and it is expensive (~$150–200+) Safety — this is one of the safest places to do it since weather is heavily monitored and it is home to some of the most experienced pilots in the world Alternatives — most hotels in Göreme have roofs where you can watch the sea of colorful balloons rise over the city. Many people also enjoy hiking to viewpoints to watch the balloons from a distance Göreme Open Air Museum — a UNESCO site with rock-cut Byzantine churches decorated with stunning frescoes dating back to the 10th century. Early Christians hid in the Cappadocia area to escape persecution and hermit-monks lived in the fairy chimneys. The Dark Church frescoes are the most impressive. Easy walk from Göreme town center Uçhisar or Ortahisar Castle — ancient rock fortresses dating back 3,000–4,000 years. Climb for a panoramic view of the entire region. Both castles have massive underground cities beneath them Uçhisar Castle is the highest point in Cappadocia with spectacular views, worth it especially around sunset Hiking — the best way to explore Cappadocia. The area has unique rock formations including tall fairy chimneys and valleys. No official trail markers but easy to navigate by phone and trails are quiet. I spent a full day hiking all the major valleys from Göreme ( AllTrails route here ). Each valley has its own character: Love Valley — the valley with the famous tall phallic rock formations. The landscape is genuinely alien and the views from the ridge above are incredible White Valley — quieter than Love Valley with beautiful white and cream colored rock formations. Great for hiking and photography Red Valley — named for the reddish volcanic rock. Best at sunset when the colors go vivid orange and red Pigeon Valley — named for the hundreds of little pigeon houses carved into the rock faces. Locals used pigeon droppings as fertilizer for centuries Uçhisar Castle — ancient castle with an underground city beneath. One of the best views in Cappadocia Where to Stay Stay in the town of Göreme — most experiences are walkable and there’s a good variety of shops and restaurants Arinna Cappadocia — one of the best hotels I’ve ever stayed at. The “balloon view” room has a glass door where you can watch the hot air balloons rise over the city right from your bed. Located higher on the hill with a great view overlooking Göreme Terra Cave Hotel — staying in a cave hotel is a unique experience only available in Göreme. Based on the ancient tradition of living in caves in Cappadocia, it was surprisingly luxurious, complete with a roof overlooking the entire city Where to Eat My Mother’s Restaurant — my favorite restaurant in Göreme. Visited multiple times and really enjoyed their Manti (Turkish Dumplings in yogurt sauce) Testi Kebab — Cappadocia is famous throughout Türkiye for this regional specialty. Kebab meat and vegetables slow-cooked in a sealed clay pot. The waiter lights the pot on fire and breaks it at the table. Fun experience worth doing at least once ATTRACTIONS 1 Göreme 2 Göreme Open Air Museum 3 Uçhisar 4 Love Valley 5 White Valley 6 Red Valley 7 Pigeon Valley 8 Uçhisar Castle RESTAURANTS & BARS 9 My Mother’s Restaurant ACCOMMODATION 10 Arinna Cappadocia 11 Terra Cave Hotel Türkiye Cappadocia Touch to explore Double-tap to open in Google Maps Antalya 2 days recommended Antalya lies on the Southern Coast of Turkey and is home to over 1.5 million. As the largest city and aiport in the region, Antalya serves as the gateway to the gorgeous Turkish Riviera (also known as the Turquoise Coast) The city is a vibrant sprawling metropolis and is worth spending a couple days before branching off into the smaller towns along the Turquoise Coast. However, I would make sure to prioritize your time in the smaller coastal towns over Antalya What to Do Kaleiçi Old Town — a vibrant old quarter characterized by classic Ottoman architecture, this is the highlight of Antalya. You can start at Hadrian’s Gate at the entrance and walk through the neighborhood all the way until the ocean. It is a great place to base yourself while staying in Antalya, but it is a relatively small area that can be explored in a half a day Düden Falls — these are the famous waterfalls that are broken into two separate parts over 40 minutes apart. Both parts are very different and are worth visiting in their own right Upper Düden Falls — the upper falls are the source of the falls that eventually flow through the city of Antalya down into the ocean. The area is very green with a few waterfalls, cave tunnels (with bats) and bright turquoise river. The entire place is part of a tourist park and you need to pay admission to get in Lower Düden Falls — in contrast, the lower portion of the falls are located right along the ocean. A massive waterfall that drops directly into the ocean. It is really impressive at scale when you see boats at the bottom dwarfed by the falls. You can visit for free and easy to reach by bus. It is also possible to take a boat tour on a massive boat Sagalassos Ancient City — located a 3 hour drive from Antalya. This is a massive ancient Roman city with a theatre, baths, main square and a recently reconstructed fountain. The architectural site was very impressive and it took us a full half day to explore given the size of the area. There were mainly Turkish tourists when I was there and it wasn't too busy There are many other architectural sites in the area that are a bit closer to Antalya including: Aspendos Theatre (45 min) or Termessos Ruins (50 min) Köprülü Canyon National Park - this is a canyon with turquoise water flowing through, located 1.5 hours from Antalya As a day trip from Antalya, I did a white water rafting tour here. It was only $30 all in including a jeep safari, zipline, canyon overlook and rafting. It wasn't the most fun adventure tour since the rapids are a bit weak (level 2). However, the scenery was beautiful and it would be a great activity for the family. Where to Eat Paşa Bey — this was recommended by locals as the best restaurant in Antalya. The Iskander kebab here (bread cooked in tomato sauce with cream) was one of my favorite meals in Turkey Tarihi Ankara Simit Fırını — this is a local bakery owned by a Kurdish family. It was great for breakfast and I found myself returning there 3 days in a row. It is located slightly outside of the old town and a very affordable option. Try the Çay, Menemen (Turkish scrambled eggs with tomato) or the meat and cheese Böregi Üstat lokantası - a cafeteria style Turkish restaurant, recommended by multiple locals. It was very afforable with large portion sizes and variety of choices Doys Döner Antalya - a great doner spot if you're looking for a quick meal. The spicy option is INSANELY spicy Where to Stay Kiana Kaleiçi - this is a great hotel located right in the heart of downtown. It was affordable, centrally located near restaurant, the facilities were great and the staff was very friendly Gold Coast Hostel - I would NOT recommend staying here. The hostel is very run down and there are a few weird staff members here. The door on my room broke twice and I was locked inside ATTRACTIONS 1 Kaleiçi Old Town 7 Upper Düden Falls 8 Lower Düden Falls RESTAURANTS & BARS 2 Paşa Bey 3 Tarihi Ankara Simit Fırını 4 Üstat lokantası 5 Doys Döner Antalya ACCOMMODATION 6 Kiana Kaleiçi Türkiye Antalya Touch to explore Double-tap to open in Google Maps Far Out Sailing Journey - Olympos to Fethiye One of the highlights of my time in Turkey was embarking on a 4 day, 3 night sail along the Turkish Riviera (or Turquoise Coast). I joined the tour offered by Far Out Turkey (also called Sail Turkey - link to tour here ) and was on the boat called the Mr. Ceyhun. Along the way they made a bunch of stops so you can explore what the coast has to offer: beautiful coastline, ancient castles, small local towns and more They offer a few different versions of the sail: A 4 day tour from (Fethiye to Olympos or in reverse ) A 7 day option They also have two boats running the same itinerary at the same time so you have the option to choose your age group: 18 - 39 or Mix Age There are weekly departures throughout the summer for each tour option. I went in May (a bit early in the season). It was a bit windy and they combined our tour with a 7-day one. I'd recommend going later in the summer for better the weather The group size for my sail was 13 people and the crew. The tour is very popular for Aussies (everyone on my boat was an Aussie except for me) Itinerary - the example itinerary provided on the website is subject to change based on the weather. This was our schedule which hit all the key highlights along the coast: Day 1 - Pickup in Demre, sail to Kekova Sunken City (Lycian ruins just below the water's surface, can't swim — UNESCO protected), Simena Castle (Ottoman era castle overlooking the bay), card games and sunset on deck Day 2 - Morning sail to Kaş (one of the most beautiful towns in the Turkish Riviera), explore town (ancient amphitheater, marina, old town alleys), afternoon hike to Limanağzı pickup point, night out at Queen Terrace Bar in Kaş Day 3 - Long sail through rough weather to Ölüdeniz area, optional paragliding from the mountain above the Blue Lagoon (highly recommend — book separately) , dock near Santa Claus Island (ruins of where St. Nicholas was buried) and sunset hike to the top Day 4 - Morning at Blue Lagoon , short sail into Fethiye port, settle tabs and say goodbye to crew Cost - this sail is a lot more affordable than similar sails in Croatia or Italy. I paid just under $500 USD (check the website for the latest pricing) . However, there were times where I felt like the company cut corners like serving meat once a day or only having one crew member that spoke English Food is included in the cost, but they have a tab system for other drinks and charge a premium for alcohol onboard The Verdict This is by far the best way to explore the Turkish Riviera . Unless you have issues with seasickness, this tour is an affordable option that stops at all the popular spots along the coast. It also left lots of free time to just relax and socializing with the other travellers onboard. Being on the boat for 4 days was the right amount of time for me and I had an absolute blast Fethiye & Ölüdeniz 2-4 days recommended Located just over 20 minutes away from each other, Fethiye & Ölüdeniz are two of the most popular cities along the Turkish Riviera, both with a very different character: Fethiye is the mid-size port city where most of the boat tours end up. Over 170,000 people live here, mostly working around the tourism industry and it is also a popular place for retirement homes in Turkey. It was very safe, clean and almost felt like an American Suburb Ölüdeniz is a much smaller town that is much more touristy consisting of almost all hotels and holiday homes along with a vibrant strip by the water of restaurants and souvenir shops. It is a nice little town, but felt very touristy catering toward European Holiday package makers Transport Flights - Both cities are serviced by Dalaman Airport (DLM) which has frequent connections to major Turkish Cities. Antalya Airport and Bodrum Airport are also roughly 3 hours away. Buses - There is a free tourist shuttle (called the \"Dolmus\") that runs through the area, connecting Fethiye and Ölüdeniz every 10 minutes. It is super convenient and there is a stop along the main road on every block. This shuttle also connects to other smaller towns including the Butterfly Valley, Hisaronu, Ovacik, Kayakoy and others What to do Ölüdeniz The Blue Lagoon — one of the most photographed beaches in the world (and for good reason). This beach is truly spectacular and one of the best that I have ever seen. There is a unique sand bar that is surrounded on one side by the florescent blue water of the Mediterranean Sea and on the other side by a clear lagoon that changes into different shades of blue throughout the day. You can visit by renting a beach chair at one of the many beach clubs or snorkel in the lagoon and see many of schools of the fish there Paragliding in Ölüdeniz — is by far one of the best things I did in Turkey. You launch from a platform at the top of a mountain and glide for about 30 minutes over the insanely bright blue lagoon below. The view was absolutely out of this world and paragliding was surprisingly more peaceful than I expected. Expect to pay about $100 - $150, but it is worth every penny and comes with a lot of photos Hike up to the Viewpoint - often referred to as the Hotel Montana Viewpoint since the trail starts at the Hotel (starting point here ). You can hike about 40 minutes away from the city to have a magnificent view overlooking the Blue Lagoon Fethiye Fethiye Old Town — there is a small old-town filled with restaurants, bars and shops. It is a fun area to wander during the day and gets lively with nightlife on the weekend Ancient City of Telmessos — there is a hand-carved temple and rock tombs embedded in the hillside above Fethiye. The area was home to the ancient Lycian civilization (similar to Ancient Greece) so you'll see remnants of the civilization all along the coast. There is not much signage so it is a quick 15 minute visit, but still worthwhile Walk along the promenade and watch the sunset — The city has a modern promenade along the water that stretches over 3+ miles. It is a great place to grab dinner or walk and watch the sunset. There are also bikes and electric scooters to rent The Lycian Way This is an ancient trail associated with the Lycian Civilization, an ancient Mediterranean civilization dating back over 2,000 years. The full trail stretches over 520 to 540 km (320 to 335 miles) and takes over 25 to 35 days to complete . The official beginning is Hisarönü, a resort village near Ölüdeniz. Luckily, it is easy to just do pieces of the longer hike. I decided to hike over 3 days from: Fethiye to Kayaköy (8.5 miles) Kayaköy to Oludeniz (~6 miles) Between Fethiye and Ölüdeniz make sure you stop at Karakoy, an abandoned an Greek Christian village emptied during the 1923 population exchange. The city is now a huge ghost town that spanned for miles and felt haunting with the fog and not too many other tourists around Oludeniz to Butterfly Valley (7.9 miles) The trail was very easily navigable on AllTrails with signs and trail markers spaced throughout. There weren't many other people on the trail. It consists of a mix of paved stone paths, walking on the side of the road and hiking paths through the forest. The terrain was very managable, just follow basic hiking common sense like bringing hiking boots, lots of water and snacks There is a variety of accommodation that you can choose from. I chose to stay in hotels in the major towns, but there are a lot campsites available along the way Where to Eat Ölüdeniz Gözlemeci Sema & Ev yemekleri — small shop run by an old Turkish grandma who specializes in beans. I ordered a mixed plate with a creamy white soup, a bean salad, chickpeas and fried eggplant which was delicious Fethiye Yeşil Asma Yaprağı Ev Yemekleri & Meze — homestyle cafeteria food, had lamb/pea/potato soup, tomato/potato/kefta dish and rice, recommended by locals Doc Coffee Company — trendy coffee shop with a great iced coffee. I ended up going twice Lokum Kokoreç — a no-frills shop that specializes in specialty Turkish street food. Try the Midye - Mussels stuff with rice or the Kokoreç (lamb intestine sandwich) if you’re feeling brave Where to Stay If I were to do it again, I would base myself in Ölüdeniz and do a quick day trip to Fethiye since it is only 20 minutes away Fethiye is skippable in my opinion. It is more of a modern city and there are less touristy things to do there. However, it is the location where most of the sails end so worth a day if you end up there Fethiye Fethiye is a large city so make sure you stay by Old Town or the Port . Many of the hotels are not in this area so research carefully. Most of the city is residential so the restaurant and bars close very early. I made the mistake of staying far away from old town and taxis were extremely expensive El Camino Pub&Hostel - I didn't stay here, but my friends really liked this place. The location is right by the port and only a 5 minute walk away from old town. The restaurant / bar was also a great place to watch the sunset. This hostel books out quickly so reserve in advance! ATTRACTIONS 1 Fethiye Old Town 2 Ancient City of Telmessos 3 Walk along the promenade and watch the sunset RESTAURANTS & BARS 4 Yeşil Asma Yaprağı Ev Yemekleri & Meze 5 Doc Coffee Company 6 Lokum Kokoreç ACCOMMODATION 7 El Camino Pub & Hostel MULTI-DAY TRIP ↗ The Lycian Way Türkiye Fethiye Touch to explore Double-tap to open in Google Maps Other Places to Consider I will definitely be back for another trip to Turkey. There are so many layers to the country and I felt like I was just scratching the surface. Here were some places recommended by other travelers: Western Turkey Izmir - one of the largest cities in Turkey located along the western coast Pamukkale - one of the most popular attractions in Turkey with the hot springs and white pools Ephesus - a famous ancient Greek city near Izmir Safranbolu - a silk road city with traditional Ottoman style architecture Southeastern Turkey Mt. Nemrut - a field of mysterious ancient statues and heads Mardin & Midyat - beautiful cities located near the Syrian border Diyarbakır - the cultural capital of Turkish Kurdistan Northeastern Turkey Trabzon - area with forest and lakes (looks more like Germany) on the border with Georgia Eastern Turkey Doğubeyazıt - a beautiful mosque with the snow capped mountains in the backdrop Mt. Ararat - a mountain in Eastern Turkey that is supposedly the location of Noah's Ark and the national symbol of Armenia"},{"url":"el-salvador/el-salvador-itinerary.html","title":"El Salvador Travel Guide with Perfect 10 Day Itinerary","text":"El Salvador Itinerary El Salvador Travel Guide with Perfect 10 Day Itinerary Everything you need to plan a backpacking trip through El Salvador, from volcanoes and colonial towns to surf beaches and hot springs Mar 28, 2026 Now is the best time to visit El Salvador! A small country nestled in the highlands of Central America, El Salvador offers stunning waterfalls, volcano hikes, historic colonial towns, great beaches for surfing and (of course) mouth-watering pupusas. It takes less than 5 hours to drive across the country, making everything close and easily accessible. Despite being such a small country, El Salvador packs something for every tourist: outdoor adventure in Santa Ana , rich history in Ruta de las Flores and surfing & nightlife in El Tunco . In 2022, the President of El Salvador, Nayib Bukele, began harsh crackdowns on gangs, completely transforming the country from the \"murder capital of the world\" to one of the safest countries in the Western Hemisphere. With the country only recently becoming safe within the last five years, tourism is brand new in El Salvador: it still remains authentic, untouched by mass tourism and extremely affordable even by Central American standards . Tourism is still very much developing, making it a truly unique experience and one of my favorites in Central America. El Salvador is the perfect standalone 1 to 2 week trip, is easily combined with a neighboring country or conveniently fits into a longer Central America backpacking itinerary. This comprehensive travel guide will provide you with everything I wish I knew before going to El Salvador and suggest the ideal 10-day itinerary for exploring the country. If you're looking to do more research, check out the in-depth guides I've written on my El Salvador page covering the best cities and day trips in the country. What to know before visiting El Salvador ☀️ Best Time to Go Dry season ( November to April ) is peak season and most recommended; visit in the off-season for fewer tourists and lusher scenery 📅 How Long? 1 week to cover the highlights and 2 weeks for a slower pace to explore thoroughly 💵 Daily Budget $30 to $50 for budget backpacking and $60 to $90 for mid-range options 🛂 Visa Requirements Visa-free for 90 days for US, EU, UK and Australia. Shares a CA-4 visa agreement with Guatemala, Honduras, and Nicaragua ✈️ Getting There Fly into El Salvador International Airport (SAL) or tourist shuttle from Guatemala, Nicaragua or Honduras 🚌 Getting Around Rent a car for flexibility, use Uber, or hop on the extensive network of chicken buses ($0.50 to $2 for most rides) 💰 Currency Uses the U.S. Dollar (and Bitcoin is widely accepted!). ATMs are widely available and credit cards accepted at major tourist sites 🌐 Language Spanish is the official language and commonly spoken throughout the country. English spoken at tourist locations Why Visit El Salvador? There are many destinations all over the world and even many other options in Central America. So, why go to El Salvador? Although it isn't known for any famous monuments or landmarks, El Salvador packs a surprising amount into such a small country. I came in with relatively low expectations after visiting two of its neighbors (Guatemala and Nicaragua) a few months earlier, but was very pleasantly surprised and El Salvador ended up being one of my favorite experiences in Latin America. Here are some things that really stood out to me: Authenticity - I can't stress enough how recently tourism opened up in El Salvador with most businesses opening up in 2022 or 2023. Salvadorans are just getting used to seeing tourists and foreigners. There are no massive tourist crowds, plenty of undiscovered attractions and genuinely warm, hospitable people Variety & Proximity - For a country of its size, El Salvador is unmatched in variety of activities: black-sand beaches, hot spring waterfalls, Mayan ruins and so much more. The well-connected transit system meant it never took more than 2 hours to get to the next location Affordability - Even compared to its neighbors in Central America, El Salvador is extremely affordable: $0.60 pupusas, $0.75 bus rides, etc… Unlike more popular destinations, there is no tourist tax or fear of getting scammed Safety - In some ways, this is the main reason to come to El Salvador. I felt safer than in any other location in Latin America to explore freely: wandering around random neighborhoods and having conversations with locals. Society has completely changed within the last few years and it was fascinating learning first-hand how locals feel about it Top Things to Do El Salvador punches well above its weight when it comes to things to do. From active volcanoes to jungle waterfalls to world-class surf breaks, there is something for every type of traveler. Here are three of my personal highlights: 7 Waterfalls Tour in Juayúa — forget standing on an observation deck admiring the view from afar. This 3-hour tour through the Salvadoran jungle has you trekking, swinging on vines, wading through streams and climbing waterfalls up close. It was by far my favorite experience in El Salvador. Santa Ana Volcano Hike — an active volcano with a vivid turquoise crater lake at the summit, the Santa Ana Volcano (Ilamatepec) is one of the best volcano hikes in Central America. At only $4 for a guide, it is also one of the best value experiences in the country. Surf, relax and party in El Tunco — black sand beaches, consistent waves, cold beers and some of the most extraordinary sunsets you'll ever see. Whether you're a seasoned surfer or just looking to unwind, El Tunco has something for everyone. For more inspiration, check out my full article on the Top 10 Things to Do in El Salvador , covering the best activities, day trips and hidden gems across the country. The Route: Suggested 10 Day Itinerary Within just 10 days, you can explore the main highlights of El Salvador. Given that you can drive from end-to-end of El Salvador in just 5 hours, transport times will be short, so you can spend more time enjoying the diverse range of activities that the country has to offer. I went for 10 days myself in early 2026 and it felt like the right amount of time without feeling too rushed. You can easily add on more time to this itinerary by spending more time surfing in El Tunco or relaxing on the beach. The itinerary below aims to provide inspiration for your next trip to El Salvador. I've written detailed guides about many of these places which I've also linked below. Suggested Route Overview 1 Land in San Salvador and Explore the Nation's Capital Land at SAL, grab the bus or Uber into the city. Check into your accommodation in the Zona Rosa or San Benito neighbourhood. Both great places for you to get situated in the country as they are safe, walkable and well-stocked with places to eat. Walk down to Plaza Barrios and the neoclassical Catedral Metropolitana. Learn about the country's recent history and enjoy your first pupusas in the country. 2–4 Santa Ana & The Volcano Head west to Santa Ana (about 1.5 hours, ~$1.50 for the bus ride). From here, hike to the summit of Santa Ana Volcano (Ilamatepec), one of the best volcano hikes in Central America. After a tough hike, spend the afternoon relaxing at Lago Coatepeque, a stunning turquoise crater lake nearby. On your second day in Santa Ana, explore Parque Libertad and take Hector's Walking Tour to learn about how life in El Salvador has changed. If you have some extra time, make your way to El Salto de Malacatiupán, the special hotspring waterfalls or the nearby Mayan ruins of Tazumal. 5–6 Ruta de las Flores Next is the scenic mountain route connecting a string of small historic colonial towns: Nahuizalco, Salcoatitán, Juayúa, Apaneca, and Ataco, each with its own character. Spend a day exploring the towns: Juayúa hosts a famous food festival every weekend. Ataco has the most vibrant murals and craft shops. Don't miss my favorite activity in all of El Salvador, the 7 Waterfalls Hike, for a day of adventure and some of the most impressive waterfalls in Central America. 7–8 El Tunco After a few days in the mountains, head south to the coast. El Tunco is the backpacker surf hub: black sand beach, consistent waves and vibrant nightlife. Spend a couple of days here doing the three main activities in El Tunco: surfing, partying and watching extraordinary sunsets. 8–10 Playa Shalpa Following a couple of hectic days in El Tunco, make your way less than an hour up the coast to the off-the-grid paradise of Playa Shalpa. Relax on the beach or decompress by the pool with a cold drink in hand and enjoy the serene, isolated energy of the area. Your time in El Salvador shouldn't be limited by my experience. There's plenty more to discover beyond what I covered. Here are some other activities worth considering. I've included some links to help you research further: Suchitoto — a beautifully preserved colonial town perched above Lago Suchitlán, perfect for a day trip from San Salvador Conchagua Volcano Camping — a volcano in eastern El Salvador offering camping and boat tours where you can watch the sun rise over the Gulf of Fonseca overlooking El Salvador, Nicaragua and Honduras Parque Nacional El Imposible — El Salvador's largest national park, home to dense jungle trails, rare wildlife and dramatic river gorges Cerro Verde National Park — a lush cloud forest near Santa Ana with hiking trails, volcano views and incredible birdwatching Joya de Cerén — often called the Pompeii of the Americas, a UNESCO-listed pre-Columbian village remarkably preserved under volcanic ash When to Visit The best time to visit El Salvador is during the dry season, which runs from November to April . It is peak season since the skies are clear, the temperature is moderate and the surf is great along the Pacific coast. Keep in mind that the weather will vary throughout the country, with the highlands being significantly cooler than the Pacific Coast. El Salvador does not struggle with overtourism so visiting during peak season is not an issue. I would not advise traveling during the rainy season (May–October) since the tropical rain can be intense and unpredictable. However, the silver lining is that it will offer more lush green landscapes, roaring waterfalls and far fewer tourists. ☀️ Dry Season Recommended Nov – Apr Nov 18–30°C 64–86°F Dec 17–29°C 63–84°F Jan 18–31°C 64–88°F Feb 18–32°C 64–90°F Mar 19–33°C 66–91°F Apr 20–34°C 68–93°F 🌧️ Wet Season May – Oct May 20–32°C 68–90°F Jun 20–30°C 68–86°F Jul 20–29°C 68–84°F Aug 20–29°C 68–84°F Sep 19–29°C 66–84°F Oct 19–29°C 66–84°F Getting There If you're coming from abroad, you're more than likely going to be flying to the El Salvador International Airport (SAL) . The airport is conveniently located about 45 minutes south of San Salvador or an hour east of El Tunco. The airport is surprisingly well-connected with direct flights from more than 18 cities in the U.S. and Canada as well as hubs like Houston, Miami, LA, and New York. If you're coming from a neighboring country, El Salvador is well connected by tourist shuttle from Guatemala, Honduras and Nicaragua . There are many companies offering these international shuttles, but I recommend Gekko Explorer which offers routes almost daily with affordable connections to and from Santa Ana, Ruta de las Flores, El Tunco and San Salvador. These buses can be long, so plan for a travel day if you're looking to use this option. Getting Around Once you're in El Salvador, don't be intimidated , getting around is very manageable. First of all, it's a tiny country! You can drive from the western border with Guatemala to the Gulf of Fonseca in the east in just 5 hours. Everything is close, affordable and well-connected. Rent a car or motorcycle — Roads are newer and in good condition, especially compared to elsewhere in Central America. Salvadorans are generally safe drivers; just watch out for those chicken buses! Great option if you want the flexibility to explore at your own pace Chicken Bus — Anyone who has traveled around Central America will be familiar with the infamous Chicken Bus! Dubbed the \"Chicken Bus\" for the occasional live chicken running around, they are a great way to get around and to experience local culture in themselves. At only $0.50–$2 per ride, these retrofitted old American school buses are the locals' choice of transportation since they are cheap, convenient and run everywhere . CentroCoasting is the best resource for schedules Rideshare — Uber and inDrive are widely available throughout El Salvador, especially in larger cities, making them a convenient option if you're short on time or traveling with luggage Private shuttles / driver — For more comfort and flexibility, private shuttles are bookable through most hostels and worth it if you value convenience. Inter-city trips will run $10–$20 per person and a daily driver will cost significantly more Budget Breakdown El Salvador is one of the more affordable destinations in Central America. If you're on a tight budget, Pupusas (the national dish) will be your friend. They generally cost less than $1 and are absolutely worth eating at every opportunity. Keep an eye out for comedores or fondas which are family-run restaurants where you can get a filling meal complete with meat, rice, beans and a tortilla for about $5. Budget travelers can get by on $30 to $60 per day covering a hostel dorm, local food and chicken buses. If you have a bit more to spend, it is extremely easy to travel very comfortably for a fraction of what you'd spend back home. This means staying at hotels and Airbnbs, taking Ubers instead of buses and eating at a mix of local and western restaurants. A mid-range traveler should expect to spend $70 to $120 per day. 🎒 Backpacker ✦ Mid-Range 🏠 Accommodation $10 – $20 Hostel dorm $35 – $55 Private room or hotel 🍽️ Food $8 – $12 Pupusas & street stalls $15 – $25 Sit-down restaurants 🚌 Transport $3 – $5 Chicken buses $10 – $20 Uber & taxis 🎭 Activities $5 – $10 Entry fees $10 – $20 Guided tours ✦ Daily Total $30 – $60 Per day $70 – $120 Per day Safety The number one question about tourism in El Salvador is about safety, so it's important to address it. No doubt, the country has long had a notorious reputation for gangs and being the “murder capital of the world” even as recently as 2021. Due to the recent president’s harsh crackdown on gangs starting in 2022, crime rates have fallen sharply and daily life has completely changed in El Salvador. The country has recently become one of the safest countries in the Western Hemisphere (and even safer than France and Sweden). It was eye-opening to learn about how these changes in safety have impacted regular citizens who have lived in high crime areas for decades as well as the controversy surrounding the President's heavy-handed policies. As a tourist, I felt perfectly safe during my time in El Salvador. I even felt comfortable enough to walk around at night, a feeling that I didn't always have in neighboring countries like Guatemala or Nicaragua. That said, it's still worth following basic traveler safety guidelines: avoid showing flashy jewelry or gear, stick to well-lit routes after dark and exercise common sense. Visa Requirements Citizens of the U.S., Canada, the European Union, U.K., and Australia can visit El Salvador visa-free for up to 90 days . El Salvador is part of the Central America (CA-4) agreement with Guatemala, Honduras, and Nicaragua . This means your 90-day allowance applies across all four countries. If you plan to visit multiple CA-4 countries, make sure you don't exceed this allowance or look into applying for a longer-term visa. Currency El Salvador removed its own currency called the Salvadoran Colón in 2001 and now uses the U.S. Dollar (USD) as its official currency . Make sure to always keep cash on hand as it is widely used. I found that credit cards were only accepted in touristy areas or higher-end establishments. As an American, it was the first country I'd been to that uses USD as the official currency. Salvadorans also use a lot of American coins that I barely see in the U.S. anymore. Fun fact: Bitcoin has also been legal tender since 2021. The government set up the Chivo Wallet app and even gave everyone who signed up $30 to boost adoption of their second official currency. In practice, I didn't see Salvadorans actually use Bitcoin. However, it was accepted at a number of businesses in El Tunco and there were also many Bitcoin ATMs around town. Language As with most Latin American countries, Spanish is the official language and is spoken throughout El Salvador . Given that the country has only recently opened up to tourism, fewer people speak English than in other Central American countries, including some tour guides and hostel workers . Don't worry! You won't have any major issues getting around without knowing fluent Spanish. The Salvadorans I met were very kind and patient. It is a great opportunity to practice your Spanish and brush up on your Duolingo - learning a few basic Spanish phrases will go a long way. Last updated: March 2026 · Based on firsthand experience"},{"url":"el-salvador/top-10-el-salvador.html","title":"Top 10 Things to Do in El Salvador","text":"El Salvador Top 10 Top 10 Things to Do in El Salvador Volcano hikes, surf breaks, hidden waterfalls, and the most extraordinary sunsets in Central America Apr 16, 2026 El Salvador is, without any doubt, one of the most underrated destinations in Central America. Once considered one of the most dangerous countries in the world, it has undergone a remarkable transformation, and tourism is only just beginning to catch up. El Salvador is more than just a safety success story. It packs a remarkable variety of experiences into an incredibly small country. You can drive from end to end in just five hours, yet within that distance you'll find active volcanoes, hidden hot spring waterfalls, colonial highland towns, black-sand surf breaks, and some of the most extraordinary sunsets in Central America. Here are the ten experiences you won't want to miss! 1. Take on the 7 Waterfalls Hike This is, without question, my favorite experience in all of El Salvador , and one of the best adventure days I've had anywhere on my travels. The 7 Waterfalls Hike is located just 20 minutes outside the town of Juayúa on the Ruta de las Flores and leads you through dense jungle to a series of seven stunning cascades, each one different in height, force, and character. The hike itself takes around 3 to 4 hours return and involves river crossings, scrambling and scaling waterfalls, which is all part of the fun. Toward the end of the hike, Los Chorros de la Calera offer pools deep enough to swim in and rocks above to dive from for braver souls. A local tour costs around $15 per person and is well worth it for navigation and safety. Most hostels in Juayúa or Ataco can arrange a guide for you. I wrote more about this adrenaline-filled excursion in my full guide to the 7 Waterfalls Hike. 2. Surf in El Tunco El Tunco is El Salvador's backpacker surf hub and a small, lively beach town built around a consistent right-hand beach break on a dramatic stretch of black volcanic sand. The waves here are some of the most reliable in Central America , making it equally appealing for complete beginners taking their first lesson and experienced surfers looking for a fast, punchy wave. The town itself is small enough to walk everywhere in ten minutes, with a string of surf schools, board rentals, beach bars, and hostels strung along the main drag. Lessons run around $30 to 40 for two hours including a board and instructor. If you already surf, board rentals start at $10 per day. Read my full guide to El Tunco here. Tip: The dry season (November to April) brings offshore winds and cleaner conditions. Wet season waves can be bigger, more powerful and better suited to experienced surfers. 3. Hike the Santa Ana Volcano The Santa Ana Volcano — known locally as Ilamatepec — is the highest active volcano in El Salvador and one of the most rewarding hikes in Central America. The highlight is the crater lake : a vivid turquoise pool sitting in the caldera, its otherworldly color caused by high concentrations of sulfur and volcanic minerals. Steaming fumaroles ring the crater rim and the views across western El Salvador stretch all the way to Guatemala on a clear day. The hike is around 4.4 miles (7.1 km) return and takes approximately 4 hours . El Salvador requires hikers to be accompanied by a government-approved guide ($4 per person), and guides only depart at set times; plan ahead. Most hostels in Santa Ana can arrange a tour that also includes a stop at Lago de Coatepeque , the deep blue crater lake 45 minutes away. Read more about this hike in my full guide to Santa Ana here. Start early! Guides typically depart around 8am. Bring layers; the summit can be surprisingly windy. 4. Learn About El Salvador's Recent History with Hector's Walking Tour Of all the things I did in El Salvador, Hector's Walking Tour in Santa Ana was one of the most unexpectedly eye-opening. Hector is a local guide who has lived through every chapter of El Salvador's recent transformation, from the height of gang violence to the extraordinary change that followed President Bukele's crackdown starting in 2022. He tells it with remarkable candor, balance, and warmth. Each tour is different depending on the tour group and their specific interests. On my tour, we started in Santa Ana's historic center, made our way to a local coffee shop to sample El Salvador's world class coffee and then made our way to the market to try out local delicacies. Hector layers in the social and political history and you leave with a much richer understanding of why this country is the way it is, and why so many Salvadorans speak about the changes with such complicated, genuine emotion. The tour runs for around 2–3 hours and tip-based, so you pay what you feel it is worth! More details in my Santa Ana guide. Tip: Book in advance through GuruWalk or via WhatsApp. 5. Visit the Natural Phenomenon El Salto de Malacatiupán El Salto de Malacatiupán is one of the most unusual natural attractions in Central America, a series of hot spring waterfalls that cascade directly into a river, where you can bathe in pools that reach up to 100°F (37°C) . These waterfalls remain largely undiscovered by tourists , feeling less like a tourist attraction and more like a genuine natural wonder that most visitors completely miss. Located about an hour outside of Santa Ana, the site is best reached by car, Uber, or taxi. Entry is only $1.50 per person. Bring a swimsuit and plan to spend at least two hours here. The combination of swimming, warm water and jungle surroundings makes it easy to lose track of time. More details in my Santa Ana guide. 6. Get Off the Grid in Playa Shalpa Located less than an hour up the coast from El Tunco, Playa Shalpa lies on an off-the-beaten-path stretch of Pacific coastline. It has none of El Tunco's crowds or noise , a long black-sand beach tucked in a private cove, calm energy, and a small handful of guesthouses tucked into the palms. It's the kind of place where the most pressing decision of the day is whether to sit by the pool or walk down to the water. Playa Shalpa is perfect for the final days of a trip: somewhere to decompress before flying home, or to simply slow down after a packed itinerary. Given how small El Salvador is, it's easy to combine with El Tunco or to use as a base for a day trip back along the coast. There are no ATMs and limited phone signal, so bring cash and embrace the disconnection. If you want to learn more, please read the section I wrote on Playa Shalpa in my article on El Salvador's Coast . 7. Take a Pupusa Making Class You haven't been to El Salvador unless you've had a pupusa. There I said it! The pupusa is El Salvador's national dish and cultural symbol. They are thick handmade corn tortillas stuffed with a variety of fillings including cheese, beans, chicharrón, or loroco (a local flower bud). Cooked on a flat griddle, pupusas are served with curtido, a crunchy cabbage slaw fermented in pineapple juice, and tomato salsa. Once you eat your first one, you will understand why Salvadorans are so proud of them. I would highly recommend joining a Pupusa Making class while in El Salvador. When I did the class at my hostel, Casa Coco, it was so good that I did it twice! Led by the lovely owner of the hostel named Yolanda, we made pupusas completely from scratch with a wide variety of fillings to choose from. The class is offered almost every evening ( link to sign up here ) and costs $15, complete with music, dancing and a free beer. Don't worry if you're not the best cook; pupusas are hard to mess up! It is one of the most genuinely enjoyable and culturally immersive things you can do in the country. More details are in my full Santa Ana guide here. 8. Ride a Motorcycle Between the Towns of Ruta de las Flores The Ruta de las Flores is considered the cultural capital of El Salvador. This winding mountain road in El Salvador's western highlands connects five small colonial towns: Nahuizalco, Salcoatitán, Juayúa, Apaneca and Concepción de Ataco. The area around the towns is full of coffee farms, waterfalls and wildflower-covered hillsides. The towns are only 10–15 minutes apart, and the road between them is one of the most scenic in the country. Riding it by motorcycle is simply the best way to experience la Ruta de las Flores. Several operators in Juayúa and Ataco rent motorbikes for the day for as little as $15 or you can join an organized motorcycle group tour. No prior experience is required for the smaller motorcycles on this route as the roads are very good and there is little traffic. If you're not confident on a motorbike, taking a chicken bus between towns is a solid alternative. Read my full guide to Ruta de las Flores here. Tip: Start in Nahuizalco in the south and work your way north to Ataco. You'll finish in the most scenic and lively town, which makes for a perfect ending to the day. 9. Watch a Miraculous Sunset in El Tunco The sunsets on Central America's Pacific coast are extraordinary and El Salvador is no exception. The combination of the black volcanic sand, the open Pacific horizon and a deep orange glow is magical. During my time on the coast, I never missed an opportunity to watch the sunset. Fun fact: the town of El Tunco is actually named after the giant black rock located right off the main beach. \"El Tunco\" is local Salvadoran slang for the pig and the rock is supposed to resemble a pig lying down in the ocean. The beach fills up naturally around 5PM as surfers paddle in and travelers wander down from their guesthouses. The best viewing spots are from the beach itself or from one of the raised terrace bars that overlook the shore: grab a cold Pilsener or a fresh coconut and settle in. More in my El Tunco guide. 10. Visit the Quirky Cafe Albania Perched in the highlands above Apaneca on the Ruta de las Flores, Café Albania is one of El Salvador's more unusual attractions: a working coffee farm that has been transformed into an adventure playground . Made famous on social media by the (in)famous rainbow slide, the cafe itself is beautiful: open-air terraces with sweeping mountain views and local coffee grown on the surrounding hillside. You can choose between a variety of adventure park rides: a gigantic rainbow slide, a tightrope walk in a suspended hamster wheel, a drop swing, a tandem bike along the ridgeline and a huge hedge maze. Entry is free with individual activities costing $1 to $10. It is a great location for families and popular among Salvadorans. More in my Ruta de las Flores guide. There are plenty more activities to explore in El Salvador. Check out my individual articles for the ultimate El Salvador Travel Guide with Perfect 10 Day Itinerary or my various articles on each part of El Salvador here ."},{"url":"el-salvador/santa-ana.html","title":"The Ultimate Guide to Santa Ana, El Salvador's Second City","text":"﻿ El Salvador City Guide The Ultimate Guide to Santa Ana, El Salvador's Second City Volcanoes, crater lakes, Mayan ruins, and the best pupusas you'll ever eat Mar 22, 2026 Getting to Santa Ana I started my journey by flying into the El Salvador International Airport (SAL) , located about 45 minutes outside of San Salvador, the capital city. All international flights into El Salvador arrive at this airport, and it will likely be your starting point regardless of where you're headed in the country. With only 10 days in the country, I decided to skip San Salvador and head directly to Santa Ana, the second largest city in the country. Here's how to make the journey... Rent a car - Salvadorans are generally safe drivers and the roads are good, but watch out for large chicken buses! The journey from the airport to Santa Ana should only take 1.5 hours Bus - You can take a bus with a transfer in San Salvador (detailed guide here ), with the total journey taking about 2 hours Rideshare - Popular ridesharing apps like Uber and inDrive are widely available throughout El Salvador, especially in larger cities, making it a convenient option if you're short on time Tourist shuttle from Guatemala or Honduras - Santa Ana is also connected by tourist shuttles from Guatemala ( Antigua , Lake Atitlán & El Paredon ) and Honduras ( Copan Ruinas ) so it is a popular first stop in El Salvador for many backpackers The Many Day Trips of Santa Ana Santa Ana is a great base for day trips in the surrounding area with options ranging from volcanos, crater lake, hotspring waterfalls and Mayan ruins. Here are the top things to do in Santa Ana: Santa Ana Volcano (Ilamatepec) The main reason most people come to Santa Ana is the famous volcano hike. The Santa Ana Volcano, also known as Ilamatepec in the local Nahuatl language, is an active volcano with a vivid turquoise, emerald green volcanic lake in its crater. This bright, often \"radioactive-looking\" color is caused by high concentrations of sulfur and other volcanic minerals, accompanied by steaming fumaroles. Although Santa Ana is an active volcano, it is generally considered safe to hike since it hasn't erupted since 2005 and authorities are constantly monitoring the volcano. The hike itself is not particularly challenging and takes approximately 2 hours each way (4.4 mi or 7.1 km) . However, for safety reasons, the government of El Salvador requires you to be accompanied by a goverment-sponsored guide while hiking up the volcano. It costs only $4 per person and hiking guides only depart at specific times during the day. I highly recommend doing this hike! It is a truly unique volcano experience that is hard to find elsewhere. Here are a few ways to do it: Book a tour — this is the easiest way to do the Santa Ana Volcano hike and usually comes bundled with a trip to Lago de Coatepeque (more on that later). I booked a tour through my hostel which costs $20 and it was well worth it not having to worry about logistics. I'm sure there were more luxury tour options, but riding in the back of a pickup truck felt like a quintessential El Salvador experience. If you're not based in Santa Ana, there are also some tour options ( link here ) with pickup from San Salvador and El Tunco DIY — less than an hour outside of Santa Ana, you can easily access the Santa Ana volcano by car, public transit, Uber or taxi. Keep in mind that you still need to be accompanied by a government approved guide to hike the volcano. They only leave a specific times during the day so make sure to plan in advance. Here is a link to a detailed guide with more logistical details on doing the hike independently. Lago de Coatepeque Lago de Coatepeque is a deep blue crater lake that lies only 45 minutes from the city center of Santa Ana. Accessible by Uber or local bus (take the #242 / #220 bus from Terminal Francisco Lara Pineda), the lake is a great place to spend an afternoon relaxing or enjoying watersports like jet skiing, kayaking and boat rentals. It is also possible to combine this with the Santa Ana volcano hike, as this was also included as a stop on my tour. Captain Morgan Hostel , situated on the shores of Lake Coatepeque, is a popular place for local and foreign tourists to spend time. Offering a day pass, boat rentals and a restaurant & bar, it is a fun, relaxing place to swim around and spend an afternoon. It even has a deck to jump off of! If you're looking to spend a night, the hostel is also a popular spot for backpackers looking to extend their stay. El Salto de Malacatiupán Hotsprings + waterfalls - ¿por que no los dos? With a water temperature of 100°F (or 37°C), El Salto de Malacatiupán is a stunning waterfall with a river flowing through it that feels like a natural jacuzzi. There are no official tours leading to the waterfalls and not many tourists know about them, making them an undiscovered gem in the region. The hotspring waterfalls are a unique phenomenon that I only experienced in El Salvador and are highly worth the trip. Located near the border with Guatemala, the waterfalls lie about an hour outside of Santa Ana or the town of Juayua and are easily accessible by local bus, car, Uber or moped. The trip can be done in a half day including transport. The waterfalls are at the end of a dirt road with a small restaurant at the entrance. The entrance fee was only $1.50 and collected by a local security guard. The water is true jacuzzi temperature! There were not many other people when I was there, just some locals washing clothes down the river. The waterfalls were also surrounded by a lush green forest which made it very serene and relaxing. Parque Arqueológico Tazumal Located in the neighboring town only 30 minutes outside of Santa Ana, El Parque Arqueológico Tazumal hosts the ancient Mayan city of Chalchuapa. First inhabited by the Maya in 250 A.D., it was later occupied by the Toltec civilization until 1,200 A.D. Today, it stands as the largest set of Mayan ruins in El Salvador . The complex is relatively large with a massive pyramid in the center (and you might even spot some iguanas running around!) You can easily access this Mayan archaeological site by taking the 202 bus out of Santa Ana or an Uber for around $7. The entrance fee was $5 for international visitors. There are tours offered in both Spanish and English for those who want more historical context and there is a small museum with some historical artifacts. The site is easily visited in an hour or so. Casa Blanca , another ancient Mayan site, lies within a short walk from Tazumal in the same town. Santa Ana — The City Itself Santa Ana is the second largest city in El Salvador with a rich cultural history shaping the northern part of the country. The city itself isn't very touristy and all the key sites can easily be explored in 1 day. Here are the top things to do in the city: Parque Libertad The central square of Santa Ana, dates back to the colonial period and has served as a marketplace, a venue for political events, and a gathering place for locals throughout its history. Today, it is home to many of the historic and regional government buildings. Most of the main tourist sights in the city are conveniently centered around here. Catedral de Nuestra Señora Santa Ana (Santa Ana Cathedral) — a beautiful white neo-gothic cathedral originally built in 1575. Its intricate facade makes it the most impressive piece of architecture I saw in El Salvador. It remains the centerpiece for the city and an important public space for locals who often take photos in front of it to commemorate important life events like weddings and graduations National Theater of Santa Ana — a historic theater built in 1910 sits only a few hundred meters from the main cathedral. The theater has been very well restored and maintained. To this day, it is used to host national cultural events and open for tours for $5 per person. Alcaldía Municipal de Santa Ana and Monumento a la Libertad — don't miss the Municipal Palace and Monumento a la Libertad that also face onto Parque Libertad. The Municipal Palace currently serves as the local government building and El Monumento a la Libertad is a marble statue in front which is an enduring symbol of the city's spirit and independence Hector's Walking Tour One of my favorite things to do in El Salvador was Hector's Walking Tour . Given all El Salvador's tough history and its rapid transformation into one of the safest countries in the Western hemisphere, I was very interested in learning first-hand from a local about the nation's history and how the country had changed with the heavy-handed crackdown on gangs by Nayib Bukele. Hector was the perfect guide for that. He led an open-ended tour where he lets the group choose what they want to talk about or do. Every day is different, depending on what the group wants to do. We started at a popular coffee shop called Beats Coffee Centro Historico where we got to have El Salvador's best coffee. He candidly answered every question that our group had about El Salvador. It really opened my eyes to how rough El Salvador's past was with the Civil War in the 1980s and then with gang violence until recently. He described to us how El Salvadorans have adapted to the newfound feeling of safety and the cautiousness he has toward the future. Feeling a bit hungry around lunchtime, he led us to the local open-air market. We tried a number of different local fruits, dishes and desserts, many of which you won't find in a travel guide. The tour is completely tip-based so you can contribute what you like. Pupusa Making Class at Casa Coco If you're not familiar, Pupusas are the national dish of El Salvador which are thick corn tortillas stuffed with any combination of fillings. The most popular varieties are Revueltas (mixed), which combines refried beans, chicharrón and cheese as well as Loroco , a local edible flower bud mixed with cheese. I signed up for the Pupusa Making class at my hostel, Casa Coco, and it was so good that I did it twice! Led by the lovely owner of the hostel named Yolanda, we made Pupusas completely from scratch with a wide variety of fillings to choose from. The class is offered most days of the week ( link to sign up here ), lasts a few hours in the evening and costs $15. It was a really fun time, complete with music and dancing. As a group of 8, we ended up making over 75 pupusas. Yolanda took another traveler and me to give out our extra pupusas to the homeless. Museo Regional de Occidente (Western Regional Museum) Museo Regional de Occidente is located at the site of the former mint for the Salvadoran Colón before they adopted the U.S. Dollar as their main currency in 2001. It has now been transformed into the main historical museum in Santa Ana . I can't personally recommend the museum for everyone. There were a few ancient artifacts and it explained the history of the Santa Ana region. However, the museum seemed a bit underfunded and the exhibits were all in Spanish (weird in a Spanish speaking country, huh ? ) . If you have an hour to spare, it's worth the $3 entrance fee. Old Art School Once the vibrant center of creativity for Santa Ana dating back to 1855, the Mariano Mendez Art School has since been abandoned. Popular with photographers, the art school stands as a reminder of Santa Ana's rich cultural heritage. It is a 20-minute walk from the city center. Learn from my mistake — I showed up without a permit, so I couldn't explore the site itself. A permit is required and must be arranged in advance through the local tourist office in Alcaldía Municipal de Santa Ana (located in Parque Libertad). Where to Eat! Breakfast, lunch and dinner — El Salvadorans love their pupusas! You can find them on almost every street corner and I was never disappointed. However, there are many other dishes to try. Here were some of my favorite places to eat in Santa Ana: Pupusería La Ceiba — considered the best pupuseria in Santa Ana! They serve 26 varieties of pupusas so there is no shortage of options to choose from Comedor y Pupuseria Claudia — a local spot offering a variety of dishes and pupusas. Comedors are popular among locals and are known to be filling, affordable meals Azados — a BBQ held every Sunday — it may not look like much on google maps, but this was one of my favorite meals in El Salvador. Every Sunday, a local family hosts an Asado (barbecue in Spanish) and a large plate is only $5 Beats Coffee Centro Historico — the highest rated coffee shop in the area and home to a nationally recognized barista. This is a great place to sample some of El Salvador's best coffee Street Stands around Parque Libertad — If you're feeling a bit adventurous, dine with the locals. There are plenty of different stands to choose from. They are very cheap and there is always at least one open at all hours of the day Places to Stay There are many wonderful places to stay in Santa Ana ranging from hostels to luxury hotels. Bear in mind that tourism is still developing in El Salvador, so don't be surprised if some places don't have hot showers! Casa Coco — I stayed here personally and had a wonderful time. Casa Coco is a small hostel with a strong communal vibe. The owner, Yolanda, was very sweet and welcoming. The hostel offered a lot of tours (Santa Ana Volcano and 7 waterfalls) and activities (pupusa making class) all for a fair price. Rick's Hostel — They have two locations: one in Santa Ana and one in Juayua on Ruta de Las Flores. The hostel offers motorbike rentals for $15 a day. They also have a service where they will transport your bags from one location to another if you want to make the journey between the two cities by motorbike. I ran into the owner (not named Rick!) a couple times on my trip and he was a very friendly guy."},{"url":"el-salvador/ruta-de-las-flores.html","title":"Ruta de las Flores — El Salvador's Historic Route","text":"﻿ El Salvador Route Guide Ruta de las Flores — El Salvador's Historic Route Colonial towns, coffee farms, waterfalls, and artisan markets along El Salvador's most scenic road Mar 25, 2026 Ruta de las Flores Located in the western highlands of El Salvador, Ruta de las Flores is one of the most important cultural sites in El Salvador. Meaning \"Route of the Flowers\" in Spanish, the scenic path connects five small historic colonial towns . The towns are nestled deep in the country's lush green highlands surrounded by coffee plantations, waterfalls and wildlife. Each town has its own charming appeal with cobblestone streets, colorful murals and churches. From November to April, the route is covered with vibrant, blooming wildflowers. This is the perfect stop in El Salvador to get a taste of El Salvadoran culture and a glimpse into its colonial past. I would recommend spending 2 to 3 days here to see the key sites (1 to 2 days for exploring the towns and an extra day for each day trip). However, it is also possible to visit these towns as a day trip from Santa Ana, El Tunco or San Salvador. Don't miss the famous 7 Waterfalls Hike , as this was my absolute favorite experience in El Salvador. Overview of the Towns La Ruta de las Flores is composed of five small towns: from North to South, they are Concepción de Ataco, Apaneca, Salcoatitán, Juayúa and Nahuizalco . The towns are located very close by: only about a 35-minute drive from end to end, with each town about 10 to 15 minutes from one another . I would recommend basing yourself in either Juayúa or Ataco and using them as a base to explore the rest of the route. The towns feature classic Spanish colonial architecture, each with its own distinct character. Each town is centered around a small (often white) cathedral with a town square around it. Note that the towns are all very small and you can easily walk around each in 30 minutes. I spent one full day dedicated to exploring the towns and visited four of the five towns. This felt like the right amount of time to me since the towns were small. Juayúa Founded in 1577 and today home to roughly 70,000 people, Juayúa is the most popular town on La Ruta de las Flores. Most of the hotels and hostels on the historic route are based here. The main things to do here are explore the cathedral and town square and take a day trip to the 7 Waterfalls Tour (more details further down in this guide). Every Saturday and Sunday starting around 11am, the town hosts the Juayúa Food Festival (Feria Gastronómica) , where many local street food vendors set up stands around the town square. This is a great opportunity to try a variety of local El Salvadoran dishes. Ataco Ataco is the most vibrant town on La Ruta de las Flores with colorful murals, street art and a lush green central park. Similar to many of the towns, Ataco is centered around the blue and white Concepción de Ataco church which overlooks Fray Rafael Fernandez Park . Located not far away is the whimsical and memorable Mural Concepción de Ataco . The small colonial town is filled with similarly vibrant artwork celebrating the long history of the region dating back to the 1500s. If you're looking for a souvenir to take home, the center of Ataco is lined with many gift shops selling local handmade crafts. Coffee historically accounted for over 50% of El Salvador's exports , with much of it coming from this particular region of El Salvador. Ataco is the perfect place to sample world-class coffee or take a tour to the plantations where it is grown. I made a stop at Axul Artesanías , a cafe and art shop known for its colorful exterior. They served high-quality local coffee and there was a lovely outdoor patio perfect for relaxing. If you're looking for a coffee plantation tour, El Carmen Estate offers an hour-long coffee plantation tour for $7. One final stop in Ataco is El Mirador de La Cruz . Located a short 10-minute walk from the central park, El Mirador de La Cruz provides a sweeping panoramic view overlooking the town and the surrounding lush green valley covered in trees. There is no entrance fee. It is a bit difficult to find, so it is worth asking some locals for directions in advance. Apaneca My favorite town on La Ruta de las Flores was definitely Apaneca . While Ataco was more colorful and flashy, Apaneca was a lot quieter and had a small-town feel that drew me in. Leading up to the main square were charming walking streets lined with roses and hedges. It led to the Parque Central de Apaneca where there was a local man selling oranges. We strolled around the town for a couple hours and stopped by Plaza Turistica Apanhecatl for lunch at a food stall run by a local abuela. Next to Apaneca is the oddly named Cafe Albania . Known for its instagram (in)famous rainbow slide, hedge maze, pendulum swing and tandem bikes, I've written more about the adrenaline-fueled outdoor park further down in this guide . How to get around Given the short distance between the towns, the towns are very easy to get around. Here are some popular ways to get around: Chicken Bus - anyone who has traveled around Central America will be familiar with the infamous Chicken Bus! Found all around the region, these retrofitted old American school buses are the locals' choice of transportation since they are cheap, convenient and at times uncomfortable. However, they are something that everyone should experience at least once in El Salvador. Bus #249 connects all five towns, comes every 20 minutes in both directions and only costs 50 cents per trip Motorcycle - for more adventurous travelers, I highly recommend renting a motorcycle. Rick's Hostel offers smaller Honda Navi motorcycles for $15 per day. It was a very fun way to get around the five towns with the freedom to stop along the many viewpoints. The roads were in very good condition and there was little traffic to be worried about. Even as an inexperienced motorcyclist, I felt perfectly safe and La Ruta de las Flores would be a good place to learn Ridesharing - Uber and inDrive are both available in El Salvador. Rides should be relatively cheap (approximately $3 - $6) given the short distances between the towns What to Do There Beyond exploring the colonial towns, there are many amazing activities you can do from La Ruta de las Flores. Many people just take a day tour to the area from San Salvador or El Tunco to see the towns. However, in my opinion, these day trips and activities are the real reason to spend more time in the area . 7 Waterfalls Hike In most waterfall tours, you’re standing far away on an observation deck and just admiring the view, but not this one… the 7 Waterfalls (Siete Cascadas) tour in Juayúa is real up-close and personal . It was 3 hours full of adrenaline in the Salvadoran jungles: trekking through the jungle, swinging on vines, wading through streams and climbing waterfalls. It was by far my favorite experience in El Salvador — a day filled with adventure and some of the most beautiful waterfalls I’ve ever seen. Offered from Santa Ana or Juayúa, the 7 Waterfalls Hike is located only 20 minutes outside of the town of Juayúa. I signed up for a tour from Rick’s Hostel in Juayúa that only cost $15. There are also many other providers that offer the same tour. The tour takes about 3 to 4 hours and you’ll be able to see 7 waterfalls and 2 chorros ( jets in Spanish) including the famous Los Chorros de la Calera. I’ve writtten a separate article extensively describing my experience here . Cafe Albania I'm not usually one for cheesy touristy theme parks, but I had a blast at Cafe Albania ! Situated next to Apaneca on a coffee farm, the outdoor adventure park offers over 10 different rides, including the rainbow slide made famous on social media. It also offers a a life-size hedge maze, a sky mirror, suspended tandem bicycling and you can even do a tight-rope walk in a suspended hamster wheel ! Rides range from $1 - $10 and it doesn't get too busy like amusement parks at home. El Salto de Malacatiupán Hotsprings + waterfalls - ¿por que no los dos? With a water temperature of 100°F (or 37°C), El Salto de Malacatiupán is a stunning waterfall with a river flowing through it that feels like a natural jacuzzi. There are no official tours leading to the waterfalls and not many tourists know about them, making them an undiscovered gem in the region. The hotspring waterfalls are a unique phenomenon that I only experienced in El Salvador and are highly worth the trip. Located near the border with Guatemala, the waterfalls lie about an hour outside Juayúa or Santa Ana and are easily accessible by local bus, car, Uber or moped. The trip can be done in a half day including transport. The waterfalls are at the end of a dirt road with a small restaurant at the entrance. The entrance fee was only $1.50 and collected by a local security guard. The water is true jacuzzi temperature! There were not many other people when I was there, just some locals washing clothes down the river. The waterfalls were also surrounded by a lush green forest which made it very serene and relaxing. Santa Teresa Hotsprings Party Going to leave photos out for this one... I signed up for the Hot Springs Party at my hostel not knowing what we were in for (or where we were going)! It started at Rick's Hostel and apparently happens once a week on Thursday evening. We loaded into a van and drove roughly 40 minutes to Santa Teresa Hot Springs . Entrance was about $10. The party was located at one main hotspring with a huge stage in front. We were the only group of gringos there and were surrounded by locals the whole time. There was live music ( reggaeton, of course ), a DJ, dancing and eventually some of the locals went up and did karaoke. At first, the locals were all staring at the huge group of gringos in the middle of the pool, but they warmed up to us and we partied with them! The Santa Teresa Hot Springs is a huge complex with a variety of pools at different temperatures and a mud bath. Apparently the place is a relaxing spa during the day... and you can also stay there for about $50 per night if you're looking for some rest and relaxation. Other Activities La Ruta de las Flores has plenty more to offer beyond what I was able to cover. Here are some other fun activities you can do with links below for further research: Nahuizalco Night Market (Mercado Nocturno) - a nightly food market in the town of Nahuizalco. A great alternative to the Juayúa Food Festival if you're not in town during the weekend Coffee Tour in Ataco at El Carmen Estate - if you're interested in trying El Salvador's world-class coffee and exploring a local coffee plantation, this tour is only $7 and lasts just over an hour ATV Tour from Apaneca - for a fun way to explore the area, this ATV tour explores Apaneca and also stops by Laguna Verde, a volcanic crater lake nearby Viewpoints along the route - Take a minute to appreciate the nature surrounding the towns. There are a few vistas along the road such as Mirador Ruta de las Flores that are worth a quick stop if you're passing by Where to Eat There are many great restaurants along La Ruta de las Flores to try local Salvadoran food and have coffee fresh from the local plantations. Juayúa Pupusas y Panes Rellenos Sugey - this is one of the most popular restaurants among locals in Juayúa. Try their Panes Rellenos , a shredded chicken sandwich overflowing with grilled veggies and served with a side of hot sauce. If you're feeling hungry, go for the Pupusa Loca, which is a whopping 3 pound pupusa the size of 3 pupusas combined! Restaurante Don Timmy - if you're looking for a break from El Salvadoran food, Restaurante Don Timmy serves some very solid Mexican food Bloom Coffee and Bourbon Coffee Roasters - amazing coffee shops utilizing fresh, locally-sourced beans. These shops are more western-style where you can get cold brew and lattes. Pro tip: although El Salvador grows some of the world's best coffee, most local spots serve watery instant coffee so go to more western-style shops if you're looking for good coffee. Ataco Axul Artesanías - a charming cafe connected to a souvenir shop that supports local artists. I spent a couple hours here and enjoyed a lovely cold brew on their outdoor patio and garden area. It is hard to miss with the vibrant cat mural on the outside. There is a second location in Apaneca as well Apaneca Plaza Turistica Apanhecatl - right off the main square, there is a small plaza with many small comedors, usually run by an abuela and her family. Each one offered a variety of plates to choose from. I decided to stop at Las Ninfas which served a delicious chicken soup with tortillas Yulu Ne Gascu - a local mom-and-pop shop selling pastries and frozen-chocolate covered bananas (a popular snack in El Salvador) Getting There La Ruta de las Flores is centrally located from the most popular tourist destinations in El Salvador : 1 hour from Santa Ana, 1.5 hours from San Salvador and 2 hours away from El Tunco. Easy ways to get around are: Rent a car - Distances are small in El Salvador so a car will provide you with the flexibility to explore quickly Bus - the bus system in El Salvador is extremely well-connected with connections to Santa Ana (#238), San Salvador (#205, then #249) and El Tunco (#287, then #249). The website CentroCoasting was the best resource for bus schedules in El Salvador Ridesharing - Uber and inDrive are also available, but it may take a while to get a ride for long distances Scooter / Motorcycle - this is a popular way to get between Santa Ana and Juayua. Rick's Hostel will help you out with luggage transport if you're planning to make this journey Tourist shuttle from Antigua, Guatemala - If you're coming from Guatemala, there is a direct tourist shuttle from Antigua to Juayúa with the journey taking 5 hours Want to visit, but short on time? Ruta de las Flores can also be visited as a day tour from San Salvador . Try to include an additional tour that visits the 7 Waterfalls (Siete Cascadas) as they were a highlight for me. Places to Stay There are a variety of accomodation options in La Ruta de las Flores, but here are two hostels that I would recommend in Juayúa. Rick's Hostel - With a big courtyard and lots of activities, I enjoyed my time at Rick's Hostel. The staff was very helpful in organizing motorcycle rentals and they plan a lot of activities everyday of the week (Waterfall Tour and Hot Springs Party). I will be honest that this hostel was on the older side and very bare-bones (old bunks and cold showers), but I met some great people here and had a good time. Hostel Samay - This is a newer hostel in town, owned by a very friendly guy named Oscar. He was dedicated to making sure we all had a good time in El Salvador, even if we weren't his guests. The rooms are brand new, and they were even building an entire new wing to the hostel when I was there. We stopped by for their Asado, a weekly barbeque popular in Latin America. They served some amazing steak and potatoes."},{"url":"el-salvador/7-waterfalls-hike.html","title":"The 7 Waterfalls Hike — El Salvador's Most Spectacular Trail","text":"﻿ El Salvador Hike Guide The 7 Waterfalls Hike — El Salvador's Most Spectacular Trail Seven cascading waterfalls, jungle trekking, and vine swings on La Ruta de las Flores Mar 28, 2026 Overview In most waterfall tours, you’re standing far away on an observation deck and just admiring the view, but not this one… the 7 Waterfalls (Siete Cascadas) tour in Juayúa is real up-close and personal . It was 3 hours full of adrenaline in the Salvadoran jungles: trekking through the jungle, swinging on vines, wading through streams and climbing waterfalls. It was by far my favorite experience in El Salvador, a day filled with adventure and some of the most beautiful waterfalls I’ve ever seen. Offered from Santa Ana or Juayúa, the 7 Waterfalls Hike is located only 20 minutes outside of the town of Juayúa. I signed up for a tour from Rick’s Hostel in Juayúa that only cost $15. There are also many other providers that offer the same tour. The tour takes about 3 to 4 hours and you’ll be able to see 7 waterfalls and 2 chorros ( jets in Spanish) including the famous Los Chorros de la Calera. Despite a bit of climbing involved, the tour isn’t particularly challenging. We even had a woman in her 70s join us on our tour. I would recommend bringing shoes with good traction, clothes you’re comfortable getting wet and sunscreen. The Experience We were picked up at our hostel and driven in the back of a large pickup truck for a 30 minute ride outside of Juayúa. We had two tour guides (neither of whom spoke English) : a lady leading the tour and a crazy, middle-aged Salvadoran man who was looking to jump off everything possible. We then trekked into the jungle for about 15 minutes. There was a loose vine hanging from the tree so we took turns swinging from them. We finally got to a stream deep in the jungle. The guides told us to start walking directly through the stream and there was no avoiding getting wet at this point. We stopped to take a group photo with the El Salvadoran flag. The tour guides were obsessed with having us take many group photos so there was no shortage of photos at the end of the tour. We got to the first waterfall which was miraculous . It was at least 40 feet tall and there was a beautiful glow from the sunlight filtering through the foliage. Our crazy tour guide started running around and showing us rocks that we could slide down. The best part of the tour was having free rein to wander off and stand underneath the waterfalls. The next waterfall was only a few hundred meters away. Most of the path was walking through the stream and climbing over little boulders along the way. We stopped at the third waterfall and were given a small piece of fruit as a snack. With no notice, our tour guide started climbing up the next waterfall with no rope. She fastened it to a tree at the top and then we followed her up one by one. It was a short climb of about 200 meters up the waterfall. Safety standards are a bit different in El Salvador to say the least. We climbed up through the waterfall with no helmet or safety equipment with just a rope attached to the tree. I would be lying if I said I wasn’t a bit nervous at first. However, the rocks were not slippery at all, but surprisingly had good traction. I was glad I brought good shoes, but one guy on our tour did the whole thing with bare feet. Other companies that offer the same tour will actually provide a helmet. I lost track of the number of waterfalls at this point (seven if I were to guess??) . We passed by a set of beautiful, silky thin waterfalls and a waterfall where the water was coming directly out of the cave walls. We then started to come upon the Chorros (meaning jets in Spanish). I had never heard of this before, but they were essentially really wide waterfalls. The last two had man-made walls which created a pool in front of them where you could swim in. We finally approached Los Chorros de la Calera . These are the most famous of the waterfalls with crystal-clear blue water. We relaxed here for half an hour, swimming around and climbing into the waterfalls. Some of our braver friends followed the crazy tour guide and jumped off high rocks into the very shallow pool. There was also a very narrow, dark man-made tunnel that the tour guide led us into. Besides the first waterfall, this was probably my favorite part of the trip. Los Chorros de la Calera were not super busy with only 2 other tour groups there. Our trip ended there and we headed back to town. Leaving around 10am and arriving back at 1pm, this was an action-packed half-day trip in El Salvador, especially if you’re looking for an adrenaline rush. All for $15, this tour was truly worth it. I’ve never had the experience of being so close to waterfalls and also having the freedom to explore. As tourism develops, this tour will probably get busier and have stricter rules (and safety standards) so the experience won’t be the same."},{"url":"el-salvador/el-tunco.html","title":"El Tunco & The Coast: The Best Beaches in El Salvador","text":"﻿ El Salvador Beach Guide El Tunco & The Coast: The Best Beaches in El Salvador Black sand beaches, world-class surf, and extraordinary sunsets on the Pacific Mar 30, 2026 Overview With sweeping black volcanic sand beaches and powerful Pacific swells, El Salvador’s coastline around El Tunco and El Zonte has drawn crowds of surfers and backpackers for decades. I highly recommend spending a few days here for anyone looking for some sun, waves, cheap cold beers on the beach and one of the most vivid sunsets you’ll ever see. Less than an hour away from the airport and only a 40-minute drive end-to-end, this section of El Salvador’s coast is extremely easy to access and explore. I’ve written in more detail about each of these towns later in the article, but here is an overview of the towns in the area: El Tunco - the most popular and developed town in the area, packed with surf schools, restaurants and nightlife (a bit more on the touristy side) El Zonte - a more laid-back option than El Tunco drawing more serious surfers and famously home to Bitcoin Beach Playa Shalpa (Taquillo) - a very quiet beach further up the coast for those looking for an \"off-the-grid\" feeling (my personal pick!) La Libertad - a larger town on the coast that is popular among locals and a common transit hub Getting There El Tunco is located about 1 hour from San Salvador, 40 minutes from the international airport or 2 hours from Santa Ana or La Ruta de las Flores . With so many transportation options, El Tunco is easily accessible from anywhere in the country. The proximity to the airport also makes the coast a convenient first or last stop in El Salvador. Bus — El Salvador has an extensive network of buses across the country which are extremely cheap and run frequently, making them a reliable option. El Tunco, in particular, is well connected to other popular tourist destinations like San Salvador, Santa Ana , Juayúa and the international airport. CentroCoasting is the best resource for bus schedules and connections in El Salvador Rideshare — Uber and inDrive are widely available ride-sharing apps in El Salvador with a ride from the airport to El Tunco, typically costing $15 to $25. This is the most convenient option if you’re traveling with luggage Rental car — With the option to pick up from the airport, a rental car gives you the flexibility to explore the coast at your own pace and makes day trips much easier Tourist Shuttle — As the most popular area of El Salvador, there are many international shuttles connecting El Tunco to Guatemala, Nicaragua and Honduras. Ranging from $30 to $90 and offering pick-up and drop-off along the coast, this is a convenient way to incorporate El Salvador as part of a longer Central America trip Once you’re in El Tunco, all of the other towns on the coast are easily accessible by local chicken bus or Uber. The local chicken bus is a unique way to travel like a local. Luckily, there is one main highway connecting these towns so it is hard to get lost. Which Town to Choose? Each town on El Salvador's coast has its own personality. Generally, I would suggest spending 3 to 4 days in this area : 2 more lively days based out of El Tunco and 1 to 2 days relaxing in El Zonte or Playa Shalpa. The towns are very small and easily explored in just a day, but if you’re surf-motivated, I met many backpackers who fell in love with surfing and got sucked into El Tunco for months. El Tunco El Tunco is the backpacker capital of El Salvador, a common stop for many on the \"Gringo Trail\" through Central America. For how popular it is, El Tunco is tiny: it is centered around a single main strip running down to the beach, lined with surf shops, hostels, open-air bars, and restaurants. El Tunco has drawn surfers for decades, known for being one of the best surf spots in Central America . It has even earned the nickname Surf City, El Salvador. The beach itself is a stretch of black sand with strong and consistent waves. And then there are the sunsets, which are extraordinary. The combination of the black sand and the Pacific horizon makes for a spectacular way to close out each day ( more on that later ). On the weekends, this small surf town floods with locals and tourists alike looking for a fun weekend of surfing and partying. It is by far the most developed and lively part of the coast, complete with nightlife, international cuisine, and plenty of activities. I would choose El Tunco if you're looking for the most lively experience on the coast. El Zonte El Zonte is El Tunco’s quieter, more relaxed neighbor. Located about 10 minutes down the coast, it has a smaller, more intimate feel with fewer tourists and fewer bars. If you’re looking for a quieter base with fewer crowds, El Zonte is an excellent choice. It’s an easy trip to El Tunco for nightlife and then return for a peaceful night’s sleep. El Zonte is also known as the world’s first Bitcoin Beach, a community experiment that aimed to turn the village into a fully functioning Bitcoin economy. In 2021, El Salvador actually became the first country to adopt Bitcoin as a legal currency. Although the Bitcoin buzz has died down since then, many local businesses still accept Bitcoin (an interesting quirk of El Salvador's coast). I didn't visit El Zonte, but I met many others who stayed there and absolutely loved it. If you want to do more research, here is an article that goes into depth about the town. Playa Shalpa (Taquillo) Located only half an hour further up the coast, Playa Shalpa feels a world away from El Tunco . If you're in search of a true \"off the grid\" feeling, Playa Shalpa may be the place for you. Feeling exhausted from a crazy couple of days in El Tunco, I decided to join my Canadian friend to come to Playa Shalpa to relax. I took an Uber north up the main road where I was dropped off on a dirt road (picture above) which was the entrance to Playa Shalpa. At first, I was a bit disoriented by the local security guard who asked for my passport at the entrance of the dirt road and checked me in. I walked another 800 meters along an El Salvadoran dirt road, with little signage, to finally arrive at my accommodation called El Rancho de Don Moncho . The worker was lazily lounging in a hammock, watching \" fútbol \" on his phone when I rudely disturbed him to check-in. He was moving on island time when he checked me in and his mom made lunch for us. There was only 1 other guest in my hotel the whole time I was there. The hotel was no-frills, but had a direct staircase right down to the black sand beach below. The whole area was nestled in a small cove with cliffs on both sides covered in palm trees. It was the most serene stop on my trip. No noises from modern technology, cars, or even street lights, only the sound of birds and the ocean. I fell asleep to the sound of waves crashing that I could hear from my room. I felt like I was sleeping on the beach. It is also home to Lagarza Hostel which was an upscale hostel with an infinity pool, excellent restaurant and even ocean views from the bunks. I highly recommend Playa Shalpa for those looking for a secret getaway to relax for a day or two. What to do This section was especially easy to write since there are basically 3 things to do in El Tunco: surf, relax and party. Surfing Watch on YouTube The main draw to El Tunco is its famous surf breaks, known to be some of the best in Central America . The waves are so well-known, they even have names like La Punta, La Bocana and K59. I met many people who spent a few weeks to a few months surfing in El Tunco. The Salvadoran Coast offers opportunities to surf for all levels (particularly in El Tunco or El Zonte). There is no shortage of surf schools for beginner and intermediate surfers looking to spend anywhere from a single day to a full week surf camp. Here are a couple options ( Sunzalito Surf School & Lapoint Surf Camp ), but there are plenty of schools lined up by the beach so you’ll have no problem finding a surf instructor. If you’re basing your trip around surfing, here are the times of the year where it would be best to go: March to October (wet season) – Peak swell season, waves consistently overhead, best for advanced surfers. November to February (dry season) – Smaller swells, cleaner conditions, best for beginners and intermediates. I’ll be honest, surfing is not my expertise so I’ll leave it to the experts who wrote the Complete Surfer’s Guide to El Salvador if you want to do more research. Watch the Sunset & Admire El Tunco Rock There's something special about the sunsets on Central America's Pacific Coast . The sunsets burn a dark orange color, different from anywhere else I've been. The whole town slowly gathered on the main beach to admire the sunset starting 30 minutes before. I also saw a bunch of surfers trying to catch some final waves for the day. Fun fact: the town of El Tunco is actually named after the giant black rock located right off the main beach. \"El Tunco\" is local Salvadoran slang for the pig. It's supposed to resemble a pig lying down in the ocean, but I'll let you be the judge of that... Nightlife El Tunco, in particular, is known to be the best place for nightlife in El Salvador . During the weekend, locals from all over El Salvador and tourists alike flood the town. So much so that all the hotels and hostels completely fill up in all the nearby towns. There are plenty of bars around El Tunco, but the entire town somehow ends up at Kako’s Gastrobar . Located right off the main beach, this is a massive open-air bar with a top level overlooking the dance floor. It has a very beachy feel and is the best place in town to get your fix of reggaeton. Other Activities There are plenty of other activities that you can do on El Salvador's coast. Here are some that I didn't have time to experience. However, I've included links to other guides for further research: Taminique Waterfalls (Day Trip) - located only 30 minutes from El Tunco, this short hike allows you to visit four different waterfalls. After doing the 7 Waterfalls Hike in Ruta de las Flores (which I wrote about here ), I decided to spend more time at the beach instead Yoga Retreats and Classes - the coast is also home to many yoga retreats and daily classes. Available in both El Tunco and El Zonte, many places like to offer a mix of surfing and yoga retreats Where to Eat There were many amazing places to eat in both El Tunco and Playa Shalpa. Being more heavily touristed, El Tunco had a large selection of western food, which sometimes is a nice break from eating local cuisine. Unsurprisingly, El Tunco was also the best place to get seafood in El Salvador. El Tunco Sabor Costeño - located right outside the main town, Sabor Costeño was a lovely family-run establishment with great seafood. This was hands-down my favorite meal in El Salvador! To this day, I don't quite know what I ordered, but it came out as a seafood medley with a cream sauce. They offer a wide variety of seafood and local Salvadoran dishes Dale Dale Cafe - a casual restaurant offering both Salvadoran and western food, situated conveniently on the main strip of El Tunco and a few steps away from the beach Point Break Cafe - a small cafe serving a variety of bagels and coffee. A great option if you're looking for a break from local cuisine Playa Shalpa Playa Shalpa has much more limited restaurant options than El Tunco, mainly due to how undeveloped the area is. However, the food at Lagarza Hostel was amazing. I recommend their Salvadoran breakfast and crispy fish tacos. For a more local option with fresh, made-to-order pupusas, visit the nearby pupuseria run by a mother and her daughter, just off the main highway. Places to Stay El Salvador's coast offers a wide range of accommodation options, from budget dorm rooms to mid-range boutique hotels. Most options are within walking distance of the beach. Be warned: if you're a last-minute planner like me, El Tunco is incredibly small and the area books up quickly on the weekends. I booked my accomodation two days in advance and there were only 2 hostel beds and no hotel rooms available in El Tunco. El Tunco Canuck’s Guest House - I stayed at this hostel for the majority of my time in El Tunco. The owner was a very friendly Canadian who has lived in El Salvador for years. It was a fine but very basic hostel experience Dos Palmas - a wonderful newer hostel in El Tunco. Unfortunately, it was completely booked when I was in town. However, it was gorgeous when I visited with modern dorms and relaxing outdoor pool Vibes Wellness House - half gym and half hostel! Funnily enough, the price of the day pass was almost equal to the price of a night stay Salty Dogs Hostel - located closer to La Libertad and away from El Tunco, this upscale hostel is a magnet for more serious surfers Playa Shalpa Lagarza Hostel - a gorgeous hostel complete with an infinity pool, deck overlooking the ocean and a stellar restaurant. I spent a whole afternoon hanging out there and wish I had booked a night. Despite its remote location, the staff was very friendly and organized a lot of tours and activities El Rancho de Don Moncho - the no-frills hotel I stayed at in Playa Shalpa. With a private staircase to the beach, it was a quiet and relaxing place, with only one other guest while I was there!"}]};